var __index = {"config":{"lang":["en"],"separator":"[\\s\\-]+","pipeline":["stopWordFilter"],"fields":{"title":{"boost":1000.0},"text":{"boost":1.0},"tags":{"boost":1000000.0}}},"docs":[{"location":"index.html","title":"\u6b22\u8fce\uff01","text":"<p>\u8fd9\u662f\u4e00\u4e2a\u5efa\u7acb\u51e0\u4e2a\u6708\u7684(\u6682\u65f6\u88ab\u5e9f\u5f03\u7684)\u4e3b\u9875</p>"},{"location":"CICD.html","title":"CI/CD \u5b66\u4e60\u7b14\u8bb0","text":""},{"location":"CICD.html#cicd_1","title":"\u4e00\u3001CI/CD \u662f\u4ec0\u4e48","text":"<p>CI/CD \u662f\u73b0\u4ee3\u8f6f\u4ef6\u4ea4\u4ed8\u6d41\u7a0b\u4e2d\u7684\u81ea\u52a8\u5316\u5b9e\u8df5\u3002</p> <p>CI \u662f Continuous Integration\uff0c\u6301\u7eed\u96c6\u6210\u3002</p> <p>CD \u53ef\u4ee5\u8868\u793a Continuous Delivery\uff0c\u6301\u7eed\u4ea4\u4ed8\uff1b\u4e5f\u53ef\u4ee5\u8868\u793a Continuous Deployment\uff0c\u6301\u7eed\u90e8\u7f72\u3002</p>"},{"location":"CICD.html#1-ci","title":"1. \u6301\u7eed\u96c6\u6210 CI","text":"<p>\u6301\u7eed\u96c6\u6210\u7684\u76ee\u6807\u662f\u8ba9\u4ee3\u7801\u9891\u7e41\u5408\u5e76\uff0c\u5e76\u901a\u8fc7\u81ea\u52a8\u5316\u68c0\u67e5\u5c3d\u65e9\u53d1\u73b0\u95ee\u9898\u3002</p> <p>\u5e38\u89c1\u52a8\u4f5c\uff1a</p> <ul> <li>\u62c9\u53d6\u4ee3\u7801\u3002</li> <li>\u5b89\u88c5\u4f9d\u8d56\u3002</li> <li>\u4ee3\u7801\u683c\u5f0f\u68c0\u67e5\u3002</li> <li>\u9759\u6001\u4ee3\u7801\u68c0\u67e5\u3002</li> <li>\u5355\u5143\u6d4b\u8bd5\u3002</li> <li>\u6784\u5efa\u5e94\u7528\u3002</li> <li>\u751f\u6210\u6784\u5efa\u4ea7\u7269\u3002</li> </ul> <p>CI \u7684\u91cd\u70b9\u662f\u5feb\u901f\u53cd\u9988\u3002\u5f00\u53d1\u8005\u63d0\u4ea4\u4ee3\u7801\u540e\uff0c\u7cfb\u7edf\u5e94\u8be5\u5c3d\u5feb\u544a\u8bc9\u4f60\u8fd9\u6b21\u63d0\u4ea4\u662f\u5426\u7834\u574f\u4e86\u9879\u76ee\u3002</p>"},{"location":"CICD.html#2-continuous-delivery","title":"2. \u6301\u7eed\u4ea4\u4ed8 Continuous Delivery","text":"<p>\u6301\u7eed\u4ea4\u4ed8\u8868\u793a\u4ee3\u7801\u7ecf\u8fc7\u81ea\u52a8\u5316\u6784\u5efa\u3001\u6d4b\u8bd5\u3001\u6253\u5305\u540e\uff0c\u968f\u65f6\u5177\u5907\u53d1\u5e03\u5230\u751f\u4ea7\u73af\u5883\u7684\u80fd\u529b\u3002</p> <p>\u7279\u70b9\uff1a</p> <ul> <li>\u81ea\u52a8\u5b8c\u6210\u6784\u5efa\u548c\u6d4b\u8bd5\u3002</li> <li>\u81ea\u52a8\u90e8\u7f72\u5230\u6d4b\u8bd5\u73af\u5883\u6216\u9884\u53d1\u5e03\u73af\u5883\u3002</li> <li>\u53d1\u5e03\u5230\u751f\u4ea7\u73af\u5883\u901a\u5e38\u9700\u8981\u4eba\u5de5\u786e\u8ba4\u3002</li> <li>\u66f4\u5f3a\u8c03\u201c\u968f\u65f6\u53ef\u53d1\u5e03\u201d\u3002</li> </ul>"},{"location":"CICD.html#3-continuous-deployment","title":"3. \u6301\u7eed\u90e8\u7f72 Continuous Deployment","text":"<p>\u6301\u7eed\u90e8\u7f72\u662f\u5728\u6301\u7eed\u4ea4\u4ed8\u57fa\u7840\u4e0a\u66f4\u8fdb\u4e00\u6b65\uff1a\u53ea\u8981\u4ee3\u7801\u901a\u8fc7\u6d41\u6c34\u7ebf\uff0c\u5c31\u81ea\u52a8\u53d1\u5e03\u5230\u751f\u4ea7\u73af\u5883\u3002</p> <p>\u7279\u70b9\uff1a</p> <ul> <li>\u81ea\u52a8\u5316\u7a0b\u5ea6\u66f4\u9ad8\u3002</li> <li>\u5bf9\u6d4b\u8bd5\u8986\u76d6\u3001\u76d1\u63a7\u3001\u56de\u6eda\u8981\u6c42\u66f4\u9ad8\u3002</li> <li>\u9002\u5408\u6210\u719f\u56e2\u961f\u548c\u4f4e\u98ce\u9669\u53d8\u66f4\u3002</li> </ul>"},{"location":"CICD.html#4-cicd","title":"4. CI/CD \u89e3\u51b3\u7684\u95ee\u9898","text":"<ul> <li>\u51cf\u5c11\u4eba\u5de5\u6784\u5efa\u548c\u90e8\u7f72\u9519\u8bef\u3002</li> <li>\u7f29\u77ed\u4ece\u63d0\u4ea4\u4ee3\u7801\u5230\u4e0a\u7ebf\u7684\u65f6\u95f4\u3002</li> <li>\u63d0\u9ad8\u4ee3\u7801\u8d28\u91cf\u3002</li> <li>\u8ba9\u53d1\u5e03\u8fc7\u7a0b\u53ef\u91cd\u590d\u3001\u53ef\u8ffd\u8e2a\u3002</li> <li>\u8ba9\u95ee\u9898\u66f4\u65e9\u66b4\u9732\u3002</li> <li>\u652f\u6301\u5feb\u901f\u56de\u6eda\u548c\u7070\u5ea6\u53d1\u5e03\u3002</li> </ul>"},{"location":"CICD.html#_1","title":"\u4e8c\u3001\u57fa\u672c\u6d41\u7a0b","text":"<p>\u4e00\u4e2a\u5e38\u89c1 CI/CD \u6d41\u7a0b\uff1a</p> <pre><code>\u5f00\u53d1\u8005\u63d0\u4ea4\u4ee3\u7801\n  -&gt; \u89e6\u53d1\u6d41\u6c34\u7ebf\n  -&gt; \u5b89\u88c5\u4f9d\u8d56\n  -&gt; \u4ee3\u7801\u68c0\u67e5\n  -&gt; \u81ea\u52a8\u5316\u6d4b\u8bd5\n  -&gt; \u6784\u5efa\u5e94\u7528\n  -&gt; \u6784\u5efa\u955c\u50cf\u6216\u6253\u5305\u4ea7\u7269\n  -&gt; \u63a8\u9001\u5236\u54c1\u4ed3\u5e93\n  -&gt; \u90e8\u7f72\u5230\u6d4b\u8bd5\u73af\u5883\n  -&gt; \u4eba\u5de5\u5ba1\u6279\n  -&gt; \u90e8\u7f72\u5230\u751f\u4ea7\u73af\u5883\n  -&gt; \u76d1\u63a7\u548c\u56de\u6eda\n</code></pre> <p>\u4e0d\u540c\u9879\u76ee\u53ef\u4ee5\u88c1\u526a\u8fd9\u4e2a\u6d41\u7a0b\uff0c\u4f46\u6838\u5fc3\u601d\u8def\u662f\uff1a\u628a\u91cd\u590d\u3001\u5bb9\u6613\u51fa\u9519\u3001\u9700\u8981\u4e00\u81f4\u6027\u7684\u6b65\u9aa4\u81ea\u52a8\u5316\u3002</p>"},{"location":"CICD.html#_2","title":"\u4e09\u3001\u6838\u5fc3\u6982\u5ff5","text":""},{"location":"CICD.html#1-pipeline","title":"1. Pipeline","text":"<p>Pipeline \u662f\u6d41\u6c34\u7ebf\uff0c\u8868\u793a\u4e00\u6b21\u5b8c\u6574\u7684\u81ea\u52a8\u5316\u6d41\u7a0b\u3002</p> <p>\u4f8b\u5982\uff1a</p> <pre><code>lint -&gt; test -&gt; build -&gt; deploy\n</code></pre>"},{"location":"CICD.html#2-stage","title":"2. Stage","text":"<p>Stage \u662f\u6d41\u6c34\u7ebf\u4e2d\u7684\u9636\u6bb5\u3002</p> <p>\u5e38\u89c1\u9636\u6bb5\uff1a</p> <ul> <li><code>lint</code></li> <li><code>test</code></li> <li><code>build</code></li> <li><code>package</code></li> <li><code>deploy</code></li> <li><code>release</code></li> </ul> <p>\u540c\u4e00\u4e2a stage \u4e2d\u7684\u591a\u4e2a job \u901a\u5e38\u53ef\u4ee5\u5e76\u884c\u6267\u884c\u3002</p>"},{"location":"CICD.html#3-job","title":"3. Job","text":"<p>Job \u662f\u6d41\u6c34\u7ebf\u4e2d\u7684\u4efb\u52a1\u5355\u5143\u3002</p> <p>\u4f8b\u5982\uff1a</p> <ul> <li>\u5b89\u88c5\u4f9d\u8d56\u3002</li> <li>\u8fd0\u884c\u5355\u5143\u6d4b\u8bd5\u3002</li> <li>\u6784\u5efa Docker \u955c\u50cf\u3002</li> <li>\u90e8\u7f72\u5230\u670d\u52a1\u5668\u3002</li> </ul>"},{"location":"CICD.html#4-step","title":"4. Step","text":"<p>Step \u662f job \u5185\u90e8\u7684\u4e00\u6761\u5177\u4f53\u547d\u4ee4\u6216\u52a8\u4f5c\u3002</p> <p>\u4f8b\u5982\uff1a</p> <pre><code>npm ci\nnpm run lint\nnpm test\n</code></pre>"},{"location":"CICD.html#5-runner-agent","title":"5. Runner / Agent","text":"<p>Runner \u6216 Agent \u662f\u771f\u6b63\u6267\u884c\u6d41\u6c34\u7ebf\u4efb\u52a1\u7684\u673a\u5668\u3002</p> <p>\u5b83\u53ef\u4ee5\u662f\uff1a</p> <ul> <li>\u5e73\u53f0\u63d0\u4f9b\u7684\u4e91\u4e3b\u673a\u3002</li> <li>\u81ea\u5df1\u90e8\u7f72\u7684\u670d\u52a1\u5668\u3002</li> <li>Kubernetes \u4e2d\u7684\u4e34\u65f6 Pod\u3002</li> <li>Docker \u5bb9\u5668\u3002</li> </ul>"},{"location":"CICD.html#6-artifact","title":"6. Artifact","text":"<p>Artifact \u662f\u6d41\u6c34\u7ebf\u4ea7\u751f\u7684\u6784\u5efa\u4ea7\u7269\u3002</p> <p>\u4f8b\u5982\uff1a</p> <ul> <li>\u524d\u7aef <code>dist</code> \u76ee\u5f55\u3002</li> <li>\u540e\u7aef jar \u5305\u3002</li> <li>\u6d4b\u8bd5\u62a5\u544a\u3002</li> <li>\u8986\u76d6\u7387\u62a5\u544a\u3002</li> <li>Docker \u955c\u50cf\u3002</li> </ul>"},{"location":"CICD.html#7-cache","title":"7. Cache","text":"<p>Cache \u662f\u7f13\u5b58\uff0c\u7528\u4e8e\u52a0\u901f\u6d41\u6c34\u7ebf\u3002</p> <p>\u5e38\u89c1\u7f13\u5b58\u5185\u5bb9\uff1a</p> <ul> <li>npm \u4f9d\u8d56\u7f13\u5b58\u3002</li> <li>Maven \u672c\u5730\u4ed3\u5e93\u3002</li> <li>Gradle \u7f13\u5b58\u3002</li> <li>pip \u7f13\u5b58\u3002</li> <li>Docker build cache\u3002</li> </ul> <p>Cache \u662f\u4e3a\u4e86\u52a0\u901f\uff0c\u4e0d\u5e94\u8be5\u4f5c\u4e3a\u552f\u4e00\u53ef\u9760\u4ea7\u7269\u6765\u6e90\u3002</p>"},{"location":"CICD.html#8-secret","title":"8. Secret","text":"<p>Secret \u662f\u6d41\u6c34\u7ebf\u4e2d\u7684\u654f\u611f\u914d\u7f6e\u3002</p> <p>\u4f8b\u5982\uff1a</p> <ul> <li>SSH \u79c1\u94a5\u3002</li> <li>API Token\u3002</li> <li>\u6570\u636e\u5e93\u5bc6\u7801\u3002</li> <li>\u955c\u50cf\u4ed3\u5e93\u5bc6\u7801\u3002</li> <li>\u4e91\u670d\u52a1\u8bbf\u95ee\u5bc6\u94a5\u3002</li> </ul> <p>Secret \u5e94\u8be5\u653e\u5728 CI/CD \u5e73\u53f0\u7684\u5bc6\u94a5\u7ba1\u7406\u4e2d\uff0c\u4e0d\u8981\u5199\u8fdb\u4ee3\u7801\u4ed3\u5e93\u3002</p>"},{"location":"CICD.html#9-environment","title":"9. Environment","text":"<p>Environment \u8868\u793a\u90e8\u7f72\u73af\u5883\u3002</p> <p>\u5e38\u89c1\u73af\u5883\uff1a</p> <ul> <li><code>dev</code>\uff1a\u5f00\u53d1\u73af\u5883\u3002</li> <li><code>test</code>\uff1a\u6d4b\u8bd5\u73af\u5883\u3002</li> <li><code>staging</code>\uff1a\u9884\u53d1\u5e03\u73af\u5883\u3002</li> <li><code>production</code>\uff1a\u751f\u4ea7\u73af\u5883\u3002</li> </ul> <p>\u4e0d\u540c\u73af\u5883\u5e94\u8be5\u4f7f\u7528\u4e0d\u540c\u914d\u7f6e\u3001\u4e0d\u540c\u6743\u9650\u548c\u4e0d\u540c\u5ba1\u6279\u89c4\u5219\u3002</p>"},{"location":"CICD.html#_3","title":"\u56db\u3001\u6d41\u6c34\u7ebf\u9636\u6bb5\u8bbe\u8ba1","text":""},{"location":"CICD.html#1","title":"1. \u5e38\u89c1\u9636\u6bb5","text":"\u9636\u6bb5 \u4f5c\u7528 Checkout \u62c9\u53d6\u4ee3\u7801 Install \u5b89\u88c5\u4f9d\u8d56 Lint \u68c0\u67e5\u4ee3\u7801\u98ce\u683c\u548c\u6f5c\u5728\u9519\u8bef Test \u8fd0\u884c\u81ea\u52a8\u5316\u6d4b\u8bd5 Build \u6784\u5efa\u5e94\u7528 Package \u6253\u5305\u5236\u54c1\u6216\u955c\u50cf Scan \u5b89\u5168\u626b\u63cf\u3001\u4f9d\u8d56\u626b\u63cf\u3001\u955c\u50cf\u626b\u63cf Deploy \u90e8\u7f72\u5230\u76ee\u6807\u73af\u5883 Verify \u90e8\u7f72\u540e\u5065\u5eb7\u68c0\u67e5 Notify \u901a\u77e5\u7ed3\u679c"},{"location":"CICD.html#2","title":"2. \u8bbe\u8ba1\u539f\u5219","text":"<ul> <li>\u8d8a\u5feb\u7684\u68c0\u67e5\u8d8a\u9760\u524d\u3002</li> <li>\u5931\u8d25\u540e\u5c3d\u65e9\u505c\u6b62\uff0c\u907f\u514d\u6d6a\u8d39\u8d44\u6e90\u3002</li> <li>\u4f9d\u8d56\u5b89\u88c5\u8981\u53ef\u91cd\u590d\u3002</li> <li>\u6784\u5efa\u4ea7\u7269\u5e94\u8be5\u53ef\u8ffd\u8e2a\u3002</li> <li>\u90e8\u7f72\u6b65\u9aa4\u8981\u652f\u6301\u56de\u6eda\u3002</li> <li>\u751f\u4ea7\u90e8\u7f72\u9700\u8981\u6743\u9650\u63a7\u5236\u3002</li> <li>\u5bc6\u94a5\u4e0d\u80fd\u51fa\u73b0\u5728\u65e5\u5fd7\u4e2d\u3002</li> <li>\u6d41\u6c34\u7ebf\u914d\u7f6e\u4e5f\u8981\u7eb3\u5165\u7248\u672c\u63a7\u5236\u3002</li> </ul>"},{"location":"CICD.html#3","title":"3. \u5feb\u901f\u53cd\u9988\u548c\u5b8c\u6574\u9a8c\u8bc1","text":"<p>\u53ef\u4ee5\u628a\u68c0\u67e5\u5206\u6210\u4e24\u7c7b\uff1a</p> \u7c7b\u578b \u76ee\u6807 \u793a\u4f8b \u5feb\u901f\u68c0\u67e5 \u51e0\u5206\u949f\u5185\u53cd\u9988\u57fa\u7840\u95ee\u9898 lint\u3001\u7c7b\u578b\u68c0\u67e5\u3001\u5355\u5143\u6d4b\u8bd5 \u5b8c\u6574\u68c0\u67e5 \u66f4\u5168\u9762\u4f46\u8017\u65f6\u8f83\u957f \u96c6\u6210\u6d4b\u8bd5\u3001\u7aef\u5230\u7aef\u6d4b\u8bd5\u3001\u5b89\u5168\u626b\u63cf <p>Pull Request \u9636\u6bb5\u901a\u5e38\u8ffd\u6c42\u5feb\u901f\u53cd\u9988\u3002\u5408\u5e76\u5230\u4e3b\u5206\u652f\u540e\u53ef\u4ee5\u8fd0\u884c\u66f4\u5b8c\u6574\u7684\u68c0\u67e5\u3002</p>"},{"location":"CICD.html#_4","title":"\u4e94\u3001\u89e6\u53d1\u65b9\u5f0f","text":"<p>\u5e38\u89c1\u89e6\u53d1\u65b9\u5f0f\uff1a</p> <ul> <li>push \u5230\u5206\u652f\u3002</li> <li>\u521b\u5efa Pull Request / Merge Request\u3002</li> <li>\u5408\u5e76\u5230\u4e3b\u5206\u652f\u3002</li> <li>\u521b\u5efa tag\u3002</li> <li>\u624b\u52a8\u89e6\u53d1\u3002</li> <li>\u5b9a\u65f6\u4efb\u52a1\u3002</li> <li>\u5916\u90e8\u7cfb\u7edf\u901a\u8fc7 webhook \u89e6\u53d1\u3002</li> </ul> <p>\u793a\u4f8b\uff1a</p> <pre><code>push feature \u5206\u652f -&gt; \u8fd0\u884c lint \u548c test\npull request -&gt; \u8fd0\u884c lint\u3001test\u3001build\nmerge main -&gt; \u6784\u5efa\u955c\u50cf\u5e76\u90e8\u7f72\u6d4b\u8bd5\u73af\u5883\ntag v1.0.0 -&gt; \u53d1\u5e03\u751f\u4ea7\u7248\u672c\n</code></pre>"},{"location":"CICD.html#_5","title":"\u516d\u3001\u5206\u652f\u548c\u53d1\u5e03\u7b56\u7565","text":""},{"location":"CICD.html#1-feature-branch","title":"1. Feature Branch","text":"<p>\u6bcf\u4e2a\u529f\u80fd\u4f7f\u7528\u72ec\u7acb\u5206\u652f\u5f00\u53d1\uff0c\u7136\u540e\u901a\u8fc7 PR/MR \u5408\u5e76\u3002</p> <p>\u4f18\u70b9\uff1a</p> <ul> <li>\u65b9\u4fbf code review\u3002</li> <li>\u4e0d\u76f4\u63a5\u6c61\u67d3\u4e3b\u5206\u652f\u3002</li> <li>\u9002\u5408\u5927\u591a\u6570\u56e2\u961f\u3002</li> </ul> <p>\u6ce8\u610f\uff1a</p> <ul> <li>\u5206\u652f\u5b58\u5728\u65f6\u95f4\u4e0d\u8981\u592a\u957f\u3002</li> <li>\u7ecf\u5e38\u540c\u6b65\u4e3b\u5206\u652f\uff0c\u51cf\u5c11\u51b2\u7a81\u3002</li> <li>\u5408\u5e76\u524d\u5fc5\u987b\u901a\u8fc7\u81ea\u52a8\u5316\u68c0\u67e5\u3002</li> </ul>"},{"location":"CICD.html#2-trunk-based-development","title":"2. Trunk Based Development","text":"<p>\u5f00\u53d1\u8005\u9891\u7e41\u5411\u4e3b\u5e72\u5408\u5e76\u5c0f\u6539\u52a8\uff0c\u914d\u5408\u529f\u80fd\u5f00\u5173\u63a7\u5236\u672a\u5b8c\u6210\u80fd\u529b\u3002</p> <p>\u4f18\u70b9\uff1a</p> <ul> <li>\u96c6\u6210\u66f4\u9891\u7e41\u3002</li> <li>\u5206\u652f\u5206\u53c9\u65f6\u95f4\u77ed\u3002</li> <li>\u53d1\u5e03\u8282\u594f\u5feb\u3002</li> </ul> <p>\u8981\u6c42\uff1a</p> <ul> <li>\u6d4b\u8bd5\u81ea\u52a8\u5316\u7a0b\u5ea6\u9ad8\u3002</li> <li>\u4e3b\u5206\u652f\u4fdd\u62a4\u4e25\u683c\u3002</li> <li>\u529f\u80fd\u5f00\u5173\u7ba1\u7406\u53ef\u9760\u3002</li> </ul>"},{"location":"CICD.html#3-git-flow","title":"3. Git Flow","text":"<p>\u5e38\u89c1\u5206\u652f\uff1a</p> <ul> <li><code>main</code> \u6216 <code>master</code>\uff1a\u751f\u4ea7\u7248\u672c\u3002</li> <li><code>develop</code>\uff1a\u5f00\u53d1\u4e3b\u7ebf\u3002</li> <li><code>feature/*</code>\uff1a\u529f\u80fd\u5206\u652f\u3002</li> <li><code>release/*</code>\uff1a\u53d1\u5e03\u5206\u652f\u3002</li> <li><code>hotfix/*</code>\uff1a\u7d27\u6025\u4fee\u590d\u3002</li> </ul> <p>Git Flow \u6d41\u7a0b\u6e05\u6670\uff0c\u4f46\u5206\u652f\u8f83\u591a\uff0c\u9002\u5408\u53d1\u5e03\u5468\u671f\u76f8\u5bf9\u56fa\u5b9a\u7684\u9879\u76ee\u3002</p>"},{"location":"CICD.html#4-tag","title":"4. Tag \u53d1\u5e03","text":"<p>\u751f\u4ea7\u53d1\u5e03\u5e38\u7528 tag \u6807\u8bb0\u7248\u672c\uff1a</p> <pre><code>git tag v1.0.0\ngit push origin v1.0.0\n</code></pre> <p>CI/CD \u53ef\u4ee5\u914d\u7f6e\u4e3a tag \u89e6\u53d1\u53d1\u5e03\u3002</p> <p>\u7248\u672c\u53f7\u5efa\u8bae\u4f7f\u7528\u8bed\u4e49\u5316\u7248\u672c\uff1a</p> <pre><code>MAJOR.MINOR.PATCH\n</code></pre> <p>\u4f8b\u5982\uff1a</p> <pre><code>v2.3.1\n</code></pre>"},{"location":"CICD.html#github-actions","title":"\u4e03\u3001GitHub Actions \u793a\u4f8b","text":"<p>GitHub Actions \u7684\u914d\u7f6e\u901a\u5e38\u653e\u5728\uff1a</p> <pre><code>.github/workflows/*.yml\n</code></pre>"},{"location":"CICD.html#1-nodejs-ci","title":"1. Node.js CI \u793a\u4f8b","text":"<pre><code>name: Node CI\n\non:\n  push:\n    branches: [main]\n  pull_request:\n    branches: [main]\n\njobs:\n  test:\n    runs-on: ubuntu-latest\n\n    steps:\n      - name: Checkout\n        uses: actions/checkout@v4\n\n      - name: Setup Node.js\n        uses: actions/setup-node@v4\n        with:\n          node-version: 20\n          cache: npm\n\n      - name: Install dependencies\n        run: npm ci\n\n      - name: Lint\n        run: npm run lint\n\n      - name: Test\n        run: npm test\n\n      - name: Build\n        run: npm run build\n</code></pre>"},{"location":"CICD.html#2-docker","title":"2. \u6784\u5efa\u5e76\u63a8\u9001 Docker \u955c\u50cf","text":"<pre><code>name: Build Docker Image\n\non:\n  push:\n    tags:\n      - \"v*\"\n\njobs:\n  docker:\n    runs-on: ubuntu-latest\n\n    permissions:\n      contents: read\n      packages: write\n\n    steps:\n      - uses: actions/checkout@v4\n\n      - name: Login to GitHub Container Registry\n        uses: docker/login-action@v3\n        with:\n          registry: ghcr.io\n          username: ${{ github.actor }}\n          password: ${{ secrets.GITHUB_TOKEN }}\n\n      - name: Build and push\n        uses: docker/build-push-action@v6\n        with:\n          context: .\n          push: true\n          tags: ghcr.io/owner/app:${{ github.ref_name }}\n</code></pre> <p>\u8fd9\u91cc\u7684 <code>${{ github.ref_name }}</code> \u5728 tag \u89e6\u53d1\u65f6\u5c31\u662f tag \u540d\u79f0\uff0c\u4f8b\u5982 <code>v1.0.0</code>\u3002</p>"},{"location":"CICD.html#gitlab-ci","title":"\u516b\u3001GitLab CI \u793a\u4f8b","text":"<p>GitLab CI \u914d\u7f6e\u6587\u4ef6\u901a\u5e38\u662f\uff1a</p> <pre><code>.gitlab-ci.yml\n</code></pre> <p>\u793a\u4f8b\uff1a</p> <pre><code>stages:\n  - test\n  - build\n  - deploy\n\ntest:\n  stage: test\n  image: node:20-alpine\n  script:\n    - npm ci\n    - npm run lint\n    - npm test\n\nbuild:\n  stage: build\n  image: node:20-alpine\n  script:\n    - npm ci\n    - npm run build\n  artifacts:\n    paths:\n      - dist/\n    expire_in: 1 week\n\ndeploy_staging:\n  stage: deploy\n  script:\n    - echo \"deploy to staging\"\n  only:\n    - main\n</code></pre> <p>\u8bf4\u660e\uff1a</p> <ul> <li><code>stages</code> \u5b9a\u4e49\u9636\u6bb5\u987a\u5e8f\u3002</li> <li><code>image</code> \u6307\u5b9a job \u8fd0\u884c\u73af\u5883\u3002</li> <li><code>script</code> \u662f\u5177\u4f53\u547d\u4ee4\u3002</li> <li><code>artifacts</code> \u4fdd\u5b58\u6784\u5efa\u4ea7\u7269\u3002</li> <li><code>only</code> \u63a7\u5236 job \u89e6\u53d1\u6761\u4ef6\u3002</li> </ul>"},{"location":"CICD.html#jenkins","title":"\u4e5d\u3001Jenkins \u57fa\u672c\u6982\u5ff5","text":"<p>Jenkins \u662f\u5e38\u89c1\u7684\u81ea\u5efa CI/CD \u5de5\u5177\u3002</p> <p>\u6838\u5fc3\u6982\u5ff5\uff1a</p> <ul> <li>Controller\uff1aJenkins \u4e3b\u8282\u70b9\uff0c\u8d1f\u8d23\u8c03\u5ea6\u548c\u7ba1\u7406\u3002</li> <li>Agent\uff1a\u6267\u884c\u4efb\u52a1\u7684\u8282\u70b9\u3002</li> <li>Job\uff1a\u4efb\u52a1\u3002</li> <li>Pipeline\uff1a\u6d41\u6c34\u7ebf\u3002</li> <li>Jenkinsfile\uff1a\u6d41\u6c34\u7ebf\u914d\u7f6e\u6587\u4ef6\u3002</li> </ul> <p>Declarative Pipeline \u793a\u4f8b\uff1a</p> <pre><code>pipeline {\n  agent any\n\n  stages {\n    stage('Install') {\n      steps {\n        sh 'npm ci'\n      }\n    }\n\n    stage('Test') {\n      steps {\n        sh 'npm test'\n      }\n    }\n\n    stage('Build') {\n      steps {\n        sh 'npm run build'\n      }\n    }\n  }\n}\n</code></pre> <p>Jenkins \u7075\u6d3b\u5ea6\u9ad8\uff0c\u4f46\u9700\u8981\u81ea\u5df1\u7ef4\u62a4\u63d2\u4ef6\u3001\u6743\u9650\u3001\u8282\u70b9\u3001\u51ed\u636e\u548c\u5347\u7ea7\u3002</p>"},{"location":"CICD.html#_6","title":"\u5341\u3001\u5236\u54c1\u7ba1\u7406","text":"<p>CI/CD \u4e2d\u4e0d\u8981\u53ea\u5173\u6ce8\u201c\u628a\u4ee3\u7801\u90e8\u7f72\u4e0a\u53bb\u201d\uff0c\u8fd8\u8981\u5173\u6ce8\u4ea7\u7269\u662f\u5426\u53ef\u8ffd\u8e2a\u3001\u53ef\u590d\u7528\u3001\u53ef\u56de\u6eda\u3002</p> <p>\u5e38\u89c1\u5236\u54c1\uff1a</p> <ul> <li>Docker \u955c\u50cf\u3002</li> <li>jar / war \u5305\u3002</li> <li>npm \u5305\u3002</li> <li>Python wheel \u5305\u3002</li> <li>\u524d\u7aef\u9759\u6001\u8d44\u6e90\u3002</li> <li>Helm chart\u3002</li> </ul> <p>\u5236\u54c1\u4ed3\u5e93\uff1a</p> <ul> <li>Docker Registry\u3002</li> <li>GitHub Packages\u3002</li> <li>GitLab Package Registry\u3002</li> <li>Nexus\u3002</li> <li>Artifactory\u3002</li> <li>Harbor\u3002</li> </ul> <p>\u597d\u7684\u5236\u54c1\u5e94\u8be5\u5177\u5907\uff1a</p> <ul> <li>\u660e\u786e\u7248\u672c\u53f7\u3002</li> <li>\u6765\u6e90 commit \u53ef\u8ffd\u8e2a\u3002</li> <li>\u6784\u5efa\u65f6\u95f4\u53ef\u8ffd\u8e2a\u3002</li> <li>\u4f9d\u8d56\u4fe1\u606f\u53ef\u8ffd\u8e2a\u3002</li> <li>\u53ef\u4ee5\u88ab\u91cd\u590d\u90e8\u7f72\u3002</li> </ul>"},{"location":"CICD.html#docker-cicd","title":"\u5341\u4e00\u3001Docker \u5728 CI/CD \u4e2d\u7684\u4f7f\u7528","text":""},{"location":"CICD.html#1_1","title":"1. \u5e38\u89c1\u6d41\u7a0b","text":"<pre><code>\u62c9\u53d6\u4ee3\u7801\n  -&gt; \u8fd0\u884c\u6d4b\u8bd5\n  -&gt; docker build \u6784\u5efa\u955c\u50cf\n  -&gt; docker push \u63a8\u9001\u955c\u50cf\u4ed3\u5e93\n  -&gt; \u90e8\u7f72\u5e73\u53f0\u62c9\u53d6\u955c\u50cf\n  -&gt; \u542f\u52a8\u65b0\u7248\u672c\u5bb9\u5668\n</code></pre>"},{"location":"CICD.html#2_1","title":"2. \u955c\u50cf\u6807\u7b7e\u5efa\u8bae","text":"<p>\u4e0d\u8981\u53ea\u4f7f\u7528 <code>latest</code>\u3002</p> <p>\u63a8\u8350\u540c\u65f6\u6253\u591a\u4e2a\u6807\u7b7e\uff1a</p> <pre><code>app:v1.2.0\napp:git-a1b2c3d\napp:main\n</code></pre> <p>\u751f\u4ea7\u90e8\u7f72\u6700\u597d\u4f7f\u7528\uff1a</p> <ul> <li>\u7248\u672c\u53f7 tag\u3002</li> <li>Git commit SHA tag\u3002</li> <li>\u955c\u50cf digest\u3002</li> </ul> <p>\u8fd9\u6837\u65b9\u4fbf\u5b9a\u4f4d\u548c\u56de\u6eda\u3002</p>"},{"location":"CICD.html#3_1","title":"3. \u955c\u50cf\u6784\u5efa\u6ce8\u610f\u70b9","text":"<ul> <li>CI \u4e2d\u6784\u5efa\u955c\u50cf\u8981\u4f7f\u7528\u786e\u5b9a\u7248\u672c\u7684\u57fa\u7840\u955c\u50cf\u3002</li> <li>\u4e0d\u8981\u628a <code>.env</code>\u3001\u79c1\u94a5\u3001Token \u653e\u8fdb\u955c\u50cf\u3002</li> <li>\u4f7f\u7528\u591a\u9636\u6bb5\u6784\u5efa\u3002</li> <li>\u4f7f\u7528 <code>.dockerignore</code> \u51cf\u5c11\u6784\u5efa\u4e0a\u4e0b\u6587\u3002</li> <li>\u5bf9\u955c\u50cf\u8fdb\u884c\u5b89\u5168\u626b\u63cf\u3002</li> <li>\u63a8\u9001\u955c\u50cf\u524d\u786e\u4fdd\u6d4b\u8bd5\u5df2\u901a\u8fc7\u3002</li> </ul>"},{"location":"CICD.html#_7","title":"\u5341\u4e8c\u3001\u90e8\u7f72\u7b56\u7565","text":""},{"location":"CICD.html#1_2","title":"1. \u76f4\u63a5\u90e8\u7f72","text":"<p>\u505c\u6b62\u65e7\u7248\u672c\uff0c\u542f\u52a8\u65b0\u7248\u672c\u3002</p> <p>\u4f18\u70b9\uff1a</p> <ul> <li>\u7b80\u5355\u3002</li> <li>\u6210\u672c\u4f4e\u3002</li> </ul> <p>\u7f3a\u70b9\uff1a</p> <ul> <li>\u53ef\u80fd\u6709\u77ed\u6682\u505c\u673a\u3002</li> <li>\u51fa\u95ee\u9898\u5f71\u54cd\u8303\u56f4\u5927\u3002</li> </ul>"},{"location":"CICD.html#2_2","title":"2. \u6eda\u52a8\u53d1\u5e03","text":"<p>\u9010\u6279\u66ff\u6362\u65e7\u5b9e\u4f8b\u3002</p> <p>\u4f18\u70b9\uff1a</p> <ul> <li>\u4e0d\u9700\u8981\u540c\u65f6\u542f\u52a8\u5b8c\u6574\u4e24\u5957\u73af\u5883\u3002</li> <li>\u53ef\u4ee5\u51cf\u5c11\u505c\u673a\u65f6\u95f4\u3002</li> </ul> <p>\u7f3a\u70b9\uff1a</p> <ul> <li>\u53d1\u5e03\u671f\u95f4\u65b0\u65e7\u7248\u672c\u4f1a\u540c\u65f6\u5b58\u5728\u3002</li> <li>\u9700\u8981\u517c\u5bb9\u6570\u636e\u5e93\u548c\u63a5\u53e3\u53d8\u66f4\u3002</li> </ul>"},{"location":"CICD.html#3_2","title":"3. \u84dd\u7eff\u53d1\u5e03","text":"<p>\u51c6\u5907\u4e24\u5957\u73af\u5883\uff1a</p> <ul> <li>\u84dd\u8272\uff1a\u5f53\u524d\u751f\u4ea7\u73af\u5883\u3002</li> <li>\u7eff\u8272\uff1a\u65b0\u7248\u672c\u73af\u5883\u3002</li> </ul> <p>\u9a8c\u8bc1\u7eff\u8272\u73af\u5883\u65e0\u95ee\u9898\u540e\uff0c\u628a\u6d41\u91cf\u5207\u5230\u7eff\u8272\u3002</p> <p>\u4f18\u70b9\uff1a</p> <ul> <li>\u56de\u6eda\u5feb\u3002</li> <li>\u53d1\u5e03\u98ce\u9669\u8f83\u4f4e\u3002</li> </ul> <p>\u7f3a\u70b9\uff1a</p> <ul> <li>\u8d44\u6e90\u6210\u672c\u8f83\u9ad8\u3002</li> <li>\u6570\u636e\u5e93\u53d8\u66f4\u4ecd\u9700\u8c28\u614e\u3002</li> </ul>"},{"location":"CICD.html#4","title":"4. \u91d1\u4e1d\u96c0\u53d1\u5e03","text":"<p>\u5148\u8ba9\u5c11\u91cf\u7528\u6237\u8bbf\u95ee\u65b0\u7248\u672c\uff0c\u89c2\u5bdf\u6307\u6807\u6b63\u5e38\u540e\u9010\u6b65\u6269\u5927\u6d41\u91cf\u3002</p> <p>\u4f18\u70b9\uff1a</p> <ul> <li>\u98ce\u9669\u53ef\u63a7\u3002</li> <li>\u9002\u5408\u9ad8\u6d41\u91cf\u7ebf\u4e0a\u670d\u52a1\u3002</li> </ul> <p>\u8981\u6c42\uff1a</p> <ul> <li>\u6709\u6d41\u91cf\u5207\u5206\u80fd\u529b\u3002</li> <li>\u6709\u76d1\u63a7\u548c\u544a\u8b66\u3002</li> <li>\u6709\u5feb\u901f\u56de\u6eda\u673a\u5236\u3002</li> </ul>"},{"location":"CICD.html#5","title":"5. \u529f\u80fd\u5f00\u5173","text":"<p>\u529f\u80fd\u5f00\u5173\u53ef\u4ee5\u8ba9\u4ee3\u7801\u5148\u4e0a\u7ebf\uff0c\u4f46\u529f\u80fd\u6682\u65f6\u5173\u95ed\u3002</p> <p>\u7528\u9014\uff1a</p> <ul> <li>\u63a7\u5236\u65b0\u529f\u80fd\u7070\u5ea6\u3002</li> <li>\u5feb\u901f\u5173\u95ed\u5f02\u5e38\u529f\u80fd\u3002</li> <li>\u652f\u6301 trunk based development\u3002</li> </ul> <p>\u6ce8\u610f\uff1a</p> <ul> <li>\u529f\u80fd\u5f00\u5173\u8981\u6709\u6e05\u7406\u673a\u5236\u3002</li> <li>\u4e0d\u8981\u8ba9\u8fc7\u671f\u5f00\u5173\u957f\u671f\u5806\u79ef\u3002</li> </ul>"},{"location":"CICD.html#_8","title":"\u5341\u4e09\u3001\u6570\u636e\u5e93\u53d8\u66f4","text":"<p>\u6570\u636e\u5e93\u53d8\u66f4\u662f CI/CD \u4e2d\u6700\u5bb9\u6613\u51fa\u4e8b\u6545\u7684\u90e8\u5206\u3002</p> <p>\u5efa\u8bae\uff1a</p> <ul> <li>\u6570\u636e\u5e93\u8fc1\u79fb\u811a\u672c\u7eb3\u5165\u7248\u672c\u63a7\u5236\u3002</li> <li>\u6bcf\u6b21\u53d8\u66f4\u53ef\u4ee5\u91cd\u590d\u6267\u884c\u6216\u6709\u660e\u786e\u7248\u672c\u8bb0\u5f55\u3002</li> <li>\u5148\u505a\u517c\u5bb9\u6027\u53d8\u66f4\uff0c\u518d\u5207\u6362\u4ee3\u7801\u3002</li> <li>\u907f\u514d\u4e0a\u7ebf\u65f6\u76f4\u63a5\u5220\u9664\u5b57\u6bb5\u6216\u6539\u5b57\u6bb5\u542b\u4e49\u3002</li> <li>\u5927\u8868\u53d8\u66f4\u8981\u8bc4\u4f30\u9501\u8868\u548c\u6027\u80fd\u5f71\u54cd\u3002</li> <li>\u53d1\u5e03\u524d\u5907\u4efd\u5173\u952e\u6570\u636e\u3002</li> </ul> <p>\u517c\u5bb9\u53d1\u5e03\u793a\u4f8b\uff1a</p> <pre><code>\u7b2c 1 \u6b21\u53d1\u5e03\uff1a\u65b0\u589e\u5b57\u6bb5\uff0c\u65e7\u4ee3\u7801\u4e0d\u4f7f\u7528\n\u7b2c 2 \u6b21\u53d1\u5e03\uff1a\u65b0\u4ee3\u7801\u540c\u65f6\u517c\u5bb9\u65b0\u65e7\u5b57\u6bb5\n\u7b2c 3 \u6b21\u53d1\u5e03\uff1a\u6570\u636e\u8fc1\u79fb\u5b8c\u6210\u540e\u79fb\u9664\u65e7\u903b\u8f91\n\u7b2c 4 \u6b21\u53d1\u5e03\uff1a\u786e\u8ba4\u65e0\u98ce\u9669\u540e\u5220\u9664\u65e7\u5b57\u6bb5\n</code></pre>"},{"location":"CICD.html#_9","title":"\u5341\u56db\u3001\u8d28\u91cf\u95e8\u7981","text":"<p>\u8d28\u91cf\u95e8\u7981\u662f\u51b3\u5b9a\u4ee3\u7801\u80fd\u5426\u8fdb\u5165\u4e0b\u4e00\u9636\u6bb5\u7684\u89c4\u5219\u3002</p> <p>\u5e38\u89c1\u95e8\u7981\uff1a</p> <ul> <li>\u5355\u5143\u6d4b\u8bd5\u5fc5\u987b\u901a\u8fc7\u3002</li> <li>\u6784\u5efa\u5fc5\u987b\u6210\u529f\u3002</li> <li>lint \u65e0\u9519\u8bef\u3002</li> <li>\u6d4b\u8bd5\u8986\u76d6\u7387\u4e0d\u4f4e\u4e8e\u9608\u503c\u3002</li> <li>\u4f9d\u8d56\u6f0f\u6d1e\u4e0d\u80fd\u8d85\u8fc7\u6307\u5b9a\u7b49\u7ea7\u3002</li> <li>\u955c\u50cf\u626b\u63cf\u4e0d\u80fd\u6709\u9ad8\u5371\u6f0f\u6d1e\u3002</li> <li>PR \u5fc5\u987b\u7ecf\u8fc7 review\u3002</li> <li>\u4e3b\u5206\u652f\u5fc5\u987b\u4fdd\u62a4\u3002</li> <li>\u751f\u4ea7\u90e8\u7f72\u5fc5\u987b\u4eba\u5de5\u5ba1\u6279\u3002</li> </ul> <p>\u95e8\u7981\u4e0d\u662f\u8d8a\u591a\u8d8a\u597d\uff0c\u5173\u952e\u662f\u80fd\u8986\u76d6\u4e3b\u8981\u98ce\u9669\uff0c\u5e76\u4e14\u4e0d\u4f1a\u8ba9\u53cd\u9988\u901f\u5ea6\u53d8\u5f97\u4e0d\u53ef\u63a5\u53d7\u3002</p>"},{"location":"CICD.html#_10","title":"\u5341\u4e94\u3001\u5b89\u5168\u5b9e\u8df5","text":""},{"location":"CICD.html#1_3","title":"1. \u5bc6\u94a5\u7ba1\u7406","text":"<ul> <li>\u4f7f\u7528 CI/CD \u5e73\u53f0\u7684 Secret \u529f\u80fd\u3002</li> <li>\u4e0d\u8981\u628a\u5bc6\u94a5\u5199\u8fdb\u4ed3\u5e93\u3002</li> <li>\u4e0d\u8981\u5728\u65e5\u5fd7\u4e2d\u6253\u5370\u5bc6\u94a5\u3002</li> <li>\u4e0d\u8981\u628a\u751f\u4ea7\u5bc6\u94a5\u66b4\u9732\u7ed9 PR \u6d41\u6c34\u7ebf\u3002</li> <li>\u5b9a\u671f\u8f6e\u6362\u5bc6\u94a5\u3002</li> <li>\u7ed9\u4e0d\u540c\u73af\u5883\u4f7f\u7528\u4e0d\u540c\u5bc6\u94a5\u3002</li> </ul>"},{"location":"CICD.html#2_3","title":"2. \u6743\u9650\u6700\u5c0f\u5316","text":"<p>\u6d41\u6c34\u7ebf\u8d26\u53f7\u53ea\u5e94\u8be5\u62e5\u6709\u5b8c\u6210\u4efb\u52a1\u6240\u9700\u7684\u6700\u5c0f\u6743\u9650\u3002</p> <p>\u4f8b\u5982\uff1a</p> <ul> <li>\u6784\u5efa\u6d41\u6c34\u7ebf\u53ea\u9700\u8981\u8bfb\u4ee3\u7801\u548c\u5199\u955c\u50cf\u4ed3\u5e93\u3002</li> <li>\u90e8\u7f72\u6d4b\u8bd5\u73af\u5883\u4e0d\u5e94\u8be5\u62e5\u6709\u751f\u4ea7\u73af\u5883\u6743\u9650\u3002</li> <li>\u751f\u4ea7\u53d1\u5e03\u9700\u8981\u66f4\u4e25\u683c\u5ba1\u6279\u3002</li> </ul>"},{"location":"CICD.html#3_3","title":"3. \u4f9d\u8d56\u548c\u955c\u50cf\u5b89\u5168","text":"<p>\u5e38\u89c1\u68c0\u67e5\uff1a</p> <ul> <li>\u4f9d\u8d56\u6f0f\u6d1e\u626b\u63cf\u3002</li> <li>\u9759\u6001\u4ee3\u7801\u626b\u63cf\u3002</li> <li>Secret \u626b\u63cf\u3002</li> <li>Docker \u955c\u50cf\u6f0f\u6d1e\u626b\u63cf\u3002</li> <li>License \u68c0\u67e5\u3002</li> <li>SBOM \u751f\u6210\u3002</li> </ul>"},{"location":"CICD.html#4_1","title":"4. \u4f9b\u5e94\u94fe\u5b89\u5168","text":"<p>\u6ce8\u610f\u70b9\uff1a</p> <ul> <li>\u56fa\u5b9a action\u3001\u63d2\u4ef6\u3001\u57fa\u7840\u955c\u50cf\u7248\u672c\u3002</li> <li>\u4f7f\u7528\u53ef\u4fe1\u6765\u6e90\u7684\u7b2c\u4e09\u65b9 action\u3002</li> <li>\u4e0d\u5728 PR \u4e2d\u8fd0\u884c\u4e0d\u53ef\u4fe1\u90e8\u7f72\u811a\u672c\u3002</li> <li>\u4fdd\u62a4\u4e3b\u5206\u652f\u548c tag\u3002</li> <li>\u5bf9\u53d1\u5e03\u5236\u54c1\u8fdb\u884c\u7b7e\u540d\u3002</li> </ul>"},{"location":"CICD.html#_11","title":"\u5341\u516d\u3001\u76d1\u63a7\u548c\u56de\u6eda","text":"<p>\u53d1\u5e03\u4e0d\u662f\u6d41\u6c34\u7ebf\u7ed3\u675f\u5c31\u5b8c\u6210\u4e86\u3002\u4e0a\u7ebf\u540e\u8fd8\u8981\u89c2\u5bdf\u7cfb\u7edf\u662f\u5426\u5065\u5eb7\u3002</p> <p>\u5e38\u89c1\u76d1\u63a7\u6307\u6807\uff1a</p> <ul> <li>\u9519\u8bef\u7387\u3002</li> <li>\u8bf7\u6c42\u5ef6\u8fdf\u3002</li> <li>CPU\u3001\u5185\u5b58\u3001\u78c1\u76d8\u3002</li> <li>\u5bb9\u5668\u91cd\u542f\u6b21\u6570\u3002</li> <li>\u65e5\u5fd7\u5f02\u5e38\u3002</li> <li>\u4e1a\u52a1\u6307\u6807\u3002</li> <li>\u961f\u5217\u5806\u79ef\u3002</li> <li>\u6570\u636e\u5e93\u8fde\u63a5\u6570\u3002</li> </ul> <p>\u56de\u6eda\u65b9\u5f0f\uff1a</p> <ul> <li>\u56de\u6eda\u5230\u4e0a\u4e00\u4e2a Docker \u955c\u50cf\u7248\u672c\u3002</li> <li>\u56de\u6eda Kubernetes Deployment\u3002</li> <li>\u5207\u56de\u84dd\u7eff\u53d1\u5e03\u4e2d\u7684\u65e7\u73af\u5883\u3002</li> <li>\u5173\u95ed\u529f\u80fd\u5f00\u5173\u3002</li> <li>\u56de\u6eda\u6570\u636e\u5e93\u53d8\u66f4\u3002</li> </ul> <p>\u6570\u636e\u5e93\u56de\u6eda\u901a\u5e38\u6700\u590d\u6742\uff0c\u56e0\u6b64\u6570\u636e\u5e93\u53d8\u66f4\u5e94\u5c3d\u91cf\u8bbe\u8ba1\u4e3a\u5411\u524d\u517c\u5bb9\u3002</p>"},{"location":"CICD.html#_12","title":"\u5341\u4e03\u3001\u5e38\u89c1\u95ee\u9898","text":""},{"location":"CICD.html#1_4","title":"1. \u6d41\u6c34\u7ebf\u5f88\u6162","text":"<p>\u4f18\u5316\u65b9\u5411\uff1a</p> <ul> <li>\u4f7f\u7528\u4f9d\u8d56\u7f13\u5b58\u3002</li> <li>\u5e76\u884c\u6267\u884c\u72ec\u7acb\u4efb\u52a1\u3002</li> <li>\u62c6\u5206\u5feb\u901f\u68c0\u67e5\u548c\u5b8c\u6574\u68c0\u67e5\u3002</li> <li>\u51cf\u5c11\u4e0d\u5fc5\u8981\u7684\u6784\u5efa\u3002</li> <li>\u4f18\u5316 Dockerfile \u7f13\u5b58\u5c42\u3002</li> <li>\u4f7f\u7528\u66f4\u5408\u9002\u7684 runner \u89c4\u683c\u3002</li> </ul>"},{"location":"CICD.html#2_4","title":"2. \u6d4b\u8bd5\u5076\u53d1\u5931\u8d25","text":"<p>\u5e38\u89c1\u539f\u56e0\uff1a</p> <ul> <li>\u6d4b\u8bd5\u4f9d\u8d56\u65f6\u95f4\u3001\u968f\u673a\u6570\u6216\u5916\u90e8\u670d\u52a1\u3002</li> <li>\u5e76\u53d1\u6d4b\u8bd5\u4e92\u76f8\u5f71\u54cd\u3002</li> <li>\u6d4b\u8bd5\u6570\u636e\u6ca1\u6709\u9694\u79bb\u3002</li> <li>\u7f51\u7edc\u8bf7\u6c42\u4e0d\u7a33\u5b9a\u3002</li> <li>\u7b49\u5f85\u6761\u4ef6\u4e0d\u51c6\u786e\u3002</li> </ul> <p>\u5904\u7406\u65b9\u5f0f\uff1a</p> <ul> <li>\u4fee\u590d flaky test\uff0c\u4e0d\u8981\u957f\u671f\u5ffd\u7565\u3002</li> <li>\u7ed9\u96c6\u6210\u6d4b\u8bd5\u63d0\u4f9b\u7a33\u5b9a\u6d4b\u8bd5\u73af\u5883\u3002</li> <li>\u4f7f\u7528 mock \u6216 test container\u3002</li> <li>\u660e\u786e\u8d85\u65f6\u548c\u91cd\u8bd5\u7b56\u7565\u3002</li> </ul>"},{"location":"CICD.html#3-ci","title":"3. \u672c\u5730\u6b63\u5e38\uff0cCI \u5931\u8d25","text":"<p>\u68c0\u67e5\u65b9\u5411\uff1a</p> <ul> <li>Node\u3001Java\u3001Python \u7b49\u8fd0\u884c\u65f6\u7248\u672c\u662f\u5426\u4e00\u81f4\u3002</li> <li>\u64cd\u4f5c\u7cfb\u7edf\u5dee\u5f02\u3002</li> <li>\u73af\u5883\u53d8\u91cf\u662f\u5426\u7f3a\u5931\u3002</li> <li>\u4f9d\u8d56\u9501\u6587\u4ef6\u662f\u5426\u63d0\u4ea4\u3002</li> <li>\u6587\u4ef6\u8def\u5f84\u5927\u5c0f\u5199\u95ee\u9898\u3002</li> <li>\u6d4b\u8bd5\u662f\u5426\u4f9d\u8d56\u672c\u5730\u6587\u4ef6\u6216\u672c\u5730\u670d\u52a1\u3002</li> </ul>"},{"location":"CICD.html#4_2","title":"4. \u90e8\u7f72\u6210\u529f\u4f46\u670d\u52a1\u4e0d\u53ef\u7528","text":"<p>\u68c0\u67e5\u65b9\u5411\uff1a</p> <ul> <li>\u5e94\u7528\u662f\u5426\u771f\u7684\u542f\u52a8\u5b8c\u6210\u3002</li> <li>\u5065\u5eb7\u68c0\u67e5\u662f\u5426\u901a\u8fc7\u3002</li> <li>\u914d\u7f6e\u548c\u5bc6\u94a5\u662f\u5426\u6b63\u786e\u3002</li> <li>\u6570\u636e\u5e93\u8fde\u63a5\u662f\u5426\u6b63\u5e38\u3002</li> <li>\u7aef\u53e3\u3001\u57df\u540d\u3001\u8d1f\u8f7d\u5747\u8861\u662f\u5426\u6b63\u786e\u3002</li> <li>\u65b0\u7248\u672c\u662f\u5426\u517c\u5bb9\u65e7\u6570\u636e\u3002</li> <li>\u65e5\u5fd7\u4e2d\u662f\u5426\u6709\u5f02\u5e38\u3002</li> </ul>"},{"location":"CICD.html#_13","title":"\u5341\u516b\u3001\u5b66\u4e60\u91cd\u70b9","text":"<ul> <li>\u7406\u89e3 CI\u3001\u6301\u7eed\u4ea4\u4ed8\u3001\u6301\u7eed\u90e8\u7f72\u7684\u533a\u522b\u3002</li> <li>\u77e5\u9053 pipeline\u3001stage\u3001job\u3001artifact\u3001cache\u3001secret \u7684\u542b\u4e49\u3002</li> <li>\u4f1a\u5199\u57fa\u7840 GitHub Actions \u6216 GitLab CI \u914d\u7f6e\u3002</li> <li>\u4f1a\u628a\u6d4b\u8bd5\u3001\u6784\u5efa\u3001\u6253\u5305\u3001\u90e8\u7f72\u4e32\u6210\u6d41\u6c34\u7ebf\u3002</li> <li>\u660e\u767d\u5bc6\u94a5\u4e0d\u80fd\u5199\u8fdb\u4ed3\u5e93\u3002</li> <li>\u77e5\u9053\u751f\u4ea7\u53d1\u5e03\u9700\u8981\u56de\u6eda\u65b9\u6848\u3002</li> <li>\u77e5\u9053\u4e0d\u540c\u90e8\u7f72\u7b56\u7565\u7684\u4f18\u7f3a\u70b9\u3002</li> <li>\u80fd\u6839\u636e\u65e5\u5fd7\u548c\u6d41\u6c34\u7ebf\u7ed3\u679c\u5b9a\u4f4d\u5931\u8d25\u539f\u56e0\u3002</li> </ul>"},{"location":"CICD.html#cicd_2","title":"\u5341\u4e5d\u3001CI/CD \u68c0\u67e5\u6e05\u5355","text":"<p>\u63d0\u4ea4\u4ee3\u7801\u524d\uff1a</p> <ul> <li>\u672c\u5730\u6d4b\u8bd5\u901a\u8fc7\u3002</li> <li>\u4f9d\u8d56\u9501\u6587\u4ef6\u5df2\u63d0\u4ea4\u3002</li> <li>\u6ca1\u6709\u63d0\u4ea4\u5bc6\u94a5\u548c\u654f\u611f\u914d\u7f6e\u3002</li> <li>\u53d8\u66f4\u8303\u56f4\u6e05\u6670\u3002</li> </ul> <p>\u5408\u5e76\u524d\uff1a</p> <ul> <li>CI \u901a\u8fc7\u3002</li> <li>Code review \u5b8c\u6210\u3002</li> <li>\u6d4b\u8bd5\u8986\u76d6\u4e3b\u8981\u903b\u8f91\u3002</li> <li>\u6570\u636e\u5e93\u53d8\u66f4\u5df2\u8bc4\u4f30\u3002</li> </ul> <p>\u53d1\u5e03\u524d\uff1a</p> <ul> <li>\u6784\u5efa\u4ea7\u7269\u53ef\u8ffd\u8e2a\u3002</li> <li>\u955c\u50cf\u6216\u5236\u54c1\u7248\u672c\u660e\u786e\u3002</li> <li>\u914d\u7f6e\u548c\u5bc6\u94a5\u5df2\u51c6\u5907\u3002</li> <li>\u56de\u6eda\u65b9\u6848\u660e\u786e\u3002</li> <li>\u76d1\u63a7\u548c\u544a\u8b66\u53ef\u7528\u3002</li> </ul> <p>\u53d1\u5e03\u540e\uff1a</p> <ul> <li>\u67e5\u770b\u5e94\u7528\u65e5\u5fd7\u3002</li> <li>\u67e5\u770b\u9519\u8bef\u7387\u548c\u5ef6\u8fdf\u3002</li> <li>\u9a8c\u8bc1\u6838\u5fc3\u4e1a\u52a1\u6d41\u7a0b\u3002</li> <li>\u89c2\u5bdf\u8d44\u6e90\u5360\u7528\u3002</li> <li>\u8bb0\u5f55\u7248\u672c\u548c\u53d1\u5e03\u65f6\u95f4\u3002</li> </ul>"},{"location":"Web.html","title":"\u8ba1\u7b97\u673a\u7f51\u7edc\u7b14\u8bb0","text":""},{"location":"Web.html#_2","title":"\u4e00\u3001\u8ba1\u7b97\u673a\u7f51\u7edc\u6982\u8ff0","text":""},{"location":"Web.html#1","title":"1. \u4ec0\u4e48\u662f\u8ba1\u7b97\u673a\u7f51\u7edc","text":"<p>\u8ba1\u7b97\u673a\u7f51\u7edc\u662f\u6307\u628a\u5206\u5e03\u5728\u4e0d\u540c\u5730\u7406\u4f4d\u7f6e\u7684\u8ba1\u7b97\u673a\u3001\u670d\u52a1\u5668\u3001\u7ec8\u7aef\u8bbe\u5907\u548c\u7f51\u7edc\u8bbe\u5907\uff0c\u901a\u8fc7\u901a\u4fe1\u7ebf\u8def\u8fde\u63a5\u8d77\u6765\uff0c\u5b9e\u73b0\u6570\u636e\u901a\u4fe1\u3001\u8d44\u6e90\u5171\u4eab\u548c\u534f\u540c\u5de5\u4f5c\u7684\u7cfb\u7edf\u3002</p> <p>\u7f51\u7edc\u7684\u6838\u5fc3\u76ee\u6807\uff1a</p> <ul> <li>\u6570\u636e\u901a\u4fe1\uff1a\u8ba9\u4e0d\u540c\u8bbe\u5907\u4e4b\u95f4\u53ef\u4ee5\u4ea4\u6362\u4fe1\u606f\u3002</li> <li>\u8d44\u6e90\u5171\u4eab\uff1a\u5171\u4eab\u6587\u4ef6\u3001\u6253\u5370\u673a\u3001\u670d\u52a1\u5668\u3001\u6570\u636e\u5e93\u7b49\u8d44\u6e90\u3002</li> <li>\u5206\u5e03\u5f0f\u5904\u7406\uff1a\u591a\u53f0\u8bbe\u5907\u5171\u540c\u5b8c\u6210\u4efb\u52a1\u3002</li> <li>\u63d0\u9ad8\u53ef\u9760\u6027\uff1a\u67d0\u4e9b\u8282\u70b9\u6545\u969c\u65f6\uff0c\u4ecd\u53ef\u901a\u8fc7\u5176\u4ed6\u8def\u5f84\u901a\u4fe1\u3002</li> </ul>"},{"location":"Web.html#2","title":"2. \u7f51\u7edc\u7684\u5206\u7c7b","text":"<p>\u6309\u8986\u76d6\u8303\u56f4\u5212\u5206\uff1a</p> \u7c7b\u578b \u4e2d\u6587\u540d \u7279\u70b9 \u793a\u4f8b PAN \u4e2a\u4eba\u533a\u57df\u7f51 \u8303\u56f4\u5f88\u5c0f\uff0c\u56f4\u7ed5\u4e2a\u4eba\u8bbe\u5907 \u84dd\u7259\u8033\u673a\u3001\u624b\u673a\u70ed\u70b9 LAN \u5c40\u57df\u7f51 \u8303\u56f4\u8f83\u5c0f\uff0c\u901f\u5ea6\u5feb\uff0c\u5ef6\u8fdf\u4f4e \u5bb6\u5ead\u7f51\u7edc\u3001\u6821\u56ed\u7f51\u3001\u516c\u53f8\u5185\u7f51 MAN \u57ce\u57df\u7f51 \u8986\u76d6\u4e00\u4e2a\u57ce\u5e02\u6216\u5730\u533a \u57ce\u5e02\u653f\u52a1\u7f51\u7edc WAN \u5e7f\u57df\u7f51 \u8de8\u5730\u533a\u3001\u8de8\u56fd\u5bb6 \u4e92\u8054\u7f51 <p>\u6309\u4f20\u8f93\u4ecb\u8d28\u5212\u5206\uff1a</p> <ul> <li>\u6709\u7ebf\u7f51\u7edc\uff1a\u53cc\u7ede\u7ebf\u3001\u540c\u8f74\u7535\u7f06\u3001\u5149\u7ea4\u3002</li> <li>\u65e0\u7ebf\u7f51\u7edc\uff1aWi-Fi\u3001\u84dd\u7259\u3001\u8702\u7a9d\u7f51\u7edc\u3001\u536b\u661f\u901a\u4fe1\u3002</li> </ul> <p>\u6309\u4ea4\u6362\u65b9\u5f0f\u5212\u5206\uff1a</p> <ul> <li>\u7535\u8def\u4ea4\u6362\uff1a\u901a\u4fe1\u524d\u5148\u5efa\u7acb\u56fa\u5b9a\u7ebf\u8def\uff0c\u5178\u578b\u4f8b\u5b50\u662f\u4f20\u7edf\u7535\u8bdd\u7f51\u7edc\u3002</li> <li>\u5206\u7ec4\u4ea4\u6362\uff1a\u628a\u6570\u636e\u62c6\u6210\u591a\u4e2a\u5206\u7ec4\u72ec\u7acb\u4f20\u8f93\uff0c\u4e92\u8054\u7f51\u4e3b\u8981\u91c7\u7528\u8fd9\u79cd\u65b9\u5f0f\u3002</li> <li>\u62a5\u6587\u4ea4\u6362\uff1a\u4ee5\u5b8c\u6574\u62a5\u6587\u4e3a\u5355\u4f4d\u5b58\u50a8\u8f6c\u53d1\uff0c\u73b0\u5728\u8f83\u5c11\u76f4\u63a5\u4f7f\u7528\u3002</li> </ul>"},{"location":"Web.html#3","title":"3. \u5e38\u89c1\u7f51\u7edc\u62d3\u6251","text":"<ul> <li>\u603b\u7ebf\u578b\uff1a\u6240\u6709\u8bbe\u5907\u5171\u4eab\u4e00\u6761\u901a\u4fe1\u7ebf\u8def\uff0c\u7ed3\u6784\u7b80\u5355\u4f46\u51b2\u7a81\u591a\u3002</li> <li>\u661f\u578b\uff1a\u8bbe\u5907\u8fde\u63a5\u5230\u4e2d\u5fc3\u4ea4\u6362\u8bbe\u5907\uff0c\u73b0\u4ee3\u5c40\u57df\u7f51\u5e38\u7528\u3002</li> <li>\u73af\u578b\uff1a\u8bbe\u5907\u9996\u5c3e\u76f8\u8fde\u5f62\u6210\u73af\uff0c\u6570\u636e\u6cbf\u56fa\u5b9a\u65b9\u5411\u4f20\u8f93\u3002</li> <li>\u7f51\u72b6\u578b\uff1a\u8282\u70b9\u4e4b\u95f4\u6709\u591a\u6761\u8fde\u63a5\uff0c\u53ef\u9760\u6027\u9ad8\uff0c\u6210\u672c\u4e5f\u9ad8\u3002</li> <li>\u6811\u578b\uff1a\u5206\u5c42\u7ed3\u6784\uff0c\u9002\u5408\u5927\u578b\u7f51\u7edc\u7ba1\u7406\u3002</li> </ul>"},{"location":"Web.html#_3","title":"\u4e8c\u3001\u7f51\u7edc\u4f53\u7cfb\u7ed3\u6784","text":""},{"location":"Web.html#1-osi","title":"1. OSI \u4e03\u5c42\u6a21\u578b","text":"\u5c42\u6b21 \u540d\u79f0 \u4f5c\u7528 \u5e38\u89c1\u534f\u8bae\u6216\u8bbe\u5907 7 \u5e94\u7528\u5c42 \u4e3a\u7528\u6237\u5e94\u7528\u63d0\u4f9b\u7f51\u7edc\u670d\u52a1 HTTP\u3001DNS\u3001FTP\u3001SMTP 6 \u8868\u793a\u5c42 \u6570\u636e\u683c\u5f0f\u8f6c\u6362\u3001\u52a0\u5bc6\u3001\u538b\u7f29 SSL/TLS\u3001JPEG\u3001ASCII 5 \u4f1a\u8bdd\u5c42 \u5efa\u7acb\u3001\u7ba1\u7406\u548c\u91ca\u653e\u4f1a\u8bdd RPC\u3001NetBIOS 4 \u4f20\u8f93\u5c42 \u7aef\u5230\u7aef\u4f20\u8f93\u3001\u53ef\u9760\u6027\u63a7\u5236 TCP\u3001UDP 3 \u7f51\u7edc\u5c42 IP \u5bfb\u5740\u548c\u8def\u7531\u9009\u62e9 IP\u3001ICMP\u3001\u8def\u7531\u5668 2 \u6570\u636e\u94fe\u8def\u5c42 \u5e27\u4f20\u8f93\u3001MAC \u5730\u5740\u3001\u5dee\u9519\u68c0\u6d4b Ethernet\u3001\u4ea4\u6362\u673a 1 \u7269\u7406\u5c42 \u6bd4\u7279\u6d41\u4f20\u8f93 \u7f51\u7ebf\u3001\u5149\u7ea4\u3001\u96c6\u7ebf\u5668"},{"location":"Web.html#2-tcpip","title":"2. TCP/IP \u56db\u5c42\u6a21\u578b","text":"TCP/IP \u6a21\u578b \u5bf9\u5e94 OSI \u5c42 \u4e3b\u8981\u529f\u80fd \u5e94\u7528\u5c42 \u5e94\u7528\u5c42\u3001\u8868\u793a\u5c42\u3001\u4f1a\u8bdd\u5c42 \u5177\u4f53\u5e94\u7528\u534f\u8bae \u4f20\u8f93\u5c42 \u4f20\u8f93\u5c42 \u8fdb\u7a0b\u5230\u8fdb\u7a0b\u901a\u4fe1 \u7f51\u9645\u5c42 \u7f51\u7edc\u5c42 IP \u5bfb\u5740\u548c\u8def\u7531 \u7f51\u7edc\u63a5\u53e3\u5c42 \u6570\u636e\u94fe\u8def\u5c42\u3001\u7269\u7406\u5c42 \u5c40\u57df\u7f51\u4f20\u8f93\u548c\u7269\u7406\u4f20\u8f93"},{"location":"Web.html#3_1","title":"3. \u6570\u636e\u5c01\u88c5\u8fc7\u7a0b","text":"<p>\u53d1\u9001\u6570\u636e\u65f6\uff0c\u6570\u636e\u4f1a\u4ece\u9ad8\u5c42\u5411\u4f4e\u5c42\u9010\u5c42\u5c01\u88c5\uff1a</p> <pre><code>\u5e94\u7528\u6570\u636e\n  -&gt; \u4f20\u8f93\u5c42\u52a0 TCP/UDP \u9996\u90e8\uff0c\u5f62\u6210\u6bb5 Segment\n  -&gt; \u7f51\u7edc\u5c42\u52a0 IP \u9996\u90e8\uff0c\u5f62\u6210\u5305 Packet\n  -&gt; \u6570\u636e\u94fe\u8def\u5c42\u52a0\u5e27\u5934\u5e27\u5c3e\uff0c\u5f62\u6210\u5e27 Frame\n  -&gt; \u7269\u7406\u5c42\u8f6c\u6362\u4e3a\u6bd4\u7279\u6d41 Bit\n</code></pre> <p>\u63a5\u6536\u6570\u636e\u65f6\uff0c\u8fc7\u7a0b\u76f8\u53cd\uff0c\u9010\u5c42\u89e3\u5c01\u88c5\u3002</p>"},{"location":"Web.html#_4","title":"\u4e09\u3001\u7269\u7406\u5c42","text":"<p>\u7269\u7406\u5c42\u8d1f\u8d23\u5728\u4f20\u8f93\u4ecb\u8d28\u4e0a\u4f20\u8f93\u539f\u59cb\u6bd4\u7279\u6d41\u3002</p>"},{"location":"Web.html#1_1","title":"1. \u5e38\u89c1\u4f20\u8f93\u4ecb\u8d28","text":"<ul> <li>\u53cc\u7ede\u7ebf\uff1a\u5c40\u57df\u7f51\u5e38\u7528\uff0c\u6210\u672c\u4f4e\uff0c\u5e38\u89c1\u63a5\u53e3\u662f RJ-45\u3002</li> <li>\u5149\u7ea4\uff1a\u4f20\u8f93\u8ddd\u79bb\u8fdc\uff0c\u901f\u5ea6\u5feb\uff0c\u6297\u5e72\u6270\u80fd\u529b\u5f3a\u3002</li> <li>\u65e0\u7ebf\u7535\u6ce2\uff1a\u7528\u4e8e Wi-Fi\u3001\u84dd\u7259\u3001\u8702\u7a9d\u7f51\u7edc\u3002</li> </ul>"},{"location":"Web.html#2_1","title":"2. \u5e38\u89c1\u5355\u4f4d","text":"<ul> <li><code>bit</code>\uff1a\u6bd4\u7279\uff0c\u7f51\u7edc\u4f20\u8f93\u7684\u57fa\u672c\u5355\u4f4d\u3002</li> <li><code>Byte</code>\uff1a\u5b57\u8282\uff0c<code>1 Byte = 8 bit</code>\u3002</li> <li><code>Mbps</code>\uff1a\u6bcf\u79d2\u767e\u4e07\u6bd4\u7279\u3002</li> <li><code>MB/s</code>\uff1a\u6bcf\u79d2\u767e\u4e07\u5b57\u8282\u3002</li> </ul> <p>\u6362\u7b97\u793a\u4f8b\uff1a</p> <pre><code>100 Mbps \u2248 12.5 MB/s\n</code></pre> <p>\u5b9e\u9645\u4e0b\u8f7d\u901f\u5ea6\u8fd8\u8981\u6263\u9664\u534f\u8bae\u5f00\u9500\uff0c\u6240\u4ee5\u901a\u5e38\u8fbe\u4e0d\u5230\u7406\u8bba\u503c\u3002</p>"},{"location":"Web.html#_5","title":"\u56db\u3001\u6570\u636e\u94fe\u8def\u5c42","text":"<p>\u6570\u636e\u94fe\u8def\u5c42\u8d1f\u8d23\u5728\u540c\u4e00\u94fe\u8def\u6216\u540c\u4e00\u5c40\u57df\u7f51\u5185\u4f20\u8f93\u6570\u636e\u5e27\u3002</p>"},{"location":"Web.html#1-mac","title":"1. MAC \u5730\u5740","text":"<p>MAC \u5730\u5740\u662f\u7f51\u5361\u7684\u786c\u4ef6\u5730\u5740\uff0c\u957f\u5ea6\u4e3a 48 \u4f4d\uff0c\u901a\u5e38\u5199\u6210\uff1a</p> <pre><code>00-1A-2B-3C-4D-5E\n</code></pre> <p>\u7279\u70b9\uff1a</p> <ul> <li>\u7528\u4e8e\u5c40\u57df\u7f51\u5185\u90e8\u8bc6\u522b\u8bbe\u5907\u3002</li> <li>\u4ea4\u6362\u673a\u6839\u636e MAC \u5730\u5740\u8f6c\u53d1\u6570\u636e\u5e27\u3002</li> <li>MAC \u5730\u5740\u5de5\u4f5c\u5728\u6570\u636e\u94fe\u8def\u5c42\u3002</li> </ul>"},{"location":"Web.html#2_2","title":"2. \u4ee5\u592a\u7f51\u5e27","text":"<p>\u4ee5\u592a\u7f51\u5e27\u7684\u6838\u5fc3\u5b57\u6bb5\uff1a</p> <ul> <li>\u76ee\u6807 MAC \u5730\u5740</li> <li>\u6e90 MAC \u5730\u5740</li> <li>\u7c7b\u578b\u5b57\u6bb5</li> <li>\u6570\u636e\u90e8\u5206</li> <li>FCS \u6821\u9a8c\u5b57\u6bb5</li> </ul> <p>FCS \u901a\u5e38\u4f7f\u7528 CRC \u6821\u9a8c\uff0c\u7528\u4e8e\u53d1\u73b0\u4f20\u8f93\u9519\u8bef\u3002</p>"},{"location":"Web.html#3_2","title":"3. \u4ea4\u6362\u673a\u5de5\u4f5c\u539f\u7406","text":"<p>\u4ea4\u6362\u673a\u4e3b\u8981\u6839\u636e MAC \u5730\u5740\u8868\u8f6c\u53d1\u6570\u636e\uff1a</p> <ol> <li>\u6536\u5230\u6570\u636e\u5e27\u540e\uff0c\u8bb0\u5f55\u6e90 MAC \u5730\u5740\u548c\u5bf9\u5e94\u7aef\u53e3\u3002</li> <li>\u67e5\u627e\u76ee\u6807 MAC \u5730\u5740\u6240\u5728\u7aef\u53e3\u3002</li> <li>\u5982\u679c\u627e\u5230\u76ee\u6807\u7aef\u53e3\uff0c\u5c31\u53ea\u5411\u8be5\u7aef\u53e3\u8f6c\u53d1\u3002</li> <li>\u5982\u679c\u627e\u4e0d\u5230\u76ee\u6807\u7aef\u53e3\uff0c\u5c31\u5411\u9664\u63a5\u6536\u7aef\u53e3\u5916\u7684\u5176\u4ed6\u7aef\u53e3\u5e7f\u64ad\u3002</li> </ol> <p>\u4ea4\u6362\u673a\u6bd4\u96c6\u7ebf\u5668\u66f4\u9ad8\u6548\uff0c\u56e0\u4e3a\u5b83\u4e0d\u4f1a\u65e0\u8111\u5e7f\u64ad\u6240\u6709\u6570\u636e\u3002</p>"},{"location":"Web.html#4","title":"4. \u5e7f\u64ad\u4e0e\u51b2\u7a81","text":"<ul> <li>\u51b2\u7a81\u57df\uff1a\u540c\u4e00\u65f6\u95f4\u53ea\u80fd\u6709\u4e00\u4e2a\u8bbe\u5907\u53d1\u9001\u6570\u636e\u7684\u8303\u56f4\u3002</li> <li>\u5e7f\u64ad\u57df\uff1a\u5e7f\u64ad\u5e27\u53ef\u4ee5\u5230\u8fbe\u7684\u8303\u56f4\u3002</li> <li>\u4ea4\u6362\u673a\u53ef\u4ee5\u9694\u79bb\u51b2\u7a81\u57df\u3002</li> <li>\u8def\u7531\u5668\u53ef\u4ee5\u9694\u79bb\u5e7f\u64ad\u57df\u3002</li> </ul>"},{"location":"Web.html#5-vlan","title":"5. VLAN","text":"<p>VLAN \u662f\u865a\u62df\u5c40\u57df\u7f51\uff0c\u53ef\u4ee5\u5728\u540c\u4e00\u7269\u7406\u4ea4\u6362\u673a\u4e0a\u5212\u5206\u591a\u4e2a\u903b\u8f91\u7f51\u7edc\u3002</p> <p>\u4f5c\u7528\uff1a</p> <ul> <li>\u9694\u79bb\u5e7f\u64ad\u57df\u3002</li> <li>\u63d0\u9ad8\u5b89\u5168\u6027\u3002</li> <li>\u65b9\u4fbf\u7f51\u7edc\u7ba1\u7406\u3002</li> </ul>"},{"location":"Web.html#_6","title":"\u4e94\u3001\u7f51\u7edc\u5c42","text":"<p>\u7f51\u7edc\u5c42\u8d1f\u8d23\u8de8\u7f51\u7edc\u4f20\u8f93\u6570\u636e\u5305\uff0c\u6838\u5fc3\u4efb\u52a1\u662f IP \u5bfb\u5740\u548c\u8def\u7531\u9009\u62e9\u3002</p>"},{"location":"Web.html#1-ip","title":"1. IP \u5730\u5740","text":"<p>IPv4 \u5730\u5740\u957f\u5ea6\u4e3a 32 \u4f4d\uff0c\u901a\u5e38\u5199\u6210\u70b9\u5206\u5341\u8fdb\u5236\uff1a</p> <pre><code>192.168.1.10\n</code></pre> <p>IP \u5730\u5740\u7531\u4e24\u90e8\u5206\u7ec4\u6210\uff1a</p> <ul> <li>\u7f51\u7edc\u53f7\uff1a\u6807\u8bc6\u6240\u5c5e\u7f51\u7edc\u3002</li> <li>\u4e3b\u673a\u53f7\uff1a\u6807\u8bc6\u8be5\u7f51\u7edc\u4e2d\u7684\u5177\u4f53\u4e3b\u673a\u3002</li> </ul> <p>IP \u534f\u8bae\u7684\u7279\u70b9\uff1a</p> <ul> <li>\u65e0\u8fde\u63a5\uff1a\u53d1\u9001 IP \u6570\u636e\u5305\u524d\uff0c\u4e0d\u9700\u8981\u5148\u5efa\u7acb\u8fde\u63a5\u3002</li> <li>\u5c3d\u529b\u800c\u4e3a\uff1aIP \u53ea\u5c3d\u529b\u8f6c\u53d1\uff0c\u4e0d\u4fdd\u8bc1\u4e00\u5b9a\u9001\u8fbe\u3002</li> <li>\u4e0d\u4fdd\u8bc1\u987a\u5e8f\uff1a\u591a\u4e2a\u6570\u636e\u5305\u53ef\u80fd\u7ecf\u8fc7\u4e0d\u540c\u8def\u5f84\uff0c\u5230\u8fbe\u987a\u5e8f\u53ef\u80fd\u4e0d\u540c\u3002</li> <li>\u4e0d\u8d1f\u8d23\u91cd\u4f20\uff1a\u4e22\u5305\u540e\u7684\u91cd\u4f20\u901a\u5e38\u7531 TCP \u6216\u5e94\u7528\u5c42\u5904\u7406\u3002</li> </ul> <p>IPv4 \u62a5\u6587\u5934\u4e2d\u7684\u91cd\u8981\u5b57\u6bb5\uff1a</p> \u5b57\u6bb5 \u4f5c\u7528 Version IP \u534f\u8bae\u7248\u672c\uff0cIPv4 \u4e2d\u503c\u4e3a 4 Header Length IP \u9996\u90e8\u957f\u5ea6 Total Length \u6574\u4e2a IP \u6570\u636e\u5305\u957f\u5ea6 Identification \u5206\u7247\u91cd\u7ec4\u65f6\u8bc6\u522b\u540c\u4e00\u4e2a\u6570\u636e\u5305 Flags \u63a7\u5236\u662f\u5426\u5141\u8bb8\u5206\u7247\uff0c\u5982 DF\u3001MF Fragment Offset \u5206\u7247\u504f\u79fb\u91cf TTL \u751f\u5b58\u65f6\u95f4\uff0c\u6bcf\u7ecf\u8fc7\u4e00\u4e2a\u8def\u7531\u5668\u51cf 1 Protocol \u4e0a\u5c42\u534f\u8bae\uff0c\u5982 TCP \u4e3a 6\uff0cUDP \u4e3a 17\uff0cICMP \u4e3a 1 Header Checksum IP \u9996\u90e8\u6821\u9a8c\u548c Source IP \u6e90 IP \u5730\u5740 Destination IP \u76ee\u6807 IP \u5730\u5740 <p>TTL \u7684\u4f5c\u7528\u662f\u9632\u6b62\u6570\u636e\u5305\u5728\u7f51\u7edc\u4e2d\u65e0\u9650\u5faa\u73af\u3002\u8def\u7531\u5668\u6bcf\u8f6c\u53d1\u4e00\u6b21\uff0cTTL \u51cf 1\uff1b\u5f53 TTL \u53d8\u4e3a 0 \u65f6\uff0c\u8def\u7531\u5668\u4e22\u5f03\u8be5\u5305\uff0c\u5e76\u53ef\u80fd\u8fd4\u56de ICMP \u8d85\u65f6\u62a5\u6587\u3002</p> <p>\u5e38\u89c1\u7279\u6b8a IPv4 \u5730\u5740\uff1a</p> \u5730\u5740 \u542b\u4e49 0.0.0.0 \u672a\u6307\u5b9a\u5730\u5740\uff0c\u4e5f\u53ef\u8868\u793a\u76d1\u542c\u672c\u673a\u6240\u6709\u7f51\u5361 127.0.0.1 \u672c\u673a\u56de\u73af\u5730\u5740\uff0c\u5e38\u7528\u4e8e\u6d4b\u8bd5\u672c\u673a\u670d\u52a1 169.254.0.0/16 \u81ea\u52a8\u79c1\u6709\u5730\u5740\uff0c\u901a\u5e38\u8868\u793a DHCP \u83b7\u53d6\u5730\u5740\u5931\u8d25 255.255.255.255 \u53d7\u9650\u5e7f\u64ad\u5730\u5740\uff0c\u53ea\u5728\u672c\u5730\u7f51\u7edc\u5185\u5e7f\u64ad \u7f51\u7edc\u5730\u5740 \u4e3b\u673a\u4f4d\u5168\u4e3a 0\uff0c\u8868\u793a\u6574\u4e2a\u7f51\u6bb5 \u5e7f\u64ad\u5730\u5740 \u4e3b\u673a\u4f4d\u5168\u4e3a 1\uff0c\u8868\u793a\u8be5\u7f51\u6bb5\u5185\u6240\u6709\u4e3b\u673a <p>IPv6 \u5730\u5740\u957f\u5ea6\u4e3a 128 \u4f4d\uff0c\u901a\u5e38\u4f7f\u7528\u5341\u516d\u8fdb\u5236\u548c\u5192\u53f7\u8868\u793a\uff1a</p> <pre><code>2001:0db8:0000:0000:0000:ff00:0042:8329\n</code></pre> <p>IPv6 \u53ef\u4ee5\u538b\u7f29\u8fde\u7eed\u7684 0\uff1a</p> <pre><code>2001:db8::ff00:42:8329\n</code></pre> <p>IPv6 \u7684\u7279\u70b9\uff1a</p> <ul> <li>\u5730\u5740\u7a7a\u95f4\u6781\u5927\uff0c\u7f13\u89e3 IPv4 \u5730\u5740\u4e0d\u8db3\u3002</li> <li>\u4e0d\u4f7f\u7528\u5e7f\u64ad\uff0c\u6539\u7528\u591a\u64ad\u548c\u4efb\u64ad\u3002</li> <li>\u9996\u90e8\u7ed3\u6784\u6bd4 IPv4 \u66f4\u7b80\u5316\u3002</li> <li>\u652f\u6301\u81ea\u52a8\u5730\u5740\u914d\u7f6e\u3002</li> <li>\u5e38\u89c1\u56de\u73af\u5730\u5740\u662f <code>::1</code>\u3002</li> <li>\u5e38\u89c1\u94fe\u8def\u672c\u5730\u5730\u5740\u524d\u7f00\u662f <code>fe80::/10</code>\u3002</li> </ul>"},{"location":"Web.html#2_3","title":"2. \u5b50\u7f51\u63a9\u7801","text":"<p>\u5b50\u7f51\u63a9\u7801\u7528\u4e8e\u533a\u5206 IP \u5730\u5740\u4e2d\u7684\u7f51\u7edc\u53f7\u548c\u4e3b\u673a\u53f7\u3002</p> <p>\u793a\u4f8b\uff1a</p> <pre><code>IP \u5730\u5740\uff1a     192.168.1.10\n\u5b50\u7f51\u63a9\u7801\uff1a   255.255.255.0\n\u7f51\u7edc\u5730\u5740\uff1a   192.168.1.0\n\u5e7f\u64ad\u5730\u5740\uff1a   192.168.1.255\n\u53ef\u7528\u4e3b\u673a\uff1a   192.168.1.1 ~ 192.168.1.254\n</code></pre> <p>\u5224\u65ad\u4e24\u4e2a IP \u662f\u5426\u5728\u540c\u4e00\u7f51\u6bb5\uff0c\u9700\u8981\u628a IP \u5730\u5740\u548c\u5b50\u7f51\u63a9\u7801\u8fdb\u884c\u6309\u4f4d\u4e0e\u8fd0\u7b97\u3002\u5982\u679c\u5f97\u5230\u7684\u7f51\u7edc\u5730\u5740\u76f8\u540c\uff0c\u8bf4\u660e\u5b83\u4eec\u5728\u540c\u4e00\u7f51\u6bb5\u3002</p> <p>\u793a\u4f8b\uff1a</p> <pre><code>192.168.1.10  AND  255.255.255.0  = 192.168.1.0\n192.168.1.20  AND  255.255.255.0  = 192.168.1.0\n</code></pre> <p>\u8fd9\u4e24\u4e2a\u5730\u5740\u7684\u7f51\u7edc\u5730\u5740\u76f8\u540c\uff0c\u6240\u4ee5\u5c5e\u4e8e\u540c\u4e00\u7f51\u6bb5\u3002</p>"},{"location":"Web.html#3-cidr","title":"3. CIDR \u8868\u793a\u6cd5","text":"<p>CIDR \u7528\u659c\u6760\u8868\u793a\u7f51\u7edc\u524d\u7f00\u957f\u5ea6\uff1a</p> <pre><code>192.168.1.0/24\n</code></pre> <p><code>/24</code> \u8868\u793a\u524d 24 \u4f4d\u662f\u7f51\u7edc\u53f7\u3002</p> <p>\u5e38\u89c1\u524d\u7f00\uff1a</p> CIDR \u5b50\u7f51\u63a9\u7801 \u53ef\u7528\u4e3b\u673a\u6570 /24 255.255.255.0 254 /25 255.255.255.128 126 /26 255.255.255.192 62 /27 255.255.255.224 30 /30 255.255.255.252 2 <p>\u53ef\u7528\u4e3b\u673a\u6570\u8ba1\u7b97\uff1a</p> <pre><code>\u53ef\u7528\u4e3b\u673a\u6570 = 2^(\u4e3b\u673a\u4f4d\u6570) - 2\n</code></pre> <p>\u51cf\u53bb\u7684 2 \u4e2a\u5730\u5740\u5206\u522b\u662f\u7f51\u7edc\u5730\u5740\u548c\u5e7f\u64ad\u5730\u5740\u3002</p> <p>\u5b50\u7f51\u5212\u5206\u793a\u4f8b\uff1a</p> <pre><code>\u539f\u7f51\u7edc\uff1a192.168.10.0/24\n\u9700\u6c42\uff1a\u5212\u5206\u4e3a 4 \u4e2a\u5b50\u7f51\n</code></pre> <p>\u9700\u8981\u501f 2 \u4f4d\u4e3b\u673a\u4f4d\u4f5c\u4e3a\u5b50\u7f51\u4f4d\uff0c\u56e0\u4e3a <code>2^2 = 4</code>\u3002\u65b0\u7684\u524d\u7f00\u957f\u5ea6\u4e3a <code>/26</code>\u3002</p> \u5b50\u7f51 \u7f51\u7edc\u5730\u5740 \u53ef\u7528\u4e3b\u673a\u8303\u56f4 \u5e7f\u64ad\u5730\u5740 1 192.168.10.0/26 192.168.10.1 ~ 192.168.10.62 192.168.10.63 2 192.168.10.64/26 192.168.10.65 ~ 192.168.10.126 192.168.10.127 3 192.168.10.128/26 192.168.10.129 ~ 192.168.10.190 192.168.10.191 4 192.168.10.192/26 192.168.10.193 ~ 192.168.10.254 192.168.10.255 <p>\u5b50\u7f51\u5212\u5206\u7684\u5173\u952e\u6b65\u9aa4\uff1a</p> <ol> <li>\u660e\u786e\u9700\u8981\u591a\u5c11\u4e2a\u5b50\u7f51\u6216\u6bcf\u4e2a\u5b50\u7f51\u9700\u8981\u591a\u5c11\u4e3b\u673a\u3002</li> <li>\u6839\u636e\u9700\u6c42\u786e\u5b9a\u9700\u8981\u501f\u51e0\u4f4d\u3002</li> <li>\u8ba1\u7b97\u65b0\u7684\u5b50\u7f51\u63a9\u7801\u3002</li> <li>\u8ba1\u7b97\u6bcf\u4e2a\u5b50\u7f51\u7684\u7f51\u7edc\u5730\u5740\u3001\u5e7f\u64ad\u5730\u5740\u548c\u53ef\u7528\u5730\u5740\u8303\u56f4\u3002</li> </ol>"},{"location":"Web.html#4-ip","title":"4. \u79c1\u6709 IP \u5730\u5740","text":"<p>\u79c1\u6709\u5730\u5740\u53ea\u80fd\u5728\u5185\u7f51\u4f7f\u7528\uff0c\u4e0d\u80fd\u76f4\u63a5\u5728\u516c\u7f51\u8def\u7531\u3002</p> \u5730\u5740\u8303\u56f4 CIDR 10.0.0.0 ~ 10.255.255.255 10.0.0.0/8 172.16.0.0 ~ 172.31.255.255 172.16.0.0/12 192.168.0.0 ~ 192.168.255.255 192.168.0.0/16"},{"location":"Web.html#5","title":"5. \u9ed8\u8ba4\u7f51\u5173","text":"<p>\u9ed8\u8ba4\u7f51\u5173\u662f\u4e3b\u673a\u8bbf\u95ee\u5176\u4ed6\u7f51\u7edc\u65f6\u4ea4\u7ed9\u7684\u4e0b\u4e00\u8df3\u8bbe\u5907\uff0c\u901a\u5e38\u662f\u8def\u7531\u5668\u63a5\u53e3\u5730\u5740\u3002</p> <p>\u5982\u679c\u76ee\u6807 IP \u548c\u672c\u673a\u4e0d\u5728\u540c\u4e00\u7f51\u6bb5\uff0c\u6570\u636e\u4f1a\u5148\u53d1\u7ed9\u9ed8\u8ba4\u7f51\u5173\u3002</p> <p>\u4e3b\u673a\u53d1\u9001\u6570\u636e\u65f6\u7684\u5224\u65ad\u6d41\u7a0b\uff1a</p> <ol> <li>\u4e3b\u673a\u5148\u7528\u81ea\u5df1\u7684 IP \u548c\u5b50\u7f51\u63a9\u7801\u7b97\u51fa\u672c\u673a\u7f51\u7edc\u5730\u5740\u3002</li> <li>\u518d\u7528\u76ee\u6807 IP \u548c\u5b50\u7f51\u63a9\u7801\u7b97\u51fa\u76ee\u6807\u7f51\u7edc\u5730\u5740\u3002</li> <li>\u5982\u679c\u4e24\u4e2a\u7f51\u7edc\u5730\u5740\u76f8\u540c\uff0c\u8bf4\u660e\u76ee\u6807\u5728\u540c\u4e00\u5c40\u57df\u7f51\uff0c\u76f4\u63a5\u901a\u8fc7 ARP \u67e5\u76ee\u6807 MAC\u3002</li> <li>\u5982\u679c\u4e24\u4e2a\u7f51\u7edc\u5730\u5740\u4e0d\u540c\uff0c\u8bf4\u660e\u76ee\u6807\u5728\u5176\u4ed6\u7f51\u7edc\uff0c\u5148\u901a\u8fc7 ARP \u67e5\u9ed8\u8ba4\u7f51\u5173\u7684 MAC\u3002</li> <li>\u6570\u636e\u5e27\u7684\u76ee\u6807 MAC \u662f\u4e0b\u4e00\u8df3\u8bbe\u5907\u7684 MAC\uff0c\u4f46 IP \u5305\u91cc\u7684\u76ee\u6807 IP \u4ecd\u7136\u662f\u6700\u7ec8\u76ee\u6807 IP\u3002</li> </ol> <p>\u4e5f\u5c31\u662f\u8bf4\uff0c\u8de8\u7f51\u6bb5\u901a\u4fe1\u65f6\uff0cMAC \u5730\u5740\u6bcf\u7ecf\u8fc7\u4e00\u8df3\u90fd\u4f1a\u6539\u53d8\uff0cIP \u5730\u5740\u901a\u5e38\u4fdd\u6301\u4e0d\u53d8\uff0c\u9664\u975e\u7ecf\u8fc7 NAT\u3002</p>"},{"location":"Web.html#6-arp","title":"6. ARP \u534f\u8bae","text":"<p>ARP \u7528\u4e8e\u6839\u636e IP \u5730\u5740\u67e5\u8be2\u5bf9\u5e94\u7684 MAC \u5730\u5740\u3002</p> <p>\u5de5\u4f5c\u8fc7\u7a0b\uff1a</p> <ol> <li>\u4e3b\u673a\u60f3\u53d1\u9001\u6570\u636e\u7ed9\u540c\u4e00\u5c40\u57df\u7f51\u5185\u7684\u67d0\u4e2a IP\u3002</li> <li>\u5982\u679c\u4e0d\u77e5\u9053\u76ee\u6807 MAC\uff0c\u5c31\u53d1\u9001 ARP \u5e7f\u64ad\u3002</li> <li>\u76ee\u6807\u4e3b\u673a\u6536\u5230\u540e\u56de\u590d\u81ea\u5df1\u7684 MAC \u5730\u5740\u3002</li> <li>\u53d1\u9001\u65b9\u628a IP \u4e0e MAC \u7684\u6620\u5c04\u4fdd\u5b58\u5230 ARP \u7f13\u5b58\u4e2d\u3002</li> </ol> <p>\u6ce8\u610f\uff1a</p> <ul> <li>ARP \u53ea\u5728\u5c40\u57df\u7f51\u5185\u5de5\u4f5c\u3002</li> <li>ARP \u6b3a\u9a97\u662f\u5e38\u89c1\u5185\u7f51\u653b\u51fb\u65b9\u5f0f\u3002</li> </ul> <p>ARP \u7f13\u5b58\u53ef\u4ee5\u51cf\u5c11\u91cd\u590d\u5e7f\u64ad\u3002Windows \u53ef\u7528 <code>arp -a</code> \u67e5\u770b ARP \u7f13\u5b58\u3002</p> <p>\u5e38\u89c1 ARP \u7c7b\u578b\uff1a</p> <ul> <li>\u666e\u901a ARP\uff1a\u6839\u636e\u76ee\u6807 IP \u67e5\u8be2\u76ee\u6807 MAC\u3002</li> <li>\u514d\u8d39 ARP\uff1a\u4e3b\u673a\u4e3b\u52a8\u5e7f\u64ad\u81ea\u5df1\u7684 IP \u548c MAC\uff0c\u7528\u4e8e\u68c0\u6d4b\u5730\u5740\u51b2\u7a81\u6216\u66f4\u65b0\u5176\u4ed6\u8bbe\u5907\u7f13\u5b58\u3002</li> <li>\u4ee3\u7406 ARP\uff1a\u8def\u7531\u5668\u4ee3\u66ff\u5176\u4ed6\u4e3b\u673a\u56de\u5e94 ARP \u8bf7\u6c42\uff0c\u5e38\u89c1\u4e8e\u7279\u6b8a\u7f51\u7edc\u573a\u666f\u3002</li> </ul>"},{"location":"Web.html#7-icmp","title":"7. ICMP \u534f\u8bae","text":"<p>ICMP \u7528\u4e8e\u7f51\u7edc\u63a7\u5236\u548c\u9519\u8bef\u62a5\u544a\u3002</p> <p>\u5e38\u89c1\u7528\u9014\uff1a</p> <ul> <li><code>ping</code>\uff1a\u6d4b\u8bd5\u4e3b\u673a\u662f\u5426\u53ef\u8fbe\u3002</li> <li><code>tracert</code> \u6216 <code>traceroute</code>\uff1a\u8ffd\u8e2a\u6570\u636e\u5305\u7ecf\u8fc7\u7684\u8def\u7531\u3002</li> </ul> <p><code>ping</code> \u901a\u5e38\u4f7f\u7528 ICMP Echo Request \u548c Echo Reply\u3002\u76ee\u6807\u4e0d\u54cd\u5e94 <code>ping</code> \u4e0d\u4e00\u5b9a\u8868\u793a\u76ee\u6807\u4e0d\u53ef\u8fbe\uff0c\u4e5f\u53ef\u80fd\u662f\u9632\u706b\u5899\u7981\u7528\u4e86 ICMP\u3002</p> <p><code>tracert</code> \u7684\u6838\u5fc3\u601d\u8def\u662f\u9010\u6b65\u589e\u52a0 TTL\uff1a</p> <ol> <li>\u7b2c\u4e00\u4e2a\u5305 TTL \u4e3a 1\uff0c\u5230\u7b2c\u4e00\u8df3\u8def\u7531\u5668\u540e TTL \u53d8\u4e3a 0\uff0c\u88ab\u4e22\u5f03\u3002</li> <li>\u7b2c\u4e00\u8df3\u8def\u7531\u5668\u8fd4\u56de ICMP \u8d85\u65f6\u6d88\u606f\u3002</li> <li>\u7b2c\u4e8c\u4e2a\u5305 TTL \u4e3a 2\uff0c\u53ef\u4ee5\u5230\u7b2c\u4e8c\u8df3\u3002</li> <li>\u4e0d\u65ad\u91cd\u590d\uff0c\u76f4\u5230\u5230\u8fbe\u76ee\u6807\u4e3b\u673a\u3002</li> </ol>"},{"location":"Web.html#8-nat","title":"8. NAT","text":"<p>NAT \u662f\u7f51\u7edc\u5730\u5740\u8f6c\u6362\uff0c\u5e38\u7528\u4e8e\u5bb6\u5ead\u6216\u4f01\u4e1a\u7f51\u7edc\u4e2d\u3002</p> <p>\u4f5c\u7528\uff1a</p> <ul> <li>\u8ba9\u591a\u4e2a\u5185\u7f51\u8bbe\u5907\u5171\u4eab\u4e00\u4e2a\u516c\u7f51 IP \u4e0a\u7f51\u3002</li> <li>\u9690\u85cf\u5185\u90e8\u7f51\u7edc\u7ed3\u6784\u3002</li> <li>\u7f13\u89e3 IPv4 \u5730\u5740\u4e0d\u8db3\u3002</li> </ul> <p>\u5e38\u89c1\u7c7b\u578b\uff1a</p> <ul> <li>\u9759\u6001 NAT\uff1a\u4e00\u4e2a\u5185\u7f51\u5730\u5740\u56fa\u5b9a\u6620\u5c04\u4e00\u4e2a\u516c\u7f51\u5730\u5740\u3002</li> <li>\u52a8\u6001 NAT\uff1a\u4ece\u516c\u7f51\u5730\u5740\u6c60\u4e2d\u52a8\u6001\u5206\u914d\u3002</li> <li>PAT\uff1a\u591a\u4e2a\u5185\u7f51\u5730\u5740\u901a\u8fc7\u4e0d\u540c\u7aef\u53e3\u590d\u7528\u540c\u4e00\u4e2a\u516c\u7f51\u5730\u5740\uff0c\u5bb6\u5ead\u8def\u7531\u5668\u5e38\u7528\u3002</li> </ul>"},{"location":"Web.html#9","title":"9. \u8def\u7531","text":"<p>\u8def\u7531\u662f\u4e3a\u6570\u636e\u5305\u9009\u62e9\u8f6c\u53d1\u8def\u5f84\u7684\u8fc7\u7a0b\u3002</p> <p>\u8def\u7531\u8868\u5e38\u89c1\u5b57\u6bb5\uff1a</p> <ul> <li>\u76ee\u6807\u7f51\u7edc</li> <li>\u5b50\u7f51\u63a9\u7801\u6216\u524d\u7f00\u957f\u5ea6</li> <li>\u4e0b\u4e00\u8df3\u5730\u5740</li> <li>\u51fa\u63a5\u53e3</li> <li>\u5ea6\u91cf\u503c</li> </ul> <p>\u5e38\u89c1\u8def\u7531\u7c7b\u578b\uff1a</p> <ul> <li>\u76f4\u8fde\u8def\u7531\uff1a\u8bbe\u5907\u63a5\u53e3\u76f4\u63a5\u8fde\u63a5\u7684\u7f51\u7edc\u3002</li> <li>\u9759\u6001\u8def\u7531\uff1a\u7ba1\u7406\u5458\u624b\u52a8\u914d\u7f6e\u3002</li> <li>\u52a8\u6001\u8def\u7531\uff1a\u8def\u7531\u5668\u901a\u8fc7\u534f\u8bae\u81ea\u52a8\u5b66\u4e60\uff0c\u5982 RIP\u3001OSPF\u3001BGP\u3002</li> </ul>"},{"location":"Web.html#_7","title":"\u516d\u3001\u4f20\u8f93\u5c42","text":"<p>\u4f20\u8f93\u5c42\u8d1f\u8d23\u8fdb\u7a0b\u5230\u8fdb\u7a0b\u4e4b\u95f4\u7684\u901a\u4fe1\u3002\u7f51\u7edc\u5c42\u53ea\u8d1f\u8d23\u4e3b\u673a\u5230\u4e3b\u673a\uff0c\u4f20\u8f93\u5c42\u901a\u8fc7\u7aef\u53e3\u53f7\u5b9a\u4f4d\u5177\u4f53\u5e94\u7528\u8fdb\u7a0b\u3002</p>"},{"location":"Web.html#1_2","title":"1. \u7aef\u53e3\u53f7","text":"<p>\u7aef\u53e3\u53f7\u8303\u56f4\uff1a<code>0 ~ 65535</code>\u3002</p> <p>\u5e38\u89c1\u7aef\u53e3\uff1a</p> \u7aef\u53e3 \u534f\u8bae \u4f5c\u7528 20/21 FTP \u6587\u4ef6\u4f20\u8f93 22 SSH \u8fdc\u7a0b\u767b\u5f55 25 SMTP \u90ae\u4ef6\u53d1\u9001 53 DNS \u57df\u540d\u89e3\u6790 80 HTTP Web \u670d\u52a1 110 POP3 \u90ae\u4ef6\u63a5\u6536 143 IMAP \u90ae\u4ef6\u63a5\u6536 443 HTTPS \u52a0\u5bc6 Web \u670d\u52a1 3306 MySQL \u6570\u636e\u5e93 6379 Redis \u7f13\u5b58\u6570\u636e\u5e93"},{"location":"Web.html#2-udp","title":"2. UDP","text":"<p>UDP \u662f\u65e0\u8fde\u63a5\u3001\u4e0d\u53ef\u9760\u3001\u9762\u5411\u62a5\u6587\u7684\u4f20\u8f93\u534f\u8bae\u3002</p> <p>\u7279\u70b9\uff1a</p> <ul> <li>\u4e0d\u5efa\u7acb\u8fde\u63a5\u3002</li> <li>\u4e0d\u4fdd\u8bc1\u53ef\u9760\u5230\u8fbe\u3002</li> <li>\u6ca1\u6709\u590d\u6742\u7684\u91cd\u4f20\u548c\u62e5\u585e\u63a7\u5236\u3002</li> <li>\u9996\u90e8\u5f00\u9500\u5c0f\uff0c\u901f\u5ea6\u5feb\u3002</li> </ul> <p>\u9002\u7528\u573a\u666f\uff1a</p> <ul> <li>DNS \u67e5\u8be2</li> <li>\u89c6\u9891\u76f4\u64ad</li> <li>\u5728\u7ebf\u8bed\u97f3</li> <li>\u6e38\u620f\u5b9e\u65f6\u901a\u4fe1</li> </ul>"},{"location":"Web.html#3-tcp","title":"3. TCP","text":"<p>TCP \u662f\u9762\u5411\u8fde\u63a5\u3001\u53ef\u9760\u3001\u9762\u5411\u5b57\u8282\u6d41\u7684\u4f20\u8f93\u534f\u8bae\u3002</p> <p>\u7279\u70b9\uff1a</p> <ul> <li>\u5efa\u7acb\u8fde\u63a5\u540e\u518d\u4f20\u8f93\u6570\u636e\u3002</li> <li>\u4fdd\u8bc1\u6570\u636e\u53ef\u9760\u3001\u6709\u5e8f\u5230\u8fbe\u3002</li> <li>\u652f\u6301\u786e\u8ba4\u3001\u91cd\u4f20\u3001\u6d41\u91cf\u63a7\u5236\u3001\u62e5\u585e\u63a7\u5236\u3002</li> <li>\u5f00\u9500\u6bd4 UDP \u5927\u3002</li> </ul> <p>\u9002\u7528\u573a\u666f\uff1a</p> <ul> <li>\u7f51\u9875\u6d4f\u89c8</li> <li>\u6587\u4ef6\u4f20\u8f93</li> <li>\u90ae\u4ef6\u4f20\u8f93</li> <li>\u6570\u636e\u5e93\u8fde\u63a5</li> </ul>"},{"location":"Web.html#4-tcp","title":"4. TCP \u4e09\u6b21\u63e1\u624b","text":"<p>\u4e09\u6b21\u63e1\u624b\u7528\u4e8e\u5efa\u7acb\u8fde\u63a5\uff1a</p> <pre><code>\u5ba2\u6237\u7aef -&gt; \u670d\u52a1\u7aef\uff1aSYN\n\u670d\u52a1\u7aef -&gt; \u5ba2\u6237\u7aef\uff1aSYN + ACK\n\u5ba2\u6237\u7aef -&gt; \u670d\u52a1\u7aef\uff1aACK\n</code></pre> <p>\u4e09\u6b21\u63e1\u624b\u7684\u76ee\u7684\uff1a</p> <ul> <li>\u786e\u8ba4\u53cc\u65b9\u53d1\u9001\u548c\u63a5\u6536\u80fd\u529b\u6b63\u5e38\u3002</li> <li>\u540c\u6b65\u521d\u59cb\u5e8f\u5217\u53f7\u3002</li> <li>\u5efa\u7acb\u53ef\u9760\u8fde\u63a5\u7684\u72b6\u6001\u3002</li> </ul>"},{"location":"Web.html#5-tcp","title":"5. TCP \u56db\u6b21\u6325\u624b","text":"<p>\u56db\u6b21\u6325\u624b\u7528\u4e8e\u91ca\u653e\u8fde\u63a5\uff1a</p> <pre><code>\u4e3b\u52a8\u5173\u95ed\u65b9 -&gt; \u88ab\u52a8\u5173\u95ed\u65b9\uff1aFIN\n\u88ab\u52a8\u5173\u95ed\u65b9 -&gt; \u4e3b\u52a8\u5173\u95ed\u65b9\uff1aACK\n\u88ab\u52a8\u5173\u95ed\u65b9 -&gt; \u4e3b\u52a8\u5173\u95ed\u65b9\uff1aFIN\n\u4e3b\u52a8\u5173\u95ed\u65b9 -&gt; \u88ab\u52a8\u5173\u95ed\u65b9\uff1aACK\n</code></pre> <p>\u4e3a\u4ec0\u4e48\u901a\u5e38\u662f\u56db\u6b21\uff1a</p> <p>TCP \u662f\u5168\u53cc\u5de5\u901a\u4fe1\uff0c\u53cc\u65b9\u7684\u53d1\u9001\u901a\u9053\u9700\u8981\u5206\u522b\u5173\u95ed\u3002\u4e00\u65b9\u8bf4\u201c\u6211\u53d1\u5b8c\u4e86\u201d\uff0c\u53e6\u4e00\u65b9\u53ef\u80fd\u8fd8\u6709\u6570\u636e\u8981\u53d1\u9001\uff0c\u6240\u4ee5 FIN \u548c ACK \u5f80\u5f80\u5206\u5f00\u53d1\u9001\u3002</p>"},{"location":"Web.html#6-tcp","title":"6. TCP \u53ef\u9760\u4f20\u8f93\u673a\u5236","text":"<p>TCP \u53ef\u9760\u6027\u4e3b\u8981\u4f9d\u9760\uff1a</p> <ul> <li>\u5e8f\u5217\u53f7\uff1a\u7ed9\u5b57\u8282\u6d41\u7f16\u53f7\uff0c\u4fdd\u8bc1\u987a\u5e8f\u3002</li> <li>\u786e\u8ba4\u5e94\u7b54\uff1a\u63a5\u6536\u65b9\u6536\u5230\u6570\u636e\u540e\u8fd4\u56de ACK\u3002</li> <li>\u8d85\u65f6\u91cd\u4f20\uff1a\u53d1\u9001\u540e\u957f\u65f6\u95f4\u672a\u6536\u5230 ACK \u5c31\u91cd\u4f20\u3002</li> <li>\u5feb\u901f\u91cd\u4f20\uff1a\u6536\u5230\u591a\u4e2a\u91cd\u590d ACK \u65f6\u63d0\u524d\u91cd\u4f20\u3002</li> <li>\u6821\u9a8c\u548c\uff1a\u68c0\u6d4b\u6570\u636e\u662f\u5426\u51fa\u9519\u3002</li> </ul>"},{"location":"Web.html#7","title":"7. \u6d41\u91cf\u63a7\u5236","text":"<p>\u6d41\u91cf\u63a7\u5236\u7528\u4e8e\u907f\u514d\u53d1\u9001\u65b9\u53d1\u9001\u592a\u5feb\uff0c\u5bfc\u81f4\u63a5\u6536\u65b9\u7f13\u51b2\u533a\u6ea2\u51fa\u3002</p> <p>TCP \u4f7f\u7528\u6ed1\u52a8\u7a97\u53e3\u673a\u5236\uff1a</p> <ul> <li>\u63a5\u6536\u65b9\u901a\u8fc7\u7a97\u53e3\u5927\u5c0f\u544a\u8bc9\u53d1\u9001\u65b9\u81ea\u5df1\u8fd8\u80fd\u63a5\u6536\u591a\u5c11\u6570\u636e\u3002</li> <li>\u53d1\u9001\u65b9\u6839\u636e\u7a97\u53e3\u5927\u5c0f\u63a7\u5236\u53d1\u9001\u901f\u7387\u3002</li> </ul>"},{"location":"Web.html#8","title":"8. \u62e5\u585e\u63a7\u5236","text":"<p>\u62e5\u585e\u63a7\u5236\u7528\u4e8e\u907f\u514d\u7f51\u7edc\u4e2d\u6570\u636e\u8fc7\u591a\u5bfc\u81f4\u4e25\u91cd\u4e22\u5305\u548c\u5ef6\u8fdf\u3002</p> <p>\u5e38\u89c1\u7b97\u6cd5\u9636\u6bb5\uff1a</p> <ul> <li>\u6162\u542f\u52a8\uff1a\u62e5\u585e\u7a97\u53e3\u4ece\u5c0f\u5f00\u59cb\u6307\u6570\u589e\u957f\u3002</li> <li>\u62e5\u585e\u907f\u514d\uff1a\u7a97\u53e3\u589e\u957f\u53d8\u6162\uff0c\u7ebf\u6027\u589e\u957f\u3002</li> <li>\u5feb\u901f\u91cd\u4f20\uff1a\u53d1\u73b0\u4e22\u5305\u540e\u5c3d\u5feb\u91cd\u4f20\u3002</li> <li>\u5feb\u901f\u6062\u590d\uff1a\u964d\u4f4e\u7a97\u53e3\u540e\u7ee7\u7eed\u4f20\u8f93\u3002</li> </ul>"},{"location":"Web.html#_8","title":"\u4e03\u3001\u5e94\u7528\u5c42\u534f\u8bae","text":""},{"location":"Web.html#1-dns","title":"1. DNS","text":"<p>DNS \u7528\u4e8e\u628a\u57df\u540d\u89e3\u6790\u4e3a IP \u5730\u5740\u3002</p> <p>DNS \u7684\u5168\u79f0\u662f Domain Name System\uff0c\u4e2d\u6587\u5e38\u79f0\u4e3a\u57df\u540d\u7cfb\u7edf\u3002\u4eba\u66f4\u5bb9\u6613\u8bb0\u4f4f\u57df\u540d\uff0c\u4f8b\u5982 <code>www.example.com</code>\uff1b\u8ba1\u7b97\u673a\u901a\u4fe1\u6700\u7ec8\u9700\u8981 IP \u5730\u5740\uff0c\u6240\u4ee5\u8bbf\u95ee\u7f51\u7ad9\u524d\u901a\u5e38\u8981\u5148\u505a DNS \u89e3\u6790\u3002</p> <p>DNS \u7684\u6838\u5fc3\u4f5c\u7528\uff1a</p> <ul> <li>\u57df\u540d\u89e3\u6790\uff1a\u628a\u57df\u540d\u8f6c\u6362\u4e3a IP \u5730\u5740\u3002</li> <li>\u670d\u52a1\u53d1\u73b0\uff1a\u901a\u8fc7 MX\u3001SRV \u7b49\u8bb0\u5f55\u627e\u5230\u5bf9\u5e94\u670d\u52a1\u3002</li> <li>\u8d1f\u8f7d\u5747\u8861\uff1a\u540c\u4e00\u4e2a\u57df\u540d\u53ef\u4ee5\u8fd4\u56de\u591a\u4e2a IP\u3002</li> <li>\u5bb9\u707e\u5207\u6362\uff1a\u901a\u8fc7\u8c03\u6574\u89e3\u6790\u7ed3\u679c\uff0c\u628a\u6d41\u91cf\u5207\u5230\u5176\u4ed6\u670d\u52a1\u5668\u3002</li> </ul>"},{"location":"Web.html#dns","title":"DNS \u5c42\u7ea7\u7ed3\u6784","text":"<p>DNS \u662f\u5206\u5c42\u7684\u6811\u72b6\u7ed3\u6784\uff1a</p> <pre><code>\u6839\u57df .\n  -&gt; \u9876\u7ea7\u57df .com / .cn / .org\n    -&gt; \u4e8c\u7ea7\u57df example.com\n      -&gt; \u4e3b\u673a\u540d www.example.com\n</code></pre> <p>\u5e38\u89c1 DNS \u670d\u52a1\u5668\u7c7b\u578b\uff1a</p> \u7c7b\u578b \u4f5c\u7528 \u6839\u57df\u540d\u670d\u52a1\u5668 \u544a\u8bc9\u67e5\u8be2\u8005\u9876\u7ea7\u57df\u540d\u670d\u52a1\u5668\u5728\u54ea\u91cc \u9876\u7ea7\u57df\u540d\u670d\u52a1\u5668 \u7ba1\u7406 <code>.com</code>\u3001<code>.cn</code> \u7b49\u9876\u7ea7\u57df \u6743\u5a01\u57df\u540d\u670d\u52a1\u5668 \u4fdd\u5b58\u67d0\u4e2a\u57df\u540d\u7684\u771f\u5b9e DNS \u8bb0\u5f55 \u672c\u5730\u9012\u5f52 DNS \u670d\u52a1\u5668 \u4ee3\u66ff\u5ba2\u6237\u7aef\u5b8c\u6210\u5b8c\u6574\u67e5\u8be2\uff0c\u5e38\u7531\u8fd0\u8425\u5546\u3001\u516c\u53f8\u6216\u516c\u5171 DNS \u63d0\u4f9b"},{"location":"Web.html#dns_1","title":"DNS \u89e3\u6790\u8fc7\u7a0b","text":"<p>\u4ee5\u89e3\u6790 <code>www.example.com</code> \u4e3a\u4f8b\uff1a</p> <ol> <li>\u6d4f\u89c8\u5668\u68c0\u67e5\u81ea\u8eab\u7f13\u5b58\u3002</li> <li>\u64cd\u4f5c\u7cfb\u7edf\u68c0\u67e5 DNS \u7f13\u5b58\u3002</li> <li>\u68c0\u67e5\u672c\u5730 <code>hosts</code> \u6587\u4ef6\u3002</li> <li>\u5982\u679c\u672c\u5730\u6ca1\u6709\u7ed3\u679c\uff0c\u5c31\u67e5\u8be2\u672c\u5730\u9012\u5f52 DNS \u670d\u52a1\u5668\u3002</li> <li>\u672c\u5730\u9012\u5f52 DNS \u670d\u52a1\u5668\u5411\u6839\u57df\u540d\u670d\u52a1\u5668\u67e5\u8be2 <code>.com</code> \u7684\u670d\u52a1\u5668\u5730\u5740\u3002</li> <li>\u518d\u5411 <code>.com</code> \u9876\u7ea7\u57df\u540d\u670d\u52a1\u5668\u67e5\u8be2 <code>example.com</code> \u7684\u6743\u5a01\u670d\u52a1\u5668\u5730\u5740\u3002</li> <li>\u518d\u5411 <code>example.com</code> \u7684\u6743\u5a01\u57df\u540d\u670d\u52a1\u5668\u67e5\u8be2 <code>www.example.com</code> \u7684\u8bb0\u5f55\u3002</li> <li>\u6743\u5a01\u670d\u52a1\u5668\u8fd4\u56de IP \u5730\u5740\u3002</li> <li>\u672c\u5730\u9012\u5f52 DNS \u7f13\u5b58\u7ed3\u679c\uff0c\u5e76\u8fd4\u56de\u7ed9\u5ba2\u6237\u7aef\u3002</li> <li>\u6d4f\u89c8\u5668\u62ff\u5230 IP \u540e\u518d\u5efa\u7acb TCP \u6216 QUIC \u8fde\u63a5\u3002</li> </ol>"},{"location":"Web.html#_9","title":"\u9012\u5f52\u67e5\u8be2\u548c\u8fed\u4ee3\u67e5\u8be2","text":"<ul> <li>\u9012\u5f52\u67e5\u8be2\uff1a\u5ba2\u6237\u7aef\u628a\u95ee\u9898\u4ea4\u7ed9\u672c\u5730 DNS\uff0c\u672c\u5730 DNS \u8d1f\u8d23\u67e5\u5230\u5e95\uff0c\u5e76\u8fd4\u56de\u6700\u7ec8\u7ed3\u679c\u3002</li> <li>\u8fed\u4ee3\u67e5\u8be2\uff1aDNS \u670d\u52a1\u5668\u4e0d\u76f4\u63a5\u7ed9\u6700\u7ec8\u7b54\u6848\uff0c\u800c\u662f\u544a\u8bc9\u67e5\u8be2\u8005\u4e0b\u4e00\u6b65\u5e94\u8be5\u95ee\u8c01\u3002</li> </ul> <p>\u666e\u901a\u7528\u6237\u8bbe\u5907\u4e00\u822c\u5411\u672c\u5730 DNS \u53d1\u8d77\u9012\u5f52\u67e5\u8be2\uff1b\u672c\u5730 DNS \u518d\u5411\u6839\u3001\u9876\u7ea7\u57df\u3001\u6743\u5a01 DNS \u53d1\u8d77\u8fed\u4ee3\u67e5\u8be2\u3002</p>"},{"location":"Web.html#dns-ttl","title":"DNS \u7f13\u5b58\u548c TTL","text":"<p>DNS \u7ed3\u679c\u901a\u5e38\u4f1a\u88ab\u7f13\u5b58\uff0c\u7f13\u5b58\u4f4d\u7f6e\u5305\u62ec\uff1a</p> <ul> <li>\u6d4f\u89c8\u5668\u7f13\u5b58</li> <li>\u64cd\u4f5c\u7cfb\u7edf\u7f13\u5b58</li> <li>\u672c\u5730\u9012\u5f52 DNS \u7f13\u5b58</li> <li>\u8def\u7531\u5668\u6216\u7f51\u5173\u7f13\u5b58</li> <li>\u5e94\u7528\u7a0b\u5e8f\u81ea\u5df1\u7684\u7f13\u5b58</li> </ul> <p>TTL \u8868\u793a DNS \u8bb0\u5f55\u53ef\u4ee5\u7f13\u5b58\u591a\u4e45\uff0c\u5355\u4f4d\u662f\u79d2\u3002</p> <p>\u4f8b\u5982\uff1a</p> <pre><code>www.example.com.  300  IN  A  93.184.216.34\n</code></pre> <p>\u8fd9\u91cc <code>300</code> \u8868\u793a\u8be5\u8bb0\u5f55\u53ef\u4ee5\u7f13\u5b58 300 \u79d2\u3002</p> <p>TTL \u7684\u5f71\u54cd\uff1a</p> <ul> <li>TTL \u8f83\u5927\uff1a\u7f13\u5b58\u65f6\u95f4\u957f\uff0c\u89e3\u6790\u538b\u529b\u5c0f\uff0c\u4f46\u53d8\u66f4\u751f\u6548\u6162\u3002</li> <li>TTL \u8f83\u5c0f\uff1a\u53d8\u66f4\u751f\u6548\u5feb\uff0c\u4f46 DNS \u67e5\u8be2\u6b21\u6570\u66f4\u591a\u3002</li> </ul> <p>\u5e38\u89c1 DNS \u8bb0\u5f55\uff1a</p> \u8bb0\u5f55\u7c7b\u578b \u4f5c\u7528 A \u57df\u540d\u5230 IPv4 \u5730\u5740 AAAA \u57df\u540d\u5230 IPv6 \u5730\u5740 CNAME \u57df\u540d\u522b\u540d MX \u90ae\u4ef6\u670d\u52a1\u5668 NS \u57df\u540d\u670d\u52a1\u5668 TXT \u6587\u672c\u8bb0\u5f55\uff0c\u5e38\u7528\u4e8e\u9a8c\u8bc1 SOA \u6743\u5a01\u533a\u57df\u7684\u8d77\u59cb\u6388\u6743\u8bb0\u5f55 PTR \u53cd\u5411\u89e3\u6790\uff0c\u628a IP \u89e3\u6790\u4e3a\u57df\u540d SRV \u6307\u5b9a\u67d0\u4e2a\u670d\u52a1\u7684\u4f4d\u7f6e\u548c\u7aef\u53e3 CAA \u6307\u5b9a\u54ea\u4e9b CA \u53ef\u4ee5\u4e3a\u57df\u540d\u7b7e\u53d1\u8bc1\u4e66 <p>\u8bb0\u5f55\u793a\u4f8b\uff1a</p> <pre><code>example.com.        A      93.184.216.34\nwww.example.com.    CNAME  example.com.\nexample.com.        MX     10 mail.example.com.\n</code></pre> <p>\u6ce8\u610f\u70b9\uff1a</p> <ul> <li><code>A</code> \u548c <code>AAAA</code> \u8fd4\u56de\u7684\u662f IP \u5730\u5740\u3002</li> <li><code>CNAME</code> \u8fd4\u56de\u7684\u662f\u53e6\u4e00\u4e2a\u57df\u540d\uff0c\u5ba2\u6237\u7aef\u8fd8\u9700\u8981\u7ee7\u7eed\u89e3\u6790\u3002</li> <li>\u4e00\u4e2a\u57df\u540d\u53ef\u4ee5\u6709\u591a\u4e2a <code>A</code> \u8bb0\u5f55\uff0c\u7528\u4e8e\u7b80\u5355\u8d1f\u8f7d\u5747\u8861\u3002</li> <li>\u90ae\u4ef6\u670d\u52a1\u901a\u5e38\u4f9d\u8d56 <code>MX</code> \u8bb0\u5f55\u3002</li> <li>\u53cd\u5411 DNS \u4f7f\u7528 <code>PTR</code> \u8bb0\u5f55\u3002</li> </ul>"},{"location":"Web.html#dns_2","title":"DNS \u4f7f\u7528\u7684\u4f20\u8f93\u534f\u8bae","text":"<p>DNS \u9ed8\u8ba4\u4f7f\u7528 UDP 53 \u7aef\u53e3\uff0c\u56e0\u4e3a UDP \u5f00\u9500\u5c0f\u3001\u901f\u5ea6\u5feb\u3002</p> <p>\u5728\u4ee5\u4e0b\u573a\u666f\u4e2d\u53ef\u80fd\u4f7f\u7528 TCP 53 \u7aef\u53e3\uff1a</p> <ul> <li>\u54cd\u5e94\u6570\u636e\u592a\u5927\uff0cUDP \u653e\u4e0d\u4e0b\u3002</li> <li>\u8fdb\u884c\u533a\u57df\u4f20\u9001\u3002</li> <li>\u5ba2\u6237\u7aef\u6216\u670d\u52a1\u5668\u8981\u6c42\u4f7f\u7528 TCP\u3002</li> </ul> <p>\u73b0\u4ee3\u573a\u666f\u8fd8\u53ef\u80fd\u4f7f\u7528\uff1a</p> <ul> <li>DoT\uff1aDNS over TLS\uff0c\u901a\u5e38\u4f7f\u7528 853 \u7aef\u53e3\u3002</li> <li>DoH\uff1aDNS over HTTPS\uff0c\u4f7f\u7528 HTTPS \u52a0\u5bc6 DNS \u67e5\u8be2\u3002</li> </ul>"},{"location":"Web.html#dns_3","title":"\u5e38\u89c1 DNS \u95ee\u9898","text":"\u95ee\u9898 \u53ef\u80fd\u539f\u56e0 \u80fd ping IP\uff0c\u4e0d\u80fd\u8bbf\u95ee\u57df\u540d DNS \u914d\u7f6e\u9519\u8bef\u6216 DNS \u670d\u52a1\u5f02\u5e38 \u57df\u540d\u89e3\u6790\u5230\u65e7 IP DNS \u7f13\u5b58\u672a\u8fc7\u671f NXDOMAIN \u57df\u540d\u4e0d\u5b58\u5728 SERVFAIL DNS \u670d\u52a1\u5668\u67e5\u8be2\u5931\u8d25 \u89e3\u6790\u7ed3\u679c\u4e0d\u7a33\u5b9a \u8d1f\u8f7d\u5747\u8861\u3001CDN \u6216\u4e0d\u540c\u5730\u533a\u7ebf\u8def\u5bfc\u81f4 <p>\u5e38\u7528\u6392\u67e5\u547d\u4ee4\uff1a</p> <pre><code>nslookup www.example.com\nipconfig /flushdns\n</code></pre> <pre><code>dig www.example.com\ndig www.example.com A\ndig www.example.com CNAME\ndig +trace www.example.com\n</code></pre>"},{"location":"Web.html#2-http","title":"2. HTTP","text":"<p>HTTP \u662f\u8d85\u6587\u672c\u4f20\u8f93\u534f\u8bae\uff0c\u4e3b\u8981\u7528\u4e8e\u6d4f\u89c8\u5668\u548c\u670d\u52a1\u5668\u4e4b\u95f4\u901a\u4fe1\u3002</p> <p>\u7279\u70b9\uff1a</p> <ul> <li>\u57fa\u4e8e\u8bf7\u6c42-\u54cd\u5e94\u6a21\u578b\u3002</li> <li>\u9ed8\u8ba4\u4f7f\u7528 TCP\u3002</li> <li>HTTP \u672c\u8eab\u662f\u65e0\u72b6\u6001\u534f\u8bae\u3002</li> <li>\u660e\u6587\u4f20\u8f93\uff0c\u5185\u5bb9\u53ef\u80fd\u88ab\u7a83\u542c\u6216\u7be1\u6539\u3002</li> <li>\u7075\u6d3b\uff0c\u53ef\u4f20\u8f93 HTML\u3001JSON\u3001\u56fe\u7247\u3001\u89c6\u9891\u7b49\u591a\u79cd\u8d44\u6e90\u3002</li> </ul>"},{"location":"Web.html#url","title":"URL \u7ed3\u6784","text":"<p>URL \u7528\u4e8e\u5b9a\u4f4d\u7f51\u7edc\u8d44\u6e90\u3002</p> <pre><code>https://www.example.com:443/path/index.html?keyword=network&amp;page=1#title\n</code></pre> <p>\u7ec4\u6210\u90e8\u5206\uff1a</p> \u90e8\u5206 \u793a\u4f8b \u542b\u4e49 \u534f\u8bae <code>https</code> \u4f7f\u7528\u7684\u5e94\u7528\u5c42\u534f\u8bae \u4e3b\u673a\u540d <code>www.example.com</code> \u670d\u52a1\u5668\u57df\u540d \u7aef\u53e3 <code>443</code> \u670d\u52a1\u76d1\u542c\u7aef\u53e3 \u8def\u5f84 <code>/path/index.html</code> \u8d44\u6e90\u5728\u670d\u52a1\u5668\u4e0a\u7684\u4f4d\u7f6e \u67e5\u8be2\u5b57\u7b26\u4e32 <code>keyword=network&amp;page=1</code> \u4f20\u9012\u7ed9\u670d\u52a1\u5668\u7684\u53c2\u6570 \u7247\u6bb5\u6807\u8bc6 <code>#title</code> \u9875\u9762\u5185\u90e8\u5b9a\u4f4d\uff0c\u4e0d\u4f1a\u53d1\u9001\u7ed9\u670d\u52a1\u5668"},{"location":"Web.html#http","title":"HTTP \u8bf7\u6c42\u62a5\u6587","text":"<p>HTTP \u8bf7\u6c42\u7531\u8bf7\u6c42\u884c\u3001\u8bf7\u6c42\u5934\u3001\u7a7a\u884c\u548c\u8bf7\u6c42\u4f53\u7ec4\u6210\u3002</p> <pre><code>GET /index.html HTTP/1.1\nHost: www.example.com\nUser-Agent: Mozilla/5.0\nAccept: text/html\n\n</code></pre> <p>\u8bf7\u6c42\u884c\u5305\u542b\uff1a</p> <ul> <li>\u8bf7\u6c42\u65b9\u6cd5\uff1a\u5982 <code>GET</code>\u3001<code>POST</code>\u3002</li> <li>\u8bf7\u6c42\u8def\u5f84\uff1a\u5982 <code>/index.html</code>\u3002</li> <li>HTTP \u7248\u672c\uff1a\u5982 <code>HTTP/1.1</code>\u3002</li> </ul> <p>\u5982\u679c\u662f\u63d0\u4ea4 JSON \u6570\u636e\uff0c\u8bf7\u6c42\u53ef\u80fd\u662f\uff1a</p> <pre><code>POST /api/users HTTP/1.1\nHost: www.example.com\nContent-Type: application/json\nContent-Length: 37\n\n{\"name\":\"Alice\",\"age\":18}\n</code></pre>"},{"location":"Web.html#http_1","title":"HTTP \u54cd\u5e94\u62a5\u6587","text":"<p>HTTP \u54cd\u5e94\u7531\u72b6\u6001\u884c\u3001\u54cd\u5e94\u5934\u3001\u7a7a\u884c\u548c\u54cd\u5e94\u4f53\u7ec4\u6210\u3002</p> <pre><code>HTTP/1.1 200 OK\nContent-Type: text/html; charset=utf-8\nContent-Length: 1256\nCache-Control: max-age=3600\n\n&lt;html&gt;...&lt;/html&gt;\n</code></pre> <p>\u72b6\u6001\u884c\u5305\u542b\uff1a</p> <ul> <li>HTTP \u7248\u672c</li> <li>\u72b6\u6001\u7801</li> <li>\u539f\u56e0\u77ed\u8bed</li> </ul> <p>\u5e38\u89c1\u8bf7\u6c42\u65b9\u6cd5\uff1a</p> \u65b9\u6cd5 \u4f5c\u7528 GET \u83b7\u53d6\u8d44\u6e90 POST \u63d0\u4ea4\u6570\u636e\u6216\u521b\u5efa\u8d44\u6e90 PUT \u6574\u4f53\u66f4\u65b0\u8d44\u6e90 PATCH \u90e8\u5206\u66f4\u65b0\u8d44\u6e90 DELETE \u5220\u9664\u8d44\u6e90 HEAD \u53ea\u83b7\u53d6\u54cd\u5e94\u5934 OPTIONS \u67e5\u8be2\u670d\u52a1\u5668\u652f\u6301\u7684\u65b9\u6cd5 <p>\u65b9\u6cd5\u7279\u6027\uff1a</p> \u65b9\u6cd5 \u662f\u5426\u5b89\u5168 \u662f\u5426\u5e42\u7b49 \u8bf4\u660e GET \u662f \u662f \u53ea\u83b7\u53d6\u8d44\u6e90\uff0c\u4e0d\u5e94\u4fee\u6539\u670d\u52a1\u5668\u72b6\u6001 HEAD \u662f \u662f \u7c7b\u4f3c GET\uff0c\u4f46\u53ea\u8fd4\u56de\u54cd\u5e94\u5934 POST \u5426 \u5426 \u5e38\u7528\u4e8e\u63d0\u4ea4\u8868\u5355\u3001\u521b\u5efa\u8ba2\u5355 PUT \u5426 \u662f \u591a\u6b21\u6574\u4f53\u66ff\u6362\u540c\u4e00\u8d44\u6e90\uff0c\u7ed3\u679c\u5e94\u4e00\u81f4 PATCH \u5426 \u4e0d\u4e00\u5b9a \u90e8\u5206\u66f4\u65b0\u8d44\u6e90 DELETE \u5426 \u662f \u591a\u6b21\u5220\u9664\u540c\u4e00\u8d44\u6e90\uff0c\u7ed3\u679c\u901a\u5e38\u4e00\u81f4 <p>\u5b89\u5168\u65b9\u6cd5\u6307\u8bed\u4e49\u4e0a\u4e0d\u5e94\u4fee\u6539\u670d\u52a1\u5668\u72b6\u6001\uff1b\u5e42\u7b49\u6307\u540c\u4e00\u4e2a\u8bf7\u6c42\u6267\u884c\u4e00\u6b21\u548c\u6267\u884c\u591a\u6b21\uff0c\u5bf9\u8d44\u6e90\u72b6\u6001\u7684\u5f71\u54cd\u5e94\u8be5\u76f8\u540c\u3002</p> <p>\u5e38\u89c1\u72b6\u6001\u7801\uff1a</p> \u72b6\u6001\u7801 \u542b\u4e49 200 \u8bf7\u6c42\u6210\u529f 201 \u521b\u5efa\u6210\u529f 301 \u6c38\u4e45\u91cd\u5b9a\u5411 302 \u4e34\u65f6\u91cd\u5b9a\u5411 304 \u4f7f\u7528\u7f13\u5b58 400 \u8bf7\u6c42\u9519\u8bef 401 \u672a\u8ba4\u8bc1 403 \u65e0\u6743\u9650 404 \u8d44\u6e90\u4e0d\u5b58\u5728 500 \u670d\u52a1\u5668\u5185\u90e8\u9519\u8bef 502 \u7f51\u5173\u9519\u8bef 503 \u670d\u52a1\u4e0d\u53ef\u7528 <p>\u72b6\u6001\u7801\u5206\u7c7b\uff1a</p> \u8303\u56f4 \u7c7b\u578b \u542b\u4e49 1xx \u4fe1\u606f\u54cd\u5e94 \u8bf7\u6c42\u5df2\u6536\u5230\uff0c\u7ee7\u7eed\u5904\u7406 2xx \u6210\u529f \u8bf7\u6c42\u6210\u529f\u5904\u7406 3xx \u91cd\u5b9a\u5411 \u9700\u8981\u8fdb\u4e00\u6b65\u64cd\u4f5c 4xx \u5ba2\u6237\u7aef\u9519\u8bef \u8bf7\u6c42\u6709\u95ee\u9898 5xx \u670d\u52a1\u7aef\u9519\u8bef \u670d\u52a1\u5668\u5904\u7406\u5931\u8d25 <p>\u66f4\u591a\u5e38\u89c1\u72b6\u6001\u7801\uff1a</p> \u72b6\u6001\u7801 \u542b\u4e49 \u5e38\u89c1\u573a\u666f 204 \u65e0\u54cd\u5e94\u4f53 \u5220\u9664\u6210\u529f\u4f46\u4e0d\u8fd4\u56de\u5185\u5bb9 206 \u90e8\u5206\u5185\u5bb9 \u5206\u7247\u4e0b\u8f7d\u3001\u89c6\u9891\u62d6\u52a8 307 \u4e34\u65f6\u91cd\u5b9a\u5411 \u4fdd\u6301\u539f\u8bf7\u6c42\u65b9\u6cd5\u91cd\u5b9a\u5411 308 \u6c38\u4e45\u91cd\u5b9a\u5411 \u4fdd\u6301\u539f\u8bf7\u6c42\u65b9\u6cd5\u6c38\u4e45\u91cd\u5b9a\u5411 405 \u65b9\u6cd5\u4e0d\u5141\u8bb8 \u7528 POST \u8bbf\u95ee\u53ea\u652f\u6301 GET \u7684\u63a5\u53e3 408 \u8bf7\u6c42\u8d85\u65f6 \u5ba2\u6237\u7aef\u53d1\u9001\u8bf7\u6c42\u592a\u6162 409 \u51b2\u7a81 \u8d44\u6e90\u72b6\u6001\u51b2\u7a81 413 \u8bf7\u6c42\u4f53\u592a\u5927 \u4e0a\u4f20\u6587\u4ef6\u8d85\u8fc7\u9650\u5236 429 \u8bf7\u6c42\u8fc7\u591a \u88ab\u9650\u6d41 504 \u7f51\u5173\u8d85\u65f6 \u4ee3\u7406\u670d\u52a1\u5668\u7b49\u4e0d\u5230\u4e0a\u6e38\u54cd\u5e94"},{"location":"Web.html#_10","title":"\u5e38\u89c1\u8bf7\u6c42\u5934","text":"\u8bf7\u6c42\u5934 \u4f5c\u7528 Host \u6307\u5b9a\u8bbf\u95ee\u7684\u4e3b\u673a\u540d\uff0cHTTP/1.1 \u5fc5\u9700 User-Agent \u5ba2\u6237\u7aef\u4fe1\u606f\uff0c\u5982\u6d4f\u89c8\u5668\u548c\u7cfb\u7edf Accept \u5ba2\u6237\u7aef\u5e0c\u671b\u63a5\u6536\u7684\u6570\u636e\u7c7b\u578b Accept-Encoding \u5ba2\u6237\u7aef\u652f\u6301\u7684\u538b\u7f29\u65b9\u5f0f\uff0c\u5982 gzip\u3001br Content-Type \u8bf7\u6c42\u4f53\u7684\u6570\u636e\u7c7b\u578b Content-Length \u8bf7\u6c42\u4f53\u957f\u5ea6 Authorization \u8eab\u4efd\u8ba4\u8bc1\u4fe1\u606f Cookie \u643a\u5e26\u6d4f\u89c8\u5668\u4fdd\u5b58\u7684 Cookie Referer \u8bf7\u6c42\u6765\u6e90\u9875\u9762 Origin \u8de8\u57df\u8bf7\u6c42\u6765\u6e90 Cache-Control \u63a7\u5236\u7f13\u5b58\u7b56\u7565"},{"location":"Web.html#_11","title":"\u5e38\u89c1\u54cd\u5e94\u5934","text":"\u54cd\u5e94\u5934 \u4f5c\u7528 Content-Type \u54cd\u5e94\u4f53\u7684\u6570\u636e\u7c7b\u578b Content-Length \u54cd\u5e94\u4f53\u957f\u5ea6 Content-Encoding \u54cd\u5e94\u4f53\u538b\u7f29\u65b9\u5f0f Set-Cookie \u8ba9\u6d4f\u89c8\u5668\u4fdd\u5b58 Cookie Location \u91cd\u5b9a\u5411\u76ee\u6807\u5730\u5740 Cache-Control \u7f13\u5b58\u63a7\u5236 ETag \u8d44\u6e90\u7248\u672c\u6807\u8bc6 Last-Modified \u8d44\u6e90\u6700\u540e\u4fee\u6539\u65f6\u95f4 Access-Control-Allow-Origin CORS \u8de8\u57df\u8bbf\u95ee\u63a7\u5236 Server \u670d\u52a1\u5668\u8f6f\u4ef6\u4fe1\u606f"},{"location":"Web.html#http-cookie","title":"HTTP \u65e0\u72b6\u6001\u4e0e Cookie","text":"<p>HTTP \u672c\u8eab\u65e0\u72b6\u6001\uff0c\u670d\u52a1\u5668\u9ed8\u8ba4\u4e0d\u77e5\u9053\u4e24\u6b21\u8bf7\u6c42\u662f\u5426\u6765\u81ea\u540c\u4e00\u4e2a\u7528\u6237\u3002</p> <p>\u4e3a\u4e86\u89e3\u51b3\u767b\u5f55\u72b6\u6001\u95ee\u9898\uff0c\u5e38\u7528 Cookie\u3001Session \u6216 Token\uff1a</p> <ul> <li>Cookie\uff1a\u6d4f\u89c8\u5668\u4fdd\u5b58\u7684\u5c0f\u6bb5\u6570\u636e\uff0c\u8bf7\u6c42\u540c\u4e00\u7ad9\u70b9\u65f6\u81ea\u52a8\u643a\u5e26\u3002</li> <li>Session\uff1a\u670d\u52a1\u7aef\u4fdd\u5b58\u4f1a\u8bdd\u6570\u636e\uff0c\u5ba2\u6237\u7aef\u901a\u5e38\u53ea\u4fdd\u5b58 Session ID\u3002</li> <li>Token\uff1a\u5ba2\u6237\u7aef\u4fdd\u5b58\u4ee4\u724c\uff0c\u8bf7\u6c42\u65f6\u653e\u5165 <code>Authorization</code> \u8bf7\u6c42\u5934\u6216 Cookie\u3002</li> </ul> <p>Cookie \u91cd\u8981\u5c5e\u6027\uff1a</p> \u5c5e\u6027 \u4f5c\u7528 Expires / Max-Age \u8bbe\u7f6e\u8fc7\u671f\u65f6\u95f4 Domain \u6307\u5b9a Cookie \u751f\u6548\u57df\u540d Path \u6307\u5b9a Cookie \u751f\u6548\u8def\u5f84 HttpOnly \u7981\u6b62 JavaScript \u8bfb\u53d6\uff0c\u964d\u4f4e XSS \u98ce\u9669 Secure \u53ea\u5728 HTTPS \u4e0b\u53d1\u9001 SameSite \u9650\u5236\u8de8\u7ad9\u8bf7\u6c42\u643a\u5e26 Cookie\uff0c\u964d\u4f4e CSRF \u98ce\u9669"},{"location":"Web.html#http_2","title":"HTTP \u7f13\u5b58","text":"<p>HTTP \u7f13\u5b58\u53ef\u4ee5\u51cf\u5c11\u91cd\u590d\u4e0b\u8f7d\uff0c\u63d0\u9ad8\u8bbf\u95ee\u901f\u5ea6\u3002</p> <p>\u5f3a\u7f13\u5b58\uff1a\u6d4f\u89c8\u5668\u76f4\u63a5\u4f7f\u7528\u672c\u5730\u7f13\u5b58\uff0c\u4e0d\u5411\u670d\u52a1\u5668\u786e\u8ba4\u3002</p> <p>\u5e38\u89c1\u54cd\u5e94\u5934\uff1a</p> <pre><code>Cache-Control: max-age=3600\n</code></pre> <p>\u542b\u4e49\u662f\u8d44\u6e90 3600 \u79d2\u5185\u53ef\u76f4\u63a5\u4f7f\u7528\u7f13\u5b58\u3002</p> <p>\u5e38\u89c1 <code>Cache-Control</code> \u6307\u4ee4\uff1a</p> \u6307\u4ee4 \u542b\u4e49 max-age=\u79d2\u6570 \u7f13\u5b58\u6709\u6548\u65f6\u95f4 no-cache \u4f7f\u7528\u7f13\u5b58\u524d\u5fc5\u987b\u5411\u670d\u52a1\u5668\u9a8c\u8bc1 no-store \u4e0d\u5141\u8bb8\u4fdd\u5b58\u7f13\u5b58 public \u53ef\u88ab\u6d4f\u89c8\u5668\u548c\u4ee3\u7406\u670d\u52a1\u5668\u7f13\u5b58 private \u53ea\u80fd\u88ab\u7528\u6237\u6d4f\u89c8\u5668\u7f13\u5b58 <p>\u534f\u5546\u7f13\u5b58\uff1a\u6d4f\u89c8\u5668\u8be2\u95ee\u670d\u52a1\u5668\u8d44\u6e90\u662f\u5426\u53d8\u5316\uff0c\u6ca1\u53d8\u5316\u5c31\u8fd4\u56de <code>304 Not Modified</code>\u3002</p> <p>\u5e38\u89c1\u673a\u5236\uff1a</p> <pre><code>ETag: \"abc123\"\nIf-None-Match: \"abc123\"\n</code></pre> <pre><code>Last-Modified: Tue, 19 May 2026 10:00:00 GMT\nIf-Modified-Since: Tue, 19 May 2026 10:00:00 GMT\n</code></pre> <p>\u5982\u679c\u8d44\u6e90\u672a\u53d8\u5316\uff0c\u670d\u52a1\u5668\u8fd4\u56de\uff1a</p> <pre><code>HTTP/1.1 304 Not Modified\n</code></pre>"},{"location":"Web.html#http_3","title":"HTTP \u8fde\u63a5\u7ba1\u7406","text":"<p>HTTP/1.0 \u9ed8\u8ba4\u77ed\u8fde\u63a5\uff0c\u4e00\u4e2a\u8bf7\u6c42\u901a\u5e38\u5bf9\u5e94\u4e00\u6b21 TCP \u8fde\u63a5\u3002</p> <p>HTTP/1.1 \u9ed8\u8ba4\u652f\u6301\u957f\u8fde\u63a5\uff1a</p> <pre><code>Connection: keep-alive\n</code></pre> <p>\u957f\u8fde\u63a5\u53ef\u4ee5\u590d\u7528 TCP \u8fde\u63a5\uff0c\u51cf\u5c11\u4e09\u6b21\u63e1\u624b\u548c\u6162\u542f\u52a8\u5f00\u9500\u3002</p> <p>HTTP/1.1 \u4ecd\u5b58\u5728\u961f\u5934\u963b\u585e\u95ee\u9898\uff1a\u540c\u4e00\u8fde\u63a5\u4e0a\u7684\u8bf7\u6c42\u9700\u8981\u6309\u987a\u5e8f\u5904\u7406\uff0c\u524d\u9762\u7684\u54cd\u5e94\u6162\uff0c\u4f1a\u5f71\u54cd\u540e\u9762\u7684\u54cd\u5e94\u3002</p> <p>HTTP/2 \u7684\u6539\u8fdb\uff1a</p> <ul> <li>\u4e8c\u8fdb\u5236\u5206\u5e27\u3002</li> <li>\u591a\u8def\u590d\u7528\uff0c\u540c\u4e00\u8fde\u63a5\u4e0a\u5e76\u53d1\u591a\u4e2a\u8bf7\u6c42\u548c\u54cd\u5e94\u3002</li> <li>\u5934\u90e8\u538b\u7f29\u3002</li> <li>\u652f\u6301\u6d41\u4f18\u5148\u7ea7\u3002</li> </ul> <p>HTTP/3 \u7684\u6539\u8fdb\uff1a</p> <ul> <li>\u57fa\u4e8e QUIC\uff0c\u800c\u4e0d\u662f\u76f4\u63a5\u57fa\u4e8e TCP\u3002</li> <li>QUIC \u57fa\u4e8e UDP\u3002</li> <li>\u51cf\u5c11\u8fde\u63a5\u5efa\u7acb\u5ef6\u8fdf\u3002</li> <li>\u7f13\u89e3 TCP \u5c42\u9762\u7684\u961f\u5934\u963b\u585e\u3002</li> </ul>"},{"location":"Web.html#cors","title":"\u8de8\u57df CORS","text":"<p>\u6d4f\u89c8\u5668\u6709\u540c\u6e90\u7b56\u7565\u3002\u534f\u8bae\u3001\u57df\u540d\u3001\u7aef\u53e3\u4e09\u8005\u90fd\u76f8\u540c\uff0c\u624d\u7b97\u540c\u6e90\u3002</p> <p>\u4f8b\u5982\uff1a</p> <pre><code>https://example.com:443\n</code></pre> <p>\u548c\u4e0b\u9762\u5730\u5740\u4e0d\u662f\u540c\u6e90\uff1a</p> <pre><code>http://example.com:80\nhttps://api.example.com:443\nhttps://example.com:8443\n</code></pre> <p>CORS \u901a\u8fc7 HTTP \u5934\u5141\u8bb8\u8de8\u57df\u8bbf\u95ee\u3002</p> <p>\u5e38\u89c1\u54cd\u5e94\u5934\uff1a</p> <pre><code>Access-Control-Allow-Origin: https://www.example.com\nAccess-Control-Allow-Methods: GET, POST, OPTIONS\nAccess-Control-Allow-Headers: Content-Type, Authorization\n</code></pre> <p>\u590d\u6742\u8de8\u57df\u8bf7\u6c42\u524d\uff0c\u6d4f\u89c8\u5668\u4f1a\u5148\u53d1\u9001 <code>OPTIONS</code> \u9884\u68c0\u8bf7\u6c42\u3002</p>"},{"location":"Web.html#3-https","title":"3. HTTPS","text":"<p>HTTPS = HTTP + TLS\u3002</p> <p>HTTPS \u7684\u4f5c\u7528\uff1a</p> <ul> <li>\u52a0\u5bc6\u4f20\u8f93\u5185\u5bb9\uff0c\u9632\u6b62\u7a83\u542c\u3002</li> <li>\u6821\u9a8c\u6570\u636e\u5b8c\u6574\u6027\uff0c\u9632\u6b62\u7be1\u6539\u3002</li> <li>\u901a\u8fc7\u8bc1\u4e66\u9a8c\u8bc1\u670d\u52a1\u5668\u8eab\u4efd\uff0c\u9632\u6b62\u4f2a\u9020\u7f51\u7ad9\u3002</li> </ul> <p>HTTP \u660e\u6587\u4f20\u8f93\uff0c\u4efb\u4f55\u80fd\u622a\u83b7\u6d41\u91cf\u7684\u4e2d\u95f4\u8282\u70b9\u90fd\u53ef\u80fd\u770b\u5230\u8bf7\u6c42\u5185\u5bb9\u3002HTTPS \u5728 HTTP \u4e0e TCP \u4e4b\u95f4\u52a0\u5165 TLS\uff0c\u52a0\u5bc6 HTTP \u62a5\u6587\u3002</p> <pre><code>HTTP\nTLS\nTCP\nIP\n</code></pre>"},{"location":"Web.html#tls","title":"TLS \u7684\u5b89\u5168\u76ee\u6807","text":"\u76ee\u6807 \u8bf4\u660e \u8eab\u4efd\u8ba4\u8bc1 \u786e\u8ba4\u8bbf\u95ee\u7684\u670d\u52a1\u5668\u786e\u5b9e\u662f\u76ee\u6807\u7f51\u7ad9 \u673a\u5bc6\u6027 \u4f20\u8f93\u5185\u5bb9\u88ab\u52a0\u5bc6\uff0c\u4e2d\u95f4\u4eba\u96be\u4ee5\u8bfb\u53d6 \u5b8c\u6574\u6027 \u6570\u636e\u88ab\u7be1\u6539\u65f6\u80fd\u591f\u88ab\u53d1\u73b0"},{"location":"Web.html#_12","title":"\u5bf9\u79f0\u52a0\u5bc6\u548c\u975e\u5bf9\u79f0\u52a0\u5bc6","text":"<p>HTTPS \u540c\u65f6\u4f7f\u7528\u5bf9\u79f0\u52a0\u5bc6\u548c\u975e\u5bf9\u79f0\u52a0\u5bc6\uff1a</p> <ul> <li>\u975e\u5bf9\u79f0\u52a0\u5bc6\uff1a\u7528\u4e8e\u8eab\u4efd\u8ba4\u8bc1\u548c\u5bc6\u94a5\u534f\u5546\uff0c\u8ba1\u7b97\u6210\u672c\u8f83\u9ad8\u3002</li> <li>\u5bf9\u79f0\u52a0\u5bc6\uff1a\u7528\u4e8e\u5927\u91cf\u5e94\u7528\u6570\u636e\u4f20\u8f93\uff0c\u901f\u5ea6\u5feb\u3002</li> </ul> <p>\u7b80\u5316\u7406\u89e3\uff1a</p> <ol> <li>\u63e1\u624b\u9636\u6bb5\u7528\u8bc1\u4e66\u548c\u975e\u5bf9\u79f0\u5bc6\u7801\u5b66\u786e\u8ba4\u8eab\u4efd\u3001\u534f\u5546\u5bc6\u94a5\u3002</li> <li>\u6570\u636e\u4f20\u8f93\u9636\u6bb5\u4f7f\u7528\u534f\u5546\u51fa\u7684\u5bf9\u79f0\u5bc6\u94a5\u52a0\u5bc6 HTTP \u5185\u5bb9\u3002</li> </ol>"},{"location":"Web.html#_13","title":"\u6570\u5b57\u8bc1\u4e66","text":"<p>\u670d\u52a1\u5668\u8bc1\u4e66\u901a\u5e38\u5305\u542b\uff1a</p> <ul> <li>\u57df\u540d</li> <li>\u516c\u94a5</li> <li>\u8bc1\u4e66\u6709\u6548\u671f</li> <li>\u8bc1\u4e66\u9881\u53d1\u673a\u6784 CA</li> <li>CA \u7684\u6570\u5b57\u7b7e\u540d</li> </ul> <p>\u6d4f\u89c8\u5668\u9a8c\u8bc1\u8bc1\u4e66\u65f6\u4f1a\u68c0\u67e5\uff1a</p> <ul> <li>\u8bc1\u4e66\u662f\u5426\u8fc7\u671f\u3002</li> <li>\u8bc1\u4e66\u57df\u540d\u662f\u5426\u5339\u914d\u5f53\u524d\u8bbf\u95ee\u57df\u540d\u3002</li> <li>\u8bc1\u4e66\u662f\u5426\u7531\u53d7\u4fe1\u4efb CA \u7b7e\u53d1\u3002</li> <li>\u8bc1\u4e66\u94fe\u662f\u5426\u5b8c\u6574\u3002</li> <li>\u8bc1\u4e66\u662f\u5426\u88ab\u540a\u9500\u3002</li> </ul>"},{"location":"Web.html#tls_1","title":"TLS \u63e1\u624b\u7b80\u5316\u8fc7\u7a0b","text":"<ol> <li>\u5ba2\u6237\u7aef\u8bf7\u6c42\u5efa\u7acb HTTPS \u8fde\u63a5\u3002</li> <li>\u5ba2\u6237\u7aef\u53d1\u9001\u652f\u6301\u7684 TLS \u7248\u672c\u3001\u52a0\u5bc6\u5957\u4ef6\u548c\u968f\u673a\u6570\u3002</li> <li>\u670d\u52a1\u7aef\u9009\u62e9 TLS \u7248\u672c\u548c\u52a0\u5bc6\u5957\u4ef6\uff0c\u8fd4\u56de\u8bc1\u4e66\u548c\u968f\u673a\u6570\u3002</li> <li>\u5ba2\u6237\u7aef\u9a8c\u8bc1\u8bc1\u4e66\u662f\u5426\u5408\u6cd5\u3002</li> <li>\u53cc\u65b9\u901a\u8fc7\u5bc6\u94a5\u534f\u5546\u7b97\u6cd5\u751f\u6210\u4f1a\u8bdd\u5bc6\u94a5\u3002</li> <li>\u540e\u7eed HTTP \u6570\u636e\u4f7f\u7528\u4f1a\u8bdd\u5bc6\u94a5\u52a0\u5bc6\u4f20\u8f93\u3002</li> </ol>"},{"location":"Web.html#sni","title":"SNI","text":"<p>SNI \u662f Server Name Indication\u3002\u5b83\u5141\u8bb8\u5ba2\u6237\u7aef\u5728 TLS \u63e1\u624b\u65f6\u544a\u8bc9\u670d\u52a1\u5668\u81ea\u5df1\u8981\u8bbf\u95ee\u54ea\u4e2a\u57df\u540d\u3002</p> <p>\u6ca1\u6709 SNI \u65f6\uff0c\u540c\u4e00\u4e2a IP \u4e0a\u90e8\u7f72\u591a\u4e2a HTTPS \u7ad9\u70b9\u4f1a\u6bd4\u8f83\u56f0\u96be\uff0c\u56e0\u4e3a\u670d\u52a1\u5668\u4e0d\u77e5\u9053\u5e94\u8be5\u8fd4\u56de\u54ea\u5f20\u8bc1\u4e66\u3002</p>"},{"location":"Web.html#hsts","title":"HSTS","text":"<p>HSTS \u662f HTTP Strict Transport Security\uff0c\u7528\u4e8e\u5f3a\u5236\u6d4f\u89c8\u5668\u4f7f\u7528 HTTPS \u8bbf\u95ee\u7f51\u7ad9\u3002</p> <p>\u54cd\u5e94\u5934\u793a\u4f8b\uff1a</p> <pre><code>Strict-Transport-Security: max-age=31536000; includeSubDomains\n</code></pre> <p>\u542f\u7528 HSTS \u540e\uff0c\u6d4f\u89c8\u5668\u4f1a\u5728\u6709\u6548\u671f\u5185\u81ea\u52a8\u628a HTTP \u8bf7\u6c42\u5347\u7ea7\u4e3a HTTPS\u3002</p>"},{"location":"Web.html#https","title":"HTTPS \u5e38\u89c1\u95ee\u9898","text":"\u95ee\u9898 \u53ef\u80fd\u539f\u56e0 \u8bc1\u4e66\u4e0d\u53d7\u4fe1\u4efb \u4f7f\u7528\u81ea\u7b7e\u540d\u8bc1\u4e66\u6216 CA \u4e0d\u53d7\u6d4f\u89c8\u5668\u4fe1\u4efb \u8bc1\u4e66\u8fc7\u671f \u8bc1\u4e66\u8d85\u8fc7\u6709\u6548\u671f \u57df\u540d\u4e0d\u5339\u914d \u8bc1\u4e66\u7ed1\u5b9a\u7684\u57df\u540d\u4e0d\u662f\u5f53\u524d\u8bbf\u95ee\u57df\u540d \u8bc1\u4e66\u94fe\u4e0d\u5b8c\u6574 \u670d\u52a1\u5668\u6ca1\u6709\u6b63\u786e\u914d\u7f6e\u4e2d\u95f4\u8bc1\u4e66 \u6df7\u5408\u5185\u5bb9 HTTPS \u9875\u9762\u4e2d\u52a0\u8f7d\u4e86 HTTP \u8d44\u6e90"},{"location":"Web.html#4-dhcp","title":"4. DHCP","text":"<p>DHCP \u7528\u4e8e\u81ea\u52a8\u5206\u914d\u7f51\u7edc\u914d\u7f6e\u3002</p> <p>\u5e38\u89c1\u5206\u914d\u5185\u5bb9\uff1a</p> <ul> <li>IP \u5730\u5740</li> <li>\u5b50\u7f51\u63a9\u7801</li> <li>\u9ed8\u8ba4\u7f51\u5173</li> <li>DNS \u670d\u52a1\u5668\u5730\u5740</li> </ul> <p>DHCP \u83b7\u53d6\u5730\u5740\u7684\u8fc7\u7a0b\uff1a</p> <pre><code>Discover -&gt; Offer -&gt; Request -&gt; ACK\n</code></pre>"},{"location":"Web.html#5-ftpsmtppop3imap","title":"5. FTP\u3001SMTP\u3001POP3\u3001IMAP","text":"<ul> <li>FTP\uff1a\u6587\u4ef6\u4f20\u8f93\u534f\u8bae\u3002</li> <li>SMTP\uff1a\u53d1\u9001\u90ae\u4ef6\u3002</li> <li>POP3\uff1a\u4e0b\u8f7d\u90ae\u4ef6\u5230\u672c\u5730\u3002</li> <li>IMAP\uff1a\u5728\u670d\u52a1\u5668\u4e0a\u540c\u6b65\u7ba1\u7406\u90ae\u4ef6\u3002</li> </ul>"},{"location":"Web.html#_14","title":"\u516b\u3001\u6d4f\u89c8\u5668\u8bbf\u95ee\u7f51\u9875\u7684\u5b8c\u6574\u8fc7\u7a0b","text":"<p>\u4ee5\u8bbf\u95ee <code>https://www.example.com</code> \u4e3a\u4f8b\uff1a</p> <ol> <li>\u6d4f\u89c8\u5668\u89e3\u6790 URL\uff0c\u5224\u65ad\u534f\u8bae\u3001\u57df\u540d\u3001\u7aef\u53e3\u548c\u8def\u5f84\u3002</li> <li>\u67e5\u8be2\u6d4f\u89c8\u5668\u7f13\u5b58\uff0c\u68c0\u67e5\u662f\u5426\u5df2\u6709\u53ef\u7528\u8d44\u6e90\u3002</li> <li>\u8fdb\u884c DNS \u89e3\u6790\uff0c\u83b7\u5f97\u670d\u52a1\u5668 IP \u5730\u5740\u3002</li> <li>\u901a\u8fc7 ARP \u83b7\u53d6\u7f51\u5173\u6216\u76ee\u6807\u4e3b\u673a\u7684 MAC \u5730\u5740\u3002</li> <li>\u5efa\u7acb TCP \u8fde\u63a5\uff0c\u5b8c\u6210\u4e09\u6b21\u63e1\u624b\u3002</li> <li>\u5982\u679c\u662f HTTPS\uff0c\u8fdb\u884c TLS \u63e1\u624b\u5e76\u534f\u5546\u5bc6\u94a5\u3002</li> <li>\u6d4f\u89c8\u5668\u53d1\u9001 HTTP \u8bf7\u6c42\u3002</li> <li>\u670d\u52a1\u5668\u5904\u7406\u8bf7\u6c42\u5e76\u8fd4\u56de HTTP \u54cd\u5e94\u3002</li> <li>\u6d4f\u89c8\u5668\u89e3\u6790 HTML\uff0c\u7ee7\u7eed\u8bf7\u6c42 CSS\u3001JavaScript\u3001\u56fe\u7247\u7b49\u8d44\u6e90\u3002</li> <li>\u6d4f\u89c8\u5668\u6784\u5efa DOM\u3001CSSOM\uff0c\u751f\u6210\u6e32\u67d3\u6811\u5e76\u7ed8\u5236\u9875\u9762\u3002</li> <li>\u8fde\u63a5\u53ef\u80fd\u4fdd\u6301\u590d\u7528\uff0c\u4e5f\u53ef\u80fd\u5728\u7a7a\u95f2\u540e\u5173\u95ed\u3002</li> </ol>"},{"location":"Web.html#_15","title":"\u4e5d\u3001\u7f51\u7edc\u5b89\u5168\u57fa\u7840","text":""},{"location":"Web.html#1_3","title":"1. \u5b89\u5168\u4e09\u8981\u7d20","text":"<ul> <li>\u673a\u5bc6\u6027\uff1a\u6570\u636e\u4e0d\u80fd\u88ab\u672a\u6388\u6743\u8005\u8bfb\u53d6\u3002</li> <li>\u5b8c\u6574\u6027\uff1a\u6570\u636e\u4e0d\u80fd\u88ab\u975e\u6cd5\u7be1\u6539\u3002</li> <li>\u53ef\u7528\u6027\uff1a\u7cfb\u7edf\u548c\u670d\u52a1\u9700\u8981\u5728\u9700\u8981\u65f6\u53ef\u7528\u3002</li> </ul>"},{"location":"Web.html#2_4","title":"2. \u5e38\u89c1\u653b\u51fb","text":"\u653b\u51fb\u65b9\u5f0f \u8bf4\u660e DDoS \u5229\u7528\u5927\u91cf\u6d41\u91cf\u538b\u57ae\u76ee\u6807\u670d\u52a1 ARP \u6b3a\u9a97 \u4f2a\u9020 IP \u4e0e MAC \u7684\u5bf9\u5e94\u5173\u7cfb DNS \u52ab\u6301 \u7be1\u6539\u57df\u540d\u89e3\u6790\u7ed3\u679c \u4e2d\u95f4\u4eba\u653b\u51fb \u653b\u51fb\u8005\u63d2\u5165\u901a\u4fe1\u53cc\u65b9\u4e4b\u95f4\u7a83\u542c\u6216\u7be1\u6539\u6570\u636e \u9493\u9c7c\u653b\u51fb \u4f2a\u9020\u7f51\u7ad9\u6216\u6d88\u606f\u9a97\u53d6\u8d26\u53f7\u5bc6\u7801 \u7aef\u53e3\u626b\u63cf \u63a2\u6d4b\u76ee\u6807\u4e3b\u673a\u5f00\u653e\u7684\u670d\u52a1"},{"location":"Web.html#3_3","title":"3. \u5e38\u89c1\u9632\u62a4\u624b\u6bb5","text":"<ul> <li>\u4f7f\u7528 HTTPS\u3001SSH \u7b49\u52a0\u5bc6\u534f\u8bae\u3002</li> <li>\u914d\u7f6e\u9632\u706b\u5899\u548c\u8bbf\u95ee\u63a7\u5236\u7b56\u7565\u3002</li> <li>\u53ca\u65f6\u66f4\u65b0\u7cfb\u7edf\u548c\u8f6f\u4ef6\u8865\u4e01\u3002</li> <li>\u4f7f\u7528\u5f3a\u5bc6\u7801\u548c\u591a\u56e0\u7d20\u8ba4\u8bc1\u3002</li> <li>\u5bf9\u91cd\u8981\u670d\u52a1\u9650\u5236\u6765\u6e90 IP\u3002</li> <li>\u5b9a\u671f\u67e5\u770b\u65e5\u5fd7\uff0c\u53d1\u73b0\u5f02\u5e38\u8bbf\u95ee\u3002</li> <li>\u5728\u516c\u5171\u7f51\u7edc\u4e2d\u8c28\u614e\u4f7f\u7528\u672a\u52a0\u5bc6\u670d\u52a1\u3002</li> </ul>"},{"location":"Web.html#4_1","title":"4. \u9632\u706b\u5899","text":"<p>\u9632\u706b\u5899\u6839\u636e\u89c4\u5219\u5141\u8bb8\u6216\u62d2\u7edd\u7f51\u7edc\u6d41\u91cf\u3002</p> <p>\u5e38\u89c1\u8fc7\u6ee4\u4f9d\u636e\uff1a</p> <ul> <li>\u6e90 IP</li> <li>\u76ee\u6807 IP</li> <li>\u6e90\u7aef\u53e3</li> <li>\u76ee\u6807\u7aef\u53e3</li> <li>\u534f\u8bae\u7c7b\u578b</li> <li>\u8fde\u63a5\u72b6\u6001</li> </ul>"},{"location":"Web.html#_16","title":"\u5341\u3001\u5e38\u7528\u7f51\u7edc\u547d\u4ee4","text":""},{"location":"Web.html#1-windows","title":"1. Windows \u5e38\u7528\u547d\u4ee4","text":"<pre><code>ipconfig\nipconfig /all\nipconfig /flushdns\nping www.baidu.com\ntracert www.baidu.com\nnslookup www.baidu.com\nnetstat -ano\narp -a\nroute print\n</code></pre> <p>\u8bf4\u660e\uff1a</p> <ul> <li><code>ipconfig</code>\uff1a\u67e5\u770b\u672c\u673a IP\u3001\u7f51\u5173\u3001DNS \u7b49\u914d\u7f6e\u3002</li> <li><code>ipconfig /all</code>\uff1a\u67e5\u770b\u5b8c\u6574\u7f51\u7edc\u914d\u7f6e\u3002</li> <li><code>ipconfig /flushdns</code>\uff1a\u6e05\u7a7a DNS \u7f13\u5b58\u3002</li> <li><code>ping</code>\uff1a\u6d4b\u8bd5\u7f51\u7edc\u8fde\u901a\u6027\u548c\u5ef6\u8fdf\u3002</li> <li><code>tracert</code>\uff1a\u67e5\u770b\u8bbf\u95ee\u76ee\u6807\u7ecf\u8fc7\u7684\u8def\u7531\u3002</li> <li><code>nslookup</code>\uff1a\u67e5\u8be2 DNS \u89e3\u6790\u7ed3\u679c\u3002</li> <li><code>netstat -ano</code>\uff1a\u67e5\u770b\u7aef\u53e3\u548c\u8fde\u63a5\u72b6\u6001\u3002</li> <li><code>arp -a</code>\uff1a\u67e5\u770b ARP \u7f13\u5b58\u3002</li> <li><code>route print</code>\uff1a\u67e5\u770b\u8def\u7531\u8868\u3002</li> </ul>"},{"location":"Web.html#2-linux","title":"2. Linux \u5e38\u7528\u547d\u4ee4","text":"<pre><code>ip addr\nip route\nping example.com\ntraceroute example.com\ndig example.com\nnslookup example.com\nss -tulnp\ncurl -I https://example.com\n</code></pre>"},{"location":"Web.html#_17","title":"\u5341\u4e00\u3001\u5e38\u89c1\u6545\u969c\u6392\u67e5\u601d\u8def","text":""},{"location":"Web.html#1_4","title":"1. \u65e0\u6cd5\u4e0a\u7f51","text":"<p>\u6392\u67e5\u987a\u5e8f\uff1a</p> <ol> <li>\u68c0\u67e5\u7f51\u7ebf\u3001Wi-Fi\u3001\u7f51\u5361\u662f\u5426\u6b63\u5e38\u3002</li> <li>\u67e5\u770b\u662f\u5426\u83b7\u53d6\u5230\u6b63\u786e\u7684 IP \u5730\u5740\u3002</li> <li>\u68c0\u67e5\u9ed8\u8ba4\u7f51\u5173\u662f\u5426\u6b63\u786e\u3002</li> <li><code>ping 127.0.0.1</code>\uff0c\u6d4b\u8bd5\u672c\u673a TCP/IP \u534f\u8bae\u6808\u3002</li> <li><code>ping \u672c\u673a IP</code>\uff0c\u6d4b\u8bd5\u7f51\u5361\u914d\u7f6e\u3002</li> <li><code>ping \u7f51\u5173 IP</code>\uff0c\u6d4b\u8bd5\u5c40\u57df\u7f51\u8fde\u901a\u6027\u3002</li> <li><code>ping \u516c\u7f51 IP</code>\uff0c\u6d4b\u8bd5\u662f\u5426\u80fd\u8bbf\u95ee\u5916\u7f51\u3002</li> <li><code>nslookup \u57df\u540d</code>\uff0c\u68c0\u67e5 DNS \u662f\u5426\u6b63\u5e38\u3002</li> </ol>"},{"location":"Web.html#2-ping-ip","title":"2. \u80fd ping IP\uff0c\u4f46\u4e0d\u80fd\u8bbf\u95ee\u57df\u540d","text":"<p>\u901a\u5e38\u662f DNS \u95ee\u9898\u3002</p> <p>\u53ef\u80fd\u539f\u56e0\uff1a</p> <ul> <li>DNS \u670d\u52a1\u5668\u914d\u7f6e\u9519\u8bef\u3002</li> <li>DNS \u7f13\u5b58\u5f02\u5e38\u3002</li> <li>\u672c\u5730 hosts \u6587\u4ef6\u914d\u7f6e\u9519\u8bef\u3002</li> <li>DNS \u88ab\u52ab\u6301\u6216\u6c61\u67d3\u3002</li> </ul>"},{"location":"Web.html#3_4","title":"3. \u80fd\u8bbf\u95ee\u7f51\u7ad9\uff0c\u4f46\u901f\u5ea6\u6162","text":"<p>\u53ef\u80fd\u539f\u56e0\uff1a</p> <ul> <li>\u672c\u5730\u5e26\u5bbd\u4e0d\u8db3\u3002</li> <li>Wi-Fi \u4fe1\u53f7\u5f31\u3002</li> <li>\u7ebf\u8def\u62e5\u585e\u3002</li> <li>DNS \u89e3\u6790\u6162\u3002</li> <li>\u670d\u52a1\u5668\u54cd\u5e94\u6162\u3002</li> <li>\u4e22\u5305\u7387\u9ad8\u3002</li> </ul>"},{"location":"Web.html#4_2","title":"4. \u67d0\u4e2a\u7aef\u53e3\u65e0\u6cd5\u8bbf\u95ee","text":"<p>\u6392\u67e5\u65b9\u5411\uff1a</p> <ul> <li>\u670d\u52a1\u662f\u5426\u542f\u52a8\u3002</li> <li>\u670d\u52a1\u662f\u5426\u76d1\u542c\u6b63\u786e\u7aef\u53e3\u3002</li> <li>\u9632\u706b\u5899\u662f\u5426\u653e\u884c\u3002</li> <li>\u8def\u7531\u662f\u5426\u53ef\u8fbe\u3002</li> <li>NAT \u6216\u7aef\u53e3\u6620\u5c04\u662f\u5426\u6b63\u786e\u3002</li> <li>\u4e91\u670d\u52a1\u5668\u5b89\u5168\u7ec4\u662f\u5426\u5f00\u653e\u3002</li> </ul>"},{"location":"docker.html","title":"Docker \u5b66\u4e60\u7b14\u8bb0","text":""},{"location":"docker.html#docker_1","title":"\u4e00\u3001Docker \u662f\u4ec0\u4e48","text":"<p>Docker \u662f\u4e00\u79cd\u5bb9\u5668\u5316\u5e73\u53f0\uff0c\u7528\u6765\u628a\u5e94\u7528\u7a0b\u5e8f\u548c\u5b83\u4f9d\u8d56\u7684\u8fd0\u884c\u73af\u5883\u6253\u5305\u5230\u4e00\u8d77\u3002\u5bb9\u5668\u53ef\u4ee5\u5728\u4e0d\u540c\u673a\u5668\u4e0a\u4ee5\u6bd4\u8f83\u4e00\u81f4\u7684\u65b9\u5f0f\u8fd0\u884c\uff0c\u51cf\u5c11\u201c\u6211\u7535\u8111\u4e0a\u53ef\u4ee5\u8dd1\uff0c\u670d\u52a1\u5668\u4e0a\u8dd1\u4e0d\u4e86\u201d\u7684\u95ee\u9898\u3002</p> <p>Docker \u7684\u6838\u5fc3\u601d\u60f3\uff1a</p> <ul> <li>\u5e94\u7528\u548c\u4f9d\u8d56\u4e00\u8d77\u6253\u5305\u3002</li> <li>\u8fd0\u884c\u73af\u5883\u6807\u51c6\u5316\u3002</li> <li>\u955c\u50cf\u4e00\u6b21\u6784\u5efa\uff0c\u591a\u5904\u8fd0\u884c\u3002</li> <li>\u5bb9\u5668\u4e4b\u95f4\u76f8\u4e92\u9694\u79bb\uff0c\u4f46\u6bd4\u865a\u62df\u673a\u66f4\u8f7b\u91cf\u3002</li> </ul>"},{"location":"docker.html#1","title":"1. \u5bb9\u5668\u548c\u865a\u62df\u673a\u7684\u533a\u522b","text":"\u5bf9\u6bd4\u9879 \u5bb9\u5668 \u865a\u62df\u673a \u9694\u79bb\u65b9\u5f0f \u5171\u4eab\u5bbf\u4e3b\u673a\u5185\u6838\uff0c\u901a\u8fc7 namespace\u3001cgroup \u9694\u79bb \u6bcf\u4e2a\u865a\u62df\u673a\u90fd\u6709\u5b8c\u6574\u64cd\u4f5c\u7cfb\u7edf \u542f\u52a8\u901f\u5ea6 \u79d2\u7ea7\u751a\u81f3\u66f4\u5feb \u901a\u5e38\u8f83\u6162 \u8d44\u6e90\u5360\u7528 \u8f83\u5c0f \u8f83\u5927 \u955c\u50cf\u4f53\u79ef \u901a\u5e38\u8f83\u5c0f \u901a\u5e38\u8f83\u5927 \u9002\u5408\u573a\u666f \u5fae\u670d\u52a1\u3001\u5f00\u53d1\u73af\u5883\u3001\u6301\u7eed\u96c6\u6210\u3001\u5e94\u7528\u90e8\u7f72 \u5f3a\u9694\u79bb\u3001\u591a\u7cfb\u7edf\u5185\u6838\u8fd0\u884c <p>\u5bb9\u5668\u4e0d\u662f\u8ff7\u4f60\u865a\u62df\u673a\u3002\u5bb9\u5668\u5185\u90e8\u770b\u8d77\u6765\u50cf\u4e00\u4e2a\u72ec\u7acb\u7cfb\u7edf\uff0c\u4f46\u672c\u8d28\u4e0a\u8fd8\u662f\u5bbf\u4e3b\u673a\u4e0a\u7684\u8fdb\u7a0b\u3002</p>"},{"location":"docker.html#docker_2","title":"\u4e8c\u3001Docker \u6838\u5fc3\u6982\u5ff5","text":""},{"location":"docker.html#1-image","title":"1. \u955c\u50cf Image","text":"<p>\u955c\u50cf\u662f\u4e00\u4e2a\u53ea\u8bfb\u6a21\u677f\uff0c\u5305\u542b\u5e94\u7528\u7a0b\u5e8f\u3001\u8fd0\u884c\u65f6\u3001\u7cfb\u7edf\u5e93\u3001\u914d\u7f6e\u6587\u4ef6\u7b49\u5185\u5bb9\u3002</p> <p>\u53ef\u4ee5\u628a\u955c\u50cf\u7406\u89e3\u6210\u201c\u5e94\u7528\u8fd0\u884c\u73af\u5883\u7684\u5feb\u7167\u201d\u3002</p> <p>\u7279\u70b9\uff1a</p> <ul> <li>\u955c\u50cf\u662f\u5206\u5c42\u7684\u3002</li> <li>\u955c\u50cf\u672c\u8eab\u4e0d\u80fd\u76f4\u63a5\u6539\u53d8\u3002</li> <li>\u5bb9\u5668\u7531\u955c\u50cf\u521b\u5efa\u3002</li> <li>\u955c\u50cf\u53ef\u4ee5\u4e0a\u4f20\u5230\u955c\u50cf\u4ed3\u5e93\u5171\u4eab\u3002</li> </ul> <p>\u5e38\u89c1\u955c\u50cf\uff1a</p> <ul> <li><code>nginx</code></li> <li><code>mysql</code></li> <li><code>redis</code></li> <li><code>node</code></li> <li><code>python</code></li> <li><code>ubuntu</code></li> <li><code>alpine</code></li> </ul>"},{"location":"docker.html#2-container","title":"2. \u5bb9\u5668 Container","text":"<p>\u5bb9\u5668\u662f\u955c\u50cf\u8fd0\u884c\u540e\u7684\u5b9e\u4f8b\u3002</p> <p>\u955c\u50cf\u548c\u5bb9\u5668\u7684\u5173\u7cfb\u7c7b\u4f3c\u4e8e\uff1a</p> <pre><code>\u955c\u50cf = \u7c7b / \u6a21\u677f\n\u5bb9\u5668 = \u5bf9\u8c61 / \u5b9e\u4f8b\n</code></pre> <p>\u4e00\u4e2a\u955c\u50cf\u53ef\u4ee5\u521b\u5efa\u591a\u4e2a\u5bb9\u5668\uff0c\u6bcf\u4e2a\u5bb9\u5668\u6709\u81ea\u5df1\u7684\u6587\u4ef6\u7cfb\u7edf\u53d8\u66f4\u3001\u7f51\u7edc\u3001\u8fdb\u7a0b\u548c\u8fd0\u884c\u72b6\u6001\u3002</p>"},{"location":"docker.html#3-registry","title":"3. \u4ed3\u5e93 Registry","text":"<p>\u955c\u50cf\u4ed3\u5e93\u7528\u6765\u5b58\u50a8\u548c\u5206\u53d1 Docker \u955c\u50cf\u3002</p> <p>\u5e38\u89c1\u4ed3\u5e93\uff1a</p> <ul> <li>Docker Hub</li> <li>GitHub Container Registry</li> <li>GitLab Container Registry</li> <li>\u963f\u91cc\u4e91\u5bb9\u5668\u955c\u50cf\u670d\u52a1</li> <li>Harbor \u79c1\u6709\u955c\u50cf\u4ed3\u5e93</li> </ul> <p>\u955c\u50cf\u5b8c\u6574\u540d\u79f0\u901a\u5e38\u5305\u542b\uff1a</p> <pre><code>registry/namespace/image:tag\n</code></pre> <p>\u4f8b\u5982\uff1a</p> <pre><code>docker.io/library/nginx:latest\nghcr.io/example/app:v1.0.0\n</code></pre>"},{"location":"docker.html#4-dockerfile","title":"4. Dockerfile","text":"<p>Dockerfile \u662f\u6784\u5efa\u955c\u50cf\u7684\u811a\u672c\u6587\u4ef6\uff0c\u91cc\u9762\u5199\u660e\u955c\u50cf\u5e94\u8be5\u4ece\u54ea\u4e2a\u57fa\u7840\u955c\u50cf\u5f00\u59cb\u3001\u590d\u5236\u54ea\u4e9b\u6587\u4ef6\u3001\u5b89\u88c5\u54ea\u4e9b\u4f9d\u8d56\u3001\u542f\u52a8\u4ec0\u4e48\u547d\u4ee4\u3002</p>"},{"location":"docker.html#5-volume","title":"5. Volume","text":"<p>Volume \u7528\u6765\u6301\u4e45\u5316\u5bb9\u5668\u6570\u636e\u3002</p> <p>\u5bb9\u5668\u5220\u9664\u540e\uff0c\u5bb9\u5668\u5185\u90e8\u666e\u901a\u6587\u4ef6\u7cfb\u7edf\u4e2d\u7684\u6570\u636e\u4e5f\u4f1a\u968f\u4e4b\u4e22\u5931\uff1b\u5982\u679c\u6570\u636e\u6302\u8f7d\u5230\u4e86 volume\uff0c\u5219\u53ef\u4ee5\u4fdd\u7559\u4e0b\u6765\u3002</p> <p>\u5e38\u89c1\u7528\u9014\uff1a</p> <ul> <li>\u6570\u636e\u5e93\u6570\u636e\u76ee\u5f55\u3002</li> <li>\u4e0a\u4f20\u6587\u4ef6\u76ee\u5f55\u3002</li> <li>\u65e5\u5fd7\u76ee\u5f55\u3002</li> <li>\u5f00\u53d1\u73af\u5883\u4ee3\u7801\u6302\u8f7d\u3002</li> </ul>"},{"location":"docker.html#6-network","title":"6. Network","text":"<p>Docker \u7f51\u7edc\u8d1f\u8d23\u5bb9\u5668\u4e4b\u95f4\u3001\u5bb9\u5668\u548c\u5bbf\u4e3b\u673a\u4e4b\u95f4\u7684\u901a\u4fe1\u3002</p> <p>\u5e38\u89c1\u7f51\u7edc\u6a21\u5f0f\uff1a</p> <ul> <li><code>bridge</code>\uff1a\u9ed8\u8ba4\u7f51\u7edc\u6a21\u5f0f\u3002</li> <li><code>host</code>\uff1a\u5bb9\u5668\u76f4\u63a5\u4f7f\u7528\u5bbf\u4e3b\u673a\u7f51\u7edc\u3002</li> <li><code>none</code>\uff1a\u4e0d\u914d\u7f6e\u7f51\u7edc\u3002</li> <li>\u81ea\u5b9a\u4e49 bridge \u7f51\u7edc\uff1a\u5e38\u7528\u4e8e Compose \u6216\u591a\u5bb9\u5668\u5e94\u7528\u3002</li> </ul>"},{"location":"docker.html#_1","title":"\u4e09\u3001\u5e38\u7528\u547d\u4ee4","text":""},{"location":"docker.html#1-docker","title":"1. \u67e5\u770b Docker \u4fe1\u606f","text":"<pre><code>docker version\ndocker info\n</code></pre> <p><code>docker version</code> \u67e5\u770b\u5ba2\u6237\u7aef\u548c\u670d\u52a1\u7aef\u7248\u672c\u3002</p> <p><code>docker info</code> \u67e5\u770b Docker \u5f15\u64ce\u3001\u955c\u50cf\u6570\u91cf\u3001\u5bb9\u5668\u6570\u91cf\u3001\u5b58\u50a8\u9a71\u52a8\u3001\u7f51\u7edc\u7b49\u4fe1\u606f\u3002</p>"},{"location":"docker.html#2","title":"2. \u955c\u50cf\u547d\u4ee4","text":"<pre><code>docker pull nginx\ndocker images\ndocker image ls\ndocker rmi nginx\ndocker image inspect nginx\n</code></pre> <p>\u8bf4\u660e\uff1a</p> <ul> <li><code>docker pull</code>\uff1a\u62c9\u53d6\u955c\u50cf\u3002</li> <li><code>docker images</code>\uff1a\u67e5\u770b\u672c\u5730\u955c\u50cf\u3002</li> <li><code>docker rmi</code>\uff1a\u5220\u9664\u955c\u50cf\u3002</li> <li><code>docker image inspect</code>\uff1a\u67e5\u770b\u955c\u50cf\u8be6\u7ec6\u4fe1\u606f\u3002</li> </ul> <p>\u62c9\u53d6\u6307\u5b9a\u7248\u672c\uff1a</p> <pre><code>docker pull nginx:1.25\ndocker pull redis:7\n</code></pre> <p>\u4e0d\u8981\u5728\u751f\u4ea7\u73af\u5883\u968f\u610f\u4f9d\u8d56 <code>latest</code>\uff0c\u56e0\u4e3a\u5b83\u53ef\u80fd\u968f\u7740\u4e0a\u6e38\u66f4\u65b0\u800c\u53d8\u5316\uff0c\u5bfc\u81f4\u73af\u5883\u4e0d\u53ef\u91cd\u590d\u3002</p>"},{"location":"docker.html#3","title":"3. \u5bb9\u5668\u8fd0\u884c","text":"<pre><code>docker run nginx\n</code></pre> <p>\u5e38\u7528\u53c2\u6570\uff1a</p> <pre><code>docker run -d --name web -p 8080:80 nginx\n</code></pre> <p>\u542b\u4e49\uff1a</p> <ul> <li><code>-d</code>\uff1a\u540e\u53f0\u8fd0\u884c\u3002</li> <li><code>--name web</code>\uff1a\u5bb9\u5668\u540d\u79f0\u4e3a <code>web</code>\u3002</li> <li><code>-p 8080:80</code>\uff1a\u628a\u5bbf\u4e3b\u673a <code>8080</code> \u7aef\u53e3\u6620\u5c04\u5230\u5bb9\u5668 <code>80</code> \u7aef\u53e3\u3002</li> <li><code>nginx</code>\uff1a\u4f7f\u7528\u7684\u955c\u50cf\u3002</li> </ul> <p>\u8bbf\u95ee\uff1a</p> <pre><code>http://localhost:8080\n</code></pre>"},{"location":"docker.html#4","title":"4. \u67e5\u770b\u5bb9\u5668","text":"<pre><code>docker ps\ndocker ps -a\n</code></pre> <p>\u8bf4\u660e\uff1a</p> <ul> <li><code>docker ps</code>\uff1a\u67e5\u770b\u6b63\u5728\u8fd0\u884c\u7684\u5bb9\u5668\u3002</li> <li><code>docker ps -a</code>\uff1a\u67e5\u770b\u6240\u6709\u5bb9\u5668\uff0c\u5305\u62ec\u5df2\u9000\u51fa\u7684\u5bb9\u5668\u3002</li> </ul>"},{"location":"docker.html#5","title":"5. \u505c\u6b62\u548c\u5220\u9664\u5bb9\u5668","text":"<pre><code>docker stop web\ndocker start web\ndocker restart web\ndocker rm web\ndocker rm -f web\n</code></pre> <p>\u8bf4\u660e\uff1a</p> <ul> <li><code>docker stop</code>\uff1a\u6b63\u5e38\u505c\u6b62\u5bb9\u5668\u3002</li> <li><code>docker start</code>\uff1a\u542f\u52a8\u5df2\u5b58\u5728\u7684\u5bb9\u5668\u3002</li> <li><code>docker restart</code>\uff1a\u91cd\u542f\u5bb9\u5668\u3002</li> <li><code>docker rm</code>\uff1a\u5220\u9664\u5df2\u505c\u6b62\u5bb9\u5668\u3002</li> <li><code>docker rm -f</code>\uff1a\u5f3a\u5236\u5220\u9664\u8fd0\u884c\u4e2d\u7684\u5bb9\u5668\u3002</li> </ul>"},{"location":"docker.html#6","title":"6. \u67e5\u770b\u65e5\u5fd7\u548c\u8fdb\u5165\u5bb9\u5668","text":"<pre><code>docker logs web\ndocker logs -f web\ndocker exec -it web sh\ndocker exec -it web bash\n</code></pre> <p>\u8bf4\u660e\uff1a</p> <ul> <li><code>docker logs</code>\uff1a\u67e5\u770b\u5bb9\u5668\u6807\u51c6\u8f93\u51fa\u65e5\u5fd7\u3002</li> <li><code>-f</code>\uff1a\u6301\u7eed\u8ddf\u8e2a\u65e5\u5fd7\u3002</li> <li><code>docker exec</code>\uff1a\u5728\u8fd0\u884c\u4e2d\u7684\u5bb9\u5668\u91cc\u6267\u884c\u547d\u4ee4\u3002</li> <li>Alpine \u7b49\u8f7b\u91cf\u955c\u50cf\u901a\u5e38\u53ea\u6709 <code>sh</code>\uff0c\u4e0d\u4e00\u5b9a\u6709 <code>bash</code>\u3002</li> </ul>"},{"location":"docker.html#7","title":"7. \u62f7\u8d1d\u6587\u4ef6","text":"<pre><code>docker cp ./index.html web:/usr/share/nginx/html/index.html\ndocker cp web:/etc/nginx/nginx.conf ./nginx.conf\n</code></pre>"},{"location":"docker.html#8","title":"8. \u67e5\u770b\u8d44\u6e90\u5360\u7528","text":"<pre><code>docker stats\ndocker top web\n</code></pre>"},{"location":"docker.html#9","title":"9. \u6e05\u7406\u8d44\u6e90","text":"<pre><code>docker container prune\ndocker image prune\ndocker volume prune\ndocker network prune\ndocker system prune\n</code></pre> <p>\u6ce8\u610f\uff1a<code>prune</code> \u4f1a\u5220\u9664\u672a\u4f7f\u7528\u8d44\u6e90\u3002\u6267\u884c\u524d\u8981\u786e\u8ba4\u662f\u5426\u6709\u4ecd\u7136\u9700\u8981\u7684\u6570\u636e\uff0c\u5c24\u5176\u662f volume\u3002</p>"},{"location":"docker.html#dockerfile","title":"\u56db\u3001Dockerfile","text":""},{"location":"docker.html#1_1","title":"1. \u57fa\u672c\u793a\u4f8b","text":"<p>\u4ee5\u4e00\u4e2a Node.js \u5e94\u7528\u4e3a\u4f8b\uff1a</p> <pre><code>FROM node:20-alpine\n\nWORKDIR /app\n\nCOPY package*.json ./\nRUN npm ci --omit=dev\n\nCOPY . .\n\nEXPOSE 3000\n\nCMD [\"node\", \"server.js\"]\n</code></pre> <p>\u6784\u5efa\u955c\u50cf\uff1a</p> <pre><code>docker build -t my-node-app:1.0.0 .\n</code></pre> <p>\u8fd0\u884c\u955c\u50cf\uff1a</p> <pre><code>docker run -d --name app -p 3000:3000 my-node-app:1.0.0\n</code></pre>"},{"location":"docker.html#2_1","title":"2. \u5e38\u89c1\u6307\u4ee4","text":"\u6307\u4ee4 \u4f5c\u7528 <code>FROM</code> \u6307\u5b9a\u57fa\u7840\u955c\u50cf <code>WORKDIR</code> \u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55 <code>COPY</code> \u590d\u5236\u672c\u5730\u6587\u4ef6\u5230\u955c\u50cf\u4e2d <code>ADD</code> \u590d\u5236\u6587\u4ef6\uff0c\u989d\u5916\u652f\u6301\u81ea\u52a8\u89e3\u538b\u548c URL\uff0c\u4e0d\u5efa\u8bae\u6ee5\u7528 <code>RUN</code> \u6784\u5efa\u955c\u50cf\u65f6\u6267\u884c\u547d\u4ee4 <code>CMD</code> \u5bb9\u5668\u542f\u52a8\u65f6\u9ed8\u8ba4\u6267\u884c\u7684\u547d\u4ee4 <code>ENTRYPOINT</code> \u5bb9\u5668\u542f\u52a8\u5165\u53e3\u547d\u4ee4 <code>ENV</code> \u8bbe\u7f6e\u73af\u5883\u53d8\u91cf <code>ARG</code> \u8bbe\u7f6e\u6784\u5efa\u53c2\u6570 <code>EXPOSE</code> \u58f0\u660e\u5bb9\u5668\u76d1\u542c\u7aef\u53e3 <code>VOLUME</code> \u58f0\u660e\u6302\u8f7d\u70b9 <code>USER</code> \u6307\u5b9a\u8fd0\u884c\u7528\u6237 <code>HEALTHCHECK</code> \u5b9a\u4e49\u5065\u5eb7\u68c0\u67e5"},{"location":"docker.html#3-cmd-entrypoint","title":"3. CMD \u548c ENTRYPOINT","text":"<p><code>CMD</code> \u63d0\u4f9b\u9ed8\u8ba4\u542f\u52a8\u547d\u4ee4\uff0c\u53ef\u4ee5\u88ab <code>docker run</code> \u540e\u9762\u7684\u547d\u4ee4\u8986\u76d6\u3002</p> <pre><code>CMD [\"node\", \"server.js\"]\n</code></pre> <p><code>ENTRYPOINT</code> \u66f4\u9002\u5408\u56fa\u5b9a\u5165\u53e3\u7a0b\u5e8f\uff0c<code>CMD</code> \u53ef\u4ee5\u4f5c\u4e3a\u9ed8\u8ba4\u53c2\u6570\u3002</p> <pre><code>ENTRYPOINT [\"node\"]\nCMD [\"server.js\"]\n</code></pre> <p>\u5b9e\u9645\u6267\u884c\u76f8\u5f53\u4e8e\uff1a</p> <pre><code>node server.js\n</code></pre>"},{"location":"docker.html#4_1","title":"4. \u6784\u5efa\u4e0a\u4e0b\u6587","text":"<p>\u6267\u884c\uff1a</p> <pre><code>docker build -t app .\n</code></pre> <p>\u6700\u540e\u7684 <code>.</code> \u8868\u793a\u6784\u5efa\u4e0a\u4e0b\u6587\u3002Docker \u4f1a\u628a\u4e0a\u4e0b\u6587\u4e2d\u7684\u6587\u4ef6\u53d1\u9001\u7ed9 Docker \u5f15\u64ce\uff0c\u518d\u6839\u636e Dockerfile \u6784\u5efa\u955c\u50cf\u3002</p> <p>\u56e0\u6b64\u5e94\u8be5\u4f7f\u7528 <code>.dockerignore</code> \u6392\u9664\u4e0d\u9700\u8981\u7684\u6587\u4ef6\uff1a</p> <pre><code>node_modules\n.git\n.env\ndist\ncoverage\n*.log\n</code></pre> <p>\u4e0d\u8981\u628a\u654f\u611f\u6587\u4ef6\u3001\u4f9d\u8d56\u7f13\u5b58\u3001\u5927\u578b\u6784\u5efa\u4ea7\u7269\u653e\u8fdb\u6784\u5efa\u4e0a\u4e0b\u6587\u3002</p>"},{"location":"docker.html#5_1","title":"5. \u955c\u50cf\u5206\u5c42\u548c\u7f13\u5b58","text":"<p>Dockerfile \u4e2d\u6bcf\u6761\u6307\u4ee4\u901a\u5e38\u4f1a\u751f\u6210\u4e00\u5c42\u955c\u50cf\u5c42\u3002Docker \u6784\u5efa\u65f6\u4f1a\u590d\u7528\u7f13\u5b58\u3002</p> <p>\u4f18\u5316\u793a\u4f8b\uff1a</p> <pre><code>COPY package*.json ./\nRUN npm ci\nCOPY . .\n</code></pre> <p>\u8fd9\u6837\u505a\u7684\u539f\u56e0\uff1a</p> <ul> <li>\u4f9d\u8d56\u6587\u4ef6\u4e0d\u53d8\u65f6\uff0c<code>npm ci</code> \u8fd9\u4e00\u5c42\u53ef\u4ee5\u590d\u7528\u7f13\u5b58\u3002</li> <li>\u4e1a\u52a1\u4ee3\u7801\u9891\u7e41\u53d8\u5316\u65f6\uff0c\u53ea\u4f1a\u91cd\u65b0\u6267\u884c\u540e\u9762\u7684\u590d\u5236\u548c\u6784\u5efa\u6b65\u9aa4\u3002</li> </ul>"},{"location":"docker.html#6_1","title":"6. \u591a\u9636\u6bb5\u6784\u5efa","text":"<p>\u591a\u9636\u6bb5\u6784\u5efa\u53ef\u4ee5\u628a\u7f16\u8bd1\u73af\u5883\u548c\u8fd0\u884c\u73af\u5883\u5206\u5f00\uff0c\u51cf\u5c11\u6700\u7ec8\u955c\u50cf\u4f53\u79ef\u3002</p> <pre><code>FROM node:20-alpine AS build\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci\nCOPY . .\nRUN npm run build\n\nFROM nginx:1.25-alpine\nCOPY --from=build /app/dist /usr/share/nginx/html\nEXPOSE 80\nCMD [\"nginx\", \"-g\", \"daemon off;\"]\n</code></pre> <p>\u4f18\u70b9\uff1a</p> <ul> <li>\u6700\u7ec8\u955c\u50cf\u4e0d\u5305\u542b\u6e90\u4ee3\u7801\u4f9d\u8d56\u548c\u6784\u5efa\u5de5\u5177\u3002</li> <li>\u955c\u50cf\u66f4\u5c0f\u3002</li> <li>\u653b\u51fb\u9762\u66f4\u5c0f\u3002</li> </ul>"},{"location":"docker.html#7-dockerfile","title":"7. Dockerfile \u6700\u4f73\u5b9e\u8df5","text":"<ul> <li>\u4f7f\u7528\u660e\u786e\u7248\u672c\u7684\u57fa\u7840\u955c\u50cf\uff0c\u4e0d\u968f\u610f\u4f7f\u7528 <code>latest</code>\u3002</li> <li>\u4f18\u5148\u4f7f\u7528\u5b98\u65b9\u955c\u50cf\u6216\u53ef\u4fe1\u955c\u50cf\u3002</li> <li>\u7528 <code>.dockerignore</code> \u51cf\u5c11\u6784\u5efa\u4e0a\u4e0b\u6587\u3002</li> <li>\u628a\u4f9d\u8d56\u5b89\u88c5\u6b65\u9aa4\u653e\u5728\u4ee3\u7801\u590d\u5236\u4e4b\u524d\uff0c\u63d0\u9ad8\u7f13\u5b58\u547d\u4e2d\u7387\u3002</li> <li>\u4f7f\u7528\u591a\u9636\u6bb5\u6784\u5efa\u51cf\u5c11\u955c\u50cf\u4f53\u79ef\u3002</li> <li>\u4e0d\u8981\u628a\u5bc6\u7801\u3001\u5bc6\u94a5\u3001Token \u5199\u5165\u955c\u50cf\u3002</li> <li>\u5bb9\u5668\u5185\u5e94\u7528\u65e5\u5fd7\u8f93\u51fa\u5230 stdout/stderr\u3002</li> <li>\u5c3d\u91cf\u4f7f\u7528\u975e root \u7528\u6237\u8fd0\u884c\u5e94\u7528\u3002</li> <li>\u6bcf\u4e2a\u5bb9\u5668\u53ea\u8fd0\u884c\u4e00\u4e2a\u4e3b\u8981\u8fdb\u7a0b\u3002</li> <li>\u5bf9\u5173\u952e\u670d\u52a1\u589e\u52a0\u5065\u5eb7\u68c0\u67e5\u3002</li> </ul>"},{"location":"docker.html#_2","title":"\u4e94\u3001\u6570\u636e\u6301\u4e45\u5316","text":""},{"location":"docker.html#1_2","title":"1. \u4e09\u79cd\u6302\u8f7d\u65b9\u5f0f","text":"\u7c7b\u578b \u8bf4\u660e \u5e38\u89c1\u7528\u9014 volume Docker \u7ba1\u7406\u7684\u6570\u636e\u5377 \u6570\u636e\u5e93\u6570\u636e\u3001\u6301\u4e45\u5316\u6587\u4ef6 bind mount \u5bbf\u4e3b\u673a\u8def\u5f84\u6302\u8f7d\u5230\u5bb9\u5668 \u672c\u5730\u5f00\u53d1\u3001\u914d\u7f6e\u6587\u4ef6\u6302\u8f7d tmpfs \u6570\u636e\u53ea\u5b58\u5728\u5185\u5b58\u4e2d \u4e34\u65f6\u654f\u611f\u6570\u636e\u3001\u7f13\u5b58"},{"location":"docker.html#2-volume","title":"2. volume \u793a\u4f8b","text":"<p>\u521b\u5efa volume\uff1a</p> <pre><code>docker volume create mysql-data\n</code></pre> <p>\u4f7f\u7528 volume\uff1a</p> <pre><code>docker run -d --name mysql \\\n  -e MYSQL_ROOT_PASSWORD=123456 \\\n  -v mysql-data:/var/lib/mysql \\\n  mysql:8\n</code></pre> <p>\u67e5\u770b volume\uff1a</p> <pre><code>docker volume ls\ndocker volume inspect mysql-data\n</code></pre>"},{"location":"docker.html#3-bind-mount","title":"3. bind mount \u793a\u4f8b","text":"<pre><code>docker run -d --name nginx \\\n  -p 8080:80 \\\n  -v \"$PWD/html:/usr/share/nginx/html\" \\\n  nginx\n</code></pre> <p>bind mount \u4f1a\u76f4\u63a5\u4f7f\u7528\u5bbf\u4e3b\u673a\u76ee\u5f55\u3002\u5f00\u53d1\u65f6\u5f88\u65b9\u4fbf\uff0c\u4f46\u751f\u4ea7\u73af\u5883\u8981\u6ce8\u610f\u6743\u9650\u548c\u8def\u5f84\u7a33\u5b9a\u6027\u3002</p>"},{"location":"docker.html#docker_3","title":"\u516d\u3001Docker \u7f51\u7edc","text":""},{"location":"docker.html#1_3","title":"1. \u67e5\u770b\u7f51\u7edc","text":"<pre><code>docker network ls\ndocker network inspect bridge\n</code></pre>"},{"location":"docker.html#2_2","title":"2. \u521b\u5efa\u81ea\u5b9a\u4e49\u7f51\u7edc","text":"<pre><code>docker network create app-net\n</code></pre> <p>\u8fd0\u884c\u5bb9\u5668\u5e76\u52a0\u5165\u7f51\u7edc\uff1a</p> <pre><code>docker run -d --name redis --network app-net redis:7\ndocker run -d --name app --network app-net my-app:1.0.0\n</code></pre> <p>\u5728\u540c\u4e00\u4e2a\u81ea\u5b9a\u4e49\u7f51\u7edc\u4e2d\uff0c\u5bb9\u5668\u53ef\u4ee5\u901a\u8fc7\u5bb9\u5668\u540d\u4e92\u76f8\u8bbf\u95ee\u3002</p> <p>\u4f8b\u5982\u5e94\u7528\u8fde\u63a5 Redis\uff1a</p> <pre><code>redis://redis:6379\n</code></pre> <p>\u8fd9\u91cc\u7684 <code>redis</code> \u662f\u5bb9\u5668\u540d\uff0c\u4e5f\u662f Docker \u5185\u90e8 DNS \u53ef\u4ee5\u89e3\u6790\u7684\u4e3b\u673a\u540d\u3002</p>"},{"location":"docker.html#3_1","title":"3. \u7aef\u53e3\u6620\u5c04","text":"<pre><code>docker run -p 8080:80 nginx\n</code></pre> <p>\u542b\u4e49\uff1a</p> <pre><code>\u5bbf\u4e3b\u673a\u7aef\u53e3:\u5bb9\u5668\u7aef\u53e3\n</code></pre> <p>\u8bbf\u95ee\u5bbf\u4e3b\u673a <code>8080</code> \u7aef\u53e3\uff0c\u4f1a\u8f6c\u53d1\u5230\u5bb9\u5668\u7684 <code>80</code> \u7aef\u53e3\u3002</p> <p>\u5982\u679c\u53ea\u5199\uff1a</p> <pre><code>docker run -p 80 nginx\n</code></pre> <p>Docker \u4f1a\u968f\u673a\u5206\u914d\u5bbf\u4e3b\u673a\u7aef\u53e3\u3002</p>"},{"location":"docker.html#docker-compose","title":"\u4e03\u3001Docker Compose","text":"<p>Docker Compose \u7528\u6765\u5b9a\u4e49\u548c\u8fd0\u884c\u591a\u5bb9\u5668\u5e94\u7528\u3002\u5b83\u901a\u5e38\u901a\u8fc7 <code>compose.yaml</code> \u6216 <code>docker-compose.yml</code> \u63cf\u8ff0\u670d\u52a1\u3001\u7f51\u7edc\u3001\u6570\u636e\u5377\u548c\u73af\u5883\u53d8\u91cf\u3002</p>"},{"location":"docker.html#1_4","title":"1. \u793a\u4f8b","text":"<pre><code>services:\n  web:\n    image: nginx:1.25-alpine\n    ports:\n      - \"8080:80\"\n    volumes:\n      - ./html:/usr/share/nginx/html:ro\n    depends_on:\n      - redis\n\n  redis:\n    image: redis:7-alpine\n    volumes:\n      - redis-data:/data\n\nvolumes:\n  redis-data:\n</code></pre> <p>\u542f\u52a8\uff1a</p> <pre><code>docker compose up -d\n</code></pre> <p>\u67e5\u770b\uff1a</p> <pre><code>docker compose ps\ndocker compose logs -f\n</code></pre> <p>\u505c\u6b62\u5e76\u5220\u9664\u5bb9\u5668\uff1a</p> <pre><code>docker compose down\n</code></pre> <p>\u5982\u679c\u8981\u540c\u65f6\u5220\u9664 volume\uff1a</p> <pre><code>docker compose down -v\n</code></pre>"},{"location":"docker.html#2-compose","title":"2. \u5e38\u7528 Compose \u547d\u4ee4","text":"<pre><code>docker compose up -d\ndocker compose down\ndocker compose ps\ndocker compose logs -f\ndocker compose exec web sh\ndocker compose build\ndocker compose pull\ndocker compose restart\n</code></pre>"},{"location":"docker.html#3-depends_on","title":"3. depends_on \u7684\u6ce8\u610f\u70b9","text":"<p><code>depends_on</code> \u53ea\u80fd\u63a7\u5236\u542f\u52a8\u987a\u5e8f\uff0c\u4e0d\u4e00\u5b9a\u4ee3\u8868\u4f9d\u8d56\u670d\u52a1\u5df2\u7ecf\u5b8c\u5168\u53ef\u7528\u3002</p> <p>\u4f8b\u5982\u6570\u636e\u5e93\u5bb9\u5668\u542f\u52a8\u4e86\uff0c\u4f46\u6570\u636e\u5e93\u670d\u52a1\u53ef\u80fd\u8fd8\u5728\u521d\u59cb\u5316\u3002\u66f4\u7a33\u59a5\u7684\u65b9\u5f0f\u662f\uff1a</p> <ul> <li>\u7ed9\u4f9d\u8d56\u670d\u52a1\u52a0 <code>healthcheck</code>\u3002</li> <li>\u5e94\u7528\u542f\u52a8\u65f6\u5b9e\u73b0\u91cd\u8bd5\u8fde\u63a5\u3002</li> <li>\u5728\u90e8\u7f72\u5e73\u53f0\u4e2d\u4f7f\u7528\u5065\u5eb7\u68c0\u67e5\u548c\u5c31\u7eea\u68c0\u67e5\u3002</li> </ul>"},{"location":"docker.html#_3","title":"\u516b\u3001\u955c\u50cf\u53d1\u5e03","text":""},{"location":"docker.html#1_5","title":"1. \u6253\u6807\u7b7e","text":"<pre><code>docker tag my-app:1.0.0 username/my-app:1.0.0\ndocker tag my-app:1.0.0 username/my-app:latest\n</code></pre>"},{"location":"docker.html#2_3","title":"2. \u767b\u5f55\u5e76\u63a8\u9001","text":"<pre><code>docker login\ndocker push username/my-app:1.0.0\ndocker push username/my-app:latest\n</code></pre>"},{"location":"docker.html#3_2","title":"3. \u955c\u50cf\u6807\u7b7e\u7b56\u7565","text":"<p>\u5e38\u89c1\u6807\u7b7e\uff1a</p> <ul> <li><code>v1.0.0</code>\uff1a\u8bed\u4e49\u5316\u7248\u672c\u3002</li> <li><code>1.0</code>\uff1a\u6b21\u7248\u672c\u3002</li> <li><code>latest</code>\uff1a\u6700\u65b0\u7a33\u5b9a\u7248\u672c\u3002</li> <li><code>git-commit-sha</code>\uff1a\u548c\u5177\u4f53\u4ee3\u7801\u63d0\u4ea4\u7ed1\u5b9a\u3002</li> <li><code>dev</code>\u3001<code>staging</code>\u3001<code>prod</code>\uff1a\u73af\u5883\u6807\u7b7e\uff0c\u4e0d\u5efa\u8bae\u4f5c\u4e3a\u552f\u4e00\u7248\u672c\u4f9d\u636e\u3002</li> </ul> <p>\u751f\u4ea7\u73af\u5883\u6700\u597d\u4f7f\u7528\u4e0d\u53ef\u53d8\u6807\u7b7e\uff0c\u4f8b\u5982 Git commit SHA \u6216\u660e\u786e\u7248\u672c\u53f7\uff0c\u65b9\u4fbf\u56de\u6eda\u548c\u5ba1\u8ba1\u3002</p>"},{"location":"docker.html#_4","title":"\u4e5d\u3001\u751f\u4ea7\u73af\u5883\u6ce8\u610f\u4e8b\u9879","text":""},{"location":"docker.html#1_6","title":"1. \u91cd\u542f\u7b56\u7565","text":"<pre><code>docker run -d --restart unless-stopped nginx\n</code></pre> <p>\u5e38\u89c1\u7b56\u7565\uff1a</p> \u7b56\u7565 \u542b\u4e49 <code>no</code> \u9ed8\u8ba4\uff0c\u4e0d\u81ea\u52a8\u91cd\u542f <code>always</code> \u603b\u662f\u81ea\u52a8\u91cd\u542f <code>unless-stopped</code> \u975e\u624b\u52a8\u505c\u6b62\u65f6\u81ea\u52a8\u91cd\u542f <code>on-failure</code> \u5f02\u5e38\u9000\u51fa\u65f6\u91cd\u542f"},{"location":"docker.html#2_4","title":"2. \u8d44\u6e90\u9650\u5236","text":"<pre><code>docker run -d --name app \\\n  --memory 512m \\\n  --cpus 1.5 \\\n  my-app:1.0.0\n</code></pre> <p>\u907f\u514d\u5355\u4e2a\u5bb9\u5668\u5360\u6ee1\u5bbf\u4e3b\u673a\u8d44\u6e90\u3002</p>"},{"location":"docker.html#3_3","title":"3. \u5065\u5eb7\u68c0\u67e5","text":"<p>Dockerfile \u793a\u4f8b\uff1a</p> <pre><code>HEALTHCHECK --interval=30s --timeout=3s --retries=3 \\\n  CMD wget -qO- http://localhost:3000/health || exit 1\n</code></pre> <p>\u5065\u5eb7\u68c0\u67e5\u53ef\u4ee5\u5e2e\u52a9\u90e8\u7f72\u7cfb\u7edf\u5224\u65ad\u5bb9\u5668\u662f\u5426\u771f\u7684\u53ef\u7528\u3002</p>"},{"location":"docker.html#4_2","title":"4. \u5b89\u5168\u5efa\u8bae","text":"<ul> <li>\u4e0d\u8981\u5728\u955c\u50cf\u4e2d\u4fdd\u5b58\u5bc6\u94a5\u3002</li> <li>\u4e0d\u8981\u628a Docker socket \u968f\u610f\u6302\u8f7d\u8fdb\u5bb9\u5668\u3002</li> <li>\u5c3d\u91cf\u4f7f\u7528\u975e root \u7528\u6237\u3002</li> <li>\u53ea\u5f00\u653e\u5fc5\u8981\u7aef\u53e3\u3002</li> <li>\u5b9a\u671f\u66f4\u65b0\u57fa\u7840\u955c\u50cf\u3002</li> <li>\u5bf9\u955c\u50cf\u505a\u6f0f\u6d1e\u626b\u63cf\u3002</li> <li>\u4f7f\u7528\u53ea\u8bfb\u6587\u4ef6\u7cfb\u7edf\u6216\u6700\u5c0f\u6743\u9650\u6302\u8f7d\u3002</li> <li>\u4f7f\u7528 <code>.dockerignore</code> \u907f\u514d\u628a <code>.env</code>\u3001\u79c1\u94a5\u3001\u6e90\u7801\u5386\u53f2\u6253\u8fdb\u955c\u50cf\u3002</li> </ul>"},{"location":"docker.html#_5","title":"\u5341\u3001\u5e38\u89c1\u95ee\u9898\u6392\u67e5","text":""},{"location":"docker.html#1_7","title":"1. \u5bb9\u5668\u542f\u52a8\u540e\u7acb\u523b\u9000\u51fa","text":"<p>\u67e5\u770b\u72b6\u6001\uff1a</p> <pre><code>docker ps -a\n</code></pre> <p>\u67e5\u770b\u65e5\u5fd7\uff1a</p> <pre><code>docker logs container-name\n</code></pre> <p>\u5e38\u89c1\u539f\u56e0\uff1a</p> <ul> <li>\u542f\u52a8\u547d\u4ee4\u9519\u8bef\u3002</li> <li>\u5e94\u7528\u914d\u7f6e\u7f3a\u5931\u3002</li> <li>\u7aef\u53e3\u88ab\u5360\u7528\u3002</li> <li>\u4f9d\u8d56\u670d\u52a1\u4e0d\u53ef\u7528\u3002</li> <li>\u7a0b\u5e8f\u8fd0\u884c\u540e\u76f4\u63a5\u7ed3\u675f\u3002</li> </ul>"},{"location":"docker.html#2_5","title":"2. \u7aef\u53e3\u65e0\u6cd5\u8bbf\u95ee","text":"<p>\u68c0\u67e5\u65b9\u5411\uff1a</p> <ul> <li>\u5bb9\u5668\u662f\u5426\u8fd0\u884c\uff1a<code>docker ps</code></li> <li>\u7aef\u53e3\u662f\u5426\u6620\u5c04\uff1a<code>docker ps</code> \u7684 <code>PORTS</code> \u5b57\u6bb5</li> <li>\u5e94\u7528\u662f\u5426\u76d1\u542c <code>0.0.0.0</code>\uff0c\u800c\u4e0d\u662f\u53ea\u76d1\u542c <code>127.0.0.1</code></li> <li>\u5bbf\u4e3b\u673a\u9632\u706b\u5899\u662f\u5426\u653e\u884c</li> <li>\u8bbf\u95ee\u7684\u5bbf\u4e3b\u673a\u7aef\u53e3\u662f\u5426\u6b63\u786e</li> </ul>"},{"location":"docker.html#3_4","title":"3. \u5bb9\u5668\u4e4b\u95f4\u65e0\u6cd5\u901a\u4fe1","text":"<p>\u68c0\u67e5\u65b9\u5411\uff1a</p> <ul> <li>\u662f\u5426\u5728\u540c\u4e00\u4e2a Docker network\u3002</li> <li>\u662f\u5426\u4f7f\u7528\u4e86\u6b63\u786e\u7684\u5bb9\u5668\u540d\u6216\u670d\u52a1\u540d\u3002</li> <li>\u76ee\u6807\u670d\u52a1\u7aef\u53e3\u662f\u5426\u6b63\u786e\u3002</li> <li>\u670d\u52a1\u662f\u5426\u5df2\u7ecf\u542f\u52a8\u5b8c\u6210\u3002</li> </ul>"},{"location":"docker.html#4_3","title":"4. \u6570\u636e\u4e22\u5931","text":"<p>\u5e38\u89c1\u539f\u56e0\uff1a</p> <ul> <li>\u6570\u636e\u5199\u5728\u5bb9\u5668\u5185\u90e8\uff0c\u6ca1\u6709\u6302\u8f7d volume\u3002</li> <li>\u6267\u884c\u4e86 <code>docker compose down -v</code> \u5220\u9664\u4e86 volume\u3002</li> <li>\u6302\u8f7d\u8def\u5f84\u5199\u9519\uff0c\u5bfc\u81f4\u6570\u636e\u5199\u5230\u522b\u7684\u4f4d\u7f6e\u3002</li> </ul> <p>\u6570\u636e\u5e93\u7c7b\u670d\u52a1\u5fc5\u987b\u786e\u8ba4\u6570\u636e\u76ee\u5f55\u5df2\u7ecf\u6302\u8f7d\u5230 volume\u3002</p>"},{"location":"docker.html#5_2","title":"5. \u78c1\u76d8\u7a7a\u95f4\u4e0d\u8db3","text":"<p>\u67e5\u770b\u5360\u7528\uff1a</p> <pre><code>docker system df\n</code></pre> <p>\u6e05\u7406\u672a\u4f7f\u7528\u8d44\u6e90\uff1a</p> <pre><code>docker system prune\n</code></pre> <p>\u5982\u679c\u8981\u6e05\u7406\u672a\u4f7f\u7528 volume\uff1a</p> <pre><code>docker volume prune\n</code></pre> <p>\u6267\u884c\u524d\u8981\u786e\u8ba4\u4e0d\u4f1a\u5220\u9664\u4ecd\u7136\u9700\u8981\u7684\u6570\u636e\u3002</p>"},{"location":"docker.html#_6","title":"\u5341\u4e00\u3001\u5e38\u7528\u5de5\u4f5c\u6d41","text":""},{"location":"docker.html#1_8","title":"1. \u672c\u5730\u5f00\u53d1","text":"<pre><code>\u7f16\u5199\u4ee3\u7801\n  -&gt; \u7f16\u5199 Dockerfile\n  -&gt; docker build \u6784\u5efa\u955c\u50cf\n  -&gt; docker run \u672c\u5730\u9a8c\u8bc1\n  -&gt; docker compose \u7ba1\u7406\u591a\u670d\u52a1\u73af\u5883\n</code></pre>"},{"location":"docker.html#2_6","title":"2. \u90e8\u7f72\u5e94\u7528","text":"<pre><code>\u63d0\u4ea4\u4ee3\u7801\n  -&gt; CI \u6784\u5efa\u955c\u50cf\n  -&gt; \u8fd0\u884c\u6d4b\u8bd5\n  -&gt; \u63a8\u9001\u955c\u50cf\u4ed3\u5e93\n  -&gt; \u670d\u52a1\u5668\u62c9\u53d6\u955c\u50cf\n  -&gt; \u542f\u52a8\u6216\u6eda\u52a8\u66f4\u65b0\u5bb9\u5668\n</code></pre>"},{"location":"docker.html#3_5","title":"3. \u5b66\u4e60\u91cd\u70b9","text":"<ul> <li>\u7406\u89e3\u955c\u50cf\u548c\u5bb9\u5668\u7684\u533a\u522b\u3002</li> <li>\u719f\u6089 <code>docker run</code>\u3001<code>docker ps</code>\u3001<code>docker logs</code>\u3001<code>docker exec</code>\u3002</li> <li>\u4f1a\u5199\u57fa\u7840 Dockerfile\u3002</li> <li>\u4f1a\u4f7f\u7528 volume \u4fdd\u5b58\u6570\u636e\u3002</li> <li>\u4f1a\u4f7f\u7528\u7f51\u7edc\u8fde\u63a5\u591a\u4e2a\u5bb9\u5668\u3002</li> <li>\u4f1a\u7528 Docker Compose \u7f16\u6392\u672c\u5730\u670d\u52a1\u3002</li> <li>\u77e5\u9053\u5982\u4f55\u67e5\u770b\u65e5\u5fd7\u3001\u7aef\u53e3\u3001\u7f51\u7edc\u548c\u78c1\u76d8\u5360\u7528\u3002</li> </ul>"},{"location":"say.html","title":"\u60f3\u8bf4\u7684\u8bdd","text":"<p>      \u4f60\u770b\u770b           \u518d\u770b\u770b       \u8fd9\u5176\u5b9e\u662f\u4e00\u4e2a\u7a7a\u67b6\u5b50</p>"},{"location":"vibecoding.html","title":"Vibe Coding \u4e0e Agent \u5b66\u4e60\u8def\u7ebf","text":"<p>\u8fd9\u4efd\u7b14\u8bb0\u6309\u56fe\u7247\u4e2d\u7684\u77e5\u8bc6\u5730\u56fe\u6574\u7406\u3002\u56fe\u91cc\u7684\u989c\u8272\u4ee3\u8868\u5b66\u4e60\u4f18\u5148\u7ea7\uff1a</p> <ul> <li>\u5fc5\u987b\u638c\u63e1\uff1a\u4e3b\u7ebf\u80fd\u529b\uff0c\u5148\u5b66\u8fd9\u4e9b\u3002</li> <li>\u5efa\u8bae\u638c\u63e1\uff1a\u80fd\u660e\u663e\u63d0\u5347\u6548\u679c\uff0c\u4f46\u53ef\u4ee5\u5728\u4e3b\u7ebf\u8dd1\u901a\u540e\u8865\u3002</li> <li>\u8fdb\u9636\u62d3\u5c55\uff1a\u66f4\u6df1\u5165\u7684\u5de5\u7a0b\u5316\u3001\u81ea\u52a8\u5316\u548c\u591a\u667a\u80fd\u4f53\u5185\u5bb9\u3002</li> <li>\u7efc\u5408\u6848\u4f8b\uff1a\u628a\u524d\u9762\u7684\u80fd\u529b\u7ec4\u5408\u8d77\u6765\u505a\u4e00\u4e2a\u5b8c\u6574\u9879\u76ee\u3002</li> </ul> <p>\u7bad\u5934\u5173\u7cfb\u4e5f\u6709\u542b\u4e49\uff1a</p> <ul> <li>\u5b9e\u7ebf\u7bad\u5934\uff1a\u4f9d\u8d56\u5173\u7cfb\uff0c\u540e\u9762\u7684\u5185\u5bb9\u901a\u5e38\u9700\u8981\u524d\u9762\u7684\u57fa\u7840\u3002</li> <li>\u865a\u7ebf\u7bad\u5934\uff1a\u8865\u5145\u5173\u7cfb\uff0c\u9002\u5408\u5728\u4e3b\u7ebf\u4e4b\u5916\u6269\u5c55\u3002</li> <li>\u865a\u7ebf\u6846\uff1a\u4f60\u4f1a\u638c\u63e1\u7684\u6982\u5ff5\uff0c\u4f46\u56fe\u4e2d\u6ca1\u6709\u7ee7\u7eed\u5c55\u5f00\u5b50\u6587\u6863\u3002</li> </ul>"},{"location":"vibecoding.html#_1","title":"\u603b\u89c8","text":"<p>\u6574\u5f20\u56fe\u53ef\u4ee5\u62c6\u6210\u4e09\u6761\u8def\u7ebf\uff1a</p> <ol> <li>\u5982\u4f55\u505a\u597d Vibe Coding\uff1a\u4ece\u5927\u6a21\u578b\u539f\u7406\u3001\u5f00\u53d1\u5de5\u5177\u3001\u63d0\u793a\u8bcd\u5de5\u7a0b\u5f00\u59cb\uff0c\u9010\u6b65\u8fdb\u5165 MVP\u3001\u8fed\u4ee3\u5f00\u53d1\u3001\u4e0a\u4e0b\u6587\u7ba1\u7406\u3001RAG\u3001SubAgent \u548c Agent Team\u3002</li> <li>\u540d\u8bcd\u6982\u5ff5\u901f\u901a\uff1a\u4ece LLM\u3001Function Calling \u8bb2\u5230 Agent\u3001SubAgent\u3001MCP\u3001Workflow\u3001Langchain\u3001RAG \u548c Skill\u3002</li> <li>DataWhale: hello-agent\uff1a\u4ece\u667a\u80fd\u4f53\u57fa\u7840\u4e00\u8def\u5230\u4e3b\u6d41\u6846\u67b6\u5b9e\u8df5\u3001\u6027\u80fd\u8bc4\u4f30\u3001\u901a\u4fe1\u534f\u8bae\u3001\u8bb0\u5fc6\u68c0\u7d22\u3001\u4e0a\u4e0b\u6587\u5de5\u7a0b\u548c\u7efc\u5408\u6848\u4f8b\u3002</li> </ol>"},{"location":"vibecoding.html#vibe-coding","title":"\u5982\u4f55\u505a\u597d Vibe Coding","text":""},{"location":"vibecoding.html#1","title":"1. \u5927\u6a21\u578b\u539f\u7406","text":"<p>Vibe Coding \u7684\u8d77\u70b9\u4e0d\u662f\u5de5\u5177\uff0c\u800c\u662f\u7406\u89e3\u5927\u6a21\u578b\u7684\u57fa\u672c\u5de5\u4f5c\u65b9\u5f0f\u3002\u81f3\u5c11\u8981\u77e5\u9053\u6a21\u578b\u4e3a\u4ec0\u4e48\u4f1a\u751f\u6210\u4ee3\u7801\u3001\u4e3a\u4ec0\u4e48\u4f1a\u51fa\u9519\u3001\u4e3a\u4ec0\u4e48\u9700\u8981\u4e0a\u4e0b\u6587\uff0c\u4ee5\u53ca\u4e3a\u4ec0\u4e48\u540c\u4e00\u4e2a\u95ee\u9898\u5728\u4e0d\u540c\u6a21\u578b\u4e0a\u6548\u679c\u5dee\u5f02\u5f88\u5927\u3002</p> <p>\u5efa\u8bae\u8865\u5145\uff1a</p> <ul> <li>\u591a\u6a21\u578b\u534f\u540c\uff1a\u53d1\u6325\u6bcf\u4e2a\u6a21\u578b\u7684\u4f18\u52bf\u3002\u6bd4\u5982\u4e00\u4e2a\u6a21\u578b\u9002\u5408\u5199\u4ee3\u7801\uff0c\u53e6\u4e00\u4e2a\u6a21\u578b\u9002\u5408\u89e3\u91ca\u3001\u5ba1\u67e5\u6216\u751f\u6210\u6587\u6863\u3002</li> </ul> <p>\u4ece\u5927\u6a21\u578b\u539f\u7406\u5f80\u4e0b\uff0c\u4f1a\u8fdb\u5165\u5f00\u53d1\u5de5\u5177\u4f53\u7cfb\u3002</p>"},{"location":"vibecoding.html#2","title":"2. \u5f00\u53d1\u5de5\u5177\u5927\u5168","text":"<p>\u5f00\u53d1\u5de5\u5177\u662f Vibe Coding \u7684\u653e\u5927\u5668\u3002\u56fe\u4e2d\u628a\u5b83\u6807\u6210\u201c\u4f60\u5c06\u638c\u63e1\u7684\u6982\u5ff5\u201d\uff0c\u8bf4\u660e\u5b83\u662f\u4e00\u4e2a\u5de5\u5177\u5165\u53e3\uff0c\u4e0d\u662f\u5355\u4e2a\u77e5\u8bc6\u70b9\u3002</p> <p>\u5de5\u5177\u5f62\u5f0f\u5f88\u591a\uff0c\u4e3b\u8981\u5305\u62ec\uff1a</p> <ul> <li>CLI \u7efc\u8ff0\uff1a\u547d\u4ee4\u884c\u91cc\u7684 AI \u7f16\u7a0b\u5de5\u5177\u3002</li> <li>\u63d2\u4ef6\u7efc\u8ff0\uff1a\u7f16\u8f91\u5668\u6216\u6d4f\u89c8\u5668\u63d2\u4ef6\u3002</li> <li>IDE \u7efc\u8ff0\uff1a\u96c6\u6210\u5728\u5f00\u53d1\u73af\u5883\u91cc\u7684 AI \u80fd\u529b\u3002</li> <li>workflow \u7efc\u8ff0\uff1a\u628a\u56fa\u5b9a\u6d41\u7a0b\u81ea\u52a8\u5316\uff0c\u5c5e\u4e8e\u8fdb\u9636\u62d3\u5c55\u3002</li> </ul> <p>\u5de5\u5177\u589e\u5f3a\u65b9\u5411\uff1a</p> <ul> <li>MCP\uff1a\u8ba9\u6a21\u578b\u80fd\u63a5\u5165\u5916\u90e8\u5de5\u5177\u3001\u8d44\u6e90\u548c\u63d0\u793a\u8bcd\u6a21\u677f\u3002</li> <li>Skill\uff1a\u628a\u56fa\u5b9a\u80fd\u529b\u5c01\u88c5\u6210\u53ef\u590d\u7528\u7684\u64cd\u4f5c\u8bf4\u660e\u6216\u5de5\u5177\u80fd\u529b\u3002</li> <li>MCP \u5de5\u5177\u63a8\u8350\uff1a\u4f5c\u4e3a MCP \u7684\u8865\u5145\u5185\u5bb9\uff0c\u5e2e\u52a9\u9009\u62e9\u53ef\u7528\u5de5\u5177\u3002</li> </ul>"},{"location":"vibecoding.html#3-vibe-coding","title":"3. Vibe Coding \u8303\u5f0f\u5bfc\u8bba","text":"<p>\u9009\u597d\u5de5\u5177\u540e\uff0c\u8fdb\u5165 Vibe Coding \u7684\u57fa\u672c\u8303\u5f0f\u3002</p> <p>\u6838\u5fc3\u95ee\u9898\u662f\uff1a\u5982\u4f55\u63cf\u8ff0\u9700\u6c42\uff1f</p> <p>\u4e0d\u8981\u53ea\u8bf4\u201c\u5e2e\u6211\u505a\u4e00\u4e2a\u529f\u80fd\u201d\uff0c\u800c\u662f\u8981\u63cf\u8ff0\u6e05\u695a\uff1a</p> <ul> <li>\u76ee\u6807\u662f\u4ec0\u4e48\u3002</li> <li>\u7528\u6237\u4f1a\u770b\u5230\u4ec0\u4e48\u3002</li> <li>\u8f93\u5165\u548c\u8f93\u51fa\u662f\u4ec0\u4e48\u3002</li> <li>\u54ea\u4e9b\u6587\u4ef6\u6216\u6a21\u5757\u76f8\u5173\u3002</li> <li>\u54ea\u4e9b\u884c\u4e3a\u4e0d\u80fd\u88ab\u7834\u574f\u3002</li> <li>\u4ec0\u4e48\u7ed3\u679c\u7b97\u5b8c\u6210\u3002</li> </ul>"},{"location":"vibecoding.html#4","title":"4. \u63d0\u793a\u8bcd\u5de5\u7a0b","text":"<p>\u63d0\u793a\u8bcd\u5de5\u7a0b\u7684\u91cd\u70b9\u4e0d\u662f\u5199\u82b1\u54e8\u7684\u8bdd\uff0c\u800c\u662f\u5148\u5efa\u7acb\u603b\u4f53\u6846\u67b6\u3002</p> <p>\u4e00\u4e2a\u6709\u6548\u63d0\u793a\u8bcd\u901a\u5e38\u5305\u542b\uff1a</p> <ul> <li>\u80cc\u666f\uff1a\u9879\u76ee\u662f\u4ec0\u4e48\uff0c\u5f53\u524d\u72b6\u6001\u662f\u4ec0\u4e48\u3002</li> <li>\u76ee\u6807\uff1a\u8981\u5b9e\u73b0\u4ec0\u4e48\u3002</li> <li>\u7ea6\u675f\uff1a\u4e0d\u80fd\u6539\u4ec0\u4e48\uff0c\u5fc5\u987b\u9075\u5b88\u4ec0\u4e48\u3002</li> <li>\u9a8c\u6536\uff1a\u5982\u4f55\u5224\u65ad\u4efb\u52a1\u5b8c\u6210\u3002</li> </ul> <p>\u5148\u8ba9\u6a21\u578b\u7406\u89e3\u5168\u5c40\uff0c\u518d\u8ba9\u5b83\u5904\u7406\u5c40\u90e8\u3002\u8fd9\u6837\u66f4\u5bb9\u6613\u51cf\u5c11\u8dd1\u504f\u548c\u53cd\u590d\u8fd4\u5de5\u3002</p>"},{"location":"vibecoding.html#5","title":"5. \u6700\u5c0f\u53ef\u884c\u4ea7\u54c1","text":"<p>\u63d0\u793a\u8bcd\u4e4b\u540e\u5148\u505a MVP\uff0c\u4e5f\u5c31\u662f\u6700\u5c0f\u53ef\u884c\u4ea7\u54c1\u3002</p> <p>MVP \u7684\u76ee\u6807\u4e0d\u662f\u5b8c\u7f8e\uff0c\u800c\u662f\u5c3d\u5feb\u5f97\u5230\u4e00\u4e2a\u53ef\u4ee5\u8fd0\u884c\u3001\u53ef\u4ee5\u9a8c\u8bc1\u7684\u7248\u672c\u3002\u9700\u8981\u6ce8\u610f\uff1a\u6a21\u578b\u8f93\u51fa\u4e0d\u4e00\u5b9a\u6b63\u786e\uff0c\u56e0\u6b64\u8981\u8865\u4e0a\uff1a</p> <ul> <li>\u4ee3\u7801\u5ba1\u6838\u4e0e\u5e7b\u89c9\u8bc6\u522b\uff1a\u68c0\u67e5 API \u662f\u5426\u771f\u5b9e\u5b58\u5728\u3001\u903b\u8f91\u662f\u5426\u5408\u7406\u3001\u8fb9\u754c\u60c5\u51b5\u662f\u5426\u88ab\u5904\u7406\u3002</li> </ul>"},{"location":"vibecoding.html#6","title":"6. \u8fed\u4ee3\u5f0f\u5f00\u53d1\u5faa\u73af","text":"<p>\u4e00\u8f6e\u5bf9\u8bdd\u5f80\u5f80\u4e0d\u591f\u8fbe\u5230\u76ee\u6807\u3002Vibe Coding \u66f4\u50cf\u662f\u5faa\u73af\uff1a</p> <ol> <li>\u63cf\u8ff0\u9700\u6c42\u3002</li> <li>\u751f\u6210\u7b2c\u4e00\u7248\u3002</li> <li>\u8fd0\u884c\u6216\u9605\u8bfb\u7ed3\u679c\u3002</li> <li>\u6307\u51fa\u5177\u4f53\u95ee\u9898\u3002</li> <li>\u7ee7\u7eed\u4fee\u6539\u3002</li> </ol> <p>\u8fdb\u9636\u62d3\u5c55\uff1a</p> <ul> <li>Hooks\uff1a\u628a\u4e00\u4e9b\u53cd\u590d\u64cd\u4f5c\u81ea\u52a8\u5316\uff0c\u6bd4\u5982\u683c\u5f0f\u5316\u3001\u6d4b\u8bd5\u3001\u6784\u5efa\u3001\u751f\u6210\u6458\u8981\u7b49\u3002</li> </ul> <p>\u8fed\u4ee3\u591a\u4e86\u4ee5\u540e\uff0c\u4e0a\u4e0b\u6587\u4f1a\u8d8a\u6765\u8d8a\u591a\uff0c\u56e0\u6b64\u9700\u8981\u7ee7\u7eed\u5b66\u4e60\uff1a</p> <ul> <li>\u4e0a\u4e0b\u6587\u7ba1\u7406\u548c\u4ee3\u7801\u8d28\u91cf\uff1a\u63a7\u5236\u6a21\u578b\u770b\u5230\u7684\u4fe1\u606f\uff0c\u907f\u514d\u4e0a\u4e0b\u6587\u6df7\u4e71\u3002</li> <li>RAG\uff1a\u63d0\u4f9b\u66f4\u597d\u7684\u4e0a\u4e0b\u6587\uff0c\u8ba9\u6a21\u578b\u80fd\u68c0\u7d22\u9879\u76ee\u8d44\u6599\u3001\u6587\u6863\u6216\u4ee3\u7801\u7247\u6bb5\u3002</li> <li>SubAgent\uff1a\u628a\u4e00\u90e8\u5206\u4efb\u52a1\u4ea4\u7ed9\u72ec\u7acb\u4e0a\u4e0b\u6587\u7684\u5b50\u667a\u80fd\u4f53\u5904\u7406\u3002</li> <li>Agent Team\uff1a\u591a\u4e2a Agent \u534f\u4f5c\u5b8c\u6210\u66f4\u590d\u6742\u7684\u4efb\u52a1\u3002</li> </ul> <p>\u8fd8\u6709\u4e00\u4e2a\u5e38\u89c1\u95ee\u9898\uff1a\u4e00\u5f00\u59cb\u5c31\u53cd\u590d\u6f84\u6e05\u9700\u6c42\uff0c\u4f1a\u5f97\u5230\u9700\u6c42\u6587\u6863\u3001\u8bbe\u8ba1\u6587\u6863\u548c\u6d41\u7a0b\u6587\u6863\uff0c\u5bb9\u6613\u4ea7\u751f\u5927\u91cf\u5197\u4f59\u5de5\u4f5c\u3002\u53ef\u4ee5\u901a\u8fc7\uff1a</p> <ul> <li>\u81ea\u7136\u8bed\u8a00\u7f16\u7a0b\u89c4\u8303\uff1a\u628a\u9700\u6c42\u63cf\u8ff0\u3001\u8bbe\u8ba1\u3001\u9a8c\u6536\u6807\u51c6\u5199\u5f97\u66f4\u7a33\u5b9a\uff0c\u51cf\u5c11\u91cd\u590d\u6c9f\u901a\u3002</li> </ul>"},{"location":"vibecoding.html#_2","title":"\u540d\u8bcd\u6982\u5ff5\u901f\u901a","text":""},{"location":"vibecoding.html#1-llm-agent","title":"1. \u4ece LLM \u5230 Agent","text":"<p>\u7406\u89e3 Agent \u8981\u4ece LLM \u8bf4\u8d77\u3002</p> <p>LLM \u672c\u8eab\u53ea\u4f1a\u6839\u636e\u4e0a\u4e0b\u6587\u751f\u6210\u6587\u672c\u3002\u5982\u679c\u5927\u6a21\u578b\u60f3\u4e0a\u7f51\u67e5\u8d44\u6599\u3001\u8c03\u7528\u5de5\u5177\u6216\u8bfb\u53d6\u5916\u90e8\u6570\u636e\uff0c\u5c31\u9700\u8981\u4e00\u79cd\u673a\u5236\u628a\u201c\u60f3\u505a\u7684\u52a8\u4f5c\u201d\u53d8\u6210\u771f\u5b9e\u64cd\u4f5c\u3002</p> <p>\u8fd9\u4e2a\u673a\u5236\u5c31\u662f\uff1a</p> <ul> <li>Function Calling\uff1a\u6a21\u578b\u8f93\u51fa\u7ed3\u6784\u5316\u8c03\u7528\u610f\u56fe\uff0c\u7531\u5916\u90e8\u7a0b\u5e8f\u89e3\u6790\u5e76\u6267\u884c\u3002</li> </ul> <p>\u63a5\u7740\u4f1a\u9047\u5230\u95ee\u9898\uff1a\u8c01\u6765\u89e3\u6790 Function Calling\uff1f</p> <p>\u7b54\u6848\u5c31\u662f\uff1a</p> <ul> <li>Agent\uff1a\u8d1f\u8d23\u89c4\u5212\u3001\u8c03\u7528\u5de5\u5177\u3001\u8bfb\u53d6\u7ed3\u679c\u3001\u7ee7\u7eed\u63a8\u7406\uff0c\u5e76\u628a\u591a\u4e2a\u6b65\u9aa4\u4e32\u8d77\u6765\u3002</li> </ul> <p>\u5982\u679c\u4efb\u52a1\u592a\u590d\u6742\uff0c\u6216\u8005\u4e0d\u540c\u4efb\u52a1\u4e4b\u95f4\u9700\u8981\u9694\u79bb\u4e0a\u4e0b\u6587\uff0c\u5c31\u9700\u8981\uff1a</p> <ul> <li>SubAgent\uff1a\u7528\u72ec\u7acb\u4e0a\u4e0b\u6587\u5904\u7406\u5c40\u90e8\u4efb\u52a1\uff0c\u51cf\u5c11\u4e3b\u4e0a\u4e0b\u6587\u6c61\u67d3\u3002</li> </ul>"},{"location":"vibecoding.html#2-mcp","title":"2. MCP \u53ca\u5176\u4e09\u5927\u539f\u8bed","text":"<p>\u5bf9\u4e8e\u4e00\u4e9b\u6bd4\u8f83\u56fa\u5316\u7684\u64cd\u4f5c\uff0cAgent \u76f4\u63a5\u81ea\u7531\u53d1\u6325\u4e0d\u7a33\u5b9a\u3002\u8fd9\u65f6\u53ef\u4ee5\u7528 MCP \u628a\u80fd\u529b\u6807\u51c6\u5316\u3002</p> <p>MCP \u4e3b\u8981\u63d0\u4f9b\u4e09\u7c7b\u539f\u8bed\uff1a</p> <ul> <li>Tool\uff1a\u5de5\u5177\u8c03\u7528\u3002Agent \u53ef\u4ee5\u901a\u8fc7 Tool \u4f7f\u7528\u8054\u7f51\u641c\u7d22\u3001\u6570\u636e\u5e93\u3001\u6587\u4ef6\u7cfb\u7edf\u3001API \u7b49\u80fd\u529b\uff0c\u83b7\u53d6\u6570\u636e\u6216\u6267\u884c\u52a8\u4f5c\u3002</li> <li>Resource\uff1a\u8d44\u6e90\u8bfb\u53d6\u3002\u7ed9 Agent \u63d0\u4f9b\u6587\u6863\u3001\u6570\u636e\u3001\u9879\u76ee\u4e0a\u4e0b\u6587\u7b49\u53ef\u8bfb\u53d6\u8d44\u6e90\u3002</li> <li>Prompt\uff1a\u63d0\u793a\u8bcd\u6a21\u677f\u3002\u590d\u7528\u7a33\u5b9a\u7684\u63d0\u793a\u8bcd\u7ed3\u6784\uff0c\u51cf\u5c11\u91cd\u590d\u5199\u63d0\u793a\u8bcd\u3002</li> </ul> <p>\u8fd9\u4e9b\u80fd\u529b\u7531\uff1a</p> <ul> <li>MCP Server \u63d0\u4f9b\u3002</li> </ul> <p>Tool \u8fd8\u53ef\u4ee5\u7528\u6765\u589e\u5f3a\u4e0a\u4e0b\u6587\uff1a</p> <ul> <li>RAG\uff1a\u8ba9 Agent \u68c0\u7d22\u76f8\u5173\u8d44\u6599\uff0c\u518d\u628a\u68c0\u7d22\u7ed3\u679c\u653e\u5165\u4e0a\u4e0b\u6587\u3002</li> </ul>"},{"location":"vibecoding.html#3-workflowlangchain-skill","title":"3. Workflow\u3001Langchain \u4e0e Skill","text":"<p>\u5982\u679c\u67d0\u4e9b\u64cd\u4f5c\u6bd4\u8f83\u56fa\u5b9a\uff0c\u4f46\u76f4\u63a5\u4ea4\u7ed9 Agent \u53c8\u4e0d\u7a33\u5b9a\uff0c\u53ef\u4ee5\u628a\u5b83\u4eec\u505a\u6210 Workflow\u3002</p> <p>Workflow \u7684\u8def\u7ebf\uff1a</p> <ul> <li>workflow\uff1a\u628a\u7a33\u5b9a\u6d41\u7a0b\u5199\u51fa\u6765\u3002</li> <li>\u5de5\u4f5c\u6d41\u8bbe\u8ba1 / ReAct \u7b49\uff1a\u8bbe\u8ba1\u201c\u601d\u8003\u3001\u884c\u52a8\u3001\u89c2\u5bdf\u201d\u7684\u5faa\u73af\u3002</li> <li>Langchain\uff1a\u7528\u6846\u67b6\u5b9e\u73b0 Agent \u5de5\u4f5c\u6d41\u3002</li> <li>\u591a\u4ee3\u7406\u7cfb\u7edf / LangGraph \u7b49\uff1a\u8fdb\u9636\u5230\u591a Agent \u7f16\u6392\u3002</li> <li>\u53ef\u89c6\u5316\u7f16\u6392\uff1a\u5f53\u4ee3\u7801\u592a\u96be\u65f6\uff0c\u7528\u53ef\u89c6\u5316\u65b9\u5f0f\u7ec4\u7ec7\u6d41\u7a0b\u3002</li> <li>Skill\uff1a\u5f53\u64cd\u4f5c\u592a\u7ec6\uff0c\u6bd4\u5982\u533a\u5206\u6587\u4ef6\u683c\u5f0f\u3001\u9009\u62e9\u5de5\u5177\u548c\u6587\u6863\u65f6\uff0c\u628a\u80fd\u529b\u5c01\u88c5\u6210 Skill\uff0c\u8ba9 Agent \u81ea\u7531\u9009\u53d6\u3002</li> </ul>"},{"location":"vibecoding.html#datawhale-hello-agent","title":"DataWhale: hello-agent \u8def\u7ebf","text":"<p>\u8fd9\u6761\u8def\u7ebf\u66f4\u50cf\u7cfb\u7edf\u8bfe\u7a0b\uff0c\u4ece\u57fa\u7840\u5230\u6848\u4f8b\u9010\u6b65\u63a8\u8fdb\u3002</p>"},{"location":"vibecoding.html#1_1","title":"1. \u57fa\u7840\u4e3b\u7ebf","text":"<p>\u5148\u6309\u987a\u5e8f\u638c\u63e1\uff1a</p> <ol> <li>\u521d\u8bc6\u667a\u80fd\u4f53</li> <li>\u667a\u80fd\u4f53\u53d1\u5c55\u53f2</li> <li>\u5927\u8bed\u8a00\u6a21\u578b\u57fa\u7840</li> <li>\u667a\u80fd\u4f53\u7ecf\u5178\u8303\u5f0f\u6784\u5efa</li> </ol> <p>\u5176\u4e2d\u201c\u521d\u8bc6\u667a\u80fd\u4f53\u201d\u5230\u201c\u667a\u80fd\u4f53\u53d1\u5c55\u53f2\u201d\u4e4b\u95f4\uff0c\u91cd\u70b9\u662f\u7406\u89e3\u6280\u672f\u53d1\u5c55\u8109\u7edc\u3002</p>"},{"location":"vibecoding.html#2_1","title":"2. \u6846\u67b6\u4e0e\u5b9e\u8df5","text":"<p>\u5f53\u4ee3\u7801\u592a\u96be\u65f6\uff0c\u53ef\u4ee5\u5148\u8bd5\u8bd5\u62d6\u62fd\u5f0f\u6216\u4f4e\u4ee3\u7801\u8def\u7ebf\uff1a</p> <ul> <li>\u57fa\u4e8e\u4f4e\u4ee3\u7801\u5e73\u53f0\u5f00\u53d1\u7684\u667a\u80fd\u4f53\u642d\u5efa</li> </ul> <p>\u4e3b\u7ebf\u4ecd\u7136\u8981\u8fdb\u5165\uff1a</p> <ol> <li>\u4e3b\u6d41\u6846\u67b6\u5f00\u53d1\u5b9e\u8df5</li> <li>\u6784\u5efa\u4f60\u7684 Agent \u6846\u67b6</li> <li>\u667a\u80fd\u4f53\u6027\u80fd\u8bc4\u4f30</li> </ol>"},{"location":"vibecoding.html#3","title":"3. \u8bb0\u5fc6\u3001\u68c0\u7d22\u4e0e\u4e0a\u4e0b\u6587","text":"<p>\u591a\u8f6e\u5bf9\u8bdd\u9700\u8981\u8bb0\u5fc6\uff0c\u4f46\u5149\u6709\u8bb0\u5fc6\u8fd8\u4e0d\u591f\uff0c\u8fd8\u9700\u8981\u65b9\u6cd5\u6784\u5efa\u4e0a\u4e0b\u6587\uff1a</p> <ol> <li>\u8bb0\u5fc6\u4e0e\u68c0\u7d22</li> <li>\u4e0a\u4e0b\u6587\u5de5\u7a0b</li> </ol> <p>\u4e0a\u4e0b\u6587\u5de5\u7a0b\u7684\u76ee\u6807\u662f\u8ba9 Agent \u5728\u957f\u4efb\u52a1\u91cc\u4fdd\u7559\u5173\u952e\u4fe1\u606f\uff0c\u5e76\u80fd\u627e\u56de\u9700\u8981\u7684\u8d44\u6599\u3002</p>"},{"location":"vibecoding.html#4_1","title":"4. \u5de5\u5177\u3001\u534f\u8bae\u4e0e\u534f\u4f5c","text":"<p>\u53e6\u4e00\u4e2a\u5173\u952e\u95ee\u9898\u662f\uff1a\u5982\u4f55\u8ba9\u667a\u80fd\u4f53\u80fd\u591f\u7528\u5de5\u5177\uff1f</p> <p>\u8def\u7ebf\u662f\uff1a</p> <ol> <li>\u667a\u80fd\u4f53\u901a\u4fe1\u534f\u8bae</li> <li>MCP \u4e0e\u591a\u667a\u80fd\u4f53\u534f\u4f5c</li> <li>\u667a\u80fd\u65c5\u884c\u52a9\u624b</li> <li>\u6784\u5efa\u8d5b\u535a\u5c0f\u9547</li> </ol> <p>\u8fdb\u9636\u62d3\u5c55\uff1a</p> <ul> <li>Agentic_RL\uff1a\u7814\u7a76\u5982\u4f55\u8ba9\u667a\u80fd\u4f53\u66f4\u597d\u5730\u4f7f\u7528\u5de5\u5177\u3002</li> </ul>"},{"location":"vibecoding.html#_3","title":"\u63a8\u8350\u5b66\u4e60\u987a\u5e8f","text":"<p>\u5982\u679c\u76ee\u6807\u662f\u5148\u628a Vibe Coding \u7528\u8d77\u6765\uff0c\u63a8\u8350\u987a\u5e8f\u662f\uff1a</p> <ol> <li>\u5927\u6a21\u578b\u539f\u7406</li> <li>\u5f00\u53d1\u5de5\u5177\u5927\u5168</li> <li>Vibe Coding \u8303\u5f0f\u5bfc\u8bba</li> <li>\u63d0\u793a\u8bcd\u5de5\u7a0b</li> <li>\u6700\u5c0f\u53ef\u884c\u4ea7\u54c1</li> <li>\u4ee3\u7801\u5ba1\u6838\u4e0e\u5e7b\u89c9\u8bc6\u522b</li> <li>\u8fed\u4ee3\u5f0f\u5f00\u53d1\u5faa\u73af</li> <li>\u4e0a\u4e0b\u6587\u7ba1\u7406\u548c\u4ee3\u7801\u8d28\u91cf</li> <li>RAG</li> <li>SubAgent</li> <li>Agent Team</li> </ol> <p>\u5982\u679c\u76ee\u6807\u662f\u7cfb\u7edf\u7406\u89e3 Agent\uff0c\u63a8\u8350\u987a\u5e8f\u662f\uff1a</p> <ol> <li>LLM</li> <li>Function Calling</li> <li>Agent</li> <li>SubAgent</li> <li>MCP \u53ca\u5176\u4e09\u5927\u539f\u8bed</li> <li>Tool\u3001Resource\u3001Prompt</li> <li>MCP Server</li> <li>Workflow</li> <li>Langchain</li> <li>LangGraph \u7b49\u591a\u4ee3\u7406\u7cfb\u7edf</li> <li>Skill</li> </ol>"},{"location":"vibecoding.html#_4","title":"\u6700\u540e\u8bb0\u6cd5","text":"<p>Vibe Coding \u7684\u6838\u5fc3\u4e0d\u662f\u201c\u8ba9 AI \u66ff\u6211\u5199\u5b8c\u6240\u6709\u4ee3\u7801\u201d\uff0c\u800c\u662f\u628a\u4eba\u548c\u6a21\u578b\u7684\u5206\u5de5\u53d8\u6e05\u695a\uff1a</p> <ul> <li>\u4eba\u8d1f\u8d23\u76ee\u6807\u3001\u5224\u65ad\u3001\u9a8c\u6536\u548c\u53d6\u820d\u3002</li> <li>\u6a21\u578b\u8d1f\u8d23\u751f\u6210\u3001\u6539\u5199\u3001\u8865\u5168\u548c\u52a0\u901f\u91cd\u590d\u52b3\u52a8\u3002</li> <li>\u5de5\u5177\u8d1f\u8d23\u8fde\u63a5\u771f\u5b9e\u73af\u5883\u3002</li> <li>Agent \u8d1f\u8d23\u628a\u591a\u6b65\u9aa4\u4efb\u52a1\u4e32\u8d77\u6765\u3002</li> <li>\u4e0a\u4e0b\u6587\u5de5\u7a0b\u8d1f\u8d23\u8ba9\u6a21\u578b\u5728\u6b63\u786e\u7684\u4fe1\u606f\u91cc\u5de5\u4f5c\u3002</li> </ul> <p>\u5148\u7528\u4e3b\u7ebf\u8dd1\u901a\uff0c\u518d\u8865\u5de5\u5177\u3001MCP\u3001RAG\u3001SubAgent \u548c Workflow\u3002\u8fd9\u6837\u5b66\u4e60\u987a\u5e8f\u6700\u7a33\u3002</p>"},{"location":"%E5%89%8D%E7%AB%AF.html","title":"\u524d\u7aef\u5b66\u4e60\u7b14\u8bb0","text":""},{"location":"%E5%89%8D%E7%AB%AF.html#html","title":"HTML","text":"<p>HTML \u662f\u7f51\u9875\u7684\u7ed3\u6784\u5c42\uff0c\u7528\u6765\u63cf\u8ff0\u9875\u9762\u5185\u5bb9\u53ca\u5176\u8bed\u4e49\u3002\u6d4f\u89c8\u5668\u4f1a\u6839\u636e HTML \u6784\u5efa DOM \u6811\uff0c\u518d\u7ed3\u5408 CSS \u548c JavaScript \u751f\u6210\u6700\u7ec8\u9875\u9762\u3002</p>"},{"location":"%E5%89%8D%E7%AB%AF.html#1","title":"1. \u57fa\u7840\u7ed3\u6784","text":"<pre><code>&lt;!doctype html&gt;\n&lt;html lang=\"zh-CN\"&gt;\n  &lt;head&gt;\n    &lt;meta charset=\"UTF-8\" /&gt;\n    &lt;meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" /&gt;\n    &lt;title&gt;\u9875\u9762\u6807\u9898&lt;/title&gt;\n  &lt;/head&gt;\n  &lt;body&gt;\n    &lt;h1&gt;\u4e3b\u6807\u9898&lt;/h1&gt;\n    &lt;p&gt;\u9875\u9762\u5185\u5bb9&lt;/p&gt;\n  &lt;/body&gt;\n&lt;/html&gt;\n</code></pre> <p>\u5173\u952e\u70b9\uff1a</p> <ul> <li><code>&lt;!doctype html&gt;</code>\uff1a\u58f0\u660e\u4f7f\u7528 HTML5 \u6807\u51c6\u3002</li> <li><code>html lang=\"zh-CN\"</code>\uff1a\u58f0\u660e\u9875\u9762\u8bed\u8a00\uff0c\u6709\u5229\u4e8e\u65e0\u969c\u788d\u548c\u641c\u7d22\u5f15\u64ce\u3002</li> <li><code>meta charset=\"UTF-8\"</code>\uff1a\u8bbe\u7f6e\u5b57\u7b26\u7f16\u7801\u3002</li> <li><code>meta viewport</code>\uff1a\u9002\u914d\u79fb\u52a8\u7aef\u89c6\u53e3\u3002</li> <li><code>title</code>\uff1a\u6d4f\u89c8\u5668\u6807\u7b7e\u9875\u6807\u9898\uff0c\u4e5f\u4f1a\u5f71\u54cd SEO\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#2","title":"2. \u5e38\u7528\u6807\u7b7e","text":"<p>\u6587\u672c\u76f8\u5173\uff1a</p> <pre><code>&lt;h1&gt;\u4e00\u7ea7\u6807\u9898&lt;/h1&gt;\n&lt;h2&gt;\u4e8c\u7ea7\u6807\u9898&lt;/h2&gt;\n&lt;p&gt;\u6bb5\u843d&lt;/p&gt;\n&lt;strong&gt;\u91cd\u8981\u5185\u5bb9&lt;/strong&gt;\n&lt;em&gt;\u5f3a\u8c03\u5185\u5bb9&lt;/em&gt;\n&lt;span&gt;\u884c\u5185\u5bb9\u5668&lt;/span&gt;\n&lt;br /&gt;\n&lt;hr /&gt;\n</code></pre> <p>\u94fe\u63a5\u548c\u56fe\u7247\uff1a</p> <pre><code>&lt;a href=\"https://example.com\" target=\"_blank\" rel=\"noopener noreferrer\"&gt;\n  \u6253\u5f00\u94fe\u63a5\n&lt;/a&gt;\n\n&lt;img src=\"./avatar.png\" alt=\"\u7528\u6237\u5934\u50cf\" /&gt;\n</code></pre> <p>\u5217\u8868\uff1a</p> <pre><code>&lt;ul&gt;\n  &lt;li&gt;\u65e0\u5e8f\u5217\u8868\u9879&lt;/li&gt;\n  &lt;li&gt;\u65e0\u5e8f\u5217\u8868\u9879&lt;/li&gt;\n&lt;/ul&gt;\n\n&lt;ol&gt;\n  &lt;li&gt;\u6709\u5e8f\u5217\u8868\u9879&lt;/li&gt;\n  &lt;li&gt;\u6709\u5e8f\u5217\u8868\u9879&lt;/li&gt;\n&lt;/ol&gt;\n</code></pre> <p>\u8868\u683c\uff1a</p> <pre><code>&lt;table&gt;\n  &lt;thead&gt;\n    &lt;tr&gt;\n      &lt;th&gt;\u59d3\u540d&lt;/th&gt;\n      &lt;th&gt;\u5e74\u9f84&lt;/th&gt;\n    &lt;/tr&gt;\n  &lt;/thead&gt;\n  &lt;tbody&gt;\n    &lt;tr&gt;\n      &lt;td&gt;\u5f20\u4e09&lt;/td&gt;\n      &lt;td&gt;18&lt;/td&gt;\n    &lt;/tr&gt;\n  &lt;/tbody&gt;\n&lt;/table&gt;\n</code></pre> <p>\u8868\u5355\uff1a</p> <pre><code>&lt;form action=\"/login\" method=\"post\"&gt;\n  &lt;label for=\"username\"&gt;\u7528\u6237\u540d&lt;/label&gt;\n  &lt;input id=\"username\" name=\"username\" type=\"text\" required /&gt;\n\n  &lt;label for=\"password\"&gt;\u5bc6\u7801&lt;/label&gt;\n  &lt;input id=\"password\" name=\"password\" type=\"password\" required /&gt;\n\n  &lt;button type=\"submit\"&gt;\u767b\u5f55&lt;/button&gt;\n&lt;/form&gt;\n</code></pre> <p>\u8868\u5355\u5e38\u89c1\u63a7\u4ef6\uff1a</p> <ul> <li><code>input type=\"text\"</code>\uff1a\u6587\u672c\u8f93\u5165\u3002</li> <li><code>input type=\"password\"</code>\uff1a\u5bc6\u7801\u8f93\u5165\u3002</li> <li><code>input type=\"email\"</code>\uff1a\u90ae\u7bb1\u8f93\u5165\u3002</li> <li><code>input type=\"checkbox\"</code>\uff1a\u591a\u9009\u6846\u3002</li> <li><code>input type=\"radio\"</code>\uff1a\u5355\u9009\u6846\u3002</li> <li><code>textarea</code>\uff1a\u591a\u884c\u6587\u672c\u3002</li> <li><code>select</code> \u548c <code>option</code>\uff1a\u4e0b\u62c9\u9009\u62e9\u3002</li> <li><code>button type=\"submit\"</code>\uff1a\u63d0\u4ea4\u6309\u94ae\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#3","title":"3. \u8bed\u4e49\u5316\u6807\u7b7e","text":"<p>\u8bed\u4e49\u5316 HTML \u662f\u6307\u7528\u5408\u9002\u7684\u6807\u7b7e\u8868\u8fbe\u5185\u5bb9\u542b\u4e49\uff0c\u800c\u4e0d\u662f\u53ea\u7528 <code>div</code> \u548c <code>span</code>\u3002</p> <pre><code>&lt;header&gt;\u9875\u9762\u5934\u90e8&lt;/header&gt;\n&lt;nav&gt;\u5bfc\u822a&lt;/nav&gt;\n&lt;main&gt;\u9875\u9762\u4e3b\u4f53&lt;/main&gt;\n&lt;section&gt;\u9875\u9762\u533a\u57df&lt;/section&gt;\n&lt;article&gt;\u72ec\u7acb\u6587\u7ae0\u5185\u5bb9&lt;/article&gt;\n&lt;aside&gt;\u4fa7\u8fb9\u680f&lt;/aside&gt;\n&lt;footer&gt;\u9875\u9762\u5e95\u90e8&lt;/footer&gt;\n</code></pre> <p>\u4f18\u70b9\uff1a</p> <ul> <li>\u7ed3\u6784\u66f4\u6e05\u6670\uff0c\u4fbf\u4e8e\u7ef4\u62a4\u3002</li> <li>\u5bf9\u641c\u7d22\u5f15\u64ce\u66f4\u53cb\u597d\u3002</li> <li>\u5bf9\u5c4f\u5e55\u9605\u8bfb\u5668\u7b49\u8f85\u52a9\u6280\u672f\u66f4\u53cb\u597d\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#4","title":"4. \u5757\u7ea7\u5143\u7d20\u548c\u884c\u5185\u5143\u7d20","text":"<p>\u5757\u7ea7\u5143\u7d20\u7279\u70b9\uff1a</p> <ul> <li>\u9ed8\u8ba4\u72ec\u5360\u4e00\u884c\u3002</li> <li>\u53ef\u4ee5\u8bbe\u7f6e\u5bbd\u9ad8\u3002</li> <li>\u5e38\u89c1\u6807\u7b7e\uff1a<code>div</code>\u3001<code>p</code>\u3001<code>h1</code> \u5230 <code>h6</code>\u3001<code>ul</code>\u3001<code>li</code>\u3001<code>section</code>\u3002</li> </ul> <p>\u884c\u5185\u5143\u7d20\u7279\u70b9\uff1a</p> <ul> <li>\u4e0d\u4f1a\u72ec\u5360\u4e00\u884c\u3002</li> <li>\u9ed8\u8ba4\u5bbd\u9ad8\u7531\u5185\u5bb9\u51b3\u5b9a\u3002</li> <li>\u5e38\u89c1\u6807\u7b7e\uff1a<code>span</code>\u3001<code>a</code>\u3001<code>strong</code>\u3001<code>em</code>\u3001<code>label</code>\u3002</li> </ul> <p>\u884c\u5185\u5757\u5143\u7d20\uff1a</p> <ul> <li>\u901a\u8fc7 <code>display: inline-block</code> \u8bbe\u7f6e\u3002</li> <li>\u4e0d\u72ec\u5360\u4e00\u884c\uff0c\u4f46\u53ef\u4ee5\u8bbe\u7f6e\u5bbd\u9ad8\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#5-html","title":"5. HTML \u5c5e\u6027","text":"<p>\u5e38\u7528\u5168\u5c40\u5c5e\u6027\uff1a</p> <ul> <li><code>id</code>\uff1a\u5143\u7d20\u552f\u4e00\u6807\u8bc6\u3002</li> <li><code>class</code>\uff1a\u5143\u7d20\u7c7b\u540d\uff0c\u53ef\u91cd\u590d\u4f7f\u7528\u3002</li> <li><code>style</code>\uff1a\u884c\u5185\u6837\u5f0f\uff0c\u4e0d\u63a8\u8350\u5927\u91cf\u4f7f\u7528\u3002</li> <li><code>title</code>\uff1a\u9f20\u6807\u60ac\u505c\u63d0\u793a\u3002</li> <li><code>data-*</code>\uff1a\u81ea\u5b9a\u4e49\u6570\u636e\u5c5e\u6027\u3002</li> </ul> <pre><code>&lt;button class=\"btn\" data-role=\"delete\"&gt;\u5220\u9664&lt;/button&gt;\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#6","title":"6. \u53ef\u8bbf\u95ee\u6027\u57fa\u7840","text":"<p>\u53ef\u8bbf\u95ee\u6027\u662f\u6307\u9875\u9762\u5bf9\u4e0d\u540c\u7528\u6237\u548c\u8bbe\u5907\u90fd\u53ef\u7528\u3002</p> <p>\u5e38\u89c1\u5b9e\u8df5\uff1a</p> <ul> <li>\u56fe\u7247\u5fc5\u987b\u63d0\u4f9b\u6709\u610f\u4e49\u7684 <code>alt</code>\u3002</li> <li>\u8868\u5355\u63a7\u4ef6\u7528 <code>label</code> \u5173\u8054\u3002</li> <li>\u6309\u94ae\u4f7f\u7528 <code>button</code>\uff0c\u4e0d\u8981\u7528 <code>div</code> \u6a21\u62df\u3002</li> <li>\u4ea4\u4e92\u5143\u7d20\u9700\u8981\u80fd\u901a\u8fc7\u952e\u76d8\u8bbf\u95ee\u3002</li> <li>\u4fdd\u6301\u5408\u7406\u7684\u6807\u9898\u5c42\u7ea7\u3002</li> </ul> <pre><code>&lt;label for=\"email\"&gt;\u90ae\u7bb1&lt;/label&gt;\n&lt;input id=\"email\" type=\"email\" /&gt;\n\n&lt;button type=\"button\"&gt;\u63d0\u4ea4&lt;/button&gt;\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#7-seo","title":"7. SEO \u57fa\u7840","text":"<p>\u5e38\u89c1\u4f18\u5316\uff1a</p> <ul> <li>\u6bcf\u4e2a\u9875\u9762\u6709\u552f\u4e00\u3001\u660e\u786e\u7684 <code>title</code>\u3002</li> <li>\u4f7f\u7528 <code>meta name=\"description\"</code> \u63cf\u8ff0\u9875\u9762\u3002</li> <li>\u5408\u7406\u4f7f\u7528 <code>h1</code> \u5230 <code>h6</code>\u3002</li> <li>\u56fe\u7247\u6dfb\u52a0 <code>alt</code>\u3002</li> <li>\u94fe\u63a5\u6587\u672c\u8981\u6709\u660e\u786e\u542b\u4e49\u3002</li> </ul> <pre><code>&lt;meta name=\"description\" content=\"\u524d\u7aef\u5b66\u4e60\u7b14\u8bb0\uff0c\u5305\u542b HTML\u3001CSS\u3001JavaScript \u548c React\u3002\" /&gt;\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#css","title":"CSS","text":"<p>CSS \u662f\u7f51\u9875\u7684\u8868\u73b0\u5c42\uff0c\u7528\u6765\u63a7\u5236\u9875\u9762\u5e03\u5c40\u3001\u989c\u8272\u3001\u5b57\u4f53\u3001\u95f4\u8ddd\u3001\u52a8\u753b\u548c\u54cd\u5e94\u5f0f\u6548\u679c\u3002</p>"},{"location":"%E5%89%8D%E7%AB%AF.html#1_1","title":"1. \u5f15\u5165\u65b9\u5f0f","text":"<p>\u884c\u5185\u6837\u5f0f\uff1a</p> <pre><code>&lt;p style=\"color: red;\"&gt;\u7ea2\u8272\u6587\u5b57&lt;/p&gt;\n</code></pre> <p>\u5185\u90e8\u6837\u5f0f\uff1a</p> <pre><code>&lt;style&gt;\n  p {\n    color: red;\n  }\n&lt;/style&gt;\n</code></pre> <p>\u5916\u90e8\u6837\u5f0f\uff1a</p> <pre><code>&lt;link rel=\"stylesheet\" href=\"./style.css\" /&gt;\n</code></pre> <p>\u5b9e\u9645\u5f00\u53d1\u4e2d\u63a8\u8350\u5916\u90e8\u6837\u5f0f\uff0c\u4fbf\u4e8e\u7ef4\u62a4\u548c\u590d\u7528\u3002</p>"},{"location":"%E5%89%8D%E7%AB%AF.html#2_1","title":"2. \u9009\u62e9\u5668","text":"<pre><code>/* \u6807\u7b7e\u9009\u62e9\u5668 */\np {\n  color: #333;\n}\n\n/* \u7c7b\u9009\u62e9\u5668 */\n.card {\n  border: 1px solid #ddd;\n}\n\n/* ID \u9009\u62e9\u5668 */\n#app {\n  min-height: 100vh;\n}\n\n/* \u540e\u4ee3\u9009\u62e9\u5668 */\n.nav a {\n  text-decoration: none;\n}\n\n/* \u5b50\u4ee3\u9009\u62e9\u5668 */\n.list &gt; li {\n  margin-bottom: 8px;\n}\n\n/* \u4f2a\u7c7b\u9009\u62e9\u5668 */\nbutton:hover {\n  background: #222;\n}\n\n/* \u4f2a\u5143\u7d20\u9009\u62e9\u5668 */\np::first-line {\n  font-weight: bold;\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#3_1","title":"3. \u9009\u62e9\u5668\u4f18\u5148\u7ea7","text":"<p>\u4f18\u5148\u7ea7\u4ece\u9ad8\u5230\u4f4e\uff1a</p> <ol> <li><code>!important</code></li> <li>\u884c\u5185\u6837\u5f0f</li> <li>ID \u9009\u62e9\u5668</li> <li>\u7c7b\u9009\u62e9\u5668\u3001\u5c5e\u6027\u9009\u62e9\u5668\u3001\u4f2a\u7c7b\u9009\u62e9\u5668</li> <li>\u6807\u7b7e\u9009\u62e9\u5668\u3001\u4f2a\u5143\u7d20\u9009\u62e9\u5668</li> <li>\u901a\u914d\u7b26\u9009\u62e9\u5668</li> </ol> <p>\u5efa\u8bae\uff1a</p> <ul> <li>\u5c11\u7528 <code>!important</code>\u3002</li> <li>\u5c11\u7528 ID \u5199\u6837\u5f0f\u3002</li> <li>\u4f7f\u7528\u6e05\u6670\u7684\u7c7b\u540d\u7ec4\u7ec7\u6837\u5f0f\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#4_1","title":"4. \u76d2\u6a21\u578b","text":"<p>\u76d2\u6a21\u578b\u7531\u56db\u90e8\u5206\u7ec4\u6210\uff1a</p> <ul> <li><code>content</code>\uff1a\u5185\u5bb9\u533a\u57df\u3002</li> <li><code>padding</code>\uff1a\u5185\u8fb9\u8ddd\u3002</li> <li><code>border</code>\uff1a\u8fb9\u6846\u3002</li> <li><code>margin</code>\uff1a\u5916\u8fb9\u8ddd\u3002</li> </ul> <pre><code>.box {\n  width: 200px;\n  padding: 16px;\n  border: 1px solid #ddd;\n  margin: 24px;\n}\n</code></pre> <p>\u9ed8\u8ba4\u76d2\u6a21\u578b\uff1a</p> <pre><code>box-sizing: content-box;\n</code></pre> <p>\u63a8\u8350\u5168\u5c40\u8bbe\u7f6e\uff1a</p> <pre><code>* {\n  box-sizing: border-box;\n}\n</code></pre> <p><code>border-box</code> \u8868\u793a\u5143\u7d20\u6700\u7ec8\u5bbd\u5ea6\u5305\u542b <code>content</code>\u3001<code>padding</code> \u548c <code>border</code>\uff0c\u5e03\u5c40\u66f4\u76f4\u89c2\u3002</p>"},{"location":"%E5%89%8D%E7%AB%AF.html#5","title":"5. \u5e38\u7528\u5355\u4f4d","text":"<ul> <li><code>px</code>\uff1a\u50cf\u7d20\uff0c\u56fa\u5b9a\u5355\u4f4d\u3002</li> <li><code>%</code>\uff1a\u76f8\u5bf9\u7236\u5143\u7d20\u3002</li> <li><code>em</code>\uff1a\u76f8\u5bf9\u5f53\u524d\u5143\u7d20\u5b57\u4f53\u5927\u5c0f\u3002</li> <li><code>rem</code>\uff1a\u76f8\u5bf9\u6839\u5143\u7d20\u5b57\u4f53\u5927\u5c0f\u3002</li> <li><code>vw</code>\uff1a\u89c6\u53e3\u5bbd\u5ea6\u7684\u767e\u5206\u6bd4\u3002</li> <li><code>vh</code>\uff1a\u89c6\u53e3\u9ad8\u5ea6\u7684\u767e\u5206\u6bd4\u3002</li> </ul> <pre><code>html {\n  font-size: 16px;\n}\n\n.title {\n  font-size: 2rem;\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#6-display","title":"6. display","text":"<pre><code>.block {\n  display: block;\n}\n\n.inline {\n  display: inline;\n}\n\n.inline-block {\n  display: inline-block;\n}\n\n.hidden {\n  display: none;\n}\n\n.flex {\n  display: flex;\n}\n\n.grid {\n  display: grid;\n}\n</code></pre> <p>\u5e38\u89c1\u533a\u522b\uff1a</p> <ul> <li><code>display: none</code>\uff1a\u5143\u7d20\u4e0d\u663e\u793a\uff0c\u4e5f\u4e0d\u5360\u4f4d\u3002</li> <li><code>visibility: hidden</code>\uff1a\u5143\u7d20\u4e0d\u53ef\u89c1\uff0c\u4f46\u4ecd\u5360\u4f4d\u3002</li> <li><code>opacity: 0</code>\uff1a\u5143\u7d20\u900f\u660e\uff0c\u4f46\u4ecd\u5360\u4f4d\uff0c\u5e76\u53ef\u80fd\u54cd\u5e94\u4e8b\u4ef6\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#7-position","title":"7. position \u5b9a\u4f4d","text":"<pre><code>.relative {\n  position: relative;\n  top: 10px;\n}\n\n.absolute {\n  position: absolute;\n  top: 0;\n  right: 0;\n}\n\n.fixed {\n  position: fixed;\n  bottom: 20px;\n  right: 20px;\n}\n\n.sticky {\n  position: sticky;\n  top: 0;\n}\n</code></pre> <p>\u5e38\u89c1\u5b9a\u4f4d\uff1a</p> <ul> <li><code>static</code>\uff1a\u9ed8\u8ba4\u5b9a\u4f4d\u3002</li> <li><code>relative</code>\uff1a\u76f8\u5bf9\u81ea\u8eab\u539f\u4f4d\u7f6e\u504f\u79fb\u3002</li> <li><code>absolute</code>\uff1a\u76f8\u5bf9\u6700\u8fd1\u7684\u975e <code>static</code> \u7956\u5148\u5143\u7d20\u5b9a\u4f4d\u3002</li> <li><code>fixed</code>\uff1a\u76f8\u5bf9\u6d4f\u89c8\u5668\u89c6\u53e3\u5b9a\u4f4d\u3002</li> <li><code>sticky</code>\uff1a\u6eda\u52a8\u5230\u6307\u5b9a\u4f4d\u7f6e\u540e\u56fa\u5b9a\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#8-flex","title":"8. Flex \u5e03\u5c40","text":"<p>Flex \u9002\u5408\u4e00\u7ef4\u5e03\u5c40\uff0c\u53ef\u4ee5\u5904\u7406\u6a2a\u5411\u6216\u7eb5\u5411\u6392\u5217\u3002</p> <pre><code>.container {\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  gap: 16px;\n}\n</code></pre> <p>\u4e3b\u8f74\u63a7\u5236\uff1a</p> <pre><code>.container {\n  flex-direction: row;\n  justify-content: space-between;\n}\n</code></pre> <p>\u4ea4\u53c9\u8f74\u63a7\u5236\uff1a</p> <pre><code>.container {\n  align-items: center;\n}\n</code></pre> <p>\u5e38\u7528\u5c5e\u6027\uff1a</p> <ul> <li><code>flex-direction</code>\uff1a\u4e3b\u8f74\u65b9\u5411\u3002</li> <li><code>justify-content</code>\uff1a\u4e3b\u8f74\u5bf9\u9f50\u3002</li> <li><code>align-items</code>\uff1a\u4ea4\u53c9\u8f74\u5bf9\u9f50\u3002</li> <li><code>flex-wrap</code>\uff1a\u662f\u5426\u6362\u884c\u3002</li> <li><code>gap</code>\uff1a\u5b50\u5143\u7d20\u95f4\u8ddd\u3002</li> <li><code>flex: 1</code>\uff1a\u6309\u6bd4\u4f8b\u5206\u914d\u5269\u4f59\u7a7a\u95f4\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#9-grid","title":"9. Grid \u5e03\u5c40","text":"<p>Grid \u9002\u5408\u4e8c\u7ef4\u5e03\u5c40\uff0c\u53ef\u4ee5\u540c\u65f6\u63a7\u5236\u884c\u548c\u5217\u3002</p> <pre><code>.grid {\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 16px;\n}\n</code></pre> <p>\u54cd\u5e94\u5f0f\u7f51\u683c\uff1a</p> <pre><code>.grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));\n  gap: 16px;\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#10","title":"10. \u54cd\u5e94\u5f0f\u5e03\u5c40","text":"<p>\u5a92\u4f53\u67e5\u8be2\uff1a</p> <pre><code>.container {\n  width: 1200px;\n  margin: 0 auto;\n}\n\n@media (max-width: 768px) {\n  .container {\n    width: 100%;\n    padding: 0 16px;\n  }\n}\n</code></pre> <p>\u5e38\u89c1\u5b9e\u8df5\uff1a</p> <ul> <li>\u4f7f\u7528 <code>max-width</code> \u800c\u4e0d\u662f\u56fa\u5b9a\u5bbd\u5ea6\u3002</li> <li>\u56fe\u7247\u8bbe\u7f6e <code>max-width: 100%</code>\u3002</li> <li>\u4f7f\u7528 Flex/Grid \u505a\u81ea\u9002\u5e94\u5e03\u5c40\u3002</li> <li>\u79fb\u52a8\u7aef\u4f18\u5148\u65f6\uff0c\u5148\u5199\u5c0f\u5c4f\u6837\u5f0f\uff0c\u518d\u7528\u5a92\u4f53\u67e5\u8be2\u589e\u5f3a\u5927\u5c4f\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#11","title":"11. \u5e38\u7528\u6837\u5f0f","text":"<p>\u6587\u672c\uff1a</p> <pre><code>.text {\n  color: #222;\n  font-size: 16px;\n  font-weight: 600;\n  line-height: 1.6;\n  text-align: center;\n}\n</code></pre> <p>\u80cc\u666f\uff1a</p> <pre><code>.hero {\n  background-color: #f5f5f5;\n  background-image: url(\"./hero.jpg\");\n  background-size: cover;\n  background-position: center;\n}\n</code></pre> <p>\u8fb9\u6846\u548c\u9634\u5f71\uff1a</p> <pre><code>.card {\n  border: 1px solid #e5e7eb;\n  border-radius: 8px;\n  box-shadow: 0 8px 24px rgb(0 0 0 / 8%);\n}\n</code></pre> <p>\u8fc7\u6e21\uff1a</p> <pre><code>.button {\n  transition: background-color 0.2s ease, transform 0.2s ease;\n}\n\n.button:hover {\n  transform: translateY(-2px);\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#12-bfc","title":"12. BFC","text":"<p>BFC \u662f\u5757\u7ea7\u683c\u5f0f\u5316\u4e0a\u4e0b\u6587\uff0c\u662f\u4e00\u4e2a\u72ec\u7acb\u7684\u6e32\u67d3\u533a\u57df\u3002\u5e38\u89c1\u4f5c\u7528\uff1a</p> <ul> <li>\u6e05\u9664\u6d6e\u52a8\u5f71\u54cd\u3002</li> <li>\u9632\u6b62\u5916\u8fb9\u8ddd\u5408\u5e76\u3002</li> <li>\u9650\u5236\u5185\u90e8\u5e03\u5c40\u4e0d\u5f71\u54cd\u5916\u90e8\u3002</li> </ul> <p>\u89e6\u53d1\u65b9\u5f0f\uff1a</p> <pre><code>.bfc {\n  overflow: hidden;\n}\n</code></pre> <p>\u5176\u4ed6\u65b9\u5f0f\uff1a</p> <ul> <li><code>display: flow-root</code></li> <li><code>display: flex</code></li> <li><code>display: grid</code></li> <li><code>position: absolute</code></li> <li><code>position: fixed</code></li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#13-css","title":"13. CSS \u53d8\u91cf","text":"<pre><code>:root {\n  --primary-color: #2563eb;\n  --radius: 8px;\n}\n\n.button {\n  background: var(--primary-color);\n  border-radius: var(--radius);\n}\n</code></pre> <p>\u4f18\u70b9\uff1a</p> <ul> <li>\u4fbf\u4e8e\u7edf\u4e00\u4e3b\u9898\u3002</li> <li>\u53ef\u4ee5\u5728\u8fd0\u884c\u65f6\u901a\u8fc7 JavaScript \u4fee\u6539\u3002</li> <li>\u51cf\u5c11\u91cd\u590d\u503c\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#javascript","title":"JavaScript","text":"<p>JavaScript \u662f\u7f51\u9875\u7684\u884c\u4e3a\u5c42\uff0c\u7528\u6765\u5904\u7406\u4ea4\u4e92\u3001\u6570\u636e\u3001\u7f51\u7edc\u8bf7\u6c42\u548c\u9875\u9762\u903b\u8f91\u3002</p>"},{"location":"%E5%89%8D%E7%AB%AF.html#1_2","title":"1. \u53d8\u91cf\u58f0\u660e","text":"<pre><code>var oldValue = 1;\nlet count = 0;\nconst name = \"Alice\";\n</code></pre> <p>\u533a\u522b\uff1a</p> <ul> <li><code>var</code>\uff1a\u51fd\u6570\u4f5c\u7528\u57df\uff0c\u53ef\u91cd\u590d\u58f0\u660e\uff0c\u6709\u53d8\u91cf\u63d0\u5347\uff0c\u4e0d\u63a8\u8350\u65b0\u4ee3\u7801\u5927\u91cf\u4f7f\u7528\u3002</li> <li><code>let</code>\uff1a\u5757\u7ea7\u4f5c\u7528\u57df\uff0c\u53ef\u91cd\u65b0\u8d4b\u503c\u3002</li> <li><code>const</code>\uff1a\u5757\u7ea7\u4f5c\u7528\u57df\uff0c\u4e0d\u53ef\u91cd\u65b0\u8d4b\u503c\u3002</li> </ul> <p>\u63a8\u8350\uff1a</p> <ul> <li>\u9ed8\u8ba4\u4f7f\u7528 <code>const</code>\u3002</li> <li>\u9700\u8981\u91cd\u65b0\u8d4b\u503c\u65f6\u4f7f\u7528 <code>let</code>\u3002</li> <li>\u907f\u514d\u4f7f\u7528 <code>var</code>\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#2_2","title":"2. \u6570\u636e\u7c7b\u578b","text":"<p>\u57fa\u672c\u7c7b\u578b\uff1a</p> <ul> <li><code>string</code></li> <li><code>number</code></li> <li><code>boolean</code></li> <li><code>undefined</code></li> <li><code>null</code></li> <li><code>symbol</code></li> <li><code>bigint</code></li> </ul> <p>\u5f15\u7528\u7c7b\u578b\uff1a</p> <ul> <li><code>object</code></li> <li><code>array</code></li> <li><code>function</code></li> <li><code>date</code></li> <li><code>regexp</code></li> </ul> <pre><code>typeof \"hello\"; // \"string\"\ntypeof 123; // \"number\"\ntypeof true; // \"boolean\"\ntypeof undefined; // \"undefined\"\ntypeof null; // \"object\"\nArray.isArray([]); // true\n</code></pre> <p>\u6ce8\u610f\uff1a<code>typeof null</code> \u8fd4\u56de <code>\"object\"</code> \u662f JavaScript \u7684\u5386\u53f2\u9057\u7559\u95ee\u9898\u3002</p>"},{"location":"%E5%89%8D%E7%AB%AF.html#3_2","title":"3. \u8fd0\u7b97\u7b26","text":"<pre><code>1 + 2;\n5 - 3;\n2 * 4;\n8 / 2;\n7 % 3;\n</code></pre> <p>\u6bd4\u8f83\uff1a</p> <pre><code>1 == \"1\"; // true\n1 === \"1\"; // false\n</code></pre> <p>\u63a8\u8350\u4f7f\u7528\u4e25\u683c\u6bd4\u8f83\uff1a</p> <pre><code>value === expected;\nvalue !== expected;\n</code></pre> <p>\u903b\u8f91\u8fd0\u7b97\uff1a</p> <pre><code>const a = true;\nconst b = false;\n\na &amp;&amp; b;\na || b;\n!a;\n</code></pre> <p>\u7a7a\u503c\u5408\u5e76\uff1a</p> <pre><code>const username = inputName ?? \"\u533f\u540d\u7528\u6237\";\n</code></pre> <p>\u53ef\u9009\u94fe\uff1a</p> <pre><code>const city = user?.address?.city;\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#4_2","title":"4. \u6761\u4ef6\u548c\u5faa\u73af","text":"<p>\u6761\u4ef6\uff1a</p> <pre><code>if (score &gt;= 90) {\n  console.log(\"\u4f18\u79c0\");\n} else if (score &gt;= 60) {\n  console.log(\"\u53ca\u683c\");\n} else {\n  console.log(\"\u4e0d\u53ca\u683c\");\n}\n</code></pre> <p><code>switch</code>\uff1a</p> <pre><code>switch (status) {\n  case \"loading\":\n    console.log(\"\u52a0\u8f7d\u4e2d\");\n    break;\n  case \"success\":\n    console.log(\"\u6210\u529f\");\n    break;\n  default:\n    console.log(\"\u672a\u77e5\u72b6\u6001\");\n}\n</code></pre> <p>\u5faa\u73af\uff1a</p> <pre><code>for (let i = 0; i &lt; 5; i += 1) {\n  console.log(i);\n}\n\nfor (const item of list) {\n  console.log(item);\n}\n\nwhile (count &lt; 10) {\n  count += 1;\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#5_1","title":"5. \u51fd\u6570","text":"<p>\u51fd\u6570\u58f0\u660e\uff1a</p> <pre><code>function add(a, b) {\n  return a + b;\n}\n</code></pre> <p>\u51fd\u6570\u8868\u8fbe\u5f0f\uff1a</p> <pre><code>const add = function (a, b) {\n  return a + b;\n};\n</code></pre> <p>\u7bad\u5934\u51fd\u6570\uff1a</p> <pre><code>const add = (a, b) =&gt; a + b;\n</code></pre> <p>\u9ed8\u8ba4\u53c2\u6570\uff1a</p> <pre><code>function greet(name = \"\u7528\u6237\") {\n  return `\u4f60\u597d\uff0c${name}`;\n}\n</code></pre> <p>\u5269\u4f59\u53c2\u6570\uff1a</p> <pre><code>function sum(...numbers) {\n  return numbers.reduce((total, item) =&gt; total + item, 0);\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#6_1","title":"6. \u4f5c\u7528\u57df\u548c\u95ed\u5305","text":"<p>\u4f5c\u7528\u57df\u51b3\u5b9a\u53d8\u91cf\u7684\u53ef\u8bbf\u95ee\u8303\u56f4\u3002</p> <pre><code>function outer() {\n  const message = \"hello\";\n\n  function inner() {\n    console.log(message);\n  }\n\n  return inner;\n}\n\nconst fn = outer();\nfn(); // \"hello\"\n</code></pre> <p>\u95ed\u5305\uff1a\u51fd\u6570\u53ef\u4ee5\u8bb0\u4f4f\u5e76\u8bbf\u95ee\u5b83\u521b\u5efa\u65f6\u6240\u5728\u7684\u8bcd\u6cd5\u4f5c\u7528\u57df\uff0c\u5373\u4f7f\u5916\u5c42\u51fd\u6570\u5df2\u7ecf\u6267\u884c\u5b8c\u6bd5\u3002</p> <p>\u5e38\u89c1\u7528\u9014\uff1a</p> <ul> <li>\u4fdd\u5b58\u79c1\u6709\u53d8\u91cf\u3002</li> <li>\u51fd\u6570\u67ef\u91cc\u5316\u3002</li> <li>\u9632\u6296\u548c\u8282\u6d41\u3002</li> <li>React Hooks \u4e2d\u7684\u72b6\u6001\u548c\u526f\u4f5c\u7528\u903b\u8f91\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#7","title":"7. \u6570\u7ec4\u5e38\u7528\u65b9\u6cd5","text":"<pre><code>const numbers = [1, 2, 3, 4];\n\nnumbers.map((item) =&gt; item * 2); // [2, 4, 6, 8]\nnumbers.filter((item) =&gt; item &gt; 2); // [3, 4]\nnumbers.find((item) =&gt; item === 3); // 3\nnumbers.some((item) =&gt; item &gt; 3); // true\nnumbers.every((item) =&gt; item &gt; 0); // true\nnumbers.reduce((total, item) =&gt; total + item, 0); // 10\n</code></pre> <p>\u4f1a\u6539\u53d8\u539f\u6570\u7ec4\u7684\u65b9\u6cd5\uff1a</p> <ul> <li><code>push</code></li> <li><code>pop</code></li> <li><code>shift</code></li> <li><code>unshift</code></li> <li><code>splice</code></li> <li><code>sort</code></li> <li><code>reverse</code></li> </ul> <p>\u4e0d\u4f1a\u6539\u53d8\u539f\u6570\u7ec4\u7684\u65b9\u6cd5\uff1a</p> <ul> <li><code>map</code></li> <li><code>filter</code></li> <li><code>slice</code></li> <li><code>concat</code></li> <li><code>find</code></li> <li><code>some</code></li> <li><code>every</code></li> </ul> <p>React \u4e2d\u66f4\u65b0\u6570\u7ec4\u65f6\u901a\u5e38\u8981\u8fd4\u56de\u65b0\u6570\u7ec4\uff0c\u800c\u4e0d\u662f\u76f4\u63a5\u4fee\u6539\u539f\u6570\u7ec4\u3002</p>"},{"location":"%E5%89%8D%E7%AB%AF.html#8","title":"8. \u5bf9\u8c61\u5e38\u7528\u64cd\u4f5c","text":"<pre><code>const user = {\n  id: 1,\n  name: \"Alice\",\n  age: 18,\n};\n\nuser.name;\nuser[\"age\"];\n</code></pre> <p>\u89e3\u6784\uff1a</p> <pre><code>const { name, age } = user;\n</code></pre> <p>\u5c55\u5f00\uff1a</p> <pre><code>const newUser = {\n  ...user,\n  age: 19,\n};\n</code></pre> <p>\u904d\u5386\uff1a</p> <pre><code>Object.keys(user);\nObject.values(user);\nObject.entries(user);\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#9","title":"9. \u539f\u578b\u548c\u539f\u578b\u94fe","text":"<p>JavaScript \u5bf9\u8c61\u53ef\u4ee5\u901a\u8fc7\u539f\u578b\u7ee7\u627f\u5c5e\u6027\u548c\u65b9\u6cd5\u3002</p> <pre><code>function Person(name) {\n  this.name = name;\n}\n\nPerson.prototype.sayHello = function () {\n  console.log(`Hello, ${this.name}`);\n};\n\nconst person = new Person(\"Alice\");\nperson.sayHello();\n</code></pre> <p>\u67e5\u627e\u5c5e\u6027\u65f6\uff1a</p> <ol> <li>\u5148\u627e\u5bf9\u8c61\u81ea\u8eab\u5c5e\u6027\u3002</li> <li>\u627e\u4e0d\u5230\u5c31\u53bb\u5bf9\u8c61\u539f\u578b\u4e0a\u627e\u3002</li> <li>\u7ee7\u7eed\u6cbf\u7740\u539f\u578b\u94fe\u67e5\u627e\u3002</li> <li>\u6700\u7ec8\u5230 <code>null</code> \u505c\u6b62\u3002</li> </ol>"},{"location":"%E5%89%8D%E7%AB%AF.html#10-this","title":"10. this \u6307\u5411","text":"<p><code>this</code> \u7684\u503c\u53d6\u51b3\u4e8e\u51fd\u6570\u8c03\u7528\u65b9\u5f0f\u3002</p> <pre><code>const user = {\n  name: \"Alice\",\n  sayName() {\n    console.log(this.name);\n  },\n};\n\nuser.sayName(); // this \u6307\u5411 user\n</code></pre> <p>\u5e38\u89c1\u89c4\u5219\uff1a</p> <ul> <li>\u666e\u901a\u51fd\u6570\u76f4\u63a5\u8c03\u7528\uff1a\u975e\u4e25\u683c\u6a21\u5f0f\u4e0b\u6307\u5411\u5168\u5c40\u5bf9\u8c61\uff0c\u4e25\u683c\u6a21\u5f0f\u4e0b\u4e3a <code>undefined</code>\u3002</li> <li>\u5bf9\u8c61\u65b9\u6cd5\u8c03\u7528\uff1a\u6307\u5411\u8c03\u7528\u8be5\u65b9\u6cd5\u7684\u5bf9\u8c61\u3002</li> <li>\u6784\u9020\u51fd\u6570\u8c03\u7528\uff1a\u6307\u5411\u65b0\u521b\u5efa\u7684\u5b9e\u4f8b\u3002</li> <li><code>call</code>\u3001<code>apply</code>\u3001<code>bind</code>\uff1a\u663e\u5f0f\u7ed1\u5b9a\u3002</li> <li>\u7bad\u5934\u51fd\u6570\uff1a\u6ca1\u6709\u81ea\u5df1\u7684 <code>this</code>\uff0c\u7ee7\u627f\u5916\u5c42\u4f5c\u7528\u57df\u7684 <code>this</code>\u3002</li> </ul> <pre><code>function sayName() {\n  console.log(this.name);\n}\n\nsayName.call({ name: \"Alice\" });\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#11-dom","title":"11. DOM \u64cd\u4f5c","text":"<p>\u83b7\u53d6\u5143\u7d20\uff1a</p> <pre><code>const title = document.querySelector(\".title\");\nconst items = document.querySelectorAll(\".item\");\n</code></pre> <p>\u4fee\u6539\u5185\u5bb9\uff1a</p> <pre><code>title.textContent = \"\u65b0\u6807\u9898\";\ntitle.innerHTML = \"&lt;span&gt;\u65b0\u6807\u9898&lt;/span&gt;\";\n</code></pre> <p>\u4fee\u6539\u6837\u5f0f\uff1a</p> <pre><code>title.style.color = \"red\";\ntitle.classList.add(\"active\");\ntitle.classList.remove(\"hidden\");\ntitle.classList.toggle(\"open\");\n</code></pre> <p>\u521b\u5efa\u5143\u7d20\uff1a</p> <pre><code>const li = document.createElement(\"li\");\nli.textContent = \"\u65b0\u5217\u8868\u9879\";\ndocument.querySelector(\"ul\").appendChild(li);\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#12","title":"12. \u4e8b\u4ef6","text":"<pre><code>const button = document.querySelector(\"button\");\n\nbutton.addEventListener(\"click\", (event) =&gt; {\n  console.log(event.target);\n});\n</code></pre> <p>\u4e8b\u4ef6\u6d41\uff1a</p> <ol> <li>\u6355\u83b7\u9636\u6bb5</li> <li>\u76ee\u6807\u9636\u6bb5</li> <li>\u5192\u6ce1\u9636\u6bb5</li> </ol> <p>\u963b\u6b62\u9ed8\u8ba4\u884c\u4e3a\uff1a</p> <pre><code>form.addEventListener(\"submit\", (event) =&gt; {\n  event.preventDefault();\n});\n</code></pre> <p>\u963b\u6b62\u5192\u6ce1\uff1a</p> <pre><code>button.addEventListener(\"click\", (event) =&gt; {\n  event.stopPropagation();\n});\n</code></pre> <p>\u4e8b\u4ef6\u59d4\u6258\uff1a</p> <pre><code>document.querySelector(\".list\").addEventListener(\"click\", (event) =&gt; {\n  if (event.target.matches(\"button\")) {\n    console.log(\"\u70b9\u51fb\u4e86\u6309\u94ae\");\n  }\n});\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#13","title":"13. \u5f02\u6b65\u7f16\u7a0b","text":"<p>\u56de\u8c03\u51fd\u6570\uff1a</p> <pre><code>setTimeout(() =&gt; {\n  console.log(\"1 \u79d2\u540e\u6267\u884c\");\n}, 1000);\n</code></pre> <p>Promise\uff1a</p> <pre><code>const request = new Promise((resolve, reject) =&gt; {\n  const success = true;\n\n  if (success) {\n    resolve(\"\u6210\u529f\");\n  } else {\n    reject(new Error(\"\u5931\u8d25\"));\n  }\n});\n\nrequest\n  .then((result) =&gt; {\n    console.log(result);\n  })\n  .catch((error) =&gt; {\n    console.error(error);\n  });\n</code></pre> <p>async/await\uff1a</p> <pre><code>async function getUser() {\n  try {\n    const response = await fetch(\"/api/user\");\n    const data = await response.json();\n    return data;\n  } catch (error) {\n    console.error(error);\n    return null;\n  }\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#14-fetch","title":"14. Fetch \u8bf7\u6c42","text":"<p>GET\uff1a</p> <pre><code>async function getList() {\n  const response = await fetch(\"/api/list\");\n\n  if (!response.ok) {\n    throw new Error(\"\u8bf7\u6c42\u5931\u8d25\");\n  }\n\n  return response.json();\n}\n</code></pre> <p>POST\uff1a</p> <pre><code>async function createUser(user) {\n  const response = await fetch(\"/api/users\", {\n    method: \"POST\",\n    headers: {\n      \"Content-Type\": \"application/json\",\n    },\n    body: JSON.stringify(user),\n  });\n\n  return response.json();\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#15","title":"15. \u9632\u6296\u548c\u8282\u6d41","text":"<p>\u9632\u6296\uff1a\u4e8b\u4ef6\u8fde\u7eed\u89e6\u53d1\u65f6\uff0c\u53ea\u5728\u6700\u540e\u4e00\u6b21\u89e6\u53d1\u540e\u6267\u884c\u3002\u9002\u5408\u641c\u7d22\u8f93\u5165\u3002</p> <pre><code>function debounce(fn, delay) {\n  let timer = null;\n\n  return function (...args) {\n    clearTimeout(timer);\n    timer = setTimeout(() =&gt; {\n      fn.apply(this, args);\n    }, delay);\n  };\n}\n</code></pre> <p>\u8282\u6d41\uff1a\u4e00\u6bb5\u65f6\u95f4\u5185\u6700\u591a\u6267\u884c\u4e00\u6b21\u3002\u9002\u5408\u6eda\u52a8\u3001\u62d6\u62fd\u3001\u7a97\u53e3 resize\u3002</p> <pre><code>function throttle(fn, delay) {\n  let lastTime = 0;\n\n  return function (...args) {\n    const now = Date.now();\n\n    if (now - lastTime &gt;= delay) {\n      lastTime = now;\n      fn.apply(this, args);\n    }\n  };\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#16","title":"16. \u6a21\u5757\u5316","text":"<p>\u5bfc\u51fa\uff1a</p> <pre><code>export const name = \"Alice\";\n\nexport function add(a, b) {\n  return a + b;\n}\n\nexport default function App() {\n  return \"App\";\n}\n</code></pre> <p>\u5bfc\u5165\uff1a</p> <pre><code>import App, { name, add } from \"./app.js\";\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#17","title":"17. \u5e38\u89c1\u9519\u8bef\u5904\u7406","text":"<pre><code>try {\n  JSON.parse(\"{ invalid json }\");\n} catch (error) {\n  console.error(\"\u89e3\u6790\u5931\u8d25\", error);\n}\n</code></pre> <p>\u5e38\u89c1\u9519\u8bef\u7c7b\u578b\uff1a</p> <ul> <li><code>SyntaxError</code>\uff1a\u8bed\u6cd5\u9519\u8bef\u3002</li> <li><code>ReferenceError</code>\uff1a\u5f15\u7528\u4e0d\u5b58\u5728\u7684\u53d8\u91cf\u3002</li> <li><code>TypeError</code>\uff1a\u7c7b\u578b\u9519\u8bef\u3002</li> <li><code>RangeError</code>\uff1a\u6570\u503c\u8d85\u51fa\u8303\u56f4\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#react","title":"React","text":"<p>React \u662f\u7528\u4e8e\u6784\u5efa\u7528\u6237\u754c\u9762\u7684 JavaScript \u5e93\u3002\u5b83\u901a\u8fc7\u7ec4\u4ef6\u5316\u3001\u58f0\u660e\u5f0f\u6e32\u67d3\u548c\u72b6\u6001\u9a71\u52a8\u89c6\u56fe\u6765\u7ec4\u7ec7\u590d\u6742\u754c\u9762\u3002</p>"},{"location":"%E5%89%8D%E7%AB%AF.html#1-react","title":"1. \u521b\u5efa React \u9879\u76ee","text":"<p>\u5e38\u7528\u65b9\u5f0f\uff1a</p> <pre><code>npm create vite@latest my-app -- --template react\ncd my-app\nnpm install\nnpm run dev\n</code></pre> <p>\u5e38\u89c1\u76ee\u5f55\uff1a</p> <pre><code>src/\n  App.jsx\n  main.jsx\n  components/\n  pages/\n  hooks/\n  utils/\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#2-jsx","title":"2. JSX","text":"<p>JSX \u662f JavaScript \u7684\u8bed\u6cd5\u6269\u5c55\uff0c\u53ef\u4ee5\u5728 JS \u4e2d\u5199\u7c7b\u4f3c HTML \u7684\u7ed3\u6784\u3002</p> <pre><code>function App() {\n  const title = \"React \u7b14\u8bb0\";\n\n  return (\n    &lt;main&gt;\n      &lt;h1&gt;{title}&lt;/h1&gt;\n      &lt;p&gt;\u7528\u7ec4\u4ef6\u6784\u5efa\u9875\u9762&lt;/p&gt;\n    &lt;/main&gt;\n  );\n}\n</code></pre> <p>\u6ce8\u610f\uff1a</p> <ul> <li>JSX \u4e2d\u53ea\u80fd\u8fd4\u56de\u4e00\u4e2a\u6839\u8282\u70b9\u3002</li> <li>\u4f7f\u7528 <code>className</code> \u4ee3\u66ff <code>class</code>\u3002</li> <li>\u4f7f\u7528 <code>htmlFor</code> \u4ee3\u66ff <code>for</code>\u3002</li> <li>JavaScript \u8868\u8fbe\u5f0f\u5199\u5728 <code>{}</code> \u4e2d\u3002</li> <li>\u6807\u7b7e\u5fc5\u987b\u95ed\u5408\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#3_3","title":"3. \u7ec4\u4ef6","text":"<p>\u51fd\u6570\u7ec4\u4ef6\uff1a</p> <pre><code>function Button() {\n  return &lt;button type=\"button\"&gt;\u70b9\u51fb&lt;/button&gt;;\n}\n</code></pre> <p>\u7ec4\u4ef6\u590d\u7528\uff1a</p> <pre><code>function UserCard({ name, age }) {\n  return (\n    &lt;section&gt;\n      &lt;h2&gt;{name}&lt;/h2&gt;\n      &lt;p&gt;{age} \u5c81&lt;/p&gt;\n    &lt;/section&gt;\n  );\n}\n\nfunction App() {\n  return &lt;UserCard name=\"Alice\" age={18} /&gt;;\n}\n</code></pre> <p>\u7ec4\u4ef6\u547d\u540d\uff1a</p> <ul> <li>\u7ec4\u4ef6\u540d\u5fc5\u987b\u4ee5\u5927\u5199\u5b57\u6bcd\u5f00\u5934\u3002</li> <li>\u6587\u4ef6\u540d\u901a\u5e38\u548c\u7ec4\u4ef6\u540d\u4e00\u81f4\u3002</li> <li>\u4e00\u4e2a\u7ec4\u4ef6\u53ea\u8d1f\u8d23\u4e00\u7c7b\u660e\u786e\u804c\u8d23\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#4-props","title":"4. Props","text":"<p>Props \u662f\u7236\u7ec4\u4ef6\u4f20\u7ed9\u5b50\u7ec4\u4ef6\u7684\u6570\u636e\u3002</p> <pre><code>function Welcome(props) {\n  return &lt;h1&gt;\u4f60\u597d\uff0c{props.name}&lt;/h1&gt;;\n}\n\nfunction App() {\n  return &lt;Welcome name=\"Alice\" /&gt;;\n}\n</code></pre> <p>\u89e3\u6784\u5199\u6cd5\uff1a</p> <pre><code>function Welcome({ name }) {\n  return &lt;h1&gt;\u4f60\u597d\uff0c{name}&lt;/h1&gt;;\n}\n</code></pre> <p>Props \u7279\u70b9\uff1a</p> <ul> <li>\u4ece\u7236\u7ec4\u4ef6\u6d41\u5411\u5b50\u7ec4\u4ef6\u3002</li> <li>\u5b50\u7ec4\u4ef6\u4e0d\u5e94\u8be5\u76f4\u63a5\u4fee\u6539 props\u3002</li> <li>props \u53ef\u4ee5\u662f\u5b57\u7b26\u4e32\u3001\u6570\u5b57\u3001\u5e03\u5c14\u503c\u3001\u6570\u7ec4\u3001\u5bf9\u8c61\u3001\u51fd\u6570\u6216 React \u8282\u70b9\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#5-state","title":"5. State","text":"<p>State \u662f\u7ec4\u4ef6\u5185\u90e8\u72b6\u6001\uff0c\u72b6\u6001\u53d8\u5316\u4f1a\u89e6\u53d1\u7ec4\u4ef6\u91cd\u65b0\u6e32\u67d3\u3002</p> <pre><code>import { useState } from \"react\";\n\nfunction Counter() {\n  const [count, setCount] = useState(0);\n\n  return (\n    &lt;div&gt;\n      &lt;p&gt;{count}&lt;/p&gt;\n      &lt;button type=\"button\" onClick={() =&gt; setCount(count + 1)}&gt;\n        +1\n      &lt;/button&gt;\n    &lt;/div&gt;\n  );\n}\n</code></pre> <p>\u57fa\u4e8e\u65e7\u72b6\u6001\u66f4\u65b0\uff1a</p> <pre><code>setCount((prevCount) =&gt; prevCount + 1);\n</code></pre> <p>\u5bf9\u8c61\u72b6\u6001\u66f4\u65b0\uff1a</p> <pre><code>const [user, setUser] = useState({ name: \"Alice\", age: 18 });\n\nsetUser((prevUser) =&gt; ({\n  ...prevUser,\n  age: 19,\n}));\n</code></pre> <p>\u6570\u7ec4\u72b6\u6001\u66f4\u65b0\uff1a</p> <pre><code>const [list, setList] = useState([]);\n\nsetList((prevList) =&gt; [...prevList, newItem]);\nsetList((prevList) =&gt; prevList.filter((item) =&gt; item.id !== id));\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#6_2","title":"6. \u6761\u4ef6\u6e32\u67d3","text":"<pre><code>function UserInfo({ user }) {\n  if (!user) {\n    return &lt;p&gt;\u8bf7\u5148\u767b\u5f55&lt;/p&gt;;\n  }\n\n  return &lt;p&gt;\u6b22\u8fce\uff0c{user.name}&lt;/p&gt;;\n}\n</code></pre> <p>\u4e09\u5143\u8868\u8fbe\u5f0f\uff1a</p> <pre><code>{isLogin ? &lt;UserPanel /&gt; : &lt;LoginButton /&gt;}\n</code></pre> <p>\u903b\u8f91\u4e0e\uff1a</p> <pre><code>{message &amp;&amp; &lt;p&gt;{message}&lt;/p&gt;}\n</code></pre> <p>\u6ce8\u610f\uff1a\u5982\u679c <code>message</code> \u53ef\u80fd\u662f <code>0</code>\uff0c\u903b\u8f91\u4e0e\u53ef\u80fd\u6e32\u67d3\u51fa <code>0</code>\uff0c\u9700\u8981\u8f6c\u6362\u4e3a\u5e03\u5c14\u503c\u3002</p> <pre><code>{Boolean(message) &amp;&amp; &lt;p&gt;{message}&lt;/p&gt;}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#7_1","title":"7. \u5217\u8868\u6e32\u67d3","text":"<pre><code>function TodoList({ todos }) {\n  return (\n    &lt;ul&gt;\n      {todos.map((todo) =&gt; (\n        &lt;li key={todo.id}&gt;{todo.title}&lt;/li&gt;\n      ))}\n    &lt;/ul&gt;\n  );\n}\n</code></pre> <p><code>key</code> \u7684\u4f5c\u7528\uff1a</p> <ul> <li>\u5e2e\u52a9 React \u8bc6\u522b\u5217\u8868\u9879\u3002</li> <li>\u63d0\u9ad8\u66f4\u65b0\u6548\u7387\u3002</li> <li>\u907f\u514d\u72b6\u6001\u9519\u4e71\u3002</li> </ul> <p>\u5efa\u8bae\uff1a</p> <ul> <li>\u4f18\u5148\u4f7f\u7528\u7a33\u5b9a\u552f\u4e00\u7684\u4e1a\u52a1 ID\u3002</li> <li>\u4e0d\u63a8\u8350\u4f7f\u7528\u6570\u7ec4\u7d22\u5f15\u4f5c\u4e3a key\uff0c\u9664\u975e\u5217\u8868\u5b8c\u5168\u9759\u6001\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#8_1","title":"8. \u4e8b\u4ef6\u5904\u7406","text":"<pre><code>function Button() {\n  function handleClick(event) {\n    console.log(event.target);\n  }\n\n  return (\n    &lt;button type=\"button\" onClick={handleClick}&gt;\n      \u70b9\u51fb\n    &lt;/button&gt;\n  );\n}\n</code></pre> <p>\u4f20\u53c2\uff1a</p> <pre><code>&lt;button type=\"button\" onClick={() =&gt; handleDelete(item.id)}&gt;\n  \u5220\u9664\n&lt;/button&gt;\n</code></pre> <p>\u6ce8\u610f\uff1a\u4e0d\u8981\u76f4\u63a5\u6267\u884c\u51fd\u6570\u3002</p> <pre><code>// \u9519\u8bef\n&lt;button onClick={handleDelete(id)}&gt;\u5220\u9664&lt;/button&gt;\n\n// \u6b63\u786e\n&lt;button onClick={() =&gt; handleDelete(id)}&gt;\u5220\u9664&lt;/button&gt;\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#9_1","title":"9. \u8868\u5355\u5904\u7406","text":"<p>\u53d7\u63a7\u7ec4\u4ef6\uff1a\u8868\u5355\u503c\u7531 React state \u63a7\u5236\u3002</p> <pre><code>import { useState } from \"react\";\n\nfunction LoginForm() {\n  const [form, setForm] = useState({\n    username: \"\",\n    password: \"\",\n  });\n\n  function handleChange(event) {\n    const { name, value } = event.target;\n\n    setForm((prevForm) =&gt; ({\n      ...prevForm,\n      [name]: value,\n    }));\n  }\n\n  function handleSubmit(event) {\n    event.preventDefault();\n    console.log(form);\n  }\n\n  return (\n    &lt;form onSubmit={handleSubmit}&gt;\n      &lt;input\n        name=\"username\"\n        value={form.username}\n        onChange={handleChange}\n      /&gt;\n      &lt;input\n        name=\"password\"\n        type=\"password\"\n        value={form.password}\n        onChange={handleChange}\n      /&gt;\n      &lt;button type=\"submit\"&gt;\u767b\u5f55&lt;/button&gt;\n    &lt;/form&gt;\n  );\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#10-useeffect","title":"10. useEffect","text":"<p><code>useEffect</code> \u7528\u4e8e\u5904\u7406\u526f\u4f5c\u7528\uff0c\u4f8b\u5982\u8bf7\u6c42\u6570\u636e\u3001\u8ba2\u9605\u4e8b\u4ef6\u3001\u64cd\u4f5c DOM\u3001\u5b9a\u65f6\u5668\u7b49\u3002</p> <pre><code>import { useEffect, useState } from \"react\";\n\nfunction UserList() {\n  const [users, setUsers] = useState([]);\n\n  useEffect(() =&gt; {\n    async function fetchUsers() {\n      const response = await fetch(\"/api/users\");\n      const data = await response.json();\n      setUsers(data);\n    }\n\n    fetchUsers();\n  }, []);\n\n  return (\n    &lt;ul&gt;\n      {users.map((user) =&gt; (\n        &lt;li key={user.id}&gt;{user.name}&lt;/li&gt;\n      ))}\n    &lt;/ul&gt;\n  );\n}\n</code></pre> <p>\u4f9d\u8d56\u6570\u7ec4\uff1a</p> <ul> <li>\u4e0d\u5199\u4f9d\u8d56\u6570\u7ec4\uff1a\u6bcf\u6b21\u6e32\u67d3\u540e\u6267\u884c\u3002</li> <li><code>[]</code>\uff1a\u7ec4\u4ef6\u6302\u8f7d\u540e\u6267\u884c\u4e00\u6b21\u3002</li> <li><code>[value]</code>\uff1a<code>value</code> \u53d8\u5316\u540e\u6267\u884c\u3002</li> </ul> <p>\u6e05\u7406\u526f\u4f5c\u7528\uff1a</p> <pre><code>useEffect(() =&gt; {\n  const timer = setInterval(() =&gt; {\n    console.log(\"tick\");\n  }, 1000);\n\n  return () =&gt; {\n    clearInterval(timer);\n  };\n}, []);\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#11-useref","title":"11. useRef","text":"<p><code>useRef</code> \u53ef\u4ee5\u4fdd\u5b58\u4e00\u4e2a\u53ef\u53d8\u503c\uff0c\u4fee\u6539\u5b83\u4e0d\u4f1a\u89e6\u53d1\u91cd\u65b0\u6e32\u67d3\u3002\u4e5f\u5e38\u7528\u4e8e\u8bbf\u95ee DOM\u3002</p> <pre><code>import { useRef } from \"react\";\n\nfunction SearchInput() {\n  const inputRef = useRef(null);\n\n  function focusInput() {\n    inputRef.current.focus();\n  }\n\n  return (\n    &lt;div&gt;\n      &lt;input ref={inputRef} /&gt;\n      &lt;button type=\"button\" onClick={focusInput}&gt;\n        \u805a\u7126\n      &lt;/button&gt;\n    &lt;/div&gt;\n  );\n}\n</code></pre> <p>\u4fdd\u5b58\u5b9a\u65f6\u5668\uff1a</p> <pre><code>const timerRef = useRef(null);\n\ntimerRef.current = setTimeout(() =&gt; {\n  console.log(\"done\");\n}, 1000);\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#12-usememo-usecallback","title":"12. useMemo \u548c useCallback","text":"<p><code>useMemo</code> \u7f13\u5b58\u8ba1\u7b97\u7ed3\u679c\uff1a</p> <pre><code>const total = useMemo(() =&gt; {\n  return list.reduce((sum, item) =&gt; sum + item.price, 0);\n}, [list]);\n</code></pre> <p><code>useCallback</code> \u7f13\u5b58\u51fd\u6570\u5f15\u7528\uff1a</p> <pre><code>const handleClick = useCallback(() =&gt; {\n  setCount((prevCount) =&gt; prevCount + 1);\n}, []);\n</code></pre> <p>\u4f7f\u7528\u5efa\u8bae\uff1a</p> <ul> <li>\u4e0d\u8981\u4e3a\u4e86\u4f7f\u7528\u800c\u4f7f\u7528\u3002</li> <li>\u5f53\u8ba1\u7b97\u6210\u672c\u8f83\u9ad8\uff0c\u6216\u51fd\u6570\u9700\u8981\u4f5c\u4e3a\u4f9d\u8d56\u4f20\u7ed9\u5b50\u7ec4\u4ef6\u65f6\u518d\u8003\u8651\u3002</li> <li>\u5148\u4fdd\u8bc1\u4ee3\u7801\u6b63\u786e\uff0c\u518d\u8003\u8651\u6027\u80fd\u4f18\u5316\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#13-hook","title":"13. \u81ea\u5b9a\u4e49 Hook","text":"<p>\u81ea\u5b9a\u4e49 Hook \u7528\u4e8e\u590d\u7528\u72b6\u6001\u903b\u8f91\uff0c\u540d\u79f0\u5fc5\u987b\u4ee5 <code>use</code> \u5f00\u5934\u3002</p> <pre><code>import { useEffect, useState } from \"react\";\n\nfunction useFetch(url) {\n  const [data, setData] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n\n  useEffect(() =&gt; {\n    let ignore = false;\n\n    async function request() {\n      try {\n        setLoading(true);\n        const response = await fetch(url);\n\n        if (!response.ok) {\n          throw new Error(\"\u8bf7\u6c42\u5931\u8d25\");\n        }\n\n        const result = await response.json();\n\n        if (!ignore) {\n          setData(result);\n        }\n      } catch (requestError) {\n        if (!ignore) {\n          setError(requestError);\n        }\n      } finally {\n        if (!ignore) {\n          setLoading(false);\n        }\n      }\n    }\n\n    request();\n\n    return () =&gt; {\n      ignore = true;\n    };\n  }, [url]);\n\n  return { data, loading, error };\n}\n</code></pre> <p>\u4f7f\u7528\uff1a</p> <pre><code>function UserPage() {\n  const { data, loading, error } = useFetch(\"/api/users\");\n\n  if (loading) return &lt;p&gt;\u52a0\u8f7d\u4e2d&lt;/p&gt;;\n  if (error) return &lt;p&gt;\u52a0\u8f7d\u5931\u8d25&lt;/p&gt;;\n\n  return &lt;pre&gt;{JSON.stringify(data, null, 2)}&lt;/pre&gt;;\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#14","title":"14. \u7ec4\u4ef6\u901a\u4fe1","text":"<p>\u7236\u4f20\u5b50\uff1a\u4f7f\u7528 props\u3002</p> <pre><code>function Parent() {\n  return &lt;Child name=\"Alice\" /&gt;;\n}\n\nfunction Child({ name }) {\n  return &lt;p&gt;{name}&lt;/p&gt;;\n}\n</code></pre> <p>\u5b50\u4f20\u7236\uff1a\u7236\u7ec4\u4ef6\u4f20\u51fd\u6570\u7ed9\u5b50\u7ec4\u4ef6\u3002</p> <pre><code>function Parent() {\n  function handleChange(value) {\n    console.log(value);\n  }\n\n  return &lt;Child onChange={handleChange} /&gt;;\n}\n\nfunction Child({ onChange }) {\n  return (\n    &lt;button type=\"button\" onClick={() =&gt; onChange(\"hello\")}&gt;\n      \u901a\u77e5\u7236\u7ec4\u4ef6\n    &lt;/button&gt;\n  );\n}\n</code></pre> <p>\u8de8\u5c42\u7ea7\u901a\u4fe1\uff1a\u4f7f\u7528 Context\u3002</p> <pre><code>import { createContext, useContext } from \"react\";\n\nconst ThemeContext = createContext(\"light\");\n\nfunction App() {\n  return (\n    &lt;ThemeContext.Provider value=\"dark\"&gt;\n      &lt;Toolbar /&gt;\n    &lt;/ThemeContext.Provider&gt;\n  );\n}\n\nfunction Toolbar() {\n  const theme = useContext(ThemeContext);\n  return &lt;p&gt;\u5f53\u524d\u4e3b\u9898\uff1a{theme}&lt;/p&gt;;\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#15-context","title":"15. Context \u4f7f\u7528\u5efa\u8bae","text":"<p>\u9002\u5408\uff1a</p> <ul> <li>\u5f53\u524d\u7528\u6237\u4fe1\u606f\u3002</li> <li>\u4e3b\u9898\u3002</li> <li>\u8bed\u8a00\u3002</li> <li>\u5168\u5c40\u914d\u7f6e\u3002</li> </ul> <p>\u4e0d\u9002\u5408\uff1a</p> <ul> <li>\u6240\u6709\u4e1a\u52a1\u72b6\u6001\u90fd\u653e\u5165 Context\u3002</li> <li>\u9ad8\u9891\u53d8\u5316\u7684\u5927\u578b\u72b6\u6001\u76f4\u63a5\u653e\u5165 Context\uff0c\u53ef\u80fd\u5f15\u8d77\u4e0d\u5fc5\u8981\u6e32\u67d3\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#16-react-router","title":"16. React Router \u57fa\u7840","text":"<p>\u5e38\u89c1\u5199\u6cd5\uff1a</p> <pre><code>import { BrowserRouter, Link, Route, Routes } from \"react-router-dom\";\n\nfunction App() {\n  return (\n    &lt;BrowserRouter&gt;\n      &lt;nav&gt;\n        &lt;Link to=\"/\"&gt;\u9996\u9875&lt;/Link&gt;\n        &lt;Link to=\"/about\"&gt;\u5173\u4e8e&lt;/Link&gt;\n      &lt;/nav&gt;\n\n      &lt;Routes&gt;\n        &lt;Route path=\"/\" element={&lt;Home /&gt;} /&gt;\n        &lt;Route path=\"/about\" element={&lt;About /&gt;} /&gt;\n      &lt;/Routes&gt;\n    &lt;/BrowserRouter&gt;\n  );\n}\n</code></pre> <p>\u52a8\u6001\u8def\u7531\uff1a</p> <pre><code>import { useParams } from \"react-router-dom\";\n\nfunction UserDetail() {\n  const { id } = useParams();\n  return &lt;p&gt;\u7528\u6237 ID\uff1a{id}&lt;/p&gt;;\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#17_1","title":"17. \u72b6\u6001\u7ba1\u7406\u601d\u8def","text":"<p>\u72b6\u6001\u5e94\u8be5\u653e\u5728\u54ea\u91cc\uff1a</p> <ul> <li>\u53ea\u6709\u4e00\u4e2a\u7ec4\u4ef6\u7528\uff1a\u653e\u5728\u5f53\u524d\u7ec4\u4ef6\u3002</li> <li>\u591a\u4e2a\u5144\u5f1f\u7ec4\u4ef6\u7528\uff1a\u63d0\u5347\u5230\u5171\u540c\u7236\u7ec4\u4ef6\u3002</li> <li>\u591a\u5c42\u7ec4\u4ef6\u5171\u4eab\uff1a\u8003\u8651 Context\u3002</li> <li>\u5927\u578b\u5e94\u7528\u590d\u6742\u5171\u4eab\u72b6\u6001\uff1a\u8003\u8651 Zustand\u3001Redux Toolkit\u3001Jotai \u7b49\u72b6\u6001\u5e93\u3002</li> </ul> <p>\u5224\u65ad\u72b6\u6001\u662f\u5426\u5fc5\u8981\uff1a</p> <ul> <li>\u80fd\u4ece props \u8ba1\u7b97\u51fa\u6765\u7684\uff0c\u4e0d\u4e00\u5b9a\u8981\u5b58 state\u3002</li> <li>\u4e0d\u53c2\u4e0e\u6e32\u67d3\u7684\u503c\uff0c\u53ef\u4ee5\u7528 <code>useRef</code>\u3002</li> <li>\u670d\u52a1\u7aef\u6570\u636e\u53ef\u4ee5\u4ea4\u7ed9 React Query\u3001SWR \u7b49\u8bf7\u6c42\u7f13\u5b58\u5e93\u7ba1\u7406\u3002</li> </ul>"},{"location":"%E5%89%8D%E7%AB%AF.html#18","title":"18. \u6027\u80fd\u4f18\u5316","text":"<p>\u5e38\u89c1\u65b9\u5411\uff1a</p> <ul> <li>\u4f7f\u7528\u7a33\u5b9a\u7684 <code>key</code>\u3002</li> <li>\u907f\u514d\u4e0d\u5fc5\u8981\u7684 state\u3002</li> <li>\u62c6\u5206\u7ec4\u4ef6\uff0c\u7f29\u5c0f\u91cd\u6e32\u67d3\u8303\u56f4\u3002</li> <li>\u5bf9\u6602\u8d35\u8ba1\u7b97\u4f7f\u7528 <code>useMemo</code>\u3002</li> <li>\u5bf9\u4f20\u7ed9\u5b50\u7ec4\u4ef6\u7684\u56de\u8c03\u4f7f\u7528 <code>useCallback</code>\u3002</li> <li>\u5927\u5217\u8868\u4f7f\u7528\u865a\u62df\u5217\u8868\u3002</li> <li>\u8def\u7531\u9875\u9762\u4f7f\u7528\u61d2\u52a0\u8f7d\u3002</li> </ul> <p>\u61d2\u52a0\u8f7d\uff1a</p> <pre><code>import { lazy, Suspense } from \"react\";\n\nconst About = lazy(() =&gt; import(\"./pages/About\"));\n\nfunction App() {\n  return (\n    &lt;Suspense fallback={&lt;p&gt;\u52a0\u8f7d\u4e2d&lt;/p&gt;}&gt;\n      &lt;About /&gt;\n    &lt;/Suspense&gt;\n  );\n}\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#19","title":"19. \u5e38\u89c1\u9519\u8bef","text":"<p>\u76f4\u63a5\u4fee\u6539 state\uff1a</p> <pre><code>// \u9519\u8bef\nuser.age = 20;\nsetUser(user);\n\n// \u6b63\u786e\nsetUser((prevUser) =&gt; ({\n  ...prevUser,\n  age: 20,\n}));\n</code></pre> <p>\u5728\u6761\u4ef6\u4e2d\u8c03\u7528 Hook\uff1a</p> <pre><code>// \u9519\u8bef\nif (show) {\n  const [value, setValue] = useState(\"\");\n}\n\n// \u6b63\u786e\nconst [value, setValue] = useState(\"\");\n</code></pre> <p>\u5fd8\u8bb0\u6e05\u7406\u526f\u4f5c\u7528\uff1a</p> <pre><code>useEffect(() =&gt; {\n  const handleResize = () =&gt; {\n    console.log(window.innerWidth);\n  };\n\n  window.addEventListener(\"resize\", handleResize);\n\n  return () =&gt; {\n    window.removeEventListener(\"resize\", handleResize);\n  };\n}, []);\n</code></pre>"},{"location":"%E5%89%8D%E7%AB%AF.html#20-react","title":"20. React \u7ec4\u4ef6\u8bbe\u8ba1\u539f\u5219","text":"<ul> <li>\u7ec4\u4ef6\u804c\u8d23\u5355\u4e00\u3002</li> <li>Props \u547d\u540d\u6e05\u6670\u3002</li> <li>\u72b6\u6001\u5c3d\u91cf\u9760\u8fd1\u4f7f\u7528\u5b83\u7684\u5730\u65b9\u3002</li> <li>\u6d3e\u751f\u6570\u636e\u4f18\u5148\u8ba1\u7b97\uff0c\u4e0d\u8f7b\u6613\u5b58\u5165 state\u3002</li> <li>\u526f\u4f5c\u7528\u653e\u5728 <code>useEffect</code> \u6216\u4e8b\u4ef6\u5904\u7406\u51fd\u6570\u4e2d\u3002</li> <li>UI \u7ec4\u4ef6\u548c\u4e1a\u52a1\u903b\u8f91\u9002\u5f53\u5206\u79bb\u3002</li> <li>\u590d\u7528\u903b\u8f91\u4f18\u5148\u8003\u8651\u81ea\u5b9a\u4e49 Hook\u3002</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html","title":"\u540e\u7aef","text":""},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#_1","title":"\u4e00\u3001\u540e\u7aef\u5f00\u53d1\u57fa\u7840","text":""},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#1","title":"1. \u540e\u7aef\u7684\u804c\u8d23","text":"<p>\u540e\u7aef\u4e3b\u8981\u8d1f\u8d23\u5904\u7406\u4e1a\u52a1\u903b\u8f91\u3001\u7ba1\u7406\u6570\u636e\u3001\u63d0\u4f9b\u63a5\u53e3\uff0c\u5e76\u4fdd\u8bc1\u7cfb\u7edf\u5b89\u5168\u3001\u7a33\u5b9a\u548c\u53ef\u7ef4\u62a4\u3002</p> <p>\u5e38\u89c1\u804c\u8d23\u5305\u62ec\uff1a</p> <ul> <li>\u63a5\u6536\u524d\u7aef\u6216\u5176\u4ed6\u670d\u52a1\u7684\u8bf7\u6c42</li> <li>\u6821\u9a8c\u8bf7\u6c42\u53c2\u6570</li> <li>\u6267\u884c\u4e1a\u52a1\u903b\u8f91</li> <li>\u8bfb\u5199\u6570\u636e\u5e93</li> <li>\u8c03\u7528\u7b2c\u4e09\u65b9\u670d\u52a1</li> <li>\u5904\u7406\u767b\u5f55\u3001\u9274\u6743\u548c\u6743\u9650\u63a7\u5236</li> <li>\u8fd4\u56de\u7edf\u4e00\u683c\u5f0f\u7684\u54cd\u5e94</li> <li>\u8bb0\u5f55\u65e5\u5fd7\u548c\u5904\u7406\u5f02\u5e38</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#2-api","title":"2. API \u7684\u5236\u5b9a","text":"<p>API \u662f\u524d\u7aef\u3001\u540e\u7aef\u548c\u5176\u4ed6\u7cfb\u7edf\u4e4b\u95f4\u7684\u901a\u4fe1\u7ea6\u5b9a\u3002\u8bbe\u8ba1 API \u65f6\u8981\u4fdd\u8bc1\u6e05\u6670\u3001\u7a33\u5b9a\u3001\u6613\u6269\u5c55\u3002</p> <p>\u5e38\u89c1\u8bbe\u8ba1\u8981\u70b9\uff1a</p> <ul> <li>\u4f7f\u7528\u6e05\u6670\u7684\u8d44\u6e90\u8def\u5f84\uff0c\u4f8b\u5982 <code>/users</code>\u3001<code>/orders</code></li> <li>\u4f7f\u7528 HTTP \u65b9\u6cd5\u8868\u8fbe\u64cd\u4f5c\u8bed\u4e49</li> <li>\u4f7f\u7528\u7edf\u4e00\u7684\u54cd\u5e94\u683c\u5f0f</li> <li>\u4f7f\u7528\u7edf\u4e00\u7684\u9519\u8bef\u7801</li> <li>\u652f\u6301\u5206\u9875\u3001\u6392\u5e8f\u548c\u7b5b\u9009</li> <li>\u6ce8\u610f\u63a5\u53e3\u5e42\u7b49\u6027</li> <li>\u4fdd\u6301\u63a5\u53e3\u7248\u672c\u517c\u5bb9</li> </ul> <p>\u5e38\u89c1 HTTP \u65b9\u6cd5\uff1a</p> <ul> <li><code>GET</code>\uff1a\u67e5\u8be2\u8d44\u6e90</li> <li><code>POST</code>\uff1a\u521b\u5efa\u8d44\u6e90</li> <li><code>PUT</code>\uff1a\u6574\u4f53\u66f4\u65b0\u8d44\u6e90</li> <li><code>PATCH</code>\uff1a\u5c40\u90e8\u66f4\u65b0\u8d44\u6e90</li> <li><code>DELETE</code>\uff1a\u5220\u9664\u8d44\u6e90</li> </ul> <p>\u7edf\u4e00\u54cd\u5e94\u793a\u4f8b\uff1a</p> <pre><code>{\n  \"code\": 0,\n  \"message\": \"success\",\n  \"data\": {}\n}\n</code></pre>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#3","title":"3. \u53c2\u6570\u6821\u9a8c","text":"<p>\u540e\u7aef\u5fc5\u987b\u8fdb\u884c\u53c2\u6570\u6821\u9a8c\uff0c\u4e0d\u80fd\u53ea\u4f9d\u8d56\u524d\u7aef\u6821\u9a8c\u3002</p> <p>\u5e38\u89c1\u6821\u9a8c\u5185\u5bb9\uff1a</p> <ul> <li>\u5fc5\u586b\u5b57\u6bb5\u662f\u5426\u4e3a\u7a7a</li> <li>\u5b57\u7b26\u4e32\u957f\u5ea6\u662f\u5426\u5408\u6cd5</li> <li>\u6570\u5b57\u8303\u56f4\u662f\u5426\u5408\u6cd5</li> <li>\u90ae\u7bb1\u3001\u624b\u673a\u53f7\u3001URL \u7b49\u683c\u5f0f\u662f\u5426\u5408\u6cd5</li> <li>\u679a\u4e3e\u503c\u662f\u5426\u5408\u6cd5</li> <li>\u5f53\u524d\u7528\u6237\u662f\u5426\u6709\u6743\u9650\u64cd\u4f5c\u8be5\u8d44\u6e90</li> </ul> <p>\u53c2\u6570\u6821\u9a8c\u53ef\u4ee5\u907f\u514d\u810f\u6570\u636e\u8fdb\u5165\u7cfb\u7edf\uff0c\u4e5f\u53ef\u4ee5\u964d\u4f4e\u5b89\u5168\u98ce\u9669\u3002</p>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#4","title":"4. \u6d4b\u8bd5\u65b9\u6cd5\u8bba","text":"<p>\u540e\u7aef\u6d4b\u8bd5\u7528\u4e8e\u4fdd\u8bc1\u4e1a\u52a1\u903b\u8f91\u6b63\u786e\u3001\u63a5\u53e3\u7a33\u5b9a\u3001\u7cfb\u7edf\u6539\u52a8\u4e0d\u4f1a\u5f15\u5165\u660e\u663e\u56de\u5f52\u3002</p> <p>\u5e38\u89c1\u6d4b\u8bd5\u7c7b\u578b\uff1a</p> <ul> <li>\u5355\u5143\u6d4b\u8bd5\uff1a\u6d4b\u8bd5\u51fd\u6570\u3001\u65b9\u6cd5\u6216\u5c0f\u6a21\u5757</li> <li>\u96c6\u6210\u6d4b\u8bd5\uff1a\u6d4b\u8bd5\u6570\u636e\u5e93\u3001\u7f13\u5b58\u3001\u7b2c\u4e09\u65b9\u63a5\u53e3\u7b49\u7ec4\u4ef6\u534f\u4f5c</li> <li>\u63a5\u53e3\u6d4b\u8bd5\uff1a\u6d4b\u8bd5 API \u5165\u53c2\u3001\u8fd4\u56de\u503c\u548c\u72b6\u6001\u7801</li> <li>\u56de\u5f52\u6d4b\u8bd5\uff1a\u9a8c\u8bc1\u65b0\u4fee\u6539\u6ca1\u6709\u7834\u574f\u65e7\u529f\u80fd</li> </ul> <p>\u6d4b\u8bd5\u91cd\u70b9\uff1a</p> <ul> <li>\u6838\u5fc3\u4e1a\u52a1\u6d41\u7a0b</li> <li>\u590d\u6742\u6761\u4ef6\u5206\u652f</li> <li>\u6743\u9650\u5224\u65ad</li> <li>\u6570\u636e\u5e93\u8bfb\u5199\u903b\u8f91</li> <li>\u5f02\u5e38\u573a\u666f</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#5","title":"5. \u6587\u4ef6\u5904\u7406\u4e0e\u4e91\u5b58\u50a8","text":"<p>\u6587\u4ef6\u5904\u7406\u662f\u540e\u7aef\u5e38\u89c1\u529f\u80fd\uff0c\u4f8b\u5982\u5934\u50cf\u4e0a\u4f20\u3001\u9644\u4ef6\u4e0a\u4f20\u3001\u5bfc\u5165\u5bfc\u51fa\u6587\u4ef6\u3002</p> <p>\u5e38\u89c1\u8bbe\u8ba1\u65b9\u5f0f\uff1a</p> <ul> <li>\u5c0f\u6587\u4ef6\u53ef\u4ee5\u76f4\u63a5\u901a\u8fc7\u540e\u7aef\u4e0a\u4f20</li> <li>\u5927\u6587\u4ef6\u9002\u5408\u5206\u7247\u4e0a\u4f20</li> <li>\u6587\u4ef6\u672c\u4f53\u901a\u5e38\u653e\u5bf9\u8c61\u5b58\u50a8</li> <li>\u6570\u636e\u5e93\u53ea\u4fdd\u5b58\u6587\u4ef6\u5143\u4fe1\u606f</li> <li>\u4e0b\u8f7d\u53ef\u4ee5\u4f7f\u7528\u7b7e\u540d URL \u63a7\u5236\u8bbf\u95ee\u6743\u9650</li> </ul> <p>\u6587\u4ef6\u5143\u4fe1\u606f\u901a\u5e38\u5305\u62ec\uff1a</p> <ul> <li>\u6587\u4ef6\u540d</li> <li>\u6587\u4ef6\u5927\u5c0f</li> <li>\u6587\u4ef6\u7c7b\u578b</li> <li>\u5b58\u50a8\u5730\u5740</li> <li>\u4e0a\u4f20\u7528\u6237</li> <li>\u4e0a\u4f20\u65f6\u95f4</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#6-golang","title":"6. Golang \u540e\u7aef\u5f00\u53d1","text":"<p>Go \u5e38\u7528\u4e8e\u5f00\u53d1\u540e\u7aef\u670d\u52a1\uff0c\u7279\u70b9\u662f\u8bed\u6cd5\u7b80\u6d01\u3001\u5e76\u53d1\u80fd\u529b\u5f3a\u3001\u90e8\u7f72\u65b9\u4fbf\u3002</p> <p>\u540e\u7aef\u5f00\u53d1\u4e2d\u9700\u8981\u91cd\u70b9\u638c\u63e1\uff1a</p> <ul> <li><code>goroutine</code>\uff1a\u8f7b\u91cf\u7ea7\u5e76\u53d1\u6267\u884c\u5355\u5143</li> <li><code>channel</code>\uff1a\u534f\u7a0b\u4e4b\u95f4\u901a\u4fe1</li> <li><code>context</code>\uff1a\u63a7\u5236\u8d85\u65f6\u3001\u53d6\u6d88\u548c\u8bf7\u6c42\u94fe\u8def</li> <li><code>interface</code>\uff1a\u62bd\u8c61\u80fd\u529b</li> <li><code>error</code>\uff1a\u663e\u5f0f\u9519\u8bef\u5904\u7406</li> <li><code>net/http</code>\uff1aHTTP \u670d\u52a1\u57fa\u7840\u5e93</li> </ul> <p>Go \u540e\u7aef\u9879\u76ee\u5e38\u89c1\u5206\u5c42\uff1a</p> <ul> <li>handler/controller\uff1a\u5904\u7406 HTTP \u8bf7\u6c42</li> <li>service\uff1a\u5904\u7406\u4e1a\u52a1\u903b\u8f91</li> <li>repository/dao\uff1a\u5904\u7406\u6570\u636e\u5e93\u8bbf\u95ee</li> <li>model/entity\uff1a\u5b9a\u4e49\u6570\u636e\u7ed3\u6784</li> <li>middleware\uff1a\u5904\u7406\u4e2d\u95f4\u4ef6\u903b\u8f91\uff0c\u4f8b\u5982\u9274\u6743\u3001\u65e5\u5fd7\u3001\u8de8\u57df</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#_2","title":"\u4e8c\u3001\u6570\u636e\u5e93\u57fa\u7840","text":""},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#1_1","title":"1. \u6570\u636e\u5e93\u7684\u4f5c\u7528","text":"<p>\u6570\u636e\u5e93\u7528\u4e8e\u6301\u4e45\u5316\u4fdd\u5b58\u4e1a\u52a1\u6570\u636e\uff0c\u5e76\u63d0\u4f9b\u53ef\u9760\u7684\u6570\u636e\u67e5\u8be2\u3001\u66f4\u65b0\u548c\u4e8b\u52a1\u80fd\u529b\u3002</p> <p>\u5e38\u89c1\u6570\u636e\u5e93\u7c7b\u578b\uff1a</p> <ul> <li>\u5173\u7cfb\u578b\u6570\u636e\u5e93\uff1aMySQL\u3001PostgreSQL</li> <li>\u7f13\u5b58\u6570\u636e\u5e93\uff1aRedis</li> <li>\u6587\u6863\u6570\u636e\u5e93\uff1aMongoDB</li> <li>\u641c\u7d22\u5f15\u64ce\uff1aElasticsearch</li> <li>\u5411\u91cf\u6570\u636e\u5e93\uff1aMilvus\u3001Qdrant\u3001Pinecone</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#2","title":"2. \u5173\u7cfb\u578b\u6570\u636e\u5e93\u6838\u5fc3\u6982\u5ff5","text":"<ul> <li>\u8868\uff1a\u4fdd\u5b58\u67d0\u7c7b\u4e1a\u52a1\u6570\u636e</li> <li>\u884c\uff1a\u4e00\u6761\u5177\u4f53\u8bb0\u5f55</li> <li>\u5217\uff1a\u6570\u636e\u5b57\u6bb5</li> <li>\u4e3b\u952e\uff1a\u552f\u4e00\u6807\u8bc6\u4e00\u6761\u8bb0\u5f55</li> <li>\u5916\u952e\uff1a\u5efa\u7acb\u8868\u4e4b\u95f4\u7684\u5173\u8054</li> <li>\u7d22\u5f15\uff1a\u63d0\u5347\u67e5\u8be2\u6548\u7387</li> <li>\u4e8b\u52a1\uff1a\u4fdd\u8bc1\u4e00\u7ec4\u64cd\u4f5c\u8981\u4e48\u5168\u90e8\u6210\u529f\uff0c\u8981\u4e48\u5168\u90e8\u5931\u8d25</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#3_1","title":"3. \u8868\u7ed3\u6784\u8bbe\u8ba1","text":"<p>\u8868\u7ed3\u6784\u8bbe\u8ba1\u8981\u56f4\u7ed5\u4e1a\u52a1\u5b9e\u4f53\u5c55\u5f00\u3002</p> <p>\u8bbe\u8ba1\u65f6\u8981\u5173\u6ce8\uff1a</p> <ul> <li>\u5b57\u6bb5\u662f\u5426\u5b8c\u6574</li> <li>\u5b57\u6bb5\u7c7b\u578b\u662f\u5426\u5408\u9002</li> <li>\u4e3b\u952e\u662f\u5426\u7a33\u5b9a</li> <li>\u662f\u5426\u9700\u8981\u552f\u4e00\u7ea6\u675f</li> <li>\u662f\u5426\u9700\u8981\u5916\u952e\u6216\u903b\u8f91\u5173\u8054</li> <li>\u662f\u5426\u9700\u8981\u521b\u5efa\u7d22\u5f15</li> <li>\u662f\u5426\u5b58\u5728\u5197\u4f59\u5b57\u6bb5</li> </ul> <p>\u7528\u6237\u8868\u793a\u4f8b\uff1a</p> <pre><code>CREATE TABLE users (\n  id BIGINT PRIMARY KEY,\n  username VARCHAR(64) NOT NULL UNIQUE,\n  password_hash VARCHAR(255) NOT NULL,\n  email VARCHAR(128),\n  created_at TIMESTAMP NOT NULL,\n  updated_at TIMESTAMP NOT NULL\n);\n</code></pre>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#4-sql","title":"4. SQL \u57fa\u7840","text":"<p>\u5e38\u89c1 SQL \u64cd\u4f5c\u5305\u62ec\u589e\u5220\u6539\u67e5\u3002</p> <pre><code>INSERT INTO users (id, username) VALUES (1, 'alice');\n\nSELECT id, username FROM users WHERE id = 1;\n\nUPDATE users SET username = 'bob' WHERE id = 1;\n\nDELETE FROM users WHERE id = 1;\n</code></pre> <p>\u5e38\u89c1\u67e5\u8be2\u80fd\u529b\uff1a</p> <ul> <li><code>WHERE</code>\uff1a\u6761\u4ef6\u8fc7\u6ee4</li> <li><code>ORDER BY</code>\uff1a\u6392\u5e8f</li> <li><code>LIMIT</code>\uff1a\u9650\u5236\u8fd4\u56de\u6570\u91cf</li> <li><code>GROUP BY</code>\uff1a\u5206\u7ec4\u7edf\u8ba1</li> <li><code>JOIN</code>\uff1a\u591a\u8868\u5173\u8054</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#5_1","title":"5. \u7d22\u5f15","text":"<p>\u7d22\u5f15\u7528\u4e8e\u63d0\u5347\u67e5\u8be2\u901f\u5ea6\uff0c\u672c\u8d28\u4e0a\u662f\u6570\u636e\u5e93\u4e3a\u5b57\u6bb5\u5efa\u7acb\u7684\u9ad8\u6548\u67e5\u627e\u7ed3\u6784\u3002</p> <p>\u9002\u5408\u5efa\u7d22\u5f15\u7684\u5b57\u6bb5\uff1a</p> <ul> <li>\u7ecf\u5e38\u51fa\u73b0\u5728 <code>WHERE</code> \u6761\u4ef6\u4e2d</li> <li>\u7ecf\u5e38\u7528\u4e8e\u6392\u5e8f</li> <li>\u7ecf\u5e38\u7528\u4e8e\u5173\u8054\u67e5\u8be2</li> <li>\u533a\u5206\u5ea6\u8f83\u9ad8\u7684\u5b57\u6bb5</li> </ul> <p>\u4e0d\u9002\u5408\u6ee5\u7528\u7d22\u5f15\u7684\u539f\u56e0\uff1a</p> <ul> <li>\u7d22\u5f15\u4f1a\u5360\u7528\u5b58\u50a8\u7a7a\u95f4</li> <li>\u5199\u5165\u3001\u66f4\u65b0\u3001\u5220\u9664\u65f6\u9700\u8981\u7ef4\u62a4\u7d22\u5f15</li> <li>\u7d22\u5f15\u8fc7\u591a\u4f1a\u589e\u52a0\u6570\u636e\u5e93\u8d1f\u62c5</li> </ul> <p>\u5e38\u89c1\u7d22\u5f15\u7c7b\u578b\uff1a</p> <ul> <li>\u666e\u901a\u7d22\u5f15</li> <li>\u552f\u4e00\u7d22\u5f15</li> <li>\u8054\u5408\u7d22\u5f15</li> <li>\u5168\u6587\u7d22\u5f15</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#6","title":"6. \u4e8b\u52a1","text":"<p>\u4e8b\u52a1\u7528\u4e8e\u4fdd\u8bc1\u4e00\u7ec4\u6570\u636e\u5e93\u64cd\u4f5c\u7684\u4e00\u81f4\u6027\u3002</p> <p>\u4e8b\u52a1\u7684 ACID \u7279\u6027\uff1a</p> <ul> <li>\u539f\u5b50\u6027\uff1a\u4e8b\u52a1\u4e2d\u7684\u64cd\u4f5c\u8981\u4e48\u5168\u90e8\u6210\u529f\uff0c\u8981\u4e48\u5168\u90e8\u5931\u8d25</li> <li>\u4e00\u81f4\u6027\uff1a\u4e8b\u52a1\u524d\u540e\u6570\u636e\u8981\u4fdd\u6301\u5408\u6cd5\u72b6\u6001</li> <li>\u9694\u79bb\u6027\uff1a\u5e76\u53d1\u4e8b\u52a1\u4e4b\u95f4\u4e0d\u80fd\u4e92\u76f8\u7834\u574f</li> <li>\u6301\u4e45\u6027\uff1a\u4e8b\u52a1\u63d0\u4ea4\u540e\u6570\u636e\u8981\u6c38\u4e45\u4fdd\u5b58</li> </ul> <p>\u5e38\u89c1\u5e76\u53d1\u95ee\u9898\uff1a</p> <ul> <li>\u810f\u8bfb</li> <li>\u4e0d\u53ef\u91cd\u590d\u8bfb</li> <li>\u5e7b\u8bfb</li> </ul> <p>\u5e38\u89c1\u9694\u79bb\u7ea7\u522b\uff1a</p> <ul> <li>\u8bfb\u672a\u63d0\u4ea4</li> <li>\u8bfb\u5df2\u63d0\u4ea4</li> <li>\u53ef\u91cd\u590d\u8bfb</li> <li>\u4e32\u884c\u5316</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#7","title":"7. \u6162\u67e5\u8be2\u4f18\u5316","text":"<p>\u6570\u636e\u5e93\u6027\u80fd\u4f18\u5316\u5e38\u89c1\u601d\u8def\uff1a</p> <ul> <li>\u907f\u514d <code>SELECT *</code></li> <li>\u7ed9\u9ad8\u9891\u67e5\u8be2\u5b57\u6bb5\u5efa\u7acb\u7d22\u5f15</li> <li>\u907f\u514d\u5728\u7d22\u5f15\u5b57\u6bb5\u4e0a\u4f7f\u7528\u51fd\u6570\u8ba1\u7b97</li> <li>\u51cf\u5c11\u6df1\u5206\u9875</li> <li>\u4f7f\u7528\u5408\u7406\u7684\u5b57\u6bb5\u7c7b\u578b</li> <li>\u62c6\u5206\u590d\u6742 SQL</li> <li>\u901a\u8fc7\u6267\u884c\u8ba1\u5212\u5206\u6790\u67e5\u8be2\u8fc7\u7a0b</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#gorm","title":"\u4e09\u3001GORM","text":"<p>GORM \u662f Go \u8bed\u8a00\u5e38\u7528\u7684 ORM \u6846\u67b6\uff0c\u7528\u4e8e\u628a\u6570\u636e\u5e93\u8868\u6620\u5c04\u4e3a Go \u7ed3\u6784\u4f53\u3002</p>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#1-gorm","title":"1. GORM \u7684\u4f5c\u7528","text":"<ul> <li>\u7b80\u5316 CRUD \u64cd\u4f5c</li> <li>\u7ba1\u7406\u6a21\u578b\u548c\u8868\u4e4b\u95f4\u7684\u6620\u5c04</li> <li>\u652f\u6301\u4e8b\u52a1</li> <li>\u652f\u6301\u5173\u8054\u67e5\u8be2</li> <li>\u652f\u6301\u81ea\u52a8\u8fc1\u79fb</li> <li>\u652f\u6301\u94a9\u5b50\u65b9\u6cd5</li> </ul> <p>\u6a21\u578b\u793a\u4f8b\uff1a</p> <pre><code>type User struct {\n    ID           uint\n    Username     string\n    PasswordHash string\n    Email        string\n}\n</code></pre> <p>\u5e38\u89c1\u67e5\u8be2\u793a\u4f8b\uff1a</p> <pre><code>var user User\ndb.Where(\"username = ?\", \"alice\").First(&amp;user)\n</code></pre>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#2-gorm","title":"2. \u4f7f\u7528 GORM \u7684\u6ce8\u610f\u70b9","text":"<ul> <li>\u4e0d\u8981\u56e0\u4e3a\u4f7f\u7528 ORM \u5c31\u5ffd\u7565 SQL \u6027\u80fd</li> <li>\u590d\u6742\u67e5\u8be2\u9700\u8981\u5173\u6ce8\u751f\u6210\u7684 SQL</li> <li>\u6279\u91cf\u64cd\u4f5c\u8981\u907f\u514d\u9010\u6761\u5faa\u73af\u5199\u5165</li> <li>\u4e8b\u52a1\u8981\u660e\u786e\u63d0\u4ea4\u548c\u56de\u6eda</li> <li>\u5173\u8054\u67e5\u8be2\u8981\u907f\u514d N+1 \u67e5\u8be2\u95ee\u9898</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#_3","title":"\u56db\u3001\u767b\u5f55\u4e0e\u9274\u6743","text":""},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#1_2","title":"1. \u767b\u5f55","text":"<p>\u767b\u5f55\u7528\u4e8e\u786e\u8ba4\u7528\u6237\u8eab\u4efd\u3002\u5e38\u89c1\u6d41\u7a0b\uff1a</p> <ol> <li>\u7528\u6237\u63d0\u4ea4\u8d26\u53f7\u548c\u5bc6\u7801</li> <li>\u540e\u7aef\u6821\u9a8c\u8d26\u53f7\u662f\u5426\u5b58\u5728</li> <li>\u540e\u7aef\u6bd4\u8f83\u5bc6\u7801\u54c8\u5e0c</li> <li>\u6821\u9a8c\u6210\u529f\u540e\u751f\u6210\u767b\u5f55\u6001</li> <li>\u524d\u7aef\u4fdd\u5b58 Cookie \u6216 Token</li> <li>\u540e\u7eed\u8bf7\u6c42\u643a\u5e26\u767b\u5f55\u51ed\u8bc1</li> </ol> <p>\u5bc6\u7801\u4e0d\u80fd\u660e\u6587\u4fdd\u5b58\uff0c\u5e94\u8be5\u4f7f\u7528\u5b89\u5168\u54c8\u5e0c\u7b97\u6cd5\u5e76\u52a0\u76d0\u3002</p>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#2_1","title":"2. \u9274\u6743","text":"<p>\u9274\u6743\u7528\u4e8e\u5224\u65ad\u5f53\u524d\u7528\u6237\u662f\u5426\u6709\u6743\u9650\u8bbf\u95ee\u67d0\u4e2a\u8d44\u6e90\u6216\u6267\u884c\u67d0\u4e2a\u64cd\u4f5c\u3002</p> <p>\u5e38\u89c1\u6a21\u578b\uff1a</p> <ul> <li>RBAC\uff1a\u57fa\u4e8e\u89d2\u8272\u7684\u6743\u9650\u63a7\u5236</li> <li>ACL\uff1a\u57fa\u4e8e\u8d44\u6e90\u7684\u8bbf\u95ee\u63a7\u5236\u5217\u8868</li> </ul> <p>\u5e38\u89c1\u9274\u6743\u65b9\u5f0f\uff1a</p> <ul> <li>Session + Cookie</li> <li>JWT</li> <li>Access Token</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#3_2","title":"3. \u5e38\u89c1\u5b89\u5168\u98ce\u9669","text":"<ul> <li>SQL \u6ce8\u5165</li> <li>\u8d8a\u6743\u8bbf\u95ee</li> <li>Token \u6cc4\u9732</li> <li>\u5bc6\u7801\u660e\u6587\u5b58\u50a8</li> <li>\u66b4\u529b\u7834\u89e3</li> <li>\u91cd\u653e\u653b\u51fb</li> </ul> <p>\u9632\u62a4\u65b9\u5f0f\uff1a</p> <ul> <li>\u4f7f\u7528\u53c2\u6570\u5316\u67e5\u8be2</li> <li>\u540e\u7aef\u7edf\u4e00\u9274\u6743</li> <li>\u5bc6\u7801\u52a0\u76d0\u54c8\u5e0c</li> <li>\u767b\u5f55\u5931\u8d25\u6b21\u6570\u9650\u5236</li> <li>Token \u8bbe\u7f6e\u8fc7\u671f\u65f6\u95f4</li> <li>\u654f\u611f\u63a5\u53e3\u4e8c\u6b21\u6821\u9a8c</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#_4","title":"\u4e94\u3001\u7f13\u5b58","text":""},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#1_3","title":"1. \u7f13\u5b58\u7684\u4f5c\u7528","text":"<p>\u7f13\u5b58\u7528\u4e8e\u63d0\u9ad8\u8bbf\u95ee\u901f\u5ea6\uff0c\u51cf\u5c11\u6570\u636e\u5e93\u538b\u529b\u3002</p> <p>\u5e38\u89c1\u7f13\u5b58\u573a\u666f\uff1a</p> <ul> <li>\u70ed\u70b9\u6570\u636e</li> <li>\u7528\u6237\u4f1a\u8bdd</li> <li>\u914d\u7f6e\u4fe1\u606f</li> <li>\u6392\u884c\u699c</li> <li>\u77ed\u65f6\u95f4\u5185\u9891\u7e41\u8bfb\u53d6\u7684\u6570\u636e</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#2-redis","title":"2. Redis \u5e38\u89c1\u7528\u9014","text":"<ul> <li>\u7f13\u5b58\u67e5\u8be2\u7ed3\u679c</li> <li>\u4fdd\u5b58\u767b\u5f55\u6001</li> <li>\u5206\u5e03\u5f0f\u9501</li> <li>\u8ba1\u6570\u5668</li> <li>\u9650\u6d41</li> <li>\u6392\u884c\u699c</li> <li>\u6d88\u606f\u961f\u5217\u7684\u7b80\u5355\u66ff\u4ee3\u65b9\u6848</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#3_3","title":"3. \u7f13\u5b58\u5e38\u89c1\u95ee\u9898","text":"<p>\u7f13\u5b58\u7a7f\u900f\uff1a</p> <ul> <li>\u67e5\u8be2\u4e0d\u5b58\u5728\u7684\u6570\u636e\uff0c\u8bf7\u6c42\u6301\u7eed\u6253\u5230\u6570\u636e\u5e93</li> <li>\u89e3\u51b3\u65b9\u5f0f\uff1a\u7a7a\u503c\u7f13\u5b58\u3001\u5e03\u9686\u8fc7\u6ee4\u5668</li> </ul> <p>\u7f13\u5b58\u51fb\u7a7f\uff1a</p> <ul> <li>\u70ed\u70b9 Key \u5931\u6548\uff0c\u5927\u91cf\u8bf7\u6c42\u540c\u65f6\u8bbf\u95ee\u6570\u636e\u5e93</li> <li>\u89e3\u51b3\u65b9\u5f0f\uff1a\u4e92\u65a5\u9501\u3001\u70ed\u70b9\u6570\u636e\u6c38\u4e0d\u8fc7\u671f\u3001\u63d0\u524d\u5237\u65b0</li> </ul> <p>\u7f13\u5b58\u96ea\u5d29\uff1a</p> <ul> <li>\u5927\u91cf Key \u540c\u65f6\u5931\u6548\uff0c\u6570\u636e\u5e93\u538b\u529b\u9aa4\u589e</li> <li>\u89e3\u51b3\u65b9\u5f0f\uff1a\u8fc7\u671f\u65f6\u95f4\u52a0\u968f\u673a\u503c\u3001\u591a\u7ea7\u7f13\u5b58\u3001\u9650\u6d41\u964d\u7ea7</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#4_1","title":"4. \u7f13\u5b58\u4e00\u81f4\u6027","text":"<p>\u7f13\u5b58\u548c\u6570\u636e\u5e93\u540c\u65f6\u5b58\u5728\u65f6\uff0c\u8981\u8003\u8651\u6570\u636e\u4e00\u81f4\u6027\u3002</p> <p>\u5e38\u89c1\u7b56\u7565\uff1a</p> <ul> <li>\u5148\u66f4\u65b0\u6570\u636e\u5e93\uff0c\u518d\u5220\u9664\u7f13\u5b58</li> <li>\u8bbe\u7f6e\u5408\u7406\u8fc7\u671f\u65f6\u95f4</li> <li>\u5bf9\u5173\u952e\u4e1a\u52a1\u4f7f\u7528\u6d88\u606f\u961f\u5217\u540c\u6b65\u53d8\u66f4</li> <li>\u5bf9\u5f3a\u4e00\u81f4\u573a\u666f\u51cf\u5c11\u7f13\u5b58\u4f9d\u8d56</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#es","title":"\u516d\u3001\u641c\u7d22\u5f15\u64ce\u4e0e ES","text":""},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#1_4","title":"1. \u641c\u7d22\u5f15\u64ce\u7684\u4f5c\u7528","text":"<p>\u641c\u7d22\u5f15\u64ce\u9002\u5408\u5904\u7406\u5168\u6587\u641c\u7d22\u3001\u590d\u6742\u7b5b\u9009\u548c\u805a\u5408\u5206\u6790\u3002</p> <p>\u9002\u7528\u573a\u666f\uff1a</p> <ul> <li>\u5546\u54c1\u641c\u7d22</li> <li>\u6587\u7ae0\u641c\u7d22</li> <li>\u65e5\u5fd7\u68c0\u7d22</li> <li>\u7528\u6237\u884c\u4e3a\u5206\u6790</li> <li>\u591a\u6761\u4ef6\u7b5b\u9009</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#2-elasticsearch","title":"2. Elasticsearch \u6838\u5fc3\u6982\u5ff5","text":"<ul> <li>Index\uff1a\u7d22\u5f15\uff0c\u7c7b\u4f3c\u6570\u636e\u5e93\u4e2d\u7684\u8868</li> <li>Document\uff1a\u6587\u6863\uff0c\u7c7b\u4f3c\u4e00\u6761\u8bb0\u5f55</li> <li>Field\uff1a\u5b57\u6bb5</li> <li>Mapping\uff1a\u5b57\u6bb5\u7ed3\u6784\u5b9a\u4e49</li> <li>Inverted Index\uff1a\u5012\u6392\u7d22\u5f15</li> <li>Analyzer\uff1a\u5206\u8bcd\u5668</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#3_4","title":"3. \u6570\u636e\u540c\u6b65","text":"<p>\u5b9e\u9645\u7cfb\u7edf\u4e2d\uff0c\u6570\u636e\u5e93\u901a\u5e38\u662f\u4e3b\u6570\u636e\u6e90\uff0cES \u662f\u641c\u7d22\u526f\u672c\u3002</p> <p>\u5e38\u89c1\u540c\u6b65\u65b9\u5f0f\uff1a</p> <ul> <li>\u4e1a\u52a1\u4ee3\u7801\u5199\u6570\u636e\u5e93\u540e\u540c\u6b65\u5199 ES</li> <li>\u4f7f\u7528\u6d88\u606f\u961f\u5217\u5f02\u6b65\u540c\u6b65</li> <li>\u76d1\u542c\u6570\u636e\u5e93 binlog \u540c\u6b65</li> </ul> <p>\u9700\u8981\u5173\u6ce8\uff1a</p> <ul> <li>\u6570\u636e\u5ef6\u8fdf</li> <li>\u540c\u6b65\u5931\u8d25\u91cd\u8bd5</li> <li>\u6570\u636e\u4e00\u81f4\u6027</li> <li>\u5220\u9664\u548c\u66f4\u65b0\u7684\u5904\u7406</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#_5","title":"\u4e03\u3001\u5411\u91cf\u6570\u636e\u5e93","text":""},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#1_5","title":"1. \u5411\u91cf\u6570\u636e\u5e93\u7684\u4f5c\u7528","text":"<p>\u5411\u91cf\u6570\u636e\u5e93\u7528\u4e8e\u5b58\u50a8\u5411\u91cf\u5e76\u8fdb\u884c\u76f8\u4f3c\u5ea6\u68c0\u7d22\u3002</p> <p>\u5e38\u89c1\u573a\u666f\uff1a</p> <ul> <li>\u8bed\u4e49\u641c\u7d22</li> <li>\u63a8\u8350\u7cfb\u7edf</li> <li>\u56fe\u7247\u76f8\u4f3c\u641c\u7d22</li> <li>RAG \u77e5\u8bc6\u5e93\u68c0\u7d22</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#2_2","title":"2. \u6838\u5fc3\u6982\u5ff5","text":"<ul> <li>Embedding\uff1a\u628a\u6587\u672c\u3001\u56fe\u7247\u7b49\u5185\u5bb9\u8f6c\u6362\u6210\u5411\u91cf</li> <li>\u76f8\u4f3c\u5ea6\uff1a\u8861\u91cf\u4e24\u4e2a\u5411\u91cf\u7684\u63a5\u8fd1\u7a0b\u5ea6</li> <li>TopK\uff1a\u8fd4\u56de\u6700\u76f8\u4f3c\u7684\u524d K \u6761\u7ed3\u679c</li> <li>ANN\uff1a\u8fd1\u4f3c\u6700\u8fd1\u90bb\u641c\u7d22\uff0c\u7528\u4e8e\u63d0\u5347\u68c0\u7d22\u6027\u80fd</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#3_5","title":"3. \u540e\u7aef\u63a5\u5165\u6d41\u7a0b","text":"<ol> <li>\u539f\u59cb\u6570\u636e\u5165\u5e93</li> <li>\u8c03\u7528\u6a21\u578b\u751f\u6210 embedding</li> <li>\u5c06\u5411\u91cf\u548c\u5143\u6570\u636e\u5199\u5165\u5411\u91cf\u6570\u636e\u5e93</li> <li>\u7528\u6237\u67e5\u8be2\u65f6\u751f\u6210\u67e5\u8be2\u5411\u91cf</li> <li>\u5728\u5411\u91cf\u6570\u636e\u5e93\u4e2d\u68c0\u7d22\u76f8\u4f3c\u5185\u5bb9</li> <li>\u8fd4\u56de\u7ed3\u679c\u6216\u8fdb\u5165\u540e\u7eed\u4e1a\u52a1\u6d41\u7a0b</li> </ol>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#_6","title":"\u516b\u3001\u5b9e\u65f6\u901a\u4fe1\u6280\u672f","text":""},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#1_6","title":"1. \u5e38\u89c1\u65b9\u5f0f","text":"<ul> <li>WebSocket\uff1a\u9002\u5408\u53cc\u5411\u5b9e\u65f6\u901a\u4fe1</li> <li>SSE\uff1a\u9002\u5408\u670d\u52a1\u7aef\u6301\u7eed\u5411\u5ba2\u6237\u7aef\u63a8\u9001</li> <li>\u957f\u8f6e\u8be2\uff1a\u517c\u5bb9\u6027\u8f83\u597d\uff0c\u4f46\u6548\u7387\u8f83\u4f4e</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#2_3","title":"2. \u9002\u7528\u573a\u666f","text":"<ul> <li>\u804a\u5929\u7cfb\u7edf</li> <li>\u5b9e\u65f6\u901a\u77e5</li> <li>\u534f\u540c\u7f16\u8f91</li> <li>\u8ba2\u5355\u72b6\u6001\u63a8\u9001</li> <li>\u5728\u7ebf\u72b6\u6001\u540c\u6b65</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#3_6","title":"3. \u540e\u7aef\u5173\u6ce8\u70b9","text":"<ul> <li>\u8fde\u63a5\u7ba1\u7406</li> <li>\u7528\u6237\u8eab\u4efd\u6821\u9a8c</li> <li>\u6d88\u606f\u8def\u7531</li> <li>\u65ad\u7ebf\u91cd\u8fde</li> <li>\u5fc3\u8df3\u68c0\u6d4b</li> <li>\u6d88\u606f\u53ef\u9760\u6027</li> </ul>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#stripe","title":"\u4e5d\u3001\u652f\u4ed8\u540e\u7aef\uff1aStripe","text":"<p>Stripe \u5c5e\u4e8e\u540e\u7aef\u5e38\u89c1\u7684\u7b2c\u4e09\u65b9\u652f\u4ed8\u96c6\u6210\u80fd\u529b\u3002</p> <p>\u540e\u7aef\u63a5\u5165\u91cd\u70b9\uff1a</p> <ul> <li>\u521b\u5efa\u652f\u4ed8\u4f1a\u8bdd</li> <li>\u63a5\u6536 Webhook \u56de\u8c03</li> <li>\u6821\u9a8c\u56de\u8c03\u7b7e\u540d</li> <li>\u5904\u7406\u652f\u4ed8\u6210\u529f\u3001\u5931\u8d25\u3001\u9000\u6b3e\u7b49\u72b6\u6001</li> <li>\u4fdd\u8bc1\u8ba2\u5355\u72b6\u6001\u5e42\u7b49\u66f4\u65b0</li> <li>\u505a\u597d\u5bf9\u8d26\u548c\u5f02\u5e38\u8865\u507f</li> </ul> <p>\u652f\u4ed8\u7cfb\u7edf\u5fc5\u987b\u91cd\u89c6\u5e42\u7b49\u6027\u3002\u76f8\u540c\u652f\u4ed8\u4e8b\u4ef6\u53ef\u80fd\u88ab\u91cd\u590d\u901a\u77e5\uff0c\u540e\u7aef\u4e0d\u80fd\u91cd\u590d\u53d1\u8d27\u6216\u91cd\u590d\u5165\u8d26\u3002</p>"},{"location":"%E5%90%8E%E7%AB%AF%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%BA%93.html#_7","title":"\u5341\u3001\u540e\u7aef\u5b66\u4e60\u91cd\u70b9\u603b\u7ed3","text":"<p>\u540e\u7aef\u90e8\u5206\u91cd\u70b9\uff1a</p> <ul> <li>API \u8bbe\u8ba1</li> <li>\u53c2\u6570\u6821\u9a8c</li> <li>\u6d4b\u8bd5</li> <li>\u767b\u5f55\u4e0e\u9274\u6743</li> <li>\u6587\u4ef6\u5904\u7406</li> <li>\u7b2c\u4e09\u65b9\u670d\u52a1\u63a5\u5165</li> <li>\u5b9e\u65f6\u901a\u4fe1</li> </ul> <p>\u6570\u636e\u5e93\u90e8\u5206\u91cd\u70b9\uff1a</p> <ul> <li>\u8868\u7ed3\u6784\u8bbe\u8ba1</li> <li>SQL \u67e5\u8be2</li> <li>\u7d22\u5f15</li> <li>\u4e8b\u52a1</li> <li>\u6162\u67e5\u8be2\u4f18\u5316</li> <li>ORM \u4f7f\u7528</li> <li>\u7f13\u5b58\u8bbe\u8ba1</li> <li>ES \u68c0\u7d22</li> <li>\u5411\u91cf\u6570\u636e\u5e93\u68c0\u7d22</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html","title":"\u57df\u540d\u548c\u57df\u540d\u89e3\u6790\u5b66\u4e60\u7b14\u8bb0","text":""},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#_2","title":"\u4e00\u3001\u57df\u540d\u662f\u4ec0\u4e48","text":"<p>\u57df\u540d\u662f\u4e92\u8054\u7f51\u4e0a\u7528\u4e8e\u6807\u8bc6\u7f51\u7ad9\u6216\u670d\u52a1\u7684\u53ef\u8bfb\u540d\u79f0\u3002</p> <p>\u4f8b\u5982\uff1a</p> <pre><code>www.example.com\n</code></pre> <p>\u4eba\u66f4\u5bb9\u6613\u8bb0\u4f4f\u57df\u540d\uff0c\u8ba1\u7b97\u673a\u771f\u6b63\u901a\u4fe1\u65f6\u9700\u8981 IP \u5730\u5740\u3002\u57df\u540d\u89e3\u6790\u7684\u4f5c\u7528\u5c31\u662f\u628a\u57df\u540d\u8f6c\u6362\u6210\u5bf9\u5e94\u7684 IP \u5730\u5740\u6216\u5176\u4ed6\u670d\u52a1\u4fe1\u606f\u3002</p> <pre><code>www.example.com -&gt; 93.184.216.34\n</code></pre>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#_3","title":"\u4e8c\u3001\u57df\u540d\u5c42\u7ea7\u7ed3\u6784","text":"<p>\u57df\u540d\u662f\u5206\u5c42\u7684\uff0c\u4ece\u53f3\u5f80\u5de6\u5c42\u7ea7\u8d8a\u6765\u8d8a\u4f4e\u3002</p> <p>\u4ee5 <code>www.example.com</code> \u4e3a\u4f8b\uff1a</p> <pre><code>www.example.com.\n\u2502   \u2502       \u2502   \u2502\n\u2502   \u2502       \u2502   \u2514\u2500 \u6839\u57df root\uff0c\u901a\u5e38\u7701\u7565\u4e0d\u5199\n\u2502   \u2502       \u2514\u2500\u2500\u2500\u2500 \u9876\u7ea7\u57df TLD\n\u2502   \u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 \u4e8c\u7ea7\u57df\n\u2514\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500 \u5b50\u57df\u540d / \u4e3b\u673a\u540d\n</code></pre>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#1","title":"1. \u6839\u57df","text":"<p>\u6839\u57df\u662f DNS \u5c42\u7ea7\u7684\u6700\u9876\u5c42\uff0c\u5b8c\u6574\u57df\u540d\u6700\u540e\u5176\u5b9e\u6709\u4e00\u4e2a\u70b9\uff1a</p> <pre><code>www.example.com.\n</code></pre> <p>\u65e5\u5e38\u4f7f\u7528\u65f6\u6700\u540e\u7684\u70b9\u901a\u5e38\u7701\u7565\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#2-tld","title":"2. \u9876\u7ea7\u57df TLD","text":"<p>\u5e38\u89c1\u9876\u7ea7\u57df\uff1a</p> <ul> <li><code>.com</code></li> <li><code>.net</code></li> <li><code>.org</code></li> <li><code>.cn</code></li> <li><code>.edu</code></li> <li><code>.io</code></li> <li><code>.dev</code></li> </ul> <p>\u9876\u7ea7\u57df\u7531\u5bf9\u5e94\u7684\u6ce8\u518c\u5c40\u7ba1\u7406\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#3","title":"3. \u4e8c\u7ea7\u57df","text":"<p>\u4f8b\u5982 <code>example.com</code> \u4e2d\u7684 <code>example</code> \u5c31\u662f\u4e8c\u7ea7\u57df\u3002</p> <p>\u4e00\u822c\u8d2d\u4e70\u57df\u540d\u65f6\uff0c\u4e70\u5230\u7684\u662f\u7c7b\u4f3c\u4e0b\u9762\u8fd9\u6837\u7684\u57df\u540d\uff1a</p> <pre><code>example.com\nexample.cn\nmy-site.net\n</code></pre>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#4","title":"4. \u5b50\u57df\u540d","text":"<p>\u5b50\u57df\u540d\u662f\u5728\u4e3b\u57df\u540d\u524d\u7ee7\u7eed\u589e\u52a0\u7684\u5c42\u7ea7\u3002</p> <p>\u4f8b\u5982\uff1a</p> <pre><code>www.example.com\napi.example.com\nblog.example.com\ndev.api.example.com\n</code></pre> <p>\u5e38\u89c1\u7528\u9014\uff1a</p> <ul> <li><code>www</code>\uff1a\u7f51\u7ad9\u4e3b\u9875\u3002</li> <li><code>api</code>\uff1a\u540e\u7aef\u63a5\u53e3\u3002</li> <li><code>admin</code>\uff1a\u7ba1\u7406\u540e\u53f0\u3002</li> <li><code>cdn</code>\uff1a\u9759\u6001\u8d44\u6e90\u3002</li> <li><code>mail</code>\uff1a\u90ae\u4ef6\u670d\u52a1\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#5-fqdn","title":"5. FQDN","text":"<p>FQDN \u662f Fully Qualified Domain Name\uff0c\u5b8c\u5168\u9650\u5b9a\u57df\u540d\u3002</p> <p>\u4e25\u683c\u6765\u8bf4\u5b8c\u6574\u5199\u6cd5\u662f\uff1a</p> <pre><code>www.example.com.\n</code></pre> <p>\u6700\u540e\u7684\u70b9\u8868\u793a\u6839\u57df\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#_4","title":"\u4e09\u3001\u57df\u540d\u6ce8\u518c\u76f8\u5173\u6982\u5ff5","text":""},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#1-registry","title":"1. \u6ce8\u518c\u5c40 Registry","text":"<p>\u6ce8\u518c\u5c40\u8d1f\u8d23\u7ba1\u7406\u67d0\u4e2a\u9876\u7ea7\u57df\u3002</p> <p>\u4f8b\u5982 <code>.com</code>\u3001<code>.cn</code> \u8fd9\u6837\u7684\u9876\u7ea7\u57df\u80cc\u540e\u90fd\u6709\u5bf9\u5e94\u7684\u6ce8\u518c\u5c40\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#2-registrar","title":"2. \u6ce8\u518c\u5546 Registrar","text":"<p>\u6ce8\u518c\u5546\u662f\u63d0\u4f9b\u57df\u540d\u8d2d\u4e70\u548c\u7ba1\u7406\u670d\u52a1\u7684\u5e73\u53f0\u3002</p> <p>\u7528\u6237\u901a\u5e38\u901a\u8fc7\u6ce8\u518c\u5546\u8d2d\u4e70\u57df\u540d\u3001\u7eed\u8d39\u57df\u540d\u3001\u8bbe\u7f6e DNS \u670d\u52a1\u5668\u3002</p> <p>\u5e38\u89c1\u529f\u80fd\uff1a</p> <ul> <li>\u67e5\u8be2\u57df\u540d\u662f\u5426\u53ef\u6ce8\u518c\u3002</li> <li>\u6ce8\u518c\u57df\u540d\u3002</li> <li>\u7eed\u8d39\u57df\u540d\u3002</li> <li>\u4fee\u6539\u57df\u540d\u8054\u7cfb\u4eba\u4fe1\u606f\u3002</li> <li>\u8bbe\u7f6e nameserver\u3002</li> <li>\u5f00\u542f\u57df\u540d\u9501\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#3-registrant","title":"3. \u6ce8\u518c\u4eba Registrant","text":"<p>\u6ce8\u518c\u4eba\u662f\u57df\u540d\u7684\u6301\u6709\u4eba\u3002</p> <p>\u57df\u540d\u5230\u671f\u540e\u5982\u679c\u6ca1\u6709\u7eed\u8d39\uff0c\u53ef\u80fd\u8fdb\u5165\u5bbd\u9650\u671f\u3001\u8d4e\u56de\u671f\uff0c\u6700\u540e\u88ab\u91ca\u653e\u91cd\u65b0\u6ce8\u518c\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#4-whois","title":"4. WHOIS","text":"<p>WHOIS \u7528\u6765\u67e5\u8be2\u57df\u540d\u6ce8\u518c\u4fe1\u606f\u3002</p> <p>\u53ef\u80fd\u5305\u542b\uff1a</p> <ul> <li>\u6ce8\u518c\u5546\u3002</li> <li>\u6ce8\u518c\u65f6\u95f4\u3002</li> <li>\u5230\u671f\u65f6\u95f4\u3002</li> <li>\u57df\u540d\u72b6\u6001\u3002</li> <li>DNS \u670d\u52a1\u5668\u3002</li> <li>\u8054\u7cfb\u4eba\u4fe1\u606f\u3002</li> </ul> <p>\u5f88\u591a\u57df\u540d\u4f1a\u5f00\u542f\u9690\u79c1\u4fdd\u62a4\uff0c\u56e0\u6b64\u4e0d\u4e00\u5b9a\u80fd\u770b\u5230\u771f\u5b9e\u8054\u7cfb\u4eba\u4fe1\u606f\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#5","title":"5. \u57df\u540d\u72b6\u6001","text":"<p>\u5e38\u89c1\u72b6\u6001\uff1a</p> \u72b6\u6001 \u542b\u4e49 <code>clientTransferProhibited</code> \u7981\u6b62\u8f6c\u79fb\uff0c\u901a\u5e38\u662f\u57df\u540d\u9501 <code>ok</code> \u6b63\u5e38\u72b6\u6001 <code>pendingDelete</code> \u7b49\u5f85\u5220\u9664 <code>redemptionPeriod</code> \u8d4e\u56de\u671f <code>serverHold</code> \u6ce8\u518c\u5c40\u6682\u505c\u89e3\u6790 <p>\u5982\u679c\u57df\u540d\u72b6\u6001\u5f02\u5e38\uff0c\u5373\u4f7f DNS \u8bb0\u5f55\u914d\u7f6e\u6b63\u786e\uff0c\u4e5f\u53ef\u80fd\u65e0\u6cd5\u6b63\u5e38\u89e3\u6790\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#dns","title":"\u56db\u3001DNS \u662f\u4ec0\u4e48","text":"<p>DNS \u662f Domain Name System\uff0c\u57df\u540d\u7cfb\u7edf\u3002</p> <p>DNS \u7684\u4f5c\u7528\uff1a</p> <ul> <li>\u628a\u57df\u540d\u89e3\u6790\u4e3a IP \u5730\u5740\u3002</li> <li>\u6307\u5b9a\u90ae\u4ef6\u670d\u52a1\u5668\u3002</li> <li>\u505a\u57df\u540d\u6240\u6709\u6743\u9a8c\u8bc1\u3002</li> <li>\u63d0\u4f9b\u670d\u52a1\u53d1\u73b0\u3002</li> <li>\u652f\u6301 CDN\u3001\u8d1f\u8f7d\u5747\u8861\u548c\u5bb9\u707e\u3002</li> </ul> <p>DNS \u662f\u5206\u5e03\u5f0f\u7cfb\u7edf\uff0c\u4e0d\u662f\u67d0\u4e00\u53f0\u670d\u52a1\u5668\u4fdd\u5b58\u6240\u6709\u57df\u540d\u8bb0\u5f55\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#dns_1","title":"\u4e94\u3001DNS \u4e2d\u7684\u91cd\u8981\u89d2\u8272","text":""},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#1-resolver","title":"1. Resolver \u89e3\u6790\u5668","text":"<p>\u89e3\u6790\u5668\u8d1f\u8d23\u5e2e\u7528\u6237\u67e5\u8be2\u57df\u540d\u7ed3\u679c\u3002</p> <p>\u5e38\u89c1\u89e3\u6790\u5668\uff1a</p> <ul> <li>\u8fd0\u8425\u5546 DNS\u3002</li> <li>\u516c\u5171 DNS\u3002</li> <li>\u516c\u53f8\u5185\u7f51 DNS\u3002</li> <li>\u672c\u673a DNS \u7f13\u5b58\u3002</li> </ul> <p>\u7528\u6237\u7535\u8111\u901a\u5e38\u4e0d\u4f1a\u76f4\u63a5\u8be2\u95ee\u6839 DNS\uff0c\u800c\u662f\u628a\u8bf7\u6c42\u4ea4\u7ed9\u9012\u5f52\u89e3\u6790\u5668\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#2-recursive-resolver","title":"2. Recursive Resolver \u9012\u5f52\u89e3\u6790\u5668","text":"<p>\u9012\u5f52\u89e3\u6790\u5668\u8d1f\u8d23\u4ee3\u66ff\u5ba2\u6237\u7aef\u5b8c\u6210\u5b8c\u6574\u67e5\u8be2\u3002</p> <p>\u5982\u679c\u7f13\u5b58\u4e2d\u6ca1\u6709\u7ed3\u679c\uff0c\u5b83\u4f1a\u7ee7\u7eed\u8be2\u95ee\uff1a</p> <pre><code>\u6839 DNS -&gt; \u9876\u7ea7\u57df DNS -&gt; \u6743\u5a01 DNS\n</code></pre> <p>\u6700\u540e\u628a\u7ed3\u679c\u8fd4\u56de\u7ed9\u5ba2\u6237\u7aef\uff0c\u5e76\u7f13\u5b58\u4e00\u6bb5\u65f6\u95f4\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#3-root-dns-dns","title":"3. Root DNS \u6839 DNS","text":"<p>\u6839 DNS \u77e5\u9053\u5404\u4e2a\u9876\u7ea7\u57df DNS \u5728\u54ea\u91cc\u3002</p> <p>\u5b83\u4e0d\u4f1a\u76f4\u63a5\u77e5\u9053 <code>www.example.com</code> \u7684 IP\uff0c\u4f46\u5b83\u77e5\u9053 <code>.com</code> \u5e94\u8be5\u53bb\u95ee\u8c01\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#4-tld-dns-dns","title":"4. TLD DNS \u9876\u7ea7\u57df DNS","text":"<p>\u9876\u7ea7\u57df DNS \u8d1f\u8d23\u67d0\u4e2a\u9876\u7ea7\u57df\u3002</p> <p>\u4f8b\u5982 <code>.com</code> \u7684 TLD DNS \u77e5\u9053 <code>example.com</code> \u7684\u6743\u5a01 DNS \u670d\u52a1\u5668\u662f\u8c01\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#5-authoritative-dns-dns","title":"5. Authoritative DNS \u6743\u5a01 DNS","text":"<p>\u6743\u5a01 DNS \u4fdd\u5b58\u67d0\u4e2a\u57df\u540d\u771f\u6b63\u7684 DNS \u8bb0\u5f55\u3002</p> <p>\u4f8b\u5982 <code>example.com</code> \u7684\u6743\u5a01 DNS \u4f1a\u4fdd\u5b58\uff1a</p> <ul> <li><code>www.example.com</code> \u5bf9\u5e94\u54ea\u4e2a IP\u3002</li> <li><code>api.example.com</code> \u5bf9\u5e94\u54ea\u4e2a IP\u3002</li> <li><code>example.com</code> \u4f7f\u7528\u54ea\u4e9b\u90ae\u4ef6\u670d\u52a1\u5668\u3002</li> <li><code>example.com</code> \u7684 TXT \u9a8c\u8bc1\u8bb0\u5f55\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#_5","title":"\u516d\u3001\u57df\u540d\u89e3\u6790\u8fc7\u7a0b","text":"<p>\u4ee5\u8bbf\u95ee <code>www.example.com</code> \u4e3a\u4f8b\uff1a</p> <pre><code>\u6d4f\u89c8\u5668\u8bbf\u95ee www.example.com\n  -&gt; \u68c0\u67e5\u6d4f\u89c8\u5668 DNS \u7f13\u5b58\n  -&gt; \u68c0\u67e5\u64cd\u4f5c\u7cfb\u7edf DNS \u7f13\u5b58\n  -&gt; \u67e5\u8be2\u672c\u5730\u914d\u7f6e\u7684\u9012\u5f52 DNS\n  -&gt; \u9012\u5f52 DNS \u67e5\u8be2\u6839 DNS\n  -&gt; \u6839 DNS \u8fd4\u56de .com \u7684 TLD DNS\n  -&gt; \u9012\u5f52 DNS \u67e5\u8be2 .com TLD DNS\n  -&gt; TLD DNS \u8fd4\u56de example.com \u7684\u6743\u5a01 DNS\n  -&gt; \u9012\u5f52 DNS \u67e5\u8be2\u6743\u5a01 DNS\n  -&gt; \u6743\u5a01 DNS \u8fd4\u56de www.example.com \u7684\u8bb0\u5f55\n  -&gt; \u9012\u5f52 DNS \u628a\u7ed3\u679c\u8fd4\u56de\u7ed9\u5ba2\u6237\u7aef\n  -&gt; \u6d4f\u89c8\u5668\u62ff\u5230 IP \u540e\u53d1\u8d77\u8fde\u63a5\n</code></pre> <p>\u7b80\u5316\u7406\u89e3\uff1a</p> <pre><code>\u5ba2\u6237\u7aef\u95ee\u9012\u5f52 DNS\uff1awww.example.com \u662f\u591a\u5c11\uff1f\n\u9012\u5f52 DNS \u8d1f\u8d23\u4e00\u8def\u95ee\u5230\u6743\u5a01 DNS\uff0c\u7136\u540e\u628a\u7b54\u6848\u8fd4\u56de\u3002\n</code></pre>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#_6","title":"\u4e03\u3001\u9012\u5f52\u67e5\u8be2\u548c\u8fed\u4ee3\u67e5\u8be2","text":""},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#1_1","title":"1. \u9012\u5f52\u67e5\u8be2","text":"<p>\u5ba2\u6237\u7aef\u8981\u6c42 DNS \u670d\u52a1\u5668\u7ed9\u51fa\u6700\u7ec8\u7ed3\u679c\u3002</p> <p>\u5982\u679c DNS \u670d\u52a1\u5668\u4e0d\u77e5\u9053\uff0c\u5b83\u9700\u8981\u7ee7\u7eed\u5e2e\u5ba2\u6237\u7aef\u67e5\u3002</p> <p>\u5e38\u89c1\u573a\u666f\uff1a</p> <pre><code>\u7535\u8111 -&gt; \u8fd0\u8425\u5546 DNS / \u516c\u5171 DNS\n</code></pre>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#2","title":"2. \u8fed\u4ee3\u67e5\u8be2","text":"<p>DNS \u670d\u52a1\u5668\u4e0d\u77e5\u9053\u6700\u7ec8\u7ed3\u679c\u65f6\uff0c\u53ea\u544a\u8bc9\u4f60\u4e0b\u4e00\u6b65\u5e94\u8be5\u95ee\u8c01\u3002</p> <p>\u5e38\u89c1\u573a\u666f\uff1a</p> <pre><code>\u9012\u5f52 DNS -&gt; \u6839 DNS\n\u9012\u5f52 DNS -&gt; TLD DNS\n\u9012\u5f52 DNS -&gt; \u6743\u5a01 DNS\n</code></pre>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#dns_2","title":"\u516b\u3001DNS \u8bb0\u5f55\u7c7b\u578b","text":""},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#1_2","title":"1. \u5e38\u89c1\u8bb0\u5f55","text":"\u7c7b\u578b \u4f5c\u7528 \u793a\u4f8b A \u57df\u540d\u6307\u5411 IPv4 \u5730\u5740 <code>www -&gt; 192.0.2.10</code> AAAA \u57df\u540d\u6307\u5411 IPv6 \u5730\u5740 <code>www -&gt; 2001:db8::1</code> CNAME \u57df\u540d\u522b\u540d\uff0c\u6307\u5411\u53e6\u4e00\u4e2a\u57df\u540d <code>www -&gt; example.com</code> MX \u6307\u5b9a\u90ae\u4ef6\u670d\u52a1\u5668 <code>example.com -&gt; mail.example.com</code> TXT \u6587\u672c\u8bb0\u5f55\uff0c\u5e38\u7528\u4e8e\u9a8c\u8bc1\u548c\u53cd\u5783\u573e\u90ae\u4ef6 SPF\u3001DKIM\u3001DMARC NS \u6307\u5b9a\u6743\u5a01 DNS \u670d\u52a1\u5668 <code>ns1.example-dns.com</code> SOA \u533a\u57df\u8d77\u59cb\u6388\u6743\u8bb0\u5f55 \u5305\u542b\u5e8f\u5217\u53f7\u3001\u5237\u65b0\u65f6\u95f4\u7b49 SRV \u6307\u5b9a\u67d0\u670d\u52a1\u7684\u4e3b\u673a\u548c\u7aef\u53e3 SIP\u3001LDAP \u7b49 CAA \u6307\u5b9a\u5141\u8bb8\u54ea\u4e9b CA \u7b7e\u53d1\u8bc1\u4e66 <code>letsencrypt.org</code> PTR \u53cd\u5411\u89e3\u6790\uff0cIP \u6307\u5411\u57df\u540d \u90ae\u4ef6\u670d\u52a1\u5668\u5e38\u7528"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#2-a","title":"2. A \u8bb0\u5f55","text":"<p>A \u8bb0\u5f55\u628a\u57df\u540d\u89e3\u6790\u5230 IPv4 \u5730\u5740\u3002</p> <p>\u793a\u4f8b\uff1a</p> <pre><code>www.example.com -&gt; 203.0.113.10\n</code></pre> <p>\u9002\u5408\uff1a</p> <ul> <li>\u7f51\u7ad9\u670d\u52a1\u5668\u3002</li> <li>API \u670d\u52a1\u5668\u3002</li> <li>\u76f4\u63a5\u7ed1\u5b9a\u516c\u7f51 IP \u7684\u670d\u52a1\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#3-aaaa","title":"3. AAAA \u8bb0\u5f55","text":"<p>AAAA \u8bb0\u5f55\u628a\u57df\u540d\u89e3\u6790\u5230 IPv6 \u5730\u5740\u3002</p> <p>\u793a\u4f8b\uff1a</p> <pre><code>www.example.com -&gt; 2001:db8::10\n</code></pre> <p>\u5982\u679c\u7f51\u7ad9\u652f\u6301 IPv6\uff0c\u53ef\u4ee5\u540c\u65f6\u914d\u7f6e A \u548c AAAA\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#4-cname","title":"4. CNAME \u8bb0\u5f55","text":"<p>CNAME \u662f\u522b\u540d\u8bb0\u5f55\uff0c\u628a\u4e00\u4e2a\u57df\u540d\u6307\u5411\u53e6\u4e00\u4e2a\u57df\u540d\u3002</p> <p>\u793a\u4f8b\uff1a</p> <pre><code>www.example.com -&gt; example.github.io\n</code></pre> <p>\u6ce8\u610f\uff1a</p> <ul> <li>CNAME \u7684\u76ee\u6807\u5e94\u8be5\u662f\u57df\u540d\uff0c\u4e0d\u662f IP\u3002</li> <li>\u4e00\u4e2a\u4e3b\u673a\u540d\u5982\u679c\u914d\u7f6e\u4e86 CNAME\uff0c\u901a\u5e38\u4e0d\u80fd\u518d\u540c\u65f6\u914d\u7f6e A\u3001MX\u3001TXT \u7b49\u5176\u4ed6\u8bb0\u5f55\u3002</li> <li>\u6839\u57df\u540d <code>example.com</code> \u662f\u5426\u652f\u6301 CNAME \u53d6\u51b3\u4e8e DNS \u670d\u52a1\u5546\uff0c\u6709\u4e9b\u5e73\u53f0\u63d0\u4f9b ALIAS\u3001ANAME \u6216 CNAME Flattening \u6765\u89e3\u51b3\u6839\u57df\u540d\u6307\u5411\u53e6\u4e00\u4e2a\u57df\u540d\u7684\u95ee\u9898\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#5-mx","title":"5. MX \u8bb0\u5f55","text":"<p>MX \u8bb0\u5f55\u6307\u5b9a\u6536\u90ae\u4ef6\u7684\u670d\u52a1\u5668\u3002</p> <p>\u793a\u4f8b\uff1a</p> <pre><code>example.com MX 10 mail.example.com\n</code></pre> <p>\u6570\u5b57\u8868\u793a\u4f18\u5148\u7ea7\uff0c\u6570\u5b57\u8d8a\u5c0f\u4f18\u5148\u7ea7\u8d8a\u9ad8\u3002</p> <p>\u90ae\u4ef6\u670d\u52a1\u901a\u5e38\u8fd8\u9700\u8981 TXT \u8bb0\u5f55\u914d\u5408\uff1a</p> <ul> <li>SPF</li> <li>DKIM</li> <li>DMARC</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#6-txt","title":"6. TXT \u8bb0\u5f55","text":"<p>TXT \u8bb0\u5f55\u4fdd\u5b58\u6587\u672c\u4fe1\u606f\u3002</p> <p>\u5e38\u89c1\u7528\u9014\uff1a</p> <ul> <li>\u8bc1\u660e\u57df\u540d\u6240\u6709\u6743\u3002</li> <li>\u914d\u7f6e SPF\u3002</li> <li>\u914d\u7f6e DKIM\u3002</li> <li>\u914d\u7f6e DMARC\u3002</li> <li>\u7b2c\u4e09\u65b9\u5e73\u53f0\u9a8c\u8bc1\u3002</li> </ul> <p>\u793a\u4f8b\uff1a</p> <pre><code>example.com TXT \"v=spf1 include:_spf.example.net -all\"\n</code></pre>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#7-ns","title":"7. NS \u8bb0\u5f55","text":"<p>NS \u8bb0\u5f55\u6307\u5b9a\u67d0\u4e2a\u57df\u540d\u7531\u54ea\u4e9b\u6743\u5a01 DNS \u670d\u52a1\u5668\u8d1f\u8d23\u3002</p> <p>\u5728\u6ce8\u518c\u5546\u5904\u8bbe\u7f6e\u7684 nameserver \u51b3\u5b9a\u6574\u4e2a\u57df\u540d\u4f7f\u7528\u54ea\u7ec4\u6743\u5a01 DNS\u3002</p> <p>\u4f8b\u5982\uff1a</p> <pre><code>ns1.example-dns.com\nns2.example-dns.com\n</code></pre>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#8-soa","title":"8. SOA \u8bb0\u5f55","text":"<p>SOA \u662f Start of Authority\uff0c\u8868\u793a DNS \u533a\u57df\u7684\u8d77\u59cb\u6388\u6743\u4fe1\u606f\u3002</p> <p>\u5305\u542b\uff1a</p> <ul> <li>\u4e3b DNS \u670d\u52a1\u5668\u3002</li> <li>\u7ba1\u7406\u5458\u90ae\u7bb1\u3002</li> <li>\u5e8f\u5217\u53f7\u3002</li> <li>\u5237\u65b0\u65f6\u95f4\u3002</li> <li>\u91cd\u8bd5\u65f6\u95f4\u3002</li> <li>\u8fc7\u671f\u65f6\u95f4\u3002</li> <li>\u6700\u5c0f TTL\u3002</li> </ul> <p>\u666e\u901a\u7f51\u7ad9\u914d\u7f6e\u4e2d\u5f88\u5c11\u76f4\u63a5\u4fee\u6539 SOA\uff0c\u4f46\u6392\u67e5\u6743\u5a01 DNS \u95ee\u9898\u65f6\u4f1a\u770b\u5230\u5b83\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#9-caa","title":"9. CAA \u8bb0\u5f55","text":"<p>CAA \u7528\u6765\u9650\u5236\u54ea\u4e9b\u8bc1\u4e66\u9881\u53d1\u673a\u6784\u53ef\u4ee5\u7ed9\u57df\u540d\u7b7e\u53d1\u8bc1\u4e66\u3002</p> <p>\u793a\u4f8b\uff1a</p> <pre><code>example.com CAA 0 issue \"letsencrypt.org\"\n</code></pre> <p>\u5982\u679c\u914d\u7f6e\u9519\u8bef\uff0c\u53ef\u80fd\u5bfc\u81f4 HTTPS \u8bc1\u4e66\u7533\u8bf7\u5931\u8d25\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#10-ptr","title":"10. PTR \u8bb0\u5f55","text":"<p>PTR \u7528\u4e8e\u53cd\u5411\u89e3\u6790\uff0c\u628a IP \u5730\u5740\u89e3\u6790\u56de\u57df\u540d\u3002</p> <p>\u5e38\u89c1\u4e8e\u90ae\u4ef6\u670d\u52a1\u5668\uff0c\u56e0\u4e3a\u5f88\u591a\u90ae\u4ef6\u670d\u52a1\u4f1a\u68c0\u67e5\u53d1\u9001\u65b9 IP \u662f\u5426\u6709\u5408\u7406\u7684\u53cd\u5411\u89e3\u6790\u3002</p> <p>PTR \u8bb0\u5f55\u901a\u5e38\u7531 IP \u6240\u5c5e\u7684\u4e91\u5382\u5546\u3001\u673a\u623f\u6216\u8fd0\u8425\u5546\u914d\u7f6e\uff0c\u4e0d\u662f\u5728\u666e\u901a\u57df\u540d DNS \u9762\u677f\u4e2d\u914d\u7f6e\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#_7","title":"\u4e5d\u3001\u4e3b\u673a\u8bb0\u5f55\u3001\u8bb0\u5f55\u503c\u548c\u7ebf\u8def","text":""},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#1_3","title":"1. \u4e3b\u673a\u8bb0\u5f55","text":"<p>\u4e3b\u673a\u8bb0\u5f55\u8868\u793a\u8981\u914d\u7f6e\u54ea\u4e2a\u5b50\u57df\u3002</p> <p>\u5e38\u89c1\u5199\u6cd5\uff1a</p> \u4e3b\u673a\u8bb0\u5f55 \u5b8c\u6574\u57df\u540d <code>@</code> <code>example.com</code> <code>www</code> <code>www.example.com</code> <code>api</code> <code>api.example.com</code> <code>*</code> \u6cdb\u89e3\u6790\uff0c\u4f8b\u5982 <code>anything.example.com</code>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#2_1","title":"2. \u8bb0\u5f55\u503c","text":"<p>\u8bb0\u5f55\u503c\u662f\u89e3\u6790\u76ee\u6807\u3002</p> <p>\u4f8b\u5982\uff1a</p> <ul> <li>A \u8bb0\u5f55\u7684\u8bb0\u5f55\u503c\u662f IPv4 \u5730\u5740\u3002</li> <li>AAAA \u8bb0\u5f55\u7684\u8bb0\u5f55\u503c\u662f IPv6 \u5730\u5740\u3002</li> <li>CNAME \u8bb0\u5f55\u7684\u8bb0\u5f55\u503c\u662f\u53e6\u4e00\u4e2a\u57df\u540d\u3002</li> <li>MX \u8bb0\u5f55\u7684\u8bb0\u5f55\u503c\u662f\u90ae\u4ef6\u670d\u52a1\u5668\u57df\u540d\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#3_1","title":"3. \u89e3\u6790\u7ebf\u8def","text":"<p>\u6709\u4e9b DNS \u670d\u52a1\u5546\u652f\u6301\u6309\u7ebf\u8def\u8fd4\u56de\u4e0d\u540c\u7ed3\u679c\u3002</p> <p>\u4f8b\u5982\uff1a</p> <ul> <li>\u9ed8\u8ba4\u7ebf\u8def\u3002</li> <li>\u7535\u4fe1\u7ebf\u8def\u3002</li> <li>\u8054\u901a\u7ebf\u8def\u3002</li> <li>\u79fb\u52a8\u7ebf\u8def\u3002</li> <li>\u6d77\u5916\u7ebf\u8def\u3002</li> </ul> <p>\u8fd9\u53ef\u4ee5\u7528\u4e8e\u8bbf\u95ee\u4f18\u5316\uff0c\u4f46\u4e5f\u4f1a\u8ba9\u4e0d\u540c\u5730\u533a\u67e5\u8be2\u5230\u4e0d\u540c IP\uff0c\u6392\u67e5\u65f6\u8981\u6ce8\u610f\u67e5\u8be2\u6765\u6e90\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#ttl-dns","title":"\u5341\u3001TTL \u548c DNS \u7f13\u5b58","text":"<p>TTL \u662f Time To Live\uff0c\u8868\u793a DNS \u8bb0\u5f55\u53ef\u4ee5\u88ab\u7f13\u5b58\u591a\u4e45\u3002</p> <p>\u4f8b\u5982 TTL \u4e3a 600\uff1a</p> <pre><code>\u9012\u5f52 DNS \u53ef\u4ee5\u628a\u8fd9\u4e2a\u7ed3\u679c\u7f13\u5b58 600 \u79d2\n</code></pre>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#1-ttl","title":"1. TTL \u7684\u5f71\u54cd","text":"<p>TTL \u8d8a\u5927\uff1a</p> <ul> <li>\u7f13\u5b58\u65f6\u95f4\u957f\u3002</li> <li>DNS \u67e5\u8be2\u538b\u529b\u5c0f\u3002</li> <li>\u4fee\u6539\u89e3\u6790\u540e\u751f\u6548\u66f4\u6162\u3002</li> </ul> <p>TTL \u8d8a\u5c0f\uff1a</p> <ul> <li>\u4fee\u6539\u89e3\u6790\u540e\u66f4\u5feb\u751f\u6548\u3002</li> <li>DNS \u67e5\u8be2\u538b\u529b\u66f4\u5927\u3002</li> <li>\u9002\u5408\u8fc1\u79fb\u3001\u5207\u6362\u524d\u4e34\u65f6\u964d\u4f4e\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#2_2","title":"2. \u4fee\u6539\u89e3\u6790\u4e3a\u4ec0\u4e48\u4e0d\u662f\u7acb\u523b\u751f\u6548","text":"<p>\u539f\u56e0\uff1a</p> <ul> <li>\u9012\u5f52 DNS \u7f13\u5b58\u8fd8\u6ca1\u8fc7\u671f\u3002</li> <li>\u672c\u673a DNS \u7f13\u5b58\u8fd8\u6ca1\u5237\u65b0\u3002</li> <li>\u6d4f\u89c8\u5668\u6709\u81ea\u5df1\u7684 DNS \u7f13\u5b58\u3002</li> <li>\u4e0d\u540c\u5730\u533a\u9012\u5f52 DNS \u66f4\u65b0\u65f6\u95f4\u4e0d\u540c\u3002</li> <li>\u6743\u5a01 DNS \u670d\u52a1\u5668\u4e4b\u95f4\u540c\u6b65\u9700\u8981\u65f6\u95f4\u3002</li> </ul> <p>\u901a\u5e38\u8bf4\u7684\u201cDNS \u751f\u6548\u65f6\u95f4\u201d\u672c\u8d28\u4e0a\u4e3b\u8981\u53d7\u7f13\u5b58\u548c TTL \u5f71\u54cd\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#3_2","title":"3. \u5207\u6362\u670d\u52a1\u5668\u524d\u7684\u505a\u6cd5","text":"<p>\u5982\u679c\u8ba1\u5212\u628a\u57df\u540d\u4ece\u65e7\u670d\u52a1\u5668\u5207\u5230\u65b0\u670d\u52a1\u5668\uff1a</p> <ol> <li>\u63d0\u524d\u628a TTL \u8c03\u4f4e\uff0c\u4f8b\u5982 300 \u79d2\u3002</li> <li>\u7b49\u65e7 TTL \u8fc7\u671f\u3002</li> <li>\u4fee\u6539 A \u8bb0\u5f55\u5230\u65b0 IP\u3002</li> <li>\u9a8c\u8bc1\u4e0d\u540c\u5730\u533a\u89e3\u6790\u7ed3\u679c\u3002</li> <li>\u786e\u8ba4\u7a33\u5b9a\u540e\u518d\u628a TTL \u8c03\u56de\u6b63\u5e38\u503c\u3002</li> </ol>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#_8","title":"\u5341\u4e00\u3001\u5e38\u89c1\u57df\u540d\u914d\u7f6e\u573a\u666f","text":""},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#1_4","title":"1. \u57df\u540d\u6307\u5411\u7f51\u7ad9\u670d\u52a1\u5668","text":"<p>\u5047\u8bbe\u670d\u52a1\u5668\u516c\u7f51 IP \u662f\uff1a</p> <pre><code>203.0.113.10\n</code></pre> <p>\u914d\u7f6e\uff1a</p> \u4e3b\u673a\u8bb0\u5f55 \u7c7b\u578b \u8bb0\u5f55\u503c <code>@</code> A <code>203.0.113.10</code> <code>www</code> A <code>203.0.113.10</code> <p>\u8bbf\u95ee\uff1a</p> <pre><code>https://example.com\nhttps://www.example.com\n</code></pre> <p>\u8fd8\u9700\u8981\uff1a</p> <ul> <li>Web \u670d\u52a1\u5668\u76d1\u542c 80/443\u3002</li> <li>\u9632\u706b\u5899\u6216\u5b89\u5168\u7ec4\u653e\u884c 80/443\u3002</li> <li>\u914d\u7f6e HTTPS \u8bc1\u4e66\u3002</li> <li>Web \u670d\u52a1\u4e2d\u7ed1\u5b9a\u5bf9\u5e94\u57df\u540d\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#2-www","title":"2. <code>www</code> \u6307\u5411\u6839\u57df\u540d","text":"<p>\u914d\u7f6e\uff1a</p> \u4e3b\u673a\u8bb0\u5f55 \u7c7b\u578b \u8bb0\u5f55\u503c <code>@</code> A <code>203.0.113.10</code> <code>www</code> CNAME <code>example.com</code> <p>\u8fd9\u6837 <code>www.example.com</code> \u4f1a\u4f5c\u4e3a\u522b\u540d\u89e3\u6790\u5230 <code>example.com</code>\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#3_3","title":"3. \u5b50\u57df\u540d\u6307\u5411\u4e0d\u540c\u670d\u52a1","text":"\u4e3b\u673a\u8bb0\u5f55 \u7c7b\u578b \u8bb0\u5f55\u503c \u7528\u9014 <code>www</code> A <code>203.0.113.10</code> \u5b98\u7f51 <code>api</code> A <code>203.0.113.20</code> API <code>admin</code> A <code>203.0.113.30</code> \u540e\u53f0 <code>cdn</code> CNAME <code>cdn-provider.example.net</code> \u9759\u6001\u8d44\u6e90"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#4-cdn","title":"4. \u4f7f\u7528 CDN","text":"<p>CDN \u901a\u5e38\u4f1a\u8981\u6c42\u914d\u7f6e CNAME\u3002</p> <p>\u793a\u4f8b\uff1a</p> <pre><code>www.example.com CNAME www.example.com.cdn-provider.net\n</code></pre> <p>\u6d41\u7a0b\uff1a</p> <pre><code>\u7528\u6237\u8bbf\u95ee www.example.com\n  -&gt; DNS \u8fd4\u56de CDN \u57df\u540d\n  -&gt; CDN \u6839\u636e\u5730\u533a\u548c\u7f51\u7edc\u8fd4\u56de\u5c31\u8fd1\u8282\u70b9\n  -&gt; \u7528\u6237\u8bbf\u95ee CDN \u8282\u70b9\n  -&gt; CDN \u547d\u4e2d\u7f13\u5b58\u6216\u56de\u6e90\u5230\u6e90\u7ad9\n</code></pre> <p>\u6ce8\u610f\uff1a</p> <ul> <li>CDN \u5e73\u53f0\u901a\u5e38\u8fd8\u8981\u914d\u7f6e\u6e90\u7ad9\u3002</li> <li>HTTPS \u8bc1\u4e66\u9700\u8981\u5728 CDN \u4e0a\u914d\u7f6e\u3002</li> <li>\u6e90\u7ad9\u8981\u9650\u5236\u4e0d\u5fc5\u8981\u7684\u516c\u7f51\u8bbf\u95ee\u65f6\uff0c\u9700\u8981\u8003\u8651 CDN \u56de\u6e90 IP\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#5_1","title":"5. \u914d\u7f6e\u90ae\u7bb1","text":"<p>\u90ae\u4ef6\u670d\u52a1\u4e00\u822c\u9700\u8981\uff1a</p> <ul> <li>MX \u8bb0\u5f55\u3002</li> <li>SPF TXT \u8bb0\u5f55\u3002</li> <li>DKIM TXT \u8bb0\u5f55\u3002</li> <li>DMARC TXT \u8bb0\u5f55\u3002</li> </ul> <p>\u793a\u4f8b\uff1a</p> <pre><code>example.com MX 10 mail.example.com\nmail.example.com A 203.0.113.50\nexample.com TXT \"v=spf1 mx -all\"\n_dmarc.example.com TXT \"v=DMARC1; p=quarantine; rua=mailto:dmarc@example.com\"\n</code></pre> <p>\u5177\u4f53\u503c\u8981\u4ee5\u90ae\u4ef6\u670d\u52a1\u5546\u63d0\u4f9b\u7684\u914d\u7f6e\u4e3a\u51c6\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#6","title":"6. \u7b2c\u4e09\u65b9\u5e73\u53f0\u57df\u540d\u9a8c\u8bc1","text":"<p>\u5f88\u591a\u5e73\u53f0\u4f1a\u8981\u6c42\u6dfb\u52a0 TXT \u8bb0\u5f55\u8bc1\u660e\u57df\u540d\u6240\u6709\u6743\u3002</p> <p>\u4f8b\u5982\uff1a</p> <pre><code>example.com TXT \"verification=abc123\"\n</code></pre> <p>\u6dfb\u52a0\u540e\u5e73\u53f0\u4f1a\u67e5\u8be2 DNS \u8bb0\u5f55\uff0c\u786e\u8ba4\u4f60\u80fd\u63a7\u5236\u8be5\u57df\u540d\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#7","title":"7. \u57df\u540d\u8df3\u8f6c","text":"<p>DNS \u672c\u8eab\u4e0d\u8d1f\u8d23 HTTP \u8df3\u8f6c\u3002</p> <p>\u4f8b\u5982\u8981\u5b9e\u73b0\uff1a</p> <pre><code>example.com -&gt; https://www.example.com\n</code></pre> <p>\u9700\u8981\u5728\u4ee5\u4e0b\u4f4d\u7f6e\u914d\u7f6e\u91cd\u5b9a\u5411\uff1a</p> <ul> <li>Web \u670d\u52a1\u5668\u3002</li> <li>CDN\u3002</li> <li>\u8d1f\u8f7d\u5747\u8861\u3002</li> <li>\u57df\u540d\u670d\u52a1\u5546\u63d0\u4f9b\u7684 URL \u8f6c\u53d1\u529f\u80fd\u3002</li> </ul> <p>DNS \u53ea\u80fd\u544a\u8bc9\u5ba2\u6237\u7aef\u53bb\u54ea\u4e2a IP \u6216\u57df\u540d\uff0c\u4e0d\u80fd\u76f4\u63a5\u8fd4\u56de HTTP 301/302\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#https","title":"\u5341\u4e8c\u3001\u57df\u540d\u548c HTTPS \u8bc1\u4e66","text":"<p>HTTPS \u8bc1\u4e66\u5fc5\u987b\u548c\u8bbf\u95ee\u57df\u540d\u5339\u914d\u3002</p> <p>\u4f8b\u5982\u8bbf\u95ee\uff1a</p> <pre><code>https://api.example.com\n</code></pre> <p>\u8bc1\u4e66\u5fc5\u987b\u5305\u542b\uff1a</p> <pre><code>api.example.com\n</code></pre> <p>\u6216\u8005\u4f7f\u7528\u901a\u914d\u7b26\u8bc1\u4e66\uff1a</p> <pre><code>*.example.com\n</code></pre>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#1_5","title":"1. \u5e38\u89c1\u8bc1\u4e66\u7c7b\u578b","text":"\u7c7b\u578b \u793a\u4f8b \u8bf4\u660e \u5355\u57df\u540d\u8bc1\u4e66 <code>www.example.com</code> \u53ea\u4fdd\u62a4\u4e00\u4e2a\u57df\u540d \u591a\u57df\u540d\u8bc1\u4e66 <code>example.com</code>\u3001<code>www.example.com</code> \u4e00\u4e2a\u8bc1\u4e66\u5305\u542b\u591a\u4e2a\u57df\u540d \u901a\u914d\u7b26\u8bc1\u4e66 <code>*.example.com</code> \u4fdd\u62a4\u4e00\u7ea7\u5b50\u57df\u540d <p>\u6ce8\u610f\uff1a</p> <pre><code>*.example.com\n</code></pre> <p>\u53ef\u4ee5\u5339\u914d\uff1a</p> <pre><code>www.example.com\napi.example.com\n</code></pre> <p>\u4e0d\u80fd\u5339\u914d\uff1a</p> <pre><code>dev.api.example.com\n</code></pre>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#2-dns","title":"2. DNS \u9a8c\u8bc1","text":"<p>\u7533\u8bf7\u8bc1\u4e66\u65f6\uff0cCA \u53ef\u80fd\u8981\u6c42\u6dfb\u52a0 TXT \u8bb0\u5f55\u5b8c\u6210 DNS \u9a8c\u8bc1\u3002</p> <p>\u5e38\u89c1\u8bb0\u5f55\uff1a</p> <pre><code>_acme-challenge.example.com TXT \"xxxx\"\n</code></pre> <p>\u9a8c\u8bc1\u901a\u8fc7\u540e\u624d\u80fd\u7b7e\u53d1\u8bc1\u4e66\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#_9","title":"\u5341\u4e09\u3001\u5e38\u7528\u6392\u67e5\u547d\u4ee4","text":""},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#1-windows","title":"1. Windows","text":"<pre><code>nslookup example.com\nnslookup www.example.com\nnslookup -type=mx example.com\nnslookup -type=txt example.com\nipconfig /flushdns\n</code></pre> <p>\u8bf4\u660e\uff1a</p> <ul> <li><code>nslookup example.com</code>\uff1a\u67e5\u8be2\u9ed8\u8ba4 A \u8bb0\u5f55\u3002</li> <li><code>-type=mx</code>\uff1a\u67e5\u8be2 MX \u8bb0\u5f55\u3002</li> <li><code>-type=txt</code>\uff1a\u67e5\u8be2 TXT \u8bb0\u5f55\u3002</li> <li><code>ipconfig /flushdns</code>\uff1a\u6e05\u7406 Windows DNS \u7f13\u5b58\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#2-linux-macos","title":"2. Linux / macOS","text":"<pre><code>dig example.com\ndig example.com A\ndig example.com AAAA\ndig example.com MX\ndig example.com TXT\ndig www.example.com CNAME\ndig +trace www.example.com\n</code></pre> <p>\u8bf4\u660e\uff1a</p> <ul> <li><code>dig</code>\uff1a\u5e38\u7528 DNS \u67e5\u8be2\u5de5\u5177\u3002</li> <li><code>dig +trace</code>\uff1a\u4ece\u6839\u57df\u5f00\u59cb\u8ffd\u8e2a\u89e3\u6790\u94fe\u8def\u3002</li> </ul> <p>\u6307\u5b9a DNS \u670d\u52a1\u5668\u67e5\u8be2\uff1a</p> <pre><code>dig @8.8.8.8 example.com\ndig @1.1.1.1 example.com\n</code></pre> <p>\u67e5\u8be2\u6743\u5a01 DNS\uff1a</p> <pre><code>dig example.com NS\n</code></pre>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#3_4","title":"3. \u67e5\u770b\u672c\u673a\u8fde\u63a5","text":"<pre><code>ping example.com\ncurl -I https://example.com\ntraceroute example.com\n</code></pre> <p>Windows\uff1a</p> <pre><code>ping example.com\ncurl -I https://example.com\ntracert example.com\n</code></pre> <p>\u6ce8\u610f\uff1a<code>ping</code> \u6210\u529f\u4e0d\u4ee3\u8868 HTTP \u670d\u52a1\u6b63\u5e38\uff0c<code>ping</code> \u5931\u8d25\u4e5f\u4e0d\u4e00\u5b9a\u4ee3\u8868\u7f51\u7ad9\u4e0d\u53ef\u8bbf\u95ee\uff0c\u56e0\u4e3a\u670d\u52a1\u5668\u6216\u9632\u706b\u5899\u53ef\u80fd\u7981\u7528\u4e86 ICMP\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#_10","title":"\u5341\u56db\u3001\u5e38\u89c1\u95ee\u9898\u6392\u67e5","text":""},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#1_6","title":"1. \u57df\u540d\u89e3\u6790\u4e0d\u5230","text":"<p>\u73b0\u8c61\uff1a</p> <pre><code>NXDOMAIN\n</code></pre> <p>\u53ef\u80fd\u539f\u56e0\uff1a</p> <ul> <li>\u57df\u540d\u6ca1\u6709\u6ce8\u518c\u3002</li> <li>\u57df\u540d\u8fc7\u671f\u3002</li> <li>\u4e3b\u673a\u8bb0\u5f55\u5199\u9519\u3002</li> <li>\u6743\u5a01 DNS \u4e2d\u6ca1\u6709\u8be5\u8bb0\u5f55\u3002</li> <li>nameserver \u914d\u7f6e\u9519\u8bef\u3002</li> </ul> <p>\u6392\u67e5\uff1a</p> <pre><code>dig example.com NS\ndig www.example.com\ndig +trace www.example.com\n</code></pre>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#2-ip","title":"2. \u89e3\u6790\u5230\u4e86\u65e7 IP","text":"<p>\u53ef\u80fd\u539f\u56e0\uff1a</p> <ul> <li>\u9012\u5f52 DNS \u7f13\u5b58\u672a\u8fc7\u671f\u3002</li> <li>\u672c\u673a DNS \u7f13\u5b58\u672a\u6e05\u7406\u3002</li> <li>\u6d4f\u89c8\u5668\u7f13\u5b58\u3002</li> <li>\u4fee\u6539\u4e86\u9519\u8bef\u7684 DNS \u670d\u52a1\u5546\u9762\u677f\u3002</li> <li>\u6743\u5a01 DNS \u8fd8\u6ca1\u540c\u6b65\u3002</li> </ul> <p>\u6392\u67e5\uff1a</p> <pre><code>dig @\u6743\u5a01DNS www.example.com\ndig @8.8.8.8 www.example.com\ndig @1.1.1.1 www.example.com\n</code></pre> <p>\u5982\u679c\u6743\u5a01 DNS \u8fd4\u56de\u65b0 IP\uff0c\u800c\u516c\u5171 DNS \u8fd4\u56de\u65e7 IP\uff0c\u591a\u534a\u662f\u7f13\u5b58\u8fd8\u6ca1\u8fc7\u671f\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#3-ping-ip","title":"3. \u80fd ping IP\uff0c\u4f46\u4e0d\u80fd\u8bbf\u95ee\u57df\u540d","text":"<p>\u53ef\u80fd\u539f\u56e0\uff1a</p> <ul> <li>DNS \u89e3\u6790\u5931\u8d25\u3002</li> <li>\u57df\u540d\u89e3\u6790\u5230\u9519\u8bef IP\u3002</li> <li>Web \u670d\u52a1\u6ca1\u6709\u7ed1\u5b9a\u8be5\u57df\u540d\u3002</li> <li>HTTPS \u8bc1\u4e66\u4e0d\u5339\u914d\u3002</li> <li>CDN \u6216\u53cd\u5411\u4ee3\u7406\u914d\u7f6e\u9519\u8bef\u3002</li> </ul> <p>\u6392\u67e5\u987a\u5e8f\uff1a</p> <ol> <li>\u67e5\u57df\u540d\u89e3\u6790\u7ed3\u679c\u3002</li> <li>\u76f4\u63a5\u8bbf\u95ee IP \u6d4b\u8bd5\u670d\u52a1\u3002</li> <li>\u68c0\u67e5 Web \u670d\u52a1\u5668\u865a\u62df\u4e3b\u673a\u914d\u7f6e\u3002</li> <li>\u68c0\u67e5 80/443 \u7aef\u53e3\u3002</li> <li>\u68c0\u67e5 HTTPS \u8bc1\u4e66\u3002</li> </ol>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#4_1","title":"4. \u57df\u540d\u80fd\u89e3\u6790\uff0c\u4f46\u7f51\u7ad9\u6253\u4e0d\u5f00","text":"<p>DNS \u53ea\u8d1f\u8d23\u628a\u57df\u540d\u89e3\u6790\u5230\u76ee\u6807\u5730\u5740\u3002\u7f51\u7ad9\u6253\u4e0d\u5f00\u4e0d\u4e00\u5b9a\u662f DNS \u95ee\u9898\u3002</p> <p>\u7ee7\u7eed\u68c0\u67e5\uff1a</p> <ul> <li>\u670d\u52a1\u5668\u662f\u5426\u8fd0\u884c\u3002</li> <li>Web \u670d\u52a1\u662f\u5426\u542f\u52a8\u3002</li> <li>\u7aef\u53e3\u662f\u5426\u5f00\u653e\u3002</li> <li>\u4e91\u670d\u52a1\u5668\u5b89\u5168\u7ec4\u662f\u5426\u653e\u884c\u3002</li> <li>\u9632\u706b\u5899\u662f\u5426\u963b\u62e6\u3002</li> <li>Nginx / Apache / \u5e94\u7528\u65e5\u5fd7\u662f\u5426\u62a5\u9519\u3002</li> <li>HTTPS \u8bc1\u4e66\u662f\u5426\u6b63\u786e\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#5-cname","title":"5. CNAME \u914d\u7f6e\u540e\u4e0d\u751f\u6548","text":"<p>\u53ef\u80fd\u539f\u56e0\uff1a</p> <ul> <li>CNAME \u548c A \u8bb0\u5f55\u51b2\u7a81\u3002</li> <li>CNAME \u76ee\u6807\u57df\u540d\u5199\u9519\u3002</li> <li>CNAME \u76ee\u6807\u672c\u8eab\u65e0\u6cd5\u89e3\u6790\u3002</li> <li>\u5728\u6839\u57df\u540d\u914d\u7f6e CNAME\uff0c\u4f46\u670d\u52a1\u5546\u4e0d\u652f\u6301\u3002</li> <li>\u7f13\u5b58\u672a\u8fc7\u671f\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#6_1","title":"6. \u90ae\u4ef6\u6536\u4e0d\u5230\u6216\u8fdb\u5165\u5783\u573e\u7bb1","text":"<p>\u68c0\u67e5\uff1a</p> <ul> <li>MX \u8bb0\u5f55\u662f\u5426\u6b63\u786e\u3002</li> <li>SPF \u662f\u5426\u6b63\u786e\u3002</li> <li>DKIM \u662f\u5426\u6b63\u786e\u3002</li> <li>DMARC \u662f\u5426\u6b63\u786e\u3002</li> <li>\u53d1\u9001\u670d\u52a1\u5668 IP \u662f\u5426\u6709 PTR \u53cd\u5411\u89e3\u6790\u3002</li> <li>\u90ae\u4ef6\u670d\u52a1\u5546\u662f\u5426\u8981\u6c42\u989d\u5916\u9a8c\u8bc1\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#7-https","title":"7. HTTPS \u8bc1\u4e66\u7533\u8bf7\u5931\u8d25","text":"<p>\u53ef\u80fd\u539f\u56e0\uff1a</p> <ul> <li>DNS \u9a8c\u8bc1 TXT \u8bb0\u5f55\u672a\u751f\u6548\u3002</li> <li>CAA \u8bb0\u5f55\u9650\u5236\u4e86\u8bc1\u4e66\u9881\u53d1\u673a\u6784\u3002</li> <li>\u8bc1\u4e66\u7533\u8bf7\u57df\u540d\u548c\u5b9e\u9645\u8bb0\u5f55\u4e0d\u4e00\u81f4\u3002</li> <li>\u4f7f\u7528\u4e86 CDN\uff0c\u9a8c\u8bc1\u8bf7\u6c42\u6ca1\u6709\u6b63\u786e\u5230\u8fbe\u6e90\u7ad9\u3002</li> <li>\u57df\u540d\u72b6\u6001\u5f02\u5e38\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#dns_3","title":"\u5341\u4e94\u3001DNS \u5b89\u5168","text":""},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#1-dns","title":"1. DNS \u52ab\u6301","text":"<p>DNS \u52ab\u6301\u662f\u6307\u89e3\u6790\u7ed3\u679c\u88ab\u6076\u610f\u7be1\u6539\uff0c\u7528\u6237\u8bbf\u95ee\u57df\u540d\u65f6\u88ab\u5f15\u5bfc\u5230\u9519\u8bef\u5730\u5740\u3002</p> <p>\u9632\u62a4\u65b9\u5f0f\uff1a</p> <ul> <li>\u4f7f\u7528\u53ef\u4fe1 DNS \u670d\u52a1\u3002</li> <li>\u91cd\u8981\u57df\u540d\u5f00\u542f DNSSEC\u3002</li> <li>\u7f51\u7ad9\u4f7f\u7528 HTTPS\u3002</li> <li>\u7528\u6237\u4fa7\u907f\u514d\u4f7f\u7528\u4e0d\u53ef\u4fe1\u7f51\u7edc\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#2-dnssec","title":"2. DNSSEC","text":"<p>DNSSEC \u7528\u6570\u5b57\u7b7e\u540d\u9a8c\u8bc1 DNS \u8bb0\u5f55\u662f\u5426\u88ab\u7be1\u6539\u3002</p> <p>\u4f5c\u7528\uff1a</p> <ul> <li>\u9a8c\u8bc1 DNS \u6570\u636e\u5b8c\u6574\u6027\u3002</li> <li>\u9632\u6b62\u90e8\u5206 DNS \u6b3a\u9a97\u653b\u51fb\u3002</li> </ul> <p>\u6ce8\u610f\uff1a</p> <ul> <li>DNSSEC \u4e0d\u80fd\u52a0\u5bc6\u67e5\u8be2\u5185\u5bb9\u3002</li> <li>\u914d\u7f6e\u9519\u8bef\u53ef\u80fd\u5bfc\u81f4\u57df\u540d\u65e0\u6cd5\u89e3\u6790\u3002</li> <li>\u5f00\u542f\u524d\u8981\u786e\u8ba4\u6ce8\u518c\u5546\u548c DNS \u670d\u52a1\u5546\u90fd\u652f\u6301\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#3-caa","title":"3. CAA","text":"<p>CAA \u53ef\u4ee5\u9650\u5236\u54ea\u4e9b CA \u53ef\u4ee5\u4e3a\u57df\u540d\u7b7e\u53d1\u8bc1\u4e66\u3002</p> <p>\u597d\u5904\uff1a</p> <ul> <li>\u964d\u4f4e\u8bc1\u4e66\u88ab\u9519\u8bef\u7b7e\u53d1\u7684\u98ce\u9669\u3002</li> </ul> <p>\u98ce\u9669\uff1a</p> <ul> <li>\u914d\u9519\u4f1a\u5bfc\u81f4\u6b63\u5e38\u8bc1\u4e66\u7b7e\u53d1\u5931\u8d25\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#4_2","title":"4. \u57df\u540d\u8d26\u53f7\u5b89\u5168","text":"<p>\u5efa\u8bae\uff1a</p> <ul> <li>\u6ce8\u518c\u5546\u8d26\u53f7\u5f00\u542f\u591a\u56e0\u7d20\u8ba4\u8bc1\u3002</li> <li>\u5f00\u542f\u57df\u540d\u8f6c\u79fb\u9501\u3002</li> <li>\u4f7f\u7528\u5f3a\u5bc6\u7801\u3002</li> <li>\u9650\u5236 DNS \u7ba1\u7406\u6743\u9650\u3002</li> <li>\u5b9a\u671f\u68c0\u67e5 DNS \u8bb0\u5f55\u3002</li> <li>\u5220\u9664\u4e0d\u7528\u7684\u5b50\u57df\u540d\u8bb0\u5f55\u3002</li> <li>\u9632\u6b62\u5b50\u57df\u540d\u63a5\u7ba1\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#5_2","title":"5. \u5b50\u57df\u540d\u63a5\u7ba1","text":"<p>\u5982\u679c DNS \u4e2d\u5b58\u5728 CNAME \u6307\u5411\u67d0\u4e2a\u7b2c\u4e09\u65b9\u5e73\u53f0\uff0c\u4f46\u8be5\u5e73\u53f0\u4e0a\u7684\u8d44\u6e90\u5df2\u7ecf\u5220\u9664\uff0c\u653b\u51fb\u8005\u53ef\u80fd\u91cd\u65b0\u521b\u5efa\u540c\u540d\u8d44\u6e90\u63a5\u7ba1\u8be5\u5b50\u57df\u540d\u3002</p> <p>\u5e38\u89c1\u98ce\u9669\uff1a</p> <pre><code>old.example.com CNAME old-site.third-party.com\n</code></pre> <p>\u5982\u679c\u7b2c\u4e09\u65b9\u5e73\u53f0\u4e0a\u7684 <code>old-site</code> \u5df2\u88ab\u5220\u9664\uff0c\u5c31\u8981\u53ca\u65f6\u5220\u9664\u8fd9\u6761 DNS \u8bb0\u5f55\u3002</p>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#_11","title":"\u5341\u516d\u3001\u57df\u540d\u63a5\u5165\u7f51\u7ad9\u7684\u5b8c\u6574\u6b65\u9aa4","text":"<p>\u4ee5\u628a <code>example.com</code> \u7ed1\u5b9a\u5230\u4e00\u53f0\u670d\u52a1\u5668\u4e3a\u4f8b\uff1a</p> <ol> <li>\u8d2d\u4e70\u57df\u540d\u3002</li> <li>\u5728\u6ce8\u518c\u5546\u5904\u786e\u8ba4\u57df\u540d\u72b6\u6001\u6b63\u5e38\u3002</li> <li>\u9009\u62e9 DNS \u670d\u52a1\u5546\u3002</li> <li>\u5728\u6ce8\u518c\u5546\u5904\u8bbe\u7f6e nameserver\uff0c\u6216\u4f7f\u7528\u6ce8\u518c\u5546\u9ed8\u8ba4 DNS\u3002</li> <li>\u5728 DNS \u9762\u677f\u6dfb\u52a0 A \u8bb0\u5f55\u3002</li> <li>\u670d\u52a1\u5668\u5f00\u653e 80 \u548c 443 \u7aef\u53e3\u3002</li> <li>Web \u670d\u52a1\u5668\u914d\u7f6e\u57df\u540d\u3002</li> <li>\u7533\u8bf7\u5e76\u914d\u7f6e HTTPS \u8bc1\u4e66\u3002</li> <li>\u4f7f\u7528 <code>dig</code> \u6216 <code>nslookup</code> \u9a8c\u8bc1\u89e3\u6790\u7ed3\u679c\u3002</li> <li>\u4f7f\u7528\u6d4f\u89c8\u5668\u548c <code>curl -I</code> \u9a8c\u8bc1\u7f51\u7ad9\u8bbf\u95ee\u3002</li> <li>\u914d\u7f6e\u76d1\u63a7\u548c\u8bc1\u4e66\u7eed\u671f\u3002</li> </ol>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#_12","title":"\u5341\u4e03\u3001\u5b66\u4e60\u91cd\u70b9","text":"<ul> <li>\u57df\u540d\u662f\u7ed9\u4eba\u770b\u7684\u540d\u5b57\uff0cIP \u662f\u8ba1\u7b97\u673a\u901a\u4fe1\u4f7f\u7528\u7684\u5730\u5740\u3002</li> <li>DNS \u8d1f\u8d23\u628a\u57df\u540d\u89e3\u6790\u4e3a IP \u6216\u5176\u4ed6\u670d\u52a1\u8bb0\u5f55\u3002</li> <li>\u57df\u540d\u89e3\u6790\u94fe\u8def\u662f\uff1a\u6839 DNS -&gt; TLD DNS -&gt; \u6743\u5a01 DNS\u3002</li> <li>\u7528\u6237\u901a\u5e38\u67e5\u8be2\u9012\u5f52 DNS\uff0c\u9012\u5f52 DNS \u4ee3\u66ff\u7528\u6237\u5b8c\u6210\u5b8c\u6574\u67e5\u8be2\u3002</li> <li>A \u8bb0\u5f55\u6307\u5411 IPv4\uff0cAAAA \u6307\u5411 IPv6\uff0cCNAME \u6307\u5411\u53e6\u4e00\u4e2a\u57df\u540d\u3002</li> <li>MX \u7528\u4e8e\u90ae\u4ef6\uff0cTXT \u5e38\u7528\u4e8e\u9a8c\u8bc1\u548c\u90ae\u4ef6\u5b89\u5168\u3002</li> <li>TTL \u51b3\u5b9a\u7f13\u5b58\u65f6\u95f4\uff0c\u5f71\u54cd\u89e3\u6790\u4fee\u6539\u540e\u7684\u751f\u6548\u901f\u5ea6\u3002</li> <li>DNS \u4e0d\u8d1f\u8d23 HTTP \u8df3\u8f6c\uff0c\u8df3\u8f6c\u8981\u5728 Web \u670d\u52a1\u5668\u3001CDN \u6216\u8d1f\u8f7d\u5747\u8861\u914d\u7f6e\u3002</li> <li>HTTPS \u8bc1\u4e66\u5fc5\u987b\u5339\u914d\u8bbf\u95ee\u7684\u57df\u540d\u3002</li> <li>\u6392\u67e5 DNS \u95ee\u9898\u65f6\u8981\u533a\u5206\u6743\u5a01 DNS \u7ed3\u679c\u548c\u9012\u5f52 DNS \u7f13\u5b58\u7ed3\u679c\u3002</li> </ul>"},{"location":"%E5%9F%9F%E5%90%8D%E5%92%8C%E5%9F%9F%E5%90%8D%E8%A7%A3%E6%9E%90.html#_13","title":"\u5341\u516b\u3001\u5e38\u7528\u68c0\u67e5\u6e05\u5355","text":"<p>\u57df\u540d\u65e0\u6cd5\u8bbf\u95ee\u65f6\uff1a</p> <ul> <li>\u57df\u540d\u662f\u5426\u8fc7\u671f\u3002</li> <li>nameserver \u662f\u5426\u6b63\u786e\u3002</li> <li>\u6743\u5a01 DNS \u662f\u5426\u6709\u8bb0\u5f55\u3002</li> <li>A / CNAME \u8bb0\u5f55\u662f\u5426\u6b63\u786e\u3002</li> <li>TTL \u662f\u5426\u8fd8\u6ca1\u8fc7\u671f\u3002</li> <li>\u672c\u673a DNS \u7f13\u5b58\u662f\u5426\u9700\u8981\u6e05\u7406\u3002</li> <li>\u670d\u52a1\u5668\u7aef\u53e3\u662f\u5426\u5f00\u653e\u3002</li> <li>Web \u670d\u52a1\u662f\u5426\u7ed1\u5b9a\u8be5\u57df\u540d\u3002</li> <li>HTTPS \u8bc1\u4e66\u662f\u5426\u5339\u914d\u3002</li> <li>CDN \u6216\u4ee3\u7406\u914d\u7f6e\u662f\u5426\u6b63\u786e\u3002</li> </ul> <p>\u65b0\u589e\u57df\u540d\u89e3\u6790\u65f6\uff1a</p> <ul> <li>\u4e3b\u673a\u8bb0\u5f55\u662f\u5426\u5199\u5bf9\u3002</li> <li>\u8bb0\u5f55\u7c7b\u578b\u662f\u5426\u9009\u5bf9\u3002</li> <li>\u8bb0\u5f55\u503c\u662f\u5426\u6b63\u786e\u3002</li> <li>\u662f\u5426\u548c\u5df2\u6709\u8bb0\u5f55\u51b2\u7a81\u3002</li> <li>TTL \u662f\u5426\u7b26\u5408\u5207\u6362\u9700\u6c42\u3002</li> <li>\u662f\u5426\u9700\u8981\u540c\u65f6\u914d\u7f6e <code>@</code> \u548c <code>www</code>\u3002</li> <li>\u662f\u5426\u9700\u8981\u914d\u7f6e HTTPS \u8bc1\u4e66\u3002</li> <li>\u662f\u5426\u9700\u8981\u914d\u7f6e\u90ae\u4ef6\u76f8\u5173\u8bb0\u5f55\u3002</li> </ul>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html","title":"Web \u6e32\u67d3\u539f\u7406","text":"<p>Web \u6e32\u67d3\u539f\u7406\u7814\u7a76\u7684\u662f\uff1a\u6d4f\u89c8\u5668\u62ff\u5230 HTML\u3001CSS\u3001JavaScript\u3001\u56fe\u7247\u7b49\u8d44\u6e90\u540e\uff0c\u5982\u4f55\u628a\u5b83\u4eec\u8f6c\u6362\u6210\u7528\u6237\u6700\u7ec8\u770b\u5230\u7684\u9875\u9762\u3002</p> <p>\u7b80\u5316\u6d41\u7a0b\uff1a</p> <pre><code>HTML/CSS/JS \u4e0b\u8f7d\n  -&gt; HTML \u89e3\u6790\u751f\u6210 DOM \u6811\n  -&gt; CSS \u89e3\u6790\u751f\u6210 CSSOM \u6811\n  -&gt; DOM + CSSOM \u5408\u6210 Render Tree\n  -&gt; Layout \u8ba1\u7b97\u5e03\u5c40\n  -&gt; Paint \u7ed8\u5236\u50cf\u7d20\n  -&gt; Composite \u5408\u6210\u56fe\u5c42\n  -&gt; \u663e\u793a\u5230\u5c4f\u5e55\n</code></pre>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#1","title":"1. \u6d4f\u89c8\u5668\u4e3b\u8981\u7ec4\u6210","text":"<p>\u6d4f\u89c8\u5668\u4e0d\u662f\u5355\u4e2a\u6a21\u5757\uff0c\u800c\u662f\u591a\u4e2a\u6a21\u5757\u534f\u540c\u5de5\u4f5c\u3002</p> \u7ec4\u6210\u90e8\u5206 \u4f5c\u7528 \u7528\u6237\u754c\u9762 \u5730\u5740\u680f\u3001\u524d\u8fdb\u540e\u9000\u3001\u4e66\u7b7e\u680f\u7b49 \u6d4f\u89c8\u5668\u5f15\u64ce \u534f\u8c03 UI \u548c\u6e32\u67d3\u5f15\u64ce \u6e32\u67d3\u5f15\u64ce \u89e3\u6790 HTML/CSS\uff0c\u5e03\u5c40\u3001\u7ed8\u5236\u9875\u9762 JavaScript \u5f15\u64ce \u89e3\u6790\u548c\u6267\u884c JavaScript \u7f51\u7edc\u6a21\u5757 \u53d1\u9001 HTTP/HTTPS \u8bf7\u6c42\uff0c\u4e0b\u8f7d\u8d44\u6e90 \u5b58\u50a8\u6a21\u5757 \u7ba1\u7406 Cookie\u3001LocalStorage\u3001Cache \u7b49 GPU \u8fdb\u7a0b \u5904\u7406\u56fe\u5c42\u5408\u6210\u3001\u90e8\u5206\u56fe\u5f62\u52a0\u901f <p>\u5e38\u89c1\u6e32\u67d3\u5f15\u64ce\uff1a</p> <ul> <li>Blink\uff1aChrome\u3001Edge \u4f7f\u7528\u3002</li> <li>WebKit\uff1aSafari \u4f7f\u7528\u3002</li> <li>Gecko\uff1aFirefox \u4f7f\u7528\u3002</li> </ul> <p>\u5e38\u89c1 JavaScript \u5f15\u64ce\uff1a</p> <ul> <li>V8\uff1aChrome\u3001Edge\u3001Node.js \u4f7f\u7528\u3002</li> <li>JavaScriptCore\uff1aSafari \u4f7f\u7528\u3002</li> <li>SpiderMonkey\uff1aFirefox \u4f7f\u7528\u3002</li> </ul>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#2","title":"2. \u591a\u8fdb\u7a0b\u67b6\u6784","text":"<p>\u73b0\u4ee3\u6d4f\u89c8\u5668\u901a\u5e38\u91c7\u7528\u591a\u8fdb\u7a0b\u67b6\u6784\uff0c\u63d0\u9ad8\u7a33\u5b9a\u6027\u548c\u5b89\u5168\u6027\u3002</p> <p>\u5e38\u89c1\u8fdb\u7a0b\uff1a</p> \u8fdb\u7a0b \u4f5c\u7528 \u6d4f\u89c8\u5668\u4e3b\u8fdb\u7a0b \u7ba1\u7406\u7a97\u53e3\u3001\u5730\u5740\u680f\u3001\u4e66\u7b7e\u3001\u4e0b\u8f7d\u7b49 \u6e32\u67d3\u8fdb\u7a0b \u8d1f\u8d23\u9875\u9762\u89e3\u6790\u3001JS \u6267\u884c\u3001\u5e03\u5c40\u3001\u7ed8\u5236 \u7f51\u7edc\u8fdb\u7a0b \u8d1f\u8d23\u7f51\u7edc\u8bf7\u6c42 GPU \u8fdb\u7a0b \u8d1f\u8d23\u56fe\u5f62\u52a0\u901f\u548c\u56fe\u5c42\u5408\u6210 \u63d2\u4ef6\u8fdb\u7a0b \u8fd0\u884c\u6d4f\u89c8\u5668\u63d2\u4ef6 <p>\u591a\u8fdb\u7a0b\u7684\u597d\u5904\uff1a</p> <ul> <li>\u4e00\u4e2a\u9875\u9762\u5d29\u6e83\u4e0d\u4e00\u5b9a\u5f71\u54cd\u6574\u4e2a\u6d4f\u89c8\u5668\u3002</li> <li>\u4e0d\u540c\u7ad9\u70b9\u53ef\u4ee5\u9694\u79bb\uff0c\u5b89\u5168\u6027\u66f4\u9ad8\u3002</li> <li>\u53ef\u4ee5\u66f4\u597d\u5730\u5229\u7528\u591a\u6838 CPU\u3002</li> </ul>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#3","title":"3. \u5173\u952e\u6e32\u67d3\u8def\u5f84","text":"<p>\u5173\u952e\u6e32\u67d3\u8def\u5f84\u662f\u6d4f\u89c8\u5668\u4ece\u63a5\u6536 HTML \u5230\u9996\u6b21\u6e32\u67d3\u9875\u9762\u6240\u7ecf\u5386\u7684\u5173\u952e\u6b65\u9aa4\u3002</p> <p>\u6838\u5fc3\u6b65\u9aa4\uff1a</p> <ol> <li>\u89e3\u6790 HTML\uff0c\u6784\u5efa DOM \u6811\u3002</li> <li>\u89e3\u6790 CSS\uff0c\u6784\u5efa CSSOM \u6811\u3002</li> <li>DOM \u548c CSSOM \u5408\u6210\u6e32\u67d3\u6811\u3002</li> <li>\u8ba1\u7b97\u6bcf\u4e2a\u8282\u70b9\u7684\u4f4d\u7f6e\u548c\u5927\u5c0f\u3002</li> <li>\u628a\u8282\u70b9\u7ed8\u5236\u5230\u4e0d\u540c\u56fe\u5c42\u3002</li> <li>\u5408\u6210\u56fe\u5c42\u5e76\u663e\u793a\u5230\u5c4f\u5e55\u3002</li> </ol> <p>\u4f18\u5316\u5173\u952e\u6e32\u67d3\u8def\u5f84\u7684\u76ee\u6807\u662f\u8ba9\u9875\u9762\u66f4\u5feb\u51fa\u73b0\u53ef\u89c1\u5185\u5bb9\u3002</p>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#4-html-dom","title":"4. HTML \u89e3\u6790\u4e0e DOM \u6811","text":"<p>\u6d4f\u89c8\u5668\u4e0b\u8f7d HTML \u540e\uff0c\u4f1a\u8fb9\u4e0b\u8f7d\u8fb9\u89e3\u6790\u3002</p> <p>HTML \u89e3\u6790\u8fc7\u7a0b\uff1a</p> <pre><code>\u5b57\u8282\u6d41 -&gt; \u5b57\u7b26 -&gt; Token -&gt; Node -&gt; DOM Tree\n</code></pre> <p>DOM \u662f Document Object Model\uff0c\u8868\u793a\u9875\u9762\u7ed3\u6784\u3002</p> <p>\u793a\u4f8b HTML\uff1a</p> <pre><code>&lt;!doctype html&gt;\n&lt;html&gt;\n  &lt;head&gt;\n    &lt;title&gt;Demo&lt;/title&gt;\n  &lt;/head&gt;\n  &lt;body&gt;\n    &lt;h1&gt;Hello&lt;/h1&gt;\n    &lt;p&gt;Web rendering&lt;/p&gt;\n  &lt;/body&gt;\n&lt;/html&gt;\n</code></pre> <p>\u5bf9\u5e94 DOM \u6811\u5927\u81f4\u662f\uff1a</p> <pre><code>Document\n  html\n    head\n      title\n    body\n      h1\n      p\n</code></pre> <p>DOM \u6811\u53ea\u63cf\u8ff0\u6587\u6863\u7ed3\u6784\uff0c\u4e0d\u5305\u542b\u6700\u7ec8\u6837\u5f0f\u548c\u5e03\u5c40\u4f4d\u7f6e\u3002</p>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#5-css-cssom","title":"5. CSS \u89e3\u6790\u4e0e CSSOM \u6811","text":"<p>CSSOM \u662f CSS Object Model\uff0c\u8868\u793a CSS \u89c4\u5219\u89e3\u6790\u540e\u7684\u7ed3\u6784\u3002</p> <p>CSS \u89e3\u6790\u8fc7\u7a0b\uff1a</p> <pre><code>CSS \u6587\u672c -&gt; Token -&gt; Rule -&gt; CSSOM Tree\n</code></pre> <p>\u793a\u4f8b CSS\uff1a</p> <pre><code>body {\n  font-size: 16px;\n}\n\nh1 {\n  color: red;\n}\n</code></pre> <p>CSSOM \u4f1a\u8bb0\u5f55\u9009\u62e9\u5668\u3001\u5c5e\u6027\u3001\u7ee7\u627f\u5173\u7cfb\u548c\u5c42\u53e0\u7ed3\u679c\u3002</p> <p>CSSOM \u7684\u7279\u70b9\uff1a</p> <ul> <li>CSS \u4f1a\u963b\u585e\u6e32\u67d3\uff0c\u56e0\u4e3a\u6d4f\u89c8\u5668\u5fc5\u987b\u77e5\u9053\u6837\u5f0f\u624d\u80fd\u6b63\u786e\u7ed8\u5236\u9875\u9762\u3002</li> <li>CSS \u4e0d\u4e00\u5b9a\u963b\u585e DOM \u89e3\u6790\uff0c\u4f46\u4f1a\u5f71\u54cd\u6e32\u67d3\u6811\u751f\u6210\u3002</li> <li>\u5916\u90e8 CSS \u6587\u4ef6\u4e0b\u8f7d\u6162\uff0c\u4f1a\u5ef6\u8fdf\u9996\u6b21\u6e32\u67d3\u3002</li> </ul>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#6-javascript","title":"6. JavaScript \u5bf9\u89e3\u6790\u7684\u5f71\u54cd","text":"<p>\u666e\u901a <code>&lt;script&gt;</code> \u4f1a\u963b\u585e HTML \u89e3\u6790\u3002</p> <p>\u539f\u56e0\uff1a</p> <ul> <li>JavaScript \u53ef\u80fd\u901a\u8fc7 <code>document.write()</code> \u4fee\u6539 HTML\u3002</li> <li>JavaScript \u53ef\u80fd\u8bfb\u53d6\u6216\u4fee\u6539 DOM\u3002</li> <li>JavaScript \u53ef\u80fd\u8bfb\u53d6\u6837\u5f0f\u8ba1\u7b97\u7ed3\u679c\u3002</li> </ul> <p>\u793a\u4f8b\uff1a</p> <pre><code>&lt;script src=\"main.js\"&gt;&lt;/script&gt;\n</code></pre> <p>\u6d4f\u89c8\u5668\u9047\u5230\u666e\u901a\u811a\u672c\u65f6\u901a\u5e38\u4f1a\uff1a</p> <ol> <li>\u6682\u505c HTML \u89e3\u6790\u3002</li> <li>\u4e0b\u8f7d\u811a\u672c\u3002</li> <li>\u6267\u884c\u811a\u672c\u3002</li> <li>\u7ee7\u7eed\u89e3\u6790 HTML\u3002</li> </ol> <p><code>defer</code> \u548c <code>async</code> \u53ef\u4ee5\u51cf\u5c11\u963b\u585e\u3002</p> \u5199\u6cd5 \u4e0b\u8f7d\u884c\u4e3a \u6267\u884c\u65f6\u673a \u662f\u5426\u4fdd\u8bc1\u987a\u5e8f \u666e\u901a script \u963b\u585e\u89e3\u6790\u65f6\u4e0b\u8f7d \u4e0b\u8f7d\u540e\u7acb\u5373\u6267\u884c \u662f defer \u4e0d\u963b\u585e HTML \u89e3\u6790 DOM \u89e3\u6790\u5b8c\u6210\u540e\u6267\u884c \u662f async \u4e0d\u963b\u585e HTML \u89e3\u6790 \u4e0b\u8f7d\u5b8c\u6210\u540e\u7acb\u5373\u6267\u884c \u5426 <p>\u4f7f\u7528\u5efa\u8bae\uff1a</p> <ul> <li>\u4f9d\u8d56 DOM \u7684\u811a\u672c\u53ef\u4ee5\u4f7f\u7528 <code>defer</code>\u3002</li> <li>\u72ec\u7acb\u7edf\u8ba1\u3001\u5e7f\u544a\u811a\u672c\u53ef\u4ee5\u4f7f\u7528 <code>async</code>\u3002</li> <li>\u5173\u952e\u4ea4\u4e92\u811a\u672c\u5e94\u63a7\u5236\u4f53\u79ef\uff0c\u907f\u514d\u957f\u65f6\u95f4\u5360\u7528\u4e3b\u7ebf\u7a0b\u3002</li> </ul>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#7-render-tree","title":"7. \u6e32\u67d3\u6811 Render Tree","text":"<p>\u6d4f\u89c8\u5668\u4f1a\u628a DOM \u548c CSSOM \u5408\u6210\u6e32\u67d3\u6811\u3002</p> <p>\u6e32\u67d3\u6811\u53ea\u5305\u542b\u9700\u8981\u663e\u793a\u7684\u8282\u70b9\u3002</p> <p>\u4e0d\u4f1a\u8fdb\u5165\u6e32\u67d3\u6811\u7684\u8282\u70b9\uff1a</p> <ul> <li><code>display: none</code> \u7684\u5143\u7d20\u3002</li> <li><code>head</code>\u3001<code>script</code>\u3001<code>meta</code> \u7b49\u4e0d\u76f4\u63a5\u663e\u793a\u7684\u8282\u70b9\u3002</li> </ul> <p>\u4f1a\u8fdb\u5165\u6e32\u67d3\u6811\u4f46\u53ef\u80fd\u4e0d\u53ef\u89c1\u7684\u8282\u70b9\uff1a</p> <ul> <li><code>visibility: hidden</code> \u7684\u5143\u7d20\u4ecd\u5360\u636e\u5e03\u5c40\u7a7a\u95f4\u3002</li> <li><code>opacity: 0</code> \u7684\u5143\u7d20\u4ecd\u53c2\u4e0e\u5e03\u5c40\u548c\u7ed8\u5236\u3002</li> </ul> <p>\u5bf9\u6bd4\uff1a</p> \u6837\u5f0f \u662f\u5426\u5360\u636e\u7a7a\u95f4 \u662f\u5426\u6e32\u67d3 <code>display: none</code> \u5426 \u5426 <code>visibility: hidden</code> \u662f \u4e0d\u53ef\u89c1 <code>opacity: 0</code> \u662f \u900f\u660e"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#8-layout","title":"8. \u5e03\u5c40 Layout","text":"<p>\u5e03\u5c40\u4e5f\u53eb\u56de\u6d41 Reflow\u3002\u5b83\u8d1f\u8d23\u8ba1\u7b97\u6bcf\u4e2a\u53ef\u89c1\u5143\u7d20\u7684\u51e0\u4f55\u4fe1\u606f\u3002</p> <p>\u5e03\u5c40\u9636\u6bb5\u4f1a\u8ba1\u7b97\uff1a</p> <ul> <li>\u5143\u7d20\u5bbd\u9ad8\u3002</li> <li>\u5143\u7d20\u4f4d\u7f6e\u3002</li> <li>\u884c\u76d2\u3001\u5757\u76d2\u3001\u5f39\u6027\u76d2\u3001\u7f51\u683c\u5e03\u5c40\u7b49\u3002</li> <li>\u7236\u5b50\u5143\u7d20\u4e4b\u95f4\u7684\u7ea6\u675f\u5173\u7cfb\u3002</li> </ul> <p>\u53ef\u80fd\u89e6\u53d1\u5e03\u5c40\u7684\u64cd\u4f5c\uff1a</p> <ul> <li>\u4fee\u6539\u5143\u7d20\u5c3a\u5bf8\uff1a<code>width</code>\u3001<code>height</code>\u3002</li> <li>\u4fee\u6539\u5143\u7d20\u4f4d\u7f6e\uff1a<code>top</code>\u3001<code>left</code>\u3001<code>margin</code>\u3002</li> <li>\u6dfb\u52a0\u6216\u5220\u9664 DOM \u8282\u70b9\u3002</li> <li>\u4fee\u6539\u5b57\u4f53\u5927\u5c0f\u3002</li> <li>\u6539\u53d8\u7a97\u53e3\u5927\u5c0f\u3002</li> <li>\u8bfb\u53d6\u67d0\u4e9b\u5e03\u5c40\u5c5e\u6027\u540e\u53c8\u4fee\u6539\u6837\u5f0f\u3002</li> </ul> <p>\u5e38\u89c1\u4f1a\u5f3a\u5236\u6d4f\u89c8\u5668\u8ba1\u7b97\u5e03\u5c40\u7684\u5c5e\u6027\uff1a</p> <pre><code>offsetWidth\noffsetHeight\noffsetTop\noffsetLeft\nclientWidth\nclientHeight\nscrollTop\nscrollHeight\ngetBoundingClientRect()\ngetComputedStyle()\n</code></pre> <p>\u5982\u679c\u5728\u5faa\u73af\u4e2d\u53cd\u590d\u8bfb\u5199\u8fd9\u4e9b\u5c5e\u6027\uff0c\u5bb9\u6613\u9020\u6210\u5e03\u5c40\u6296\u52a8\u3002</p>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#9-paint","title":"9. \u7ed8\u5236 Paint","text":"<p>\u7ed8\u5236\u9636\u6bb5\u4f1a\u628a\u6e32\u67d3\u6811\u4e2d\u7684\u8282\u70b9\u8f6c\u6362\u4e3a\u7ed8\u5236\u6307\u4ee4\u3002</p> <p>\u7ed8\u5236\u5185\u5bb9\u5305\u62ec\uff1a</p> <ul> <li>\u6587\u672c\u3002</li> <li>\u989c\u8272\u3002</li> <li>\u8fb9\u6846\u3002</li> <li>\u9634\u5f71\u3002</li> <li>\u56fe\u7247\u3002</li> <li>\u80cc\u666f\u3002</li> </ul> <p>\u5e38\u89c1\u4f1a\u89e6\u53d1\u91cd\u7ed8\u7684\u64cd\u4f5c\uff1a</p> <ul> <li>\u4fee\u6539 <code>color</code>\u3002</li> <li>\u4fee\u6539 <code>background-color</code>\u3002</li> <li>\u4fee\u6539 <code>box-shadow</code>\u3002</li> <li>\u4fee\u6539 <code>visibility</code>\u3002</li> </ul> <p>\u91cd\u7ed8\u4e0d\u4e00\u5b9a\u91cd\u65b0\u5e03\u5c40\uff0c\u4f46\u4ecd\u7136\u6709\u6027\u80fd\u6210\u672c\u3002</p>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#10-composite","title":"10. \u5408\u6210 Composite","text":"<p>\u6d4f\u89c8\u5668\u53ef\u80fd\u4f1a\u628a\u9875\u9762\u62c6\u5206\u4e3a\u591a\u4e2a\u56fe\u5c42\u3002\u7ed8\u5236\u5b8c\u6210\u540e\uff0c\u5408\u6210\u7ebf\u7a0b\u628a\u8fd9\u4e9b\u56fe\u5c42\u6309\u6b63\u786e\u987a\u5e8f\u5408\u6210\u5230\u5c4f\u5e55\u4e0a\u3002</p> <p>\u53ef\u80fd\u521b\u5efa\u72ec\u7acb\u5408\u6210\u5c42\u7684\u60c5\u51b5\uff1a</p> <ul> <li>\u4f7f\u7528 <code>transform</code>\u3002</li> <li>\u4f7f\u7528 <code>opacity</code> \u52a8\u753b\u3002</li> <li>\u4f7f\u7528 <code>position: fixed</code>\u3002</li> <li>\u4f7f\u7528 <code>will-change</code>\u3002</li> <li>\u4f7f\u7528\u89c6\u9891\u3001Canvas\u3001WebGL\u3002</li> </ul> <p>\u5408\u6210\u7684\u4f18\u52bf\uff1a</p> <ul> <li>\u67d0\u4e9b\u52a8\u753b\u53ef\u4ee5\u53ea\u5728\u5408\u6210\u5c42\u5b8c\u6210\uff0c\u4e0d\u89e6\u53d1\u5e03\u5c40\u548c\u7ed8\u5236\u3002</li> <li><code>transform</code> \u548c <code>opacity</code> \u901a\u5e38\u6bd4\u4fee\u6539 <code>left</code>\u3001<code>top</code> \u66f4\u6d41\u7545\u3002</li> </ul> <p>\u793a\u4f8b\uff1a</p> <pre><code>/* \u63a8\u8350\u7528\u4e8e\u52a8\u753b */\n.box {\n  transform: translateX(100px);\n}\n\n/* \u5bb9\u6613\u89e6\u53d1\u5e03\u5c40 */\n.box {\n  left: 100px;\n}\n</code></pre> <p>\u6ce8\u610f\uff1a\u4e0d\u8981\u6ee5\u7528 <code>will-change</code>\uff0c\u8fc7\u591a\u56fe\u5c42\u4f1a\u589e\u52a0\u5185\u5b58\u5360\u7528\u548c\u5408\u6210\u6210\u672c\u3002</p>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#11","title":"11. \u56de\u6d41\u3001\u91cd\u7ed8\u3001\u5408\u6210\u7684\u533a\u522b","text":"\u7c7b\u578b \u82f1\u6587 \u5f71\u54cd\u8303\u56f4 \u6027\u80fd\u6210\u672c \u56de\u6d41 Layout / Reflow \u91cd\u65b0\u8ba1\u7b97\u5e03\u5c40 \u6700\u5927 \u91cd\u7ed8 Paint / Repaint \u91cd\u65b0\u7ed8\u5236\u50cf\u7d20 \u4e2d\u7b49 \u5408\u6210 Composite \u5408\u6210\u5df2\u6709\u56fe\u5c42 \u8f83\u5c0f <p>\u6027\u80fd\u6210\u672c\u5927\u81f4\uff1a</p> <pre><code>\u56de\u6d41 &gt; \u91cd\u7ed8 &gt; \u5408\u6210\n</code></pre> <p>\u4f8b\u5b50\uff1a</p> \u64cd\u4f5c \u53ef\u80fd\u89e6\u53d1 \u6539 <code>width</code> \u56de\u6d41 + \u91cd\u7ed8 + \u5408\u6210 \u6539 <code>color</code> \u91cd\u7ed8 + \u5408\u6210 \u6539 <code>transform</code> \u5408\u6210 \u6539 <code>opacity</code> \u5408\u6210 \u6dfb\u52a0 DOM \u8282\u70b9 \u56de\u6d41 + \u91cd\u7ed8 + \u5408\u6210"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#12","title":"12. \u6d4f\u89c8\u5668\u4e3b\u7ebf\u7a0b\u4e0e\u4e8b\u4ef6\u5faa\u73af","text":"<p>\u6e32\u67d3\u8fdb\u7a0b\u4e2d\u6709\u4e00\u4e2a\u91cd\u8981\u7684\u4e3b\u7ebf\u7a0b\uff0c\u8d1f\u8d23\u5927\u91cf\u9875\u9762\u5de5\u4f5c\u3002</p> <p>\u4e3b\u7ebf\u7a0b\u901a\u5e38\u8d1f\u8d23\uff1a</p> <ul> <li>\u6267\u884c JavaScript\u3002</li> <li>\u89e3\u6790 HTML\u3002</li> <li>\u6837\u5f0f\u8ba1\u7b97\u3002</li> <li>\u5e03\u5c40\u3002</li> <li>\u7ed8\u5236\u51c6\u5907\u3002</li> <li>\u5904\u7406\u7528\u6237\u8f93\u5165\u4e8b\u4ef6\u3002</li> </ul> <p>\u5982\u679c JavaScript \u957f\u65f6\u95f4\u5360\u7528\u4e3b\u7ebf\u7a0b\uff0c\u9875\u9762\u5c31\u53ef\u80fd\u5361\u987f\uff0c\u7528\u6237\u70b9\u51fb\u3001\u6eda\u52a8\u4e5f\u4f1a\u53d8\u6162\u3002</p> <p>\u4e8b\u4ef6\u5faa\u73af\u5927\u81f4\u6d41\u7a0b\uff1a</p> <pre><code>\u6267\u884c\u4e00\u4e2a\u5b8f\u4efb\u52a1\n  -&gt; \u6e05\u7a7a\u5fae\u4efb\u52a1\u961f\u5217\n  -&gt; \u5fc5\u8981\u65f6\u6267\u884c\u6e32\u67d3\n  -&gt; \u6267\u884c\u4e0b\u4e00\u4e2a\u5b8f\u4efb\u52a1\n</code></pre> <p>\u5e38\u89c1\u5b8f\u4efb\u52a1\uff1a</p> <ul> <li><code>setTimeout</code></li> <li><code>setInterval</code></li> <li>\u7528\u6237\u4ea4\u4e92\u4e8b\u4ef6</li> <li>\u7f51\u7edc\u56de\u8c03</li> <li>\u6574\u4f53\u811a\u672c\u6267\u884c</li> </ul> <p>\u5e38\u89c1\u5fae\u4efb\u52a1\uff1a</p> <ul> <li><code>Promise.then</code></li> <li><code>queueMicrotask</code></li> <li><code>MutationObserver</code></li> </ul> <p>\u793a\u4f8b\uff1a</p> <pre><code>console.log('start');\n\nsetTimeout(() =&gt; {\n  console.log('timeout');\n});\n\nPromise.resolve().then(() =&gt; {\n  console.log('promise');\n});\n\nconsole.log('end');\n</code></pre> <p>\u8f93\u51fa\u987a\u5e8f\uff1a</p> <pre><code>start\nend\npromise\ntimeout\n</code></pre>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#13","title":"13. \u4e00\u5e27\u662f\u5982\u4f55\u6e32\u67d3\u7684","text":"<p>\u5927\u591a\u6570\u5c4f\u5e55\u5237\u65b0\u7387\u662f 60Hz\uff0c\u4e5f\u5c31\u662f\u6bcf\u79d2\u5237\u65b0 60 \u6b21\u3002</p> <p>\u6bcf\u5e27\u65f6\u95f4\u7ea6\u4e3a\uff1a</p> <pre><code>1000ms / 60 \u2248 16.7ms\n</code></pre> <p>\u4e00\u5e27\u4e2d\u53ef\u80fd\u5305\u542b\uff1a</p> <ol> <li>\u5904\u7406\u8f93\u5165\u4e8b\u4ef6\u3002</li> <li>\u6267\u884c JavaScript\u3002</li> <li>\u6267\u884c <code>requestAnimationFrame</code> \u56de\u8c03\u3002</li> <li>\u6837\u5f0f\u8ba1\u7b97\u3002</li> <li>\u5e03\u5c40\u3002</li> <li>\u7ed8\u5236\u3002</li> <li>\u5408\u6210\u3002</li> <li>\u663e\u793a\u5230\u5c4f\u5e55\u3002</li> </ol> <p>\u5982\u679c\u4e00\u5e27\u5185\u5de5\u4f5c\u8d85\u8fc7 16.7ms\uff0c\u5c31\u53ef\u80fd\u6389\u5e27\uff0c\u7528\u6237\u4f1a\u611f\u89c9\u5361\u987f\u3002</p> <p><code>requestAnimationFrame</code> \u9002\u5408\u505a\u52a8\u753b\uff0c\u56e0\u4e3a\u5b83\u4f1a\u5728\u6d4f\u89c8\u5668\u4e0b\u4e00\u6b21\u7ed8\u5236\u524d\u6267\u884c\u3002</p> <pre><code>function move() {\n  element.style.transform = 'translateX(100px)';\n  requestAnimationFrame(move);\n}\n\nrequestAnimationFrame(move);\n</code></pre>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#14","title":"14. \u8d44\u6e90\u52a0\u8f7d\u5bf9\u6e32\u67d3\u7684\u5f71\u54cd","text":"<p>\u4e0d\u540c\u8d44\u6e90\u5bf9\u6e32\u67d3\u7684\u5f71\u54cd\u4e0d\u540c\u3002</p> \u8d44\u6e90 \u5bf9\u6e32\u67d3\u7684\u5f71\u54cd HTML \u6e32\u67d3\u5165\u53e3\uff0c\u5fc5\u987b\u5148\u89e3\u6790 CSS \u963b\u585e\u6e32\u67d3\uff0c\u5f71\u54cd CSSOM \u548c\u6e32\u67d3\u6811 \u666e\u901a JS \u963b\u585e HTML \u89e3\u6790 defer JS \u4e0d\u963b\u585e HTML \u89e3\u6790\uff0cDOM \u5b8c\u6210\u540e\u6267\u884c async JS \u4e0d\u963b\u585e HTML \u89e3\u6790\uff0c\u4e0b\u8f7d\u5b8c\u7acb\u5373\u6267\u884c \u56fe\u7247 \u901a\u5e38\u4e0d\u963b\u585e DOM \u89e3\u6790\uff0c\u4f46\u4f1a\u5f71\u54cd\u5e03\u5c40\u548c LCP \u5b57\u4f53 \u53ef\u80fd\u5bfc\u81f4\u6587\u5b57\u4e0d\u53ef\u89c1\u6216\u5b57\u4f53\u5207\u6362 <p>\u5e38\u89c1\u8d44\u6e90\u4f18\u5316\u624b\u6bb5\uff1a</p> <pre><code>&lt;link rel=\"preload\" href=\"/style.css\" as=\"style\"&gt;\n&lt;link rel=\"preconnect\" href=\"https://cdn.example.com\"&gt;\n&lt;script src=\"/main.js\" defer&gt;&lt;/script&gt;\n&lt;img src=\"/hero.jpg\" loading=\"lazy\" alt=\"\"&gt;\n</code></pre> <p>\u8bf4\u660e\uff1a</p> <ul> <li><code>preload</code>\uff1a\u63d0\u524d\u52a0\u8f7d\u5f53\u524d\u9875\u9762\u9a6c\u4e0a\u8981\u7528\u7684\u5173\u952e\u8d44\u6e90\u3002</li> <li><code>preconnect</code>\uff1a\u63d0\u524d\u5efa\u7acb\u5230\u7b2c\u4e09\u65b9\u6e90\u7684\u8fde\u63a5\u3002</li> <li><code>defer</code>\uff1a\u5ef6\u540e\u6267\u884c\u811a\u672c\uff0c\u51cf\u5c11\u89e3\u6790\u963b\u585e\u3002</li> <li><code>loading=\"lazy\"</code>\uff1a\u56fe\u7247\u61d2\u52a0\u8f7d\uff0c\u51cf\u5c11\u9996\u5c4f\u8d44\u6e90\u538b\u529b\u3002</li> </ul>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#15","title":"15. \u524d\u7aef\u6027\u80fd\u6307\u6807","text":"<p>\u5e38\u89c1\u9875\u9762\u6027\u80fd\u6307\u6807\uff1a</p> \u6307\u6807 \u542b\u4e49 FP First Paint\uff0c\u9996\u6b21\u7ed8\u5236 FCP First Contentful Paint\uff0c\u9996\u6b21\u5185\u5bb9\u7ed8\u5236 LCP Largest Contentful Paint\uff0c\u6700\u5927\u5185\u5bb9\u7ed8\u5236 CLS Cumulative Layout Shift\uff0c\u7d2f\u8ba1\u5e03\u5c40\u504f\u79fb TTFB Time To First Byte\uff0c\u9996\u5b57\u8282\u65f6\u95f4 TTI Time To Interactive\uff0c\u53ef\u4ea4\u4e92\u65f6\u95f4 INP Interaction to Next Paint\uff0c\u4ea4\u4e92\u5230\u4e0b\u4e00\u6b21\u7ed8\u5236\u7684\u5ef6\u8fdf <p>\u91cd\u70b9\u7406\u89e3\uff1a</p> <ul> <li>FCP \u5173\u6ce8\u9875\u9762\u4f55\u65f6\u5f00\u59cb\u51fa\u73b0\u5185\u5bb9\u3002</li> <li>LCP \u5173\u6ce8\u9996\u5c4f\u4e3b\u8981\u5185\u5bb9\u4f55\u65f6\u5b8c\u6210\u663e\u793a\u3002</li> <li>CLS \u5173\u6ce8\u9875\u9762\u662f\u5426\u53d1\u751f\u610f\u5916\u5e03\u5c40\u8df3\u52a8\u3002</li> <li>INP \u5173\u6ce8\u7528\u6237\u4ea4\u4e92\u540e\u9875\u9762\u54cd\u5e94\u662f\u5426\u53ca\u65f6\u3002</li> <li>TTFB \u53cd\u6620\u7f51\u7edc\u548c\u670d\u52a1\u7aef\u54cd\u5e94\u901f\u5ea6\u3002</li> </ul>"},{"location":"%E7%BD%91%E9%A1%B5%E6%B8%B2%E6%9F%93%E5%8E%9F%E7%90%86.html#16","title":"16. \u5e38\u89c1\u4f18\u5316\u601d\u8def","text":"<p>\u51cf\u5c11\u7f51\u7edc\u8017\u65f6\uff1a</p> <ul> <li>\u5f00\u542f HTTP \u7f13\u5b58\u3002</li> <li>\u4f7f\u7528 CDN\u3002</li> <li>\u538b\u7f29 HTML\u3001CSS\u3001JavaScript\u3002</li> <li>\u4f7f\u7528 HTTP/2 \u6216 HTTP/3\u3002</li> <li>\u51cf\u5c11\u4e0d\u5fc5\u8981\u8bf7\u6c42\u3002</li> </ul> <p>\u51cf\u5c11\u6e32\u67d3\u963b\u585e\uff1a</p> <ul> <li>\u5173\u952e CSS \u5185\u8054\u6216\u4f18\u5148\u52a0\u8f7d\u3002</li> <li>\u975e\u5173\u952e CSS \u5ef6\u8fdf\u52a0\u8f7d\u3002</li> <li>JavaScript \u4f7f\u7528 <code>defer</code> \u6216\u6309\u9700\u52a0\u8f7d\u3002</li> <li>\u51cf\u5c11\u9996\u5c4f\u4f9d\u8d56\u7684\u5927\u4f53\u79ef\u8d44\u6e90\u3002</li> </ul> <p>\u51cf\u5c11\u56de\u6d41\u548c\u91cd\u7ed8\uff1a</p> <ul> <li>\u6279\u91cf\u4fee\u6539 DOM\u3002</li> <li>\u907f\u514d\u5faa\u73af\u4e2d\u4ea4\u66ff\u8bfb\u53d6\u5e03\u5c40\u5c5e\u6027\u548c\u4fee\u6539\u6837\u5f0f\u3002</li> <li>\u52a8\u753b\u4f18\u5148\u4f7f\u7528 <code>transform</code> \u548c <code>opacity</code>\u3002</li> <li>\u907f\u514d\u9891\u7e41\u4fee\u6539\u5f71\u54cd\u5e03\u5c40\u7684 CSS \u5c5e\u6027\u3002</li> </ul> <p>\u4f18\u5316\u56fe\u7247\u548c\u5b57\u4f53\uff1a</p> <ul> <li>\u4f7f\u7528\u5408\u9002\u5c3a\u5bf8\u7684\u56fe\u7247\u3002</li> <li>\u4f7f\u7528 WebP\u3001AVIF \u7b49\u9ad8\u538b\u7f29\u683c\u5f0f\u3002</li> <li>\u7ed9\u56fe\u7247\u8bbe\u7f6e <code>width</code> \u548c <code>height</code>\uff0c\u51cf\u5c11\u5e03\u5c40\u504f\u79fb\u3002</li> <li>\u5b57\u4f53\u6309\u9700\u52a0\u8f7d\uff0c\u907f\u514d\u52a0\u8f7d\u8fc7\u591a\u5b57\u91cd\u3002</li> </ul> <p>\u4f18\u5316 JavaScript\uff1a</p> <ul> <li>\u62c6\u5206\u957f\u4efb\u52a1\u3002</li> <li>\u51cf\u5c11\u4e3b\u7ebf\u7a0b\u963b\u585e\u3002</li> <li>\u4f7f\u7528 Web Worker \u5904\u7406\u590d\u6742\u8ba1\u7b97\u3002</li> <li>\u5bf9\u6eda\u52a8\u3001\u8f93\u5165\u7b49\u9ad8\u9891\u4e8b\u4ef6\u4f7f\u7528\u8282\u6d41\u6216\u9632\u6296\u3002</li> </ul>"}]}